314	export type DzIssue = { path: string; code: string; message: string };
315	export type CheckStatus = "pass" | "warn" | "fail" | "not_run";
316	export type DzCheck = { id: string; status: CheckStatus; items: string[] };
317	export type AbilityBudget = { ability: string; actions: number; entities: number; tasks: number; particles: number; projectiles: number; nodes: number; depth: number };
318	export type DesignValidation =
319	  | { ok: true; design: ItemDesign; errors: []; warnings: DzIssue[]; checks: DzCheck[]; budgets: AbilityBudget[]; features: DesignFeatures }
320	  | { ok: false; errors: DzIssue[]; warnings: DzIssue[]; checks: DzCheck[]; budgets: AbilityBudget[] };
