322	export type DesignContext = {
323	  version: string;
324	  namespace: string;
325	  /** Keys of the other design items of the same mod (give_item / item_identity / recipe ingredients may use them). */
326	  items?: string[];
327	  /** Asset keys the mod has: item model keys (`nx_x:name`) and sound keys (`nx_x:set.event`). Undefined = not checked. */
328	  assets?: { models?: string[]; sounds?: string[]; /** item model states per model key (lib/cyrus/itemmodel needs) */ itemModels?: Record<string, { modes: string[]; flags: string[]; use: boolean }> };
