379	export function validateDesign(input: unknown, ctx: DesignContext): DesignValidation {
380	  const errors: DzIssue[] = [];
381	  const warnings: DzIssue[] = [];
382	  const bucket = new Map<string, string[]>(DESIGN_CHECKS.map((c) => [c, []]));
383	  const failed = new Set<string>();
384	  const ran = new Set<string>(["schema"]);
385	  const fail = (check: string, path: string, code: string, message: string) => { errors.push({ path, code, message }); failed.add(check); bucket.get(check)!.push(`${path}: ${message}`); };
386	  const warn = (check: string, path: string, code: string, message: string) => { warnings.push({ path, code, message }); bucket.get(check)!.push(`warn ${path}: ${message}`); };
387	  const budgets: AbilityBudget[] = [];
388	  const checksOf = (): DzCheck[] => DESIGN_CHECKS.map((id) => {
389	    const items = bucket.get(id)!;
390	    return { id, status: !ran.has(id) ? "not_run" : failed.has(id) ? "fail" : items.length ? "warn" : "pass", items: items.slice(0, 20) };
391	  });
392	  const bad = (): DesignValidation => ({ ok: false, errors, warnings, checks: checksOf(), budgets });
393	
394	  ran.add("namespace");
395	  if (!NAMESPACE_RE.test(ctx.namespace)) { fail("namespace", "namespace", "bad_namespace", `"${ctx.namespace}" is not a reserved nx_ namespace`); return bad(); }
396	  ran.add("version_features");
397	  const fe = designFeatures(ctx.version);
398	  if (!fe.ok) { fail("version_features", "version", "unsupported_version", fe.error); return bad(); }
399	  const v = ctx.version;
400	  if (input && typeof input === "object" && !Array.isArray(input) && (input as { schemaVersion?: unknown }).schemaVersion !== undefined && (input as { schemaVersion?: unknown }).schemaVersion !== DESIGN_SPEC_VERSION) {
401	    fail("schema", "schemaVersion", "schema_version", `schemaVersion must be ${DESIGN_SPEC_VERSION}`); return bad();
402	  }
403	  const bytes = (() => { try { return new TextEncoder().encode(JSON.stringify(input)).length; } catch { return Infinity; } })();
404	  ran.add("limits");
405	  if (bytes > DESIGN_LIMITS.maxSpecBytes) { fail("limits", "(root)", "spec_size", `the design is ${bytes} bytes; the limit is ${DESIGN_LIMITS.maxSpecBytes}`); return bad(); }
406	  const parsed = ItemDesignSchema.safeParse(input);
407	  if (!parsed.success) {
408	    for (const i of parsed.error.issues.slice(0, 30)) fail("schema", issuePath(i.path) || "(root)", "schema", i.message);
409	    return bad();
410	  }
411	  const d = parsed.data;
412	  for (const c of ["vanilla_ids", "references", "context", "budget"]) ran.add(c);
413	  const ns = ctx.namespace;
414	  const id = buildIdentifier(ns, "item", d.id);
415	  if (!id.ok) fail("namespace", "id", "bad_id", id.error);
416	
417	  // base item
418	  const base = d.base.slice("minecraft:".length);
419	  if (!isVanilla("item", d.base, v)) fail("vanilla_ids", "base", "unknown_vanilla_id", missingIdReason("item", d.base, v));
420	  if (BANNED_BASES.test(base)) fail("context", "base", "banned_base", `${d.base} cannot be a design item's base (operator item, or its own right-click teleports/places/spawns)`);
421	  const clicks = d.abilities.some((a) => ["right_click", "sneak_right_click", "charge_release"].includes(a.trigger.type));
422	  if (clicks && isBlockItem(base, v)) fail("context", "base", "block_base", `${d.base} is a block: right-clicking would place it. Pick a non-block base item for click abilities`);
423	  const consume = d.abilities.some((a) => a.trigger.type === "item_consume");
424	  if (consume && !(CONSUMABLE_BASES as readonly string[]).includes(base)) fail("context", "base", "not_consumable", `item_consume needs an edible/drinkable base item (${CONSUMABLE_BASES.slice(0, 8).join(", ")}, ...); ${d.base} is not one`);
425	  if (d.stats && (d.stats.damage !== undefined) !== (d.stats.attackSpeed !== undefined)) fail("context", "stats", "stats_pair", "set damage and attackSpeed together: a custom attack modifier replaces the base item's default damage AND speed");
426	  if (d.stats?.durability !== undefined && d.stats.unbreakable) warn("context", "stats.durability", "unbreakable", "durability has no effect on an unbreakable item");
427	
428	  // assets
429	  if (d.assets?.model) {
430	    if (!d.assets.model.startsWith(`${ns}:`)) fail("namespace", "assets.model", "foreign_namespace", `the item model must be in this mod's namespace ${ns}`);
431	    else if (ctx.assets?.models && !ctx.assets.models.includes(d.assets.model)) warn("references", "assets.model", "asset_unresolved", `${d.assets.model}: this mod has no such item model (no custom texture for it, or your plan does not include custom textures), so the item keeps the ${d.base} look`);
432	    if (!fe.features.itemModel) warn("version_features", "assets.model", "item_model_unsupported", `custom item models need Minecraft 1.21.4 or newer; on ${v} the item keeps the ${d.base} look (a legacy custom_model_data emitter is not built)`);
433	  }
434	  const declaredSounds = new Set(d.assets?.sounds ?? []);
435	  const soundRef = (at: string, key: string) => {
436	    const kns = key.split(":")[0];
437	    if (kns === "minecraft") { warn("references", at, "vanilla_sound_unchecked", `${key}: vanilla sound keys are not checked against the game (a wrong key plays nothing)`); return; }
438	    if (kns !== ns) { fail("namespace", at, "foreign_namespace", `${key} uses the namespace ${kns}; sounds must be minecraft: or this mod's ${ns}`); return; }
439	    if (ctx.assets?.sounds && !ctx.assets.sounds.includes(key)) warn("references", at, "asset_unresolved", `${key}: this mod has no such custom sound (no sound set for it, or your plan does not include custom sounds), so it plays nothing`);
440	    else if (!ctx.assets?.sounds && declaredSounds.size && !declaredSounds.has(key)) warn("references", at, "sound_undeclared", `${key} is not listed in assets.sounds`);
441	  };
442	  (d.assets?.sounds ?? []).forEach((s, i) => { if (!s.startsWith(`${ns}:`) && !s.startsWith("minecraft:")) fail("namespace", `assets.sounds[${i}]`, "foreign_namespace", `${s} must be minecraft: or ${ns}:`); });
443	
444	  // uniqueness + local tables
445	  const abilityIds = new Set<string>();
446	  d.abilities.forEach((a, i) => { if (abilityIds.has(a.id)) fail("references", `abilities[${i}].id`, "duplicate_id", `ability ${a.id} is defined twice`); abilityIds.add(a.id); });
447	  const marks = new Map<string, z.infer<typeof MarkSchema>>();
448	  (d.marks ?? []).forEach((m, i) => { if (marks.has(m.name)) fail("references", `marks[${i}].name`, "duplicate_id", `mark ${m.name} is defined twice`); marks.set(m.name, m); });
449	  const perms = new Set<string>();
450	  (d.permissions ?? []).forEach((p, i) => { if (perms.has(p.node)) fail("references", `permissions[${i}].node`, "duplicate_id", `permission ${p.node} is declared twice`); if (["give", "reload", "command", "list", "params"].includes(p.node)) fail("references", `permissions[${i}].node`, "reserved_node", `${ns}.${p.node} is reserved for the mod's own command`); perms.add(p.node); });
451	  const otherItems = new Set([...(ctx.items ?? []), d.id]);
452	  const launchTags = new Set<string>();
453	  for (const ab of d.abilities) walkActions(ab.actions, (a) => { if (a.type === "launch_projectile" && a.tag) launchTags.add(a.tag); });
454	  const passives = new Set<string>();
455	  (d.passives ?? []).forEach((p, i) => {
456	    if ((HARMFUL_EFFECTS as readonly string[]).includes(p.effect)) fail("context", `passives[${i}].effect`, "harmful_passive", `${p.effect} is harmful: a passive may only give the holder a helpful effect`);
457	    if (["instant_health", "instant_damage", "saturation"].includes(p.effect)) fail("context", `passives[${i}].effect`, "instant_passive", `${p.effect} is instant and would apply every 2 seconds; use an ability instead`);
458	    if (passives.has(p.effect)) fail("references", `passives[${i}]`, "duplicate_id", `passive ${p.effect} is listed twice`); passives.add(p.effect);
459	  });
460	  const sneakRight = d.abilities.some((a) => a.trigger.type === "sneak_right_click");
461	  const chargeRight = d.abilities.some((a) => a.trigger.type === "charge_release" && a.trigger.release === "right_click");
462	  if (sneakRight && chargeRight) fail("context", "abilities", "ambiguous_trigger", "an item cannot have both sneak_right_click and a charge_release released by right-click (both fire on a sneaking right-click)");
463	
464	  // abilities
465	  d.abilities.forEach((ab, i) => {
466	    const at = `abilities[${i}]`;
467	    const tr = ab.trigger;
468	    if (tr.type === "charge_release" && tr.maxChargeTicks < tr.minChargeTicks) fail("context", `${at}.trigger.maxChargeTicks`, "charge_order", "maxChargeTicks must be at least minChargeTicks");
