470	    if (ab.manualCooldown && !ab.cooldownTicks) warn("context", `${at}.manualCooldown`, "no_cooldown", "manualCooldown without cooldownTicks does nothing");
471	    if (ab.manualCharges && !ab.charges) warn("context", `${at}.manualCharges`, "no_charges", "manualCharges without charges does nothing");
472	    if (tr.type === "held_interval" && ab.cooldownTicks && ab.cooldownTicks < tr.periodTicks) warn("context", `${at}.cooldownTicks`, "cooldown_below_period", "the cooldown is shorter than the interval, so it never blocks");
