511	      switch (a.type) {
512	        case "pull_to": if (a.to === "self" && (a.target ?? "target") === "self") fail("context", ap, "self_pull", "pulling yourself to yourself does nothing"); break;
513	        case "push_from": if (a.from === "self" && (a.target ?? "target") === "self") fail("context", ap, "self_push", "pushing yourself from yourself does nothing"); break;
514	        case "play_sound": soundRef(`${ap}.sound`, a.sound); break;
515	        case "give_item":
516	          if (a.item.startsWith("minecraft:")) { if (!isVanilla("item", a.item, v)) fail("vanilla_ids", `${ap}.item`, "unknown_vanilla_id", missingIdReason("item", a.item, v)); else if (BANNED_BASES.test(a.item.slice(10))) fail("context", `${ap}.item`, "banned_item", `${a.item} cannot be given by an ability`); }
517	          else if (!otherItems.has(a.item)) fail("references", `${ap}.item`, "unresolved_ref", `no design item "${a.item}" in this mod`);
518	          break;
519	        case "set_cooldown": abilityRef(ap, a.ability, "cooldown"); if (a.ticks === undefined && !(d.abilities.find((x) => x.id === (a.ability ?? ab.id))?.cooldownTicks)) fail("references", ap, "no_ticks", "set_cooldown needs ticks when the ability has no cooldownTicks"); break;
520	        case "consume_charge": abilityRef(ap, a.ability, "charges"); break;
521	        case "apply_mark": case "query_marked": if (!marks.has(a.mark)) fail("references", `${ap}.mark`, "unresolved_ref", `no mark "${a.mark}" in this item's "marks"`); break;
522	        case "query_nearby":
523	          a.types?.forEach((t, j) => { if (!isVanilla("entity_type", t, v)) fail("vanilla_ids", `${ap}.types[${j}]`, "unknown_vanilla_id", missingIdReason("entity_type", t, v)); });
524	          if (a.includePlayers && !(a.kinds?.includes("player") || a.kinds?.includes("living") || !a.kinds?.length)) warn("context", ap, "players_filtered", "includePlayers has no effect: kinds excludes players");
