    plan, planLabel: plan ? PLAN_LABEL[plan] : "Unknown",
    edit: { texture: canAsset(plan, "texture", "edit"), sound: canAsset(plan, "sound", "edit"), model: canAsset(plan, "model", "edit") },
  };
}

