export function studioRenderHost(env: Record<string, string | undefined> = process.env): RenderHostSelection {
  if (env.CYRUS_STUDIO_SOUND_RENDER === "fake" && env.NODE_ENV !== "production") return { ok: true, host: (GF.__cyrusFakeRender ??= fakeRenderHost()) };
  return selectRenderHost(env);
}
export function soundCandidateBackend(env: Record<string, string | undefined> = process.env): SoundCandidateBackend {
  if (env.CYRUS_STUDIO_CANDIDATES === "fake" && env.NODE_ENV !== "production") return (GF.__cyrusFakeSoundCands ??= fakeSoundCandidates({ readyAfter: 1 }));
  return changeBuildSoundCandidates(prismaStudioStore);
