export function apiDeps(env: Record<string, string | undefined> = process.env): StudioApiDeps {
  const uploads: UploadStore | null = env.CYRUS_UPLOAD_STORE === "local" && env.NODE_ENV !== "production" ? localUploadStore(env.CYRUS_UPLOAD_DIR || ".data/cyrus-uploads") : null;
  return {
    viewer: studioViewer,
    service: serviceDeps(env),
    candidates: candidateBackend(env),
    catalog: { providers: [SoundLibraryProvider, TextureLibraryProvider, ...userAssetProviders(prismaUserAssetStore)], planOf: studioPlanOf(env) },
    rateLimit: (key, max, windowMs) => getHost().rateLimit.check(`cyrus:studio:${key}`, { max, windowMs }),
    uploads,
    // Sound Studio: the library licence flag (same as builds), the render host, the candidate backend
    sound: { libraryCleared: () => soundLibraryCleared(env), renderHost: () => studioRenderHost(env) },
    soundCandidates: soundCandidateBackend(env),
