function LivePreview({ cur, rasters, keys, itemModels }: { cur: string; rasters: Record<string, Raster>; keys: string[]; itemModels: ItemModelSpec[] }) {
  const [pv, setPv] = useState<"slot" | "hand" | "tile">("slot");
  const [bg, setBg] = useState<"dark" | "light">("dark");
  const [cv, setCv] = useState<PreviewContext>("firstperson");
  // Cyrus item model states: the item model this texture belongs to (or the pack's default for it) and its states
  const model = useMemo(() => previewModel(cur, itemModels), [cur, itemModels]);
  const [stateId, setStateId] = useState("idle");
  useEffect(() => { setStateId(model.states.find((x) => x.texture === cur)?.id ?? "idle"); }, [cur, model]);
  const r = rasters[cur];
  const st = model.states.find((x) => x.id === stateId) ?? model.states[0];
  const sr = rasters[st.texture] ?? r;
  const idle = rasters[model.spec.name] ?? r;
  const disp = useMemo(() => previewDisplays(model, idle), [model, idle]);
  const meta = PREVIEW_CONTEXTS.find((c) => c.id === cv)!;
  const t = (disp[st.id] ?? disp.idle)[meta.display];
  const hint = pv === "slot" ? "Hotbar, then the item at GUI scale 1, 2 and 4" : pv === "tile" ? "3 × 3 repeat: seams show for block textures" : `${meta.hint}${st.id !== "idle" ? ` · ${st.label}` : ""}`;
  return (
    <div className="cys-panel cys-glass tx-prev">
      <div className="cys-ph"><span className="cys-eyebrow">Live preview</span>
        <div className="cys-seg sm cys-soft">{([["slot", "Hotbar"], ["hand", "In game"], ["tile", "Tile"]] as const).map(([v, l]) => <button key={v} type="button" className={pv === v ? "on" : ""} onClick={() => setPv(v)}>{l}</button>)}</div>
      </div>
      {pv === "hand" && (
        <div className="tx-ctxrow"><div className="cys-seg sm cys-soft" role="group" aria-label="Where the item is shown">{PREVIEW_CONTEXTS.map((c) => <button key={c.id} type="button" className={cv === c.id ? "on" : ""} aria-pressed={cv === c.id} onClick={() => setCv(c.id)}>{c.label}</button>)}</div></div>
      )}
      <div className={`tx-pvstage ${bg}`}>
        {pv === "slot" && (
          <div>
            <div className="tx-hotbar">{Array.from({ length: 9 }, (_, i) => <div key={i} className={`tx-slot ${keys[i] === cur ? "sel" : ""}`}>{keys[i] && <RasterCanvas raster={rasters[keys[i]]} />}</div>)}</div>
            <div className="tx-scales">{[[2, "1×"], [4, "2×"], [8, "4×"]].map(([k, l]) => <figure key={l}><RasterCanvas raster={r} style={{ width: 16 * (k as number), height: 16 * (k as number) }} />{l}</figure>)}</div>
          </div>
        )}
        {pv === "tile" && <TileCanvas r={r} />}
        {pv === "hand" && (
          <>
            <ContextCanvas r={sr} name={model.spec.name} ctx={cv} t={t} gun={model.spec.category === "gun"} />
            <span className="cys-tag dim" style={{ position: "absolute", right: 8, top: 8 }} title="The display transforms are the pack's (the game's own values for tools, bows and crossbows); the camera, the hand, the slot, frame and head are drawn by Cyrus, so this is close to, not exactly, the game">approximate</span>
          </>
        )}
      </div>
      {pv === "hand" && model.states.length > 1 && (
        <div className="tx-states" role="group" aria-label="Item state">
          <span className="cys-eyebrow">State</span>
          <div className="cys-seg sm cys-soft">{model.states.map((x) => <button key={x.id} type="button" className={st.id === x.id ? "on" : ""} aria-pressed={st.id === x.id} onClick={() => setStateId(x.id)} disabled={!rasters[x.texture]}>{x.label}</button>)}</div>
        </div>
      )}
      <div className="tx-pvopts"><span className="cys-hint">{hint}</span>
        <div className="cys-seg sm cys-soft">{(["dark", "light"] as const).map((v) => <button key={v} type="button" className={bg === v ? "on" : ""} onClick={() => setBg(v)}>{v === "dark" ? "Dark" : "Light"}</button>)}</div>
      </div>
    </div>
  );
}

function TileCanvas({ r }: { r: Raster }) {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const c = ref.current; if (!c) return;
    const n = r.size; c.width = n * 3; c.height = n * 3;
    const t = document.createElement("canvas"); paintRaster(t, r, 1);
    const x = c.getContext("2d")!; x.clearRect(0, 0, c.width, c.height);
    for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) x.drawImage(t, i * n, j * n);
  }, [r]);
  return <canvas ref={ref} className="tx-tilecv" aria-label="Tiled 3 by 3" />;
}

function ContextCanvas({ r, name, ctx, t, gun }: { r: Raster; name: string; ctx: PreviewContext; t: import("@/lib/cyrus/textures/display").DisplayTransform; gun: boolean }) {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const c = ref.current; if (!c) return;
    const W = c.clientWidth || 316, H = c.clientHeight || 150, dpr = Math.min(2, window.devicePixelRatio || 1);
    c.width = W * dpr; c.height = H * dpr;
    const x = c.getContext("2d")!; x.setTransform(dpr, 0, 0, dpr, 0, 0); x.clearRect(0, 0, W, H);
    const top = 8;
    x.translate(0, top);
    const s = contextScene(r, name, ctx, t, W, H - top - 4, gun);
    x.lineJoin = "round";
    for (const p of s.polys) {
      x.beginPath(); p.pts.forEach(([a, b], i) => (i ? x.lineTo(a, b) : x.moveTo(a, b))); x.closePath();
      x.fillStyle = p.fill; x.fill();
      if (p.stroke) { x.strokeStyle = p.stroke; x.lineWidth = 1; x.stroke(); }
      else if (p.fill.length === 7) { x.strokeStyle = p.fill; x.lineWidth = 0.6; x.stroke(); } // close hairline gaps between texels
    }
  }, [r, name, ctx, t, gun]);
  const label = PREVIEW_CONTEXTS.find((c) => c.id === ctx)?.label ?? ctx;
  return <canvas ref={ref} className="tx-held" aria-label={`${name}: ${label} view`} />;
}

