const fieldOf = (rel: string) => "p_" + rel.replace(/[.]/g, "_");
const COLOR_NAMES: Record<string, string> = { black: "BLACK", dark_blue: "DARK_BLUE", dark_green: "DARK_GREEN", dark_aqua: "DARK_AQUA", dark_red: "DARK_RED", dark_purple: "DARK_PURPLE", gold: "GOLD", gray: "GRAY", dark_gray: "DARK_GRAY", blue: "BLUE", green: "GREEN", aqua: "AQUA", red: "RED", light_purple: "LIGHT_PURPLE", yellow: "YELLOW", white: "WHITE" };
export const colorExpr = (c?: string) => (!c ? "null" : c.startsWith("#") ? `TextColor.color(0x${c.slice(1).toUpperCase()})` : `NamedTextColor.${COLOR_NAMES[c]}`);
const KIND_BITS: Record<string, number> = { player: 1, hostile: 2, animal: 4, living: 8 };
export const maskOf = (k?: string[]) => (k ?? []).reduce((m, x) => m | (KIND_BITS[x] ?? 0), 0);
export const bare = (id: string) => id.replace(/^minecraft:/, "");
export const MATERIAL = (id: string) => `Material.${bare(id).toUpperCase()}`;

/** Optional-field defaults (documented in docs "Cyrus gameplay designers (R3)"). */
export const DEFAULTS = {
  knockbackVertical: 0.35, pullVertical: 0.25, pushVertical: 0.35, amplifier: 0, lifetimeTicks: 100, spread: 0.3, particleSpeed: 0.02,
  volume: 1, pitch: 1, fadeInTicks: 10, stayTicks: 40, fadeOutTicks: 10, giveCount: 1, chargeCost: 1, passiveAmplifier: 0,
} as const;

// ------------------------------------------------------------------------------------------------------- parameters
export type ParamSink = { params: Param[]; base: string; item: string; ability?: string; abilityName?: string };
export function addParam(s: ParamSink, rel: string, kind: ParamKind, cap: CapName | [number, number], value: number | string, label: string, role: string): Param {
  const [min, max] = Array.isArray(cap) ? cap : CAPS[cap as CapName];
  const p: Param = { path: s.base + rel, field: fieldOf(rel), kind, min, max, value, label: s.abilityName ? `${s.abilityName}: ${label}` : label, item: s.item, ...(s.ability ? { ability: s.ability } : {}), role };
  s.params.push(p);
  return p;
}

/** The parameters of one ability, in config order (also the Java field order). */
export function abilityParams(item: ItemDesign, ab: Ability): Param[] {
  const s: ParamSink = { params: [], base: `items.${item.id}.abilities.${ab.id}.`, item: item.id, ability: ab.id, abilityName: ab.name };
  if (ab.cooldownTicks !== undefined) addParam(s, "cooldown_ticks", "ticks", "cooldownTicks", ab.cooldownTicks, "cooldown (ticks, 20 = 1 s)", "cooldown");
  if (ab.charges) { addParam(s, "charges.max", "int", "chargesMax", ab.charges.max, "charges", "charges"); addParam(s, "charges.regen_ticks", "ticks", "chargeRegenTicks", ab.charges.regenTicks, "ticks per charge regained", "cooldown"); }
  const t = ab.trigger;
  if ("targetRange" in t && t.targetRange !== undefined) addParam(s, "trigger.target_range", "num", "targetRange", t.targetRange, "target range (blocks)", "range");
  if (t.type === "held_interval") addParam(s, "trigger.period_ticks", "ticks", "periodTicks", t.periodTicks, "interval (ticks)", "cooldown");
  if (t.type === "charge_release") { addParam(s, "trigger.min_charge_ticks", "ticks", "minChargeTicks", t.minChargeTicks, "minimum charge (ticks)", "duration"); addParam(s, "trigger.max_charge_ticks", "ticks", "maxChargeTicks", t.maxChargeTicks, "full charge (ticks)", "duration"); }
  const cond = (c: Condition, rel: string) => {
    switch (c.type) {
      case "health_below": case "health_above": addParam(s, `${rel}.fraction`, "num", "healthFraction", c.fraction, `${c.type.replace("_", " ")} (fraction of max health)`, "other"); break;
      case "random_chance": addParam(s, `${rel}.chance`, "num", "chance", c.chance, "chance (0-1)", "chance"); break;
      case "time_of_day": addParam(s, `${rel}.from`, "int", "timeOfDay", c.from, "time window start (ticks)", "other"); addParam(s, `${rel}.to`, "int", "timeOfDay", c.to, "time window end (ticks)", "other"); break;
      case "charges_available": addParam(s, `${rel}.amount`, "int", "chargeCost", c.amount, "charges needed", "count"); break;
      default: break;
    }
  };
  (ab.conditions ?? []).forEach((c, i) => cond(c, `c${i}`));
  walkActions(ab.actions, (a, p) => {
    switch (a.type) {
      case "damage": addParam(s, `${p}.amount`, "num", "damage", a.amount, "damage (health points)", "damage"); break;
      case "heal": addParam(s, `${p}.amount`, "num", "heal", a.amount, "heal (health points)", "heal"); break;
      case "potion_effect": addParam(s, `${p}.duration_ticks`, "ticks", "potionTicks", a.durationTicks, `${a.effect} duration (ticks)`, "duration"); addParam(s, `${p}.amplifier`, "int", "amplifier", a.amplifier ?? DEFAULTS.amplifier, `${a.effect} level - 1`, "level"); break;
      case "knockback": case "pull_to": case "push_from": {
        const dv = a.type === "knockback" ? DEFAULTS.knockbackVertical : a.type === "pull_to" ? DEFAULTS.pullVertical : DEFAULTS.pushVertical;
        addParam(s, `${p}.strength`, "num", "strength", a.strength, `${a.type.replace("_", " ")} strength`, "strength"); addParam(s, `${p}.vertical`, "num", "vertical", a.vertical ?? dv, `${a.type.replace("_", " ")} lift`, "lift"); break;
      }
      case "teleport_short": addParam(s, `${p}.range`, "num", "teleportRange", a.range, "teleport range (blocks)", "range"); break;
      case "launch_projectile": addParam(s, `${p}.speed`, "num", "projectileSpeed", a.speed, `${a.kind} speed`, "speed"); addParam(s, `${p}.lifetime_ticks`, "ticks", "projectileLifetime", a.lifetimeTicks ?? DEFAULTS.lifetimeTicks, `${a.kind} lifetime (ticks)`, "duration"); break;
      case "spawn_particles": addParam(s, `${p}.count`, "int", "particleCount", a.count, `${a.particle} particles`, "count"); addParam(s, `${p}.spread`, "num", "particleSpread", a.spread ?? DEFAULTS.spread, `${a.particle} spread`, "other"); addParam(s, `${p}.speed`, "num", "particleSpeed", a.speed ?? DEFAULTS.particleSpeed, `${a.particle} speed`, "other"); break;
      case "play_sound": addParam(s, `${p}.sound`, "sound", [0, 100], a.sound, "sound key", "sound"); addParam(s, `${p}.volume`, "num", "volume", a.volume ?? DEFAULTS.volume, "sound volume", "other"); addParam(s, `${p}.pitch`, "num", "pitch", a.pitch ?? DEFAULTS.pitch, "sound pitch", "other"); break;
      case "send_message": case "actionbar": addParam(s, `${p}.text`, "text", [0, RUNTIME_CAPS.textChars], a.text, a.type === "actionbar" ? "actionbar text" : "message text", "text"); break;
      case "title":
        addParam(s, `${p}.title`, "text", [0, RUNTIME_CAPS.titleChars], a.title, "title text", "text");
        if (a.subtitle !== undefined) addParam(s, `${p}.subtitle`, "text", [0, RUNTIME_CAPS.subtitleChars], a.subtitle, "subtitle text", "text");
        addParam(s, `${p}.fade_in_ticks`, "ticks", "titleFadeTicks", a.fadeInTicks ?? DEFAULTS.fadeInTicks, "title fade in", "duration");
        addParam(s, `${p}.stay_ticks`, "ticks", "titleStayTicks", a.stayTicks ?? DEFAULTS.stayTicks, "title stay", "duration");
        addParam(s, `${p}.fade_out_ticks`, "ticks", "titleFadeTicks", a.fadeOutTicks ?? DEFAULTS.fadeOutTicks, "title fade out", "duration");
        break;
      case "give_item": addParam(s, `${p}.count`, "int", "giveCount", a.count ?? DEFAULTS.giveCount, `${a.item} count`, "count"); break;
      case "set_cooldown": {
        const ref = item.abilities.find((x) => x.id === (a.ability ?? ab.id));
        addParam(s, `${p}.ticks`, "ticks", "cooldownTicks", a.ticks ?? ref?.cooldownTicks ?? 0, `cooldown set on ${a.ability ?? ab.id} (ticks)`, "cooldown"); break;
      }
      case "consume_charge": addParam(s, `${p}.amount`, "int", "chargeCost", a.amount ?? DEFAULTS.chargeCost, "charges spent", "count"); break;
      case "query_marked": addParam(s, `${p}.radius`, "num", "queryMarkedRadius", a.radius, `marked "${a.mark}" search radius`, "range"); addParam(s, `${p}.max`, "int", "queryMax", a.max, "max targets", "count"); break;
      case "query_nearby": addParam(s, `${p}.radius`, "num", "queryNearbyRadius", a.radius, "nearby search radius", "range"); addParam(s, `${p}.max`, "int", "queryMax", a.max, "max targets", "count"); break;
      case "delayed": addParam(s, `${p}.delay_ticks`, "ticks", "delayTicks", a.delayTicks, "delay (ticks)", "duration"); break;
      case "branch": a.if.forEach((c, i) => cond(c, `${p}.if${i}`)); break;
      default: break;
    }
  });
  return s.params;
}

export function itemParams(item: ItemDesign): Param[] {
  const s: ParamSink = { params: [], base: `items.${item.id}.`, item: item.id };
  for (const m of item.marks ?? []) { addParam(s, `marks.${m.name}.duration_ticks`, "ticks", "markTicks", m.durationTicks, `mark "${m.name}" duration (ticks)`, "duration"); addParam(s, `marks.${m.name}.max_per_owner`, "int", "marksPerOwner", m.maxPerOwner, `mark "${m.name}" max per player`, "count"); }
  (item.passives ?? []).forEach((p, i) => addParam(s, `passives.p${i}.amplifier`, "int", "passiveAmplifier", p.amplifier ?? DEFAULTS.passiveAmplifier, `passive ${p.effect} level - 1`, "level"));
  (item.acquisition?.loot ?? []).forEach((l, i) => addParam(s, `loot.l${i}.chance`, "num", "lootChance", l.chance, `chance in ${l.table}`, "chance"));
  (item.acquisition?.drops ?? []).forEach((l, i) => addParam(s, `drops.d${i}.chance`, "num", "lootChance", l.chance, `drop chance from ${l.entity}`, "chance"));
  return s.params;
}

export function designParams(designs: ItemDesign[]): Param[] {
  return [...designs].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0)).flatMap((d) => [...itemParams(d), ...d.abilities.flatMap((ab) => abilityParams(d, ab))]);
}

// ---------------------------------------------------------------------------------------------------- Java codegen
class Out {
  lines: string[] = [];
  push(ind: number, s: string) { this.lines.push("    ".repeat(ind) + s); }
}

  const out: Clickable[] = [];
  for (const { path, c, slot } of menuClickables(m)) {
    const node = slot !== undefined ? `b${slot}` : path.startsWith("choices") ? `c${/\[(\d+)\]$/.exec(path)![1]}` : `e${/\[(\d+)\]$/.exec(path)![1]}`;
    out.push(withCfg(node, c, slot ?? -1));
  }
  if (m.style === "chest" && m.list?.source.type === "config") {
    const cur = m.list.source.currency;
    for (const e of m.list.source.entries) {
      const cost: Cost | undefined = cur.type === "item" ? { type: "item", item: cur.item, count: Math.round(e.price) } : cur.type === "xp_levels" ? { type: "xp_levels", levels: Math.round(e.price) } : cur.type === "economy" ? { type: "economy", amount: e.price } : undefined;
      out.push({ slot: -1, label: e.name ?? e.material, actions: [{ type: "give_item", item: e.material, count: e.amount }], cost });
    }
  }
  return out;
}
private allowed(name: string, c: { permission?: string }) { return !c.permission || this.players.get(name)!.perms.has(`${this.opts.namespace}.${c.permission}`); }

/** MenuManager.open: what each slot holds (null = refused). */
openMenu(name: string, id: string, page = 0, push = true): Open | null {
  const p = this.players.get(name)!;
  if (!p.online || !p.alive) return null;
  const m = this.menus.get(id);
  if (!m) { this.ev(name, "no_menu", id); return null; }
  if (m.permission && !p.perms.has(`${this.opts.namespace}.${m.permission}`)) { this.ev(name, "no_permission_menu", id); return null; }
  const cur = this.open.get(name);
  if (push && cur && cur.menu !== id) { const st = this.back.get(name) ?? []; st.unshift(cur.menu); while (st.length > GAMEPLAY_LIMITS.maxBack) st.pop(); this.back.set(name, st); }
  const o: Open = { menu: id, page, slots: new Map() };
  const all = this.clickables(m);
  if (m.style === "dialogue") {
    const vis = all.filter((c) => !c.hide || this.allowed(name, c));
    const pos = [[], [22], [20, 24], [20, 22, 24], [19, 21, 23, 25], [18, 20, 22, 24, 26]][Math.min(5, vis.length)];
    pos.forEach((s, i) => o.slots.set(s, vis[i]));
  } else {
    for (const c of all.filter((x) => x.slot >= 0)) if (this.allowed(name, c) || !c.hide) o.slots.set(c.slot, c);
    if (m.list) {
      const vis = all.filter((x) => x.slot < 0).filter((c) => !c.hide || this.allowed(name, c));
      const size = m.list.slots.length;
      o.page = Pagination.clamp(page, vis.length, size);
      const first = Pagination.first(o.page, size), n = Pagination.count(o.page, vis.length, size);
      for (let i = 0; i < n; i++) o.slots.set(m.list.slots[i], vis[first + i]);
      if (Pagination.hasPrev(o.page, vis.length, size)) o.slots.set(m.list.prev.slot, { slot: m.list.prev.slot, label: "prev", actions: [{ type: "prev_page" }], nav: "prev" });
      if (Pagination.hasNext(o.page, vis.length, size)) o.slots.set(m.list.next.slot, { slot: m.list.next.slot, label: "next", actions: [{ type: "next_page" }], nav: "next" });
    }
  }
  this.open.set(name, o);
  this.ev(name, "open", `${id}#${o.page}`);
  if (m.style === "dialogue") this.addProgress(name, "talk", (ob) => (ob.type === "talk" && ob.menu === id ? 1 : 0));
  return o;
}
current(name: string) { return this.open.get(name) ?? null; }
closeMenu(name: string) { this.open.delete(name); this.ev(name, "close"); }

/** MenuManager.onClick: EVERY click is cancelled; only plain left/right on a menu slot acts. */
click(name: string, slot: number, type: ClickType = "left"): ClickResult {
  const o = this.open.get(name);
  if (!o) return { cancelled: true, ran: false, reason: "no_menu" };
  const m = this.menus.get(o.menu)!;
  const size = m.style === "chest" ? m.rows * 9 : 27;
  if (type !== "left" && type !== "right") return { cancelled: true, ran: false, reason: "click_type" };
  if (slot < 0 || slot >= size) return { cancelled: true, ran: false, reason: "outside" };
  const c = o.slots.get(slot);
  if (!c) return { cancelled: true, ran: false, reason: "empty" };
  const last = this.lastClick.get(name) ?? -1000;
  if (this.tick - last < this.clickCooldown) return { cancelled: true, ran: false, reason: "rate_limited" };
  this.lastClick.set(name, this.tick);
  if (!this.allowed(name, c)) return { cancelled: true, ran: false, reason: "no_permission" };
  const gives = c.actions.filter((a): a is Extract<MenuAction, { type: "give_item" }> => a.type === "give_item").map((a) => ({ item: a.item, count: a.count ?? 1 }));
  if (!this.fits(name, gives)) return { cancelled: true, ran: false, reason: "no_space" };
  const why = this.refusal(name, c.cost);
  if (why) return { cancelled: true, ran: false, reason: why };
  if (!this.take(name, c.cost)) return { cancelled: true, ran: false, reason: "cannot_pay" };
  if (c.cost) this.ev(name, "paid", JSON.stringify(c.cost));
  for (const a of c.actions) this.menuAction(name, o, a);
  return { cancelled: true, ran: true, reason: "ok" };
}
/** A drag over menu slots: always cancelled, nothing happens. */
drag(name: string): ClickResult { return { cancelled: true, ran: false, reason: this.open.has(name) ? "drag" : "no_menu" }; }

private menuAction(name: string, o: Open, a: MenuAction) {
  switch (a.type) {
    case "give_item": this.give(name, a.item, a.count ?? 1); this.ev(name, "give", `${a.count ?? 1} x ${a.item}`); break;
    case "open_menu": this.openMenu(name, a.menu, 0, true); break;
    case "close": this.closeMenu(name); break;
    case "back": { const st = this.back.get(name) ?? []; const prev = st.shift(); if (prev) this.openMenu(name, prev, 0, false); else this.closeMenu(name); break; }
    case "next_page": this.openMenu(name, o.menu, o.page + 1, false); break;
    case "prev_page": this.openMenu(name, o.menu, o.page - 1, false); break;
    case "start_quest": this.startQuest(name, a.quest, false); break;
    case "abandon_quest": this.abandonQuest(name, a.quest); break;
    case "choose_branch": if (this.chooseBranch(name, a.quest, a.branch)) this.closeMenu(name); break;
    default: this.ev(name, a.type, "text" in a ? a.text : "sound" in a ? a.sound : "effect" in a ? a.effect : "item" in a ? `${a.item}` : undefined);
  }
}

// ---------------------------------------------------------------------------------------------- quests
entries(name: string): Map<string, ProgressEntry> { let m = this.progress.get(name); if (!m) { m = new Map(); this.progress.set(name, m); } return m; }
encoded(name: string) { return encodeProgress(this.entries(name)); }
private target(q: QuestDesign, stepId: string, j: number, o: Objective): number {
  const base = `quests.${q.id}.steps.${stepId}.o${j}`;
  return o.type === "visit_location" || o.type === "talk" ? 1 : o.type === "survive" ? this.cfg(`${base}.seconds`, o.seconds) : this.cfg(`${base}.count`, o.count);
}
private cooldown(q: QuestDesign) { return (q.repeat?.mode ?? "once") === "once" ? 0 : this.cfg(`quests.${q.id}.repeat.cooldown_seconds`, repeatCooldown(q)); }
active(name: string) { return [...this.entries(name).values()].filter((e) => e.state === "A" || e.state === "C").length; }

export const GENERAL_DEFAULTS = { menuClickCooldownTicks: 4, maxActiveQuests: 3 } as const;

export type ModCompileOk = CompileOk & {
  menus: MenuDesign[];
  quests: QuestDesign[];
  /** Compile-only dependencies from the import allowlist the javac classpath needs (vault-api for money costs). */
  deps: string[];
  counts: { items: number; menus: number; quests: number; /** motion designs (present only when the mod has some) */ motions?: number };
  /** false for an item-only mod (compiled by the item compiler). */
  gameplay: boolean;
  /** motion designs compiled into the mod (../motion; absent when there are none) */
  motions?: MotionDesign[];
  motionCompile?: WithMotions<object>["motionCompile"];
};
export type ModCompileResult = ModCompileOk | { ok: false; errors: GpIssue[]; warnings: GpIssue[] };

const cap = (c: GpCapName): [number, number] => [GAMEPLAY_CAPS[c][0], GAMEPLAY_CAPS[c][1]];

// -------------------------------------------------------------------------------------------------- parameters
function sinkFor(base: string, id: string): ParamSink { return { params: [], base, item: id }; }
const own = (s: ParamSink, owner: "menu" | "quest") => s.params.map((p) => ({ ...p, owner }));

function iconParams(s: ParamSink, rel: string, ic: Icon, what: string) {
  if (ic.name) addParam(s, `${rel}.name`, "text", [0, 60], ic.name.text, `${what} name`, "text");
  (ic.lore ?? []).forEach((l, j) => addParam(s, `${rel}.lore${j}`, "text", [0, 60], l.text, `${what} lore line ${j + 1}`, "text"));
  if (ic.amount !== undefined) addParam(s, `${rel}.amount`, "int", cap("iconAmount"), ic.amount, `${what} stack size shown`, "count");
}
function costParams(s: ParamSink, rel: string, c: Cost | undefined, what: string) {
  if (!c) return;
  if (c.type === "item") addParam(s, `${rel}.cost.count`, "int", cap("itemCost"), c.count, `${what} price (${c.item.replace(/^minecraft:/, "")})`, "price");
  if (c.type === "xp_levels") addParam(s, `${rel}.cost.levels`, "int", cap("xpLevelCost"), c.levels, `${what} price (XP levels)`, "price");
  if (c.type === "economy") addParam(s, `${rel}.cost.amount`, "num", cap("economyCost"), c.amount, `${what} price (money, Vault)`, "price");
}
function actionParams(s: ParamSink, rel: string, list: MenuAction[] | undefined, what: string) {
  (list ?? []).forEach((a, k) => {
    const r = `${rel}.a${k}`;
    switch (a.type) {
      case "give_item": addParam(s, `${r}.count`, "int", cap("giveCount"), a.count ?? DEFAULTS.giveCount, `${what} gives ${a.item.replace(/^minecraft:/, "")} (count)`, "count"); break;
      case "send_message": case "actionbar": addParam(s, `${r}.text`, "text", [0, 120], a.text, `${what} ${a.type === "actionbar" ? "actionbar" : "message"} text`, "text"); break;
      case "play_sound": addParam(s, `${r}.sound`, "sound", [0, 100], a.sound, `${what} sound key`, "sound"); addParam(s, `${r}.volume`, "num", cap("volume"), a.volume ?? DEFAULTS.volume, `${what} sound volume`, "other"); addParam(s, `${r}.pitch`, "num", cap("pitch"), a.pitch ?? DEFAULTS.pitch, `${what} sound pitch`, "other"); break;
      case "potion_effect": addParam(s, `${r}.duration_ticks`, "ticks", cap("potionTicks"), a.durationTicks, `${what} ${a.effect} duration (ticks)`, "duration"); addParam(s, `${r}.amplifier`, "int", cap("amplifier"), a.amplifier ?? DEFAULTS.amplifier, `${what} ${a.effect} level - 1`, "level"); break;
      case "heal": addParam(s, `${r}.amount`, "num", cap("heal"), a.amount, `${what} heal (health points)`, "heal"); break;
      default: break;
    }
  });
}
/** Node id of each clickable: buttons by slot (b<slot>), fixed list entries e<i>, dialogue choices c<i>. */
export function clickNode(path: string, slot?: number): string {
  if (slot !== undefined) return `b${slot}`;
  const m = /\[(\d+)\]$/.exec(path);
  return path.startsWith("choices") ? `c${m![1]}` : `e${m![1]}`;
}

export function menuParams(m: MenuDesign): Param[] {
  const s = sinkFor(`menus.${m.id}.`, m.id);
  addParam(s, "title", "text", [0, 32], m.title, "menu title", "text");
  if (m.style === "dialogue") {
    addParam(s, "speaker", "text", [0, 60], m.speaker.text, "speaker name", "text");
    m.lines.forEach((l, i) => addParam(s, `line${i}`, "text", [0, 80], l, `dialogue line ${i + 1}`, "text"));
    if (m.speakerIcon) iconParams(s, "speaker_icon", m.speakerIcon, "speaker icon");
  }
  for (const { path, c, slot } of menuClickables(m)) {
    const node = clickNode(path, slot);
    const what = slot !== undefined ? `slot ${slot}` : path.startsWith("choices") ? `choice ${node.slice(1)}` : `entry ${node.slice(1)}`;
    iconParams(s, node, c.icon, what);
    costParams(s, node, c.cost, what);
    actionParams(s, node, c.actions, what);
  }
  if (m.style === "chest" && m.list) { iconParams(s, "prev", m.list.prev.icon, "previous page button"); iconParams(s, "next", m.list.next.icon, "next page button"); }
  return own(s, "menu");
}

function objectiveParams(s: ParamSink, rel: string, o: Objective, what: string) {
  switch (o.type) {
    case "kill_entity": addParam(s, `${rel}.count`, "int", cap("killCount"), o.count, `${what}: kills needed`, "count"); break;
    case "collect_item": addParam(s, `${rel}.count`, "int", cap("collectCount"), o.count, `${what}: ${o.item.replace(/^minecraft:/, "")} needed`, "count"); break;
    case "craft_item": addParam(s, `${rel}.count`, "int", cap("craftCount"), o.count, `${what}: crafts needed`, "count"); break;
