// node:crypto). The editor applies a value edit locally for instant feedback with `setParamValue`; the server then
// re-validates and re-compiles the whole mod (./analyze.ts) and is the only judge of what is valid. The path rules are
// a port of ../params.ts setInDesign and ../gameplay/params.ts setInMenu / setInQuest; test/cyrus-designer-studio.test.ts
// checks this port agrees with applyParameterEdits / applyGameplayEdits for every parameter of the fixtures.
import type { Ability, Action, Condition, ItemDesign } from "../spec";
import type { MenuDesign, QuestDesign } from "../gameplay/spec";

export type DesignFile = ItemDesign | MenuDesign | QuestDesign | (Record<string, unknown> & { id: string; kind: string });
export type FileKind = "item" | "menu" | "quest" | "motion" | "other";
type Obj = Record<string, unknown>;

export const fileKind = (d: unknown): FileKind => {
  if (!d || typeof d !== "object" || Array.isArray(d)) return "other";
  const k = (d as { kind?: unknown }).kind;
  return k === undefined || k === "item" ? "item" : k === "menu" || k === "quest" || k === "motion" ? k : "other";
};
export const isItem = (d: unknown): d is ItemDesign => fileKind(d) === "item";
export const isMenu = (d: unknown): d is MenuDesign => fileKind(d) === "menu";
export const isQuest = (d: unknown): d is QuestDesign => fileKind(d) === "quest";

export const camelKey = (s: string) => s.replace(/_([a-z])/g, (_, c: string) => c.toUpperCase());
export const snakeKey = (s: string) => s.replace(/[A-Z]/g, (m) => `_${m.toLowerCase()}`);
const clone = <T,>(x: T): T => JSON.parse(JSON.stringify(x)) as T;

/** Navigate a relative ability path ("a0.n1", "a2.then0", "c1", "a3.if0") to its node (the port of params.ts nodeAt). */
export function nodeAt(ab: Obj, rel: string[]): Obj | null {
  let cur: Obj | null = null;
  for (let i = 0; i < rel.length; i++) {
    const m = /^(a|n|then|else|c|if)(\d+)$/.exec(rel[i]);
    if (!m) return null;
    const idx = Number(m[2]);
    const list = (m[1] === "a" ? ab.actions : m[1] === "c" ? ab.conditions : m[1] === "n" ? cur?.actions : m[1] === "then" ? cur?.then : m[1] === "else" ? cur?.else : cur?.if) as unknown[] | undefined;
    if ((m[1] === "a" || m[1] === "c") && i !== 0) return null;
    if (!Array.isArray(list) || !list[idx] || typeof list[idx] !== "object") return null;
    cur = list[idx] as Obj;
  }
  return cur;
}

function setInItem(d: Obj, rest: string[], value: number | string): string | null {
  if (rest[0] === "abilities") {
    const ab = (d.abilities as Obj[]).find((a) => a.id === rest[1]);
    if (!ab) return `no ability ${rest[1]}`;
    const tail = rest.slice(2);
    if (tail.length === 1 && tail[0] === "cooldown_ticks") { ab.cooldownTicks = value; return null; }
    if (tail[0] === "charges" && tail.length === 2) { const c = ab.charges as Obj | undefined; if (!c) return "no charges"; c[camelKey(tail[1])] = value; return null; }
    if (tail[0] === "trigger" && tail.length === 2) { (ab.trigger as Obj)[camelKey(tail[1])] = value; return null; }
    const node = nodeAt(ab, tail.slice(0, -1));
    if (!node) return `no node at ${tail.slice(0, -1).join(".")}`;
    node[camelKey(tail[tail.length - 1])] = value;
    return null;
  }
  if (rest[0] === "marks" && rest.length === 3) { const m = (d.marks as Obj[] | undefined)?.find((x) => x.name === rest[1]); if (!m) return `no mark ${rest[1]}`; m[camelKey(rest[2])] = value; return null; }
  if (rest[0] === "passives" && rest.length === 3) { const p = (d.passives as Obj[] | undefined)?.[Number(rest[1].slice(1))]; if (!p) return `no passive ${rest[1]}`; p[camelKey(rest[2])] = value; return null; }
  if ((rest[0] === "loot" || rest[0] === "drops") && rest.length === 3) { const l = ((d.acquisition as Record<string, Obj[]> | undefined)?.[rest[0]])?.[Number(rest[1].slice(1))]; if (!l) return `no ${rest[0]} ${rest[1]}`; l[camelKey(rest[2])] = value; return null; }
  return `${rest.join(".")} is not a designer parameter`;
}

function iconSet(icon: Obj | undefined, field: string, value: number | string): string | null {
  if (!icon) return "no icon";
  if (field === "name") { if (!icon.name) return "no name"; (icon.name as Obj).text = value; return null; }
  if (field === "amount") { icon.amount = value; return null; }
  const l = /^lore(\d+)$/.exec(field);
  if (l) { const line = (icon.lore as Obj[] | undefined)?.[Number(l[1])]; if (!line) return "no lore line"; line.text = value; return null; }
  return `unknown icon field ${field}`;
}
function clickSet(c: Obj, rest: string[], value: number | string): string | null {
  if (rest.length === 1) return iconSet(c.icon as Obj, rest[0], value);
  if (rest[0] === "cost" && rest.length === 2) { const cost = c.cost as Obj | undefined; if (!cost) return "no cost"; cost[rest[1]] = value; return null; }
  const a = /^a(\d+)$/.exec(rest[0]);
  if (a && rest.length === 2) { const act = (c.actions as Obj[] | undefined)?.[Number(a[1])]; if (!act) return `no action ${rest[0]}`; act[camelKey(rest[1])] = value; return null; }
  return `unknown path ${rest.join(".")}`;
}
function setInMenu(m: Obj, rest: string[], value: number | string): string | null {
  const [head, ...tail] = rest;
  if (head === "title" && !tail.length) { m.title = value; return null; }
  if (head === "speaker" && !tail.length) { (m.speaker as Obj).text = value; return null; }
  const line = /^line(\d+)$/.exec(head);
  if (line && !tail.length) { const lines = m.lines as string[]; if (Number(line[1]) >= lines.length) return "no line"; lines[Number(line[1])] = String(value); return null; }
  if (head === "speaker_icon") return iconSet(m.speakerIcon as Obj, tail[0], value);
  if (head === "prev" || head === "next") return iconSet(((m.list as Obj | undefined)?.[head] as Obj | undefined)?.icon as Obj, tail[0], value);
  const b = /^b(\d+)$/.exec(head), e = /^e(\d+)$/.exec(head), c = /^c(\d+)$/.exec(head);
  const node = b ? (m.buttons as Obj[] | undefined)?.find((x) => x.slot === Number(b[1])) : e ? (((m.list as Obj | undefined)?.source as Obj | undefined)?.entries as Obj[] | undefined)?.[Number(e[1])] : c ? (m.choices as Obj[] | undefined)?.[Number(c[1])] : undefined;
  if (!node) return `no clickable ${head}`;
  return clickSet(node, tail, value);
}
function setInQuest(q: Obj, rest: string[], value: number | string): string | null {
  const [head, ...tail] = rest;
  if ((head === "title" || head === "description") && !tail.length) { q[head] = value; return null; }
  if (head === "icon") return iconSet(q.icon as Obj, tail[0], value);
  if (head === "repeat" && tail[0] === "cooldown_seconds") { (q.repeat as Obj).cooldownSeconds = value; return null; }
  if (head === "failure" && tail[0] === "time_limit_seconds") { (q.failure as Obj).timeLimitSeconds = value; return null; }
  const steps = () => [...(q.steps as Obj[]), ...(((q.branches as Obj | undefined)?.options as Obj[] | undefined) ?? []).flatMap((x) => x.steps as Obj[])];
  const rewardSet = (list: Obj[] | undefined, r: string, field: string) => { const m = /^r(\d+)$/.exec(r); const x = m ? list?.[Number(m[1])] : undefined; if (!x) return `no reward ${r}`; x[camelKey(field)] = value; return null; };
  if (head === "steps") {
    const st = steps().find((s) => s.id === tail[0]);
    if (!st) return `no step ${tail[0]}`;
    if (tail[1] === "text" && tail.length === 2) { st.text = value; return null; }
    const o = /^o(\d+)$/.exec(tail[1] ?? "");
    const obj = o ? (st.objectives as Obj[])[Number(o[1])] : undefined;
    if (!obj || tail.length !== 3) return `no objective ${tail.slice(1).join(".")}`;
    obj[tail[2]] = value;
    return null;
  }
  if (head === "branches") {
    const br = q.branches as Obj | undefined;
    if (!br) return "no branches";
    if (tail[0] === "prompt" && tail.length === 1) { br.prompt = value; return null; }
    const b = (br.options as Obj[]).find((x) => x.id === tail[0]);
    if (!b) return `no branch ${tail[0]}`;
    if (tail[1] === "label" && tail.length === 2) { (b.label as Obj).text = value; return null; }
    if (tail[1] === "rewards" && tail.length === 4) return rewardSet(b.rewards as Obj[] | undefined, tail[2], tail[3]);
    return `unknown branch path ${tail.join(".")}`;
  }
  if (head === "rewards" && tail.length === 2) return rewardSet(q.rewards as Obj[] | undefined, tail[0], tail[1]);
  return `unknown quest path ${rest.join(".")}`;
}

/**
 * Set one config.yml parameter (exact path: items.<id>..., menus.<id>..., quests.<id>...) in a COPY of the mod's design
 * files. Returns the new list or an error. Caps are not checked here: the server's check shows the validator's own codes.
 */
export function setParamValue(files: readonly DesignFile[], path: string, value: number | string): { ok: true; files: DesignFile[] } | { ok: false; error: string } {
  const parts = path.split(".");
  const kind = parts[0] === "items" ? "item" : parts[0] === "menus" ? "menu" : parts[0] === "quests" ? "quest" : null;
  if (!kind) return { ok: false, error: `${path} is not a designer parameter` };
  const i = files.findIndex((f) => f.id === parts[1] && fileKind(f) === kind);
  if (i < 0) return { ok: false, error: `no ${kind} ${parts[1]}` };
  const copy = clone(files[i]) as unknown as Obj;
  const err = kind === "item" ? setInItem(copy, parts.slice(2), value) : kind === "menu" ? setInMenu(copy, parts.slice(2), value) : setInQuest(copy, parts.slice(2), value);
  if (err) return { ok: false, error: err };
  const out = [...files];
  out[i] = copy as unknown as DesignFile;
  return { ok: true, files: out };
}

/** The config path of a graph node's field ("items.void_reaper.abilities.void_pull.a0.n1.count"). */
export const nodeParamPath = (item: string, ability: string, node: string, field: string) =>
  node === "trigger" ? `items.${item}.abilities.${ability}.trigger.${snakeKey(field)}` : node === "ability" ? `items.${item}.abilities.${ability}.${snakeKey(field)}` : `items.${item}.abilities.${ability}.${node}.${snakeKey(field)}`;

// ---------------------------------------------------------------------------------------------- structural edits
/** The children lists a container action has (query/delayed: n, branch: then/else). */
export const childLists = (a: Action): { key: "actions" | "then" | "else"; seg: "n" | "then" | "else"; list: Action[] }[] =>
  a.type === "query_marked" || a.type === "query_nearby" || a.type === "delayed" ? [{ key: "actions", seg: "n", list: a.actions }]
    : a.type === "branch" ? [{ key: "then", seg: "then", list: a.then }, ...(a.else ? [{ key: "else" as const, seg: "else" as const, list: a.else }] : [])] : [];

/** A list inside an ability addressed by a container path ("" = the top list, "a0" = a0's children, "a2.then" / "a2.else"). */
function listAt(ab: Ability, container: string): Action[] | null {
  if (!container) return ab.actions;
  const segs = container.split(".");
  const last = segs[segs.length - 1];
  const which = last === "then" || last === "else" ? last : "n";
  const nodeSegs = which === "n" ? segs : segs.slice(0, -1);
  const node = nodeAt(ab as unknown as Obj, nodeSegs) as unknown as Action | null;
  if (!node) return null;
  if (which === "n") return node.type === "query_marked" || node.type === "query_nearby" || node.type === "delayed" ? node.actions : null;
  if (node.type !== "branch") return null;
  if (which === "then") return node.then;
  node.else ??= [];
  return node.else;
}

/** Sensible starting values for a new action (the user then edits them; the server validates). */
export const ACTION_TEMPLATES: Record<string, (ctx: { marks: string[]; sound?: string }) => Action> = {
  spawn_particles: () => ({ type: "spawn_particles", particle: "end_rod", count: 8, spread: 0.3, at: "self" }),
  play_sound: (c) => ({ type: "play_sound", sound: c.sound ?? "minecraft:entity.experience_orb.pickup", volume: 1, pitch: 1, at: "self" }),
  send_message: () => ({ type: "send_message", text: "Done.", to: "self" }),
  actionbar: () => ({ type: "actionbar", text: "Ready." }),
  heal: () => ({ type: "heal", amount: 4, target: "self" }),
  damage: () => ({ type: "damage", amount: 4, target: "target" }),
  potion_effect: () => ({ type: "potion_effect", effect: "speed", durationTicks: 100, amplifier: 0, target: "self" }),
  knockback: () => ({ type: "knockback", strength: 1, vertical: 0.35, target: "target" }),
  teleport_short: () => ({ type: "teleport_short", range: 6 }),
  apply_mark: (c) => ({ type: "apply_mark", mark: c.marks[0] ?? "mark" }),
  delayed: () => ({ type: "delayed", delayTicks: 20, actions: [{ type: "actionbar", text: "Later." }] }),
};
export const CONDITION_TEMPLATES: Record<string, () => Condition> = {
  sneaking: () => ({ type: "sneaking" }),
  random_chance: () => ({ type: "random_chance", chance: 0.5 }),
  health_below: () => ({ type: "health_below", subject: "self", fraction: 0.5 }),
  target_is: () => ({ type: "target_is", kinds: ["hostile"] }),
  time_of_day: () => ({ type: "time_of_day", from: 13000, to: 23000 }),
};

/** Insert an action into an ability's list (container path as in listAt). New file list or an error. */
export function insertAction(files: readonly DesignFile[], item: string, ability: string, container: string, action: Action): { ok: true; files: DesignFile[]; path: string } | { ok: false; error: string } {
  const i = files.findIndex((f) => f.id === item && isItem(f));
  if (i < 0) return { ok: false, error: `no item ${item}` };
  const d = clone(files[i]) as ItemDesign;
  const ab = d.abilities.find((a) => a.id === ability);
  if (!ab) return { ok: false, error: `no ability ${ability}` };
  const list = listAt(ab, container);
  if (!list) return { ok: false, error: `${container} holds no actions` };
  list.push(action);
  const out = [...files]; out[i] = d;
  const idx = list.length - 1;
  const path = !container ? `a${idx}` : container.endsWith(".then") || container.endsWith(".else") ? `${container}${idx}` : `${container}.n${idx}`;
  return { ok: true, files: out, path };
}

/** Remove the node at an ability path ("a1", "a0.n1", "a2.then0", "c0"). */
export function removeNode(files: readonly DesignFile[], item: string, ability: string, path: string): { ok: true; files: DesignFile[] } | { ok: false; error: string } {
  const i = files.findIndex((f) => f.id === item && isItem(f));
  if (i < 0) return { ok: false, error: `no item ${item}` };
  const d = clone(files[i]) as ItemDesign;
  const ab = d.abilities.find((a) => a.id === ability);
  if (!ab) return { ok: false, error: `no ability ${ability}` };
  const segs = path.split(".");
  const last = /^(a|n|then|else|c)(\d+)$/.exec(segs[segs.length - 1]);
  if (!last) return { ok: false, error: `bad path ${path}` };
  const idx = Number(last[2]);
  if (last[1] === "c") { if (segs.length !== 1 || !ab.conditions?.[idx]) return { ok: false, error: "no such condition" }; ab.conditions.splice(idx, 1); if (!ab.conditions.length) delete ab.conditions; }
  else if (last[1] === "a") { if (segs.length !== 1 || !ab.actions[idx]) return { ok: false, error: "no such action" }; ab.actions.splice(idx, 1); }
  else {
    const parent = nodeAt(ab as unknown as Obj, segs.slice(0, -1)) as unknown as Action | null;
    const list = !parent ? null : last[1] === "n" ? ("actions" in parent ? (parent as { actions: Action[] }).actions : null) : parent.type === "branch" ? (last[1] === "then" ? parent.then : parent.else ?? null) : null;
    if (!list || !list[idx]) return { ok: false, error: "no such action" };
    list.splice(idx, 1);
  }
  const out = [...files]; out[i] = d;
  return { ok: true, files: out };
}

/** Add a condition to an ability's "Only if" list. */
export function insertCondition(files: readonly DesignFile[], item: string, ability: string, c: Condition): { ok: true; files: DesignFile[] } | { ok: false; error: string } {
  const i = files.findIndex((f) => f.id === item && isItem(f));
  if (i < 0) return { ok: false, error: `no item ${item}` };
  const d = clone(files[i]) as ItemDesign;
  const ab = d.abilities.find((a) => a.id === ability);
  if (!ab) return { ok: false, error: `no ability ${ability}` };
  (ab.conditions ??= []).push(c);
  const out = [...files]; out[i] = d;
  return { ok: true, files: out };
}

/** Replace one design file by id (the JSON view). The server decides whether it is valid. */
export function replaceFile(files: readonly DesignFile[], id: string, next: unknown): { ok: true; files: DesignFile[] } | { ok: false; error: string } {
  if (!next || typeof next !== "object" || Array.isArray(next)) return { ok: false, error: "a design file is a JSON object" };
  if ((next as { id?: unknown }).id !== id) return { ok: false, error: `the id must stay "${id}" (renaming is a structural change for a build)` };
  const i = files.findIndex((f) => f.id === id);
  if (i < 0) return { ok: false, error: `no design ${id}` };
  const out = [...files]; out[i] = next as DesignFile;
  return { ok: true, files: out };
}

/** Stable comparison of two design lists (key order insensitive). */
export function canonical(x: unknown): string {
  if (Array.isArray(x)) return `[${x.map(canonical).join(",")}]`;
  if (x && typeof x === "object") return `{${Object.keys(x as Obj).sort().map((k) => `${JSON.stringify(k)}:${canonical((x as Obj)[k])}`).join(",")}}`;
  return JSON.stringify(x);
}
export const changedIds = (a: readonly DesignFile[], b: readonly DesignFile[]): string[] => {
  const am = new Map(a.map((f) => [f.id, canonical(f)]));
  return b.filter((f) => am.get(f.id) !== canonical(f)).map((f) => f.id);
};

