/**
 * Set one config.yml parameter (exact path: items.<id>..., menus.<id>..., quests.<id>...) in a COPY of the mod's design
 * files. Returns the new list or an error. Caps are not checked here: the server's check shows the validator's own codes.
 */
export function setParamValue(files: readonly DesignFile[], path: string, value: number | string): { ok: true; files: DesignFile[] } | { ok: false; error: string } {
  const parts = path.split(".");
  const kind = parts[0] === "items" ? "item" : parts[0] === "menus" ? "menu" : parts[0] === "quests" ? "quest" : null;
  if (!kind) return { ok: false, error: `${path} is not a designer parameter` };
  const i = files.findIndex((f) => f.id === parts[1] && fileKind(f) === kind);
  if (i < 0) return { ok: false, error: `no ${kind} ${parts[1]}` };
  const copy = clone(files[i]) as unknown as Obj;
  const err = kind === "item" ? setInItem(copy, parts.slice(2), value) : kind === "menu" ? setInMenu(copy, parts.slice(2), value) : setInQuest(copy, parts.slice(2), value);
  if (err) return { ok: false, error: err };
  const out = [...files];
  out[i] = copy as unknown as DesignFile;
  return { ok: true, files: out };
}

/** The config path of a graph node's field ("items.void_reaper.abilities.void_pull.a0.n1.count"). */
export const nodeParamPath = (item: string, ability: string, node: string, field: string) =>
  node === "trigger" ? `items.${item}.abilities.${ability}.trigger.${snakeKey(field)}` : node === "ability" ? `items.${item}.abilities.${ability}.${snakeKey(field)}` : `items.${item}.abilities.${ability}.${node}.${snakeKey(field)}`;

// ---------------------------------------------------------------------------------------------- structural edits
/** The children lists a container action has (query/delayed: n, branch: then/else). */
export const childLists = (a: Action): { key: "actions" | "then" | "else"; seg: "n" | "then" | "else"; list: Action[] }[] =>
  a.type === "query_marked" || a.type === "query_nearby" || a.type === "delayed" ? [{ key: "actions", seg: "n", list: a.actions }]
    : a.type === "branch" ? [{ key: "then", seg: "then", list: a.then }, ...(a.else ? [{ key: "else" as const, seg: "else" as const, list: a.else }] : [])] : [];

/** A list inside an ability addressed by a container path ("" = the top list, "a0" = a0's children, "a2.then" / "a2.else"). */
function listAt(ab: Ability, container: string): Action[] | null {
  if (!container) return ab.actions;
  const segs = container.split(".");
  const last = segs[segs.length - 1];
  const which = last === "then" || last === "else" ? last : "n";
  const nodeSegs = which === "n" ? segs : segs.slice(0, -1);
  const node = nodeAt(ab as unknown as Obj, nodeSegs) as unknown as Action | null;
  if (!node) return null;
  if (which === "n") return node.type === "query_marked" || node.type === "query_nearby" || node.type === "delayed" ? node.actions : null;
  if (node.type !== "branch") return null;
  if (which === "then") return node.then;
  node.else ??= [];
  return node.else;
}

/** Sensible starting values for a new action (the user then edits them; the server validates). */
export const ACTION_TEMPLATES: Record<string, (ctx: { marks: string[]; sound?: string }) => Action> = {
  spawn_particles: () => ({ type: "spawn_particles", particle: "end_rod", count: 8, spread: 0.3, at: "self" }),
  play_sound: (c) => ({ type: "play_sound", sound: c.sound ?? "minecraft:entity.experience_orb.pickup", volume: 1, pitch: 1, at: "self" }),
  send_message: () => ({ type: "send_message", text: "Done.", to: "self" }),
  actionbar: () => ({ type: "actionbar", text: "Ready." }),
  heal: () => ({ type: "heal", amount: 4, target: "self" }),
  damage: () => ({ type: "damage", amount: 4, target: "target" }),
  potion_effect: () => ({ type: "potion_effect", effect: "speed", durationTicks: 100, amplifier: 0, target: "self" }),
  knockback: () => ({ type: "knockback", strength: 1, vertical: 0.35, target: "target" }),
  teleport_short: () => ({ type: "teleport_short", range: 6 }),
  apply_mark: (c) => ({ type: "apply_mark", mark: c.marks[0] ?? "mark" }),
  delayed: () => ({ type: "delayed", delayTicks: 20, actions: [{ type: "actionbar", text: "Later." }] }),
};
export const CONDITION_TEMPLATES: Record<string, () => Condition> = {
  sneaking: () => ({ type: "sneaking" }),
  random_chance: () => ({ type: "random_chance", chance: 0.5 }),
  health_below: () => ({ type: "health_below", subject: "self", fraction: 0.5 }),
  target_is: () => ({ type: "target_is", kinds: ["hostile"] }),
  time_of_day: () => ({ type: "time_of_day", from: 13000, to: 23000 }),
};

/** Insert an action into an ability's list (container path as in listAt). New file list or an error. */
export function insertAction(files: readonly DesignFile[], item: string, ability: string, container: string, action: Action): { ok: true; files: DesignFile[]; path: string } | { ok: false; error: string } {
  const i = files.findIndex((f) => f.id === item && isItem(f));
  if (i < 0) return { ok: false, error: `no item ${item}` };
  const d = clone(files[i]) as ItemDesign;
  const ab = d.abilities.find((a) => a.id === ability);
  if (!ab) return { ok: false, error: `no ability ${ability}` };
  const list = listAt(ab, container);
  if (!list) return { ok: false, error: `${container} holds no actions` };
  list.push(action);
  const out = [...files]; out[i] = d;
  const idx = list.length - 1;
  const path = !container ? `a${idx}` : container.endsWith(".then") || container.endsWith(".else") ? `${container}${idx}` : `${container}.n${idx}`;
  return { ok: true, files: out, path };
}

/** Remove the node at an ability path ("a1", "a0.n1", "a2.then0", "c0"). */
export function removeNode(files: readonly DesignFile[], item: string, ability: string, path: string): { ok: true; files: DesignFile[] } | { ok: false; error: string } {
  const i = files.findIndex((f) => f.id === item && isItem(f));
  if (i < 0) return { ok: false, error: `no item ${item}` };
  const d = clone(files[i]) as ItemDesign;
  const ab = d.abilities.find((a) => a.id === ability);
  if (!ab) return { ok: false, error: `no ability ${ability}` };
  const segs = path.split(".");
  const last = /^(a|n|then|else|c)(\d+)$/.exec(segs[segs.length - 1]);
  if (!last) return { ok: false, error: `bad path ${path}` };
  const idx = Number(last[2]);
  if (last[1] === "c") { if (segs.length !== 1 || !ab.conditions?.[idx]) return { ok: false, error: "no such condition" }; ab.conditions.splice(idx, 1); if (!ab.conditions.length) delete ab.conditions; }
  else if (last[1] === "a") { if (segs.length !== 1 || !ab.actions[idx]) return { ok: false, error: "no such action" }; ab.actions.splice(idx, 1); }
  else {
    const parent = nodeAt(ab as unknown as Obj, segs.slice(0, -1)) as unknown as Action | null;
    const list = !parent ? null : last[1] === "n" ? ("actions" in parent ? (parent as { actions: Action[] }).actions : null) : parent.type === "branch" ? (last[1] === "then" ? parent.then : parent.else ?? null) : null;
    if (!list || !list[idx]) return { ok: false, error: "no such action" };
    list.splice(idx, 1);
  }
  const out = [...files]; out[i] = d;
  return { ok: true, files: out };
}

/** Add a condition to an ability's "Only if" list. */
export function insertCondition(files: readonly DesignFile[], item: string, ability: string, c: Condition): { ok: true; files: DesignFile[] } | { ok: false; error: string } {
  const i = files.findIndex((f) => f.id === item && isItem(f));
  if (i < 0) return { ok: false, error: `no item ${item}` };
  const d = clone(files[i]) as ItemDesign;
  const ab = d.abilities.find((a) => a.id === ability);
  if (!ab) return { ok: false, error: `no ability ${ability}` };
  (ab.conditions ??= []).push(c);
  const out = [...files]; out[i] = d;
  return { ok: true, files: out };
}

/** Replace one design file by id (the JSON view). The server decides whether it is valid. */
export function replaceFile(files: readonly DesignFile[], id: string, next: unknown): { ok: true; files: DesignFile[] } | { ok: false; error: string } {
  if (!next || typeof next !== "object" || Array.isArray(next)) return { ok: false, error: "a design file is a JSON object" };
  if ((next as { id?: unknown }).id !== id) return { ok: false, error: `the id must stay "${id}" (renaming is a structural change for a build)` };
  const i = files.findIndex((f) => f.id === id);
  if (i < 0) return { ok: false, error: `no design ${id}` };
  const out = [...files]; out[i] = next as DesignFile;
  return { ok: true, files: out };
}

/** Stable comparison of two design lists (key order insensitive). */
export function canonical(x: unknown): string {
  if (Array.isArray(x)) return `[${x.map(canonical).join(",")}]`;
  if (x && typeof x === "object") return `{${Object.keys(x as Obj).sort().map((k) => `${JSON.stringify(k)}:${canonical((x as Obj)[k])}`).join(",")}}`;
  return JSON.stringify(x);
}
export const changedIds = (a: readonly DesignFile[], b: readonly DesignFile[]): string[] => {
  const am = new Map(a.map((f) => [f.id, canonical(f)]));
  return b.filter((f) => am.get(f.id) !== canonical(f)).map((f) => f.id);
};

