// Cyrus designer studio UI: the server-side ANALYSIS of a mod's design files (the saved ones or the editor's working
// copy). Pure: no I/O, no model call. It runs the real validators (validateGameplay -> the item validator, the menu /
// quest / boss / encounter / HUD / motion validators and the cross-file checks), the static per-activation budgets
// (budgetOf), the config.yml parameters (modParams) and compiles the whole mod with the TypeScript compiler, so the UI
// can say exactly what an edit changes: "config.yml only" (values) or which Java files a structural edit rebuilds.
import { BUDGET, DESIGN_CHECKS, DESIGN_LIMITS, budgetOf, type DzCheck, type ItemDesign } from "../spec";
import { GAMEPLAY_LIMITS, validateGameplay, type GameplayValidation, type GpContext, type GpIssue } from "../gameplay/spec";
import { compileMod, modParams } from "../gameplay/compile";
import { diffCompiled } from "../params";
import type { Param } from "../compile";
import { fileKind, type DesignFile, type FileKind } from "./edit";

export type StudioCtx = { version: string; namespace: string; pluginName: string; assets?: GpContext["assets"]; configVersion?: number };
export type FileReport = { id: string; kind: FileKind; ok: boolean; errors: GpIssue[]; warnings: GpIssue[] };
export type AbilityBudgetView = { item: string; ability: string; actions: number; entities: number; tasks: number; particles: number; projectiles: number; nodes: number; depth: number };
export type CheckRow = { id: string; status: "pass" | "warn" | "fail" | "not_run"; items: string[] };
export type CompileSummary =
  | { ok: true; hash: string; configVersion: number; files: number; java: number; command: string; mainClass: string; javacVerified: boolean; configYml: string }
  | { ok: false; errors: GpIssue[] };
export type DiffSummary = { configOnly: boolean; javaChanged: string[]; changed: { path: string; status: string }[]; unchanged: number; configVersion: { from: number; to: number }; readmeChanged: boolean };
export type Analysis = {
  ok: boolean;
  /** the validators could run the cross-file checks (namespace + version known) */
  ranCross: boolean;
  files: FileReport[];
  /** mod-level errors that name no file */
  modErrors: GpIssue[];
  budgets: AbilityBudgetView[];
  /** the item validator's own check rows (DESIGN_CHECKS) per item id */
  itemChecks: Record<string, CheckRow[]>;
  /** gameplay check rows per kind: pass / warn / fail by validator code (codes listed in GAMEPLAY_ROWS) */
  gameplayChecks: { menu: CheckRow[]; quest: CheckRow[]; boss: CheckRow[] };
  params: Param[];
  progressChars: number;
  compile: CompileSummary;
  diff: DiffSummary | null;
};

export const STUDIO_LIMITS = {
  budget: BUDGET, maxNodes: DESIGN_LIMITS.maxNodes, maxDepth: DESIGN_LIMITS.maxDepth, maxActions: DESIGN_LIMITS.maxActions, maxConditions: DESIGN_LIMITS.maxConditions,
  maxAbilities: DESIGN_LIMITS.maxAbilities, maxItems: DESIGN_LIMITS.maxItems, maxMarks: DESIGN_LIMITS.maxMarks,
  maxMenus: GAMEPLAY_LIMITS.maxMenus, maxQuests: GAMEPLAY_LIMITS.maxQuests, maxProgressChars: GAMEPLAY_LIMITS.maxProgressChars, activeQuests: GAMEPLAY_LIMITS.activeQuests,
  maxClickActions: GAMEPLAY_LIMITS.maxClickActions, maxRewards: GAMEPLAY_LIMITS.maxRewards, maxSteps: GAMEPLAY_LIMITS.maxSteps, maxBranches: GAMEPLAY_LIMITS.maxBranches,
  maxConfigEntries: GAMEPLAY_LIMITS.maxConfigEntries,
} as const;
export type StudioLimits = typeof STUDIO_LIMITS;

/** The validator codes each designer lists as rows (a code with no issue = pass, only when the checks ran). */
export const GAMEPLAY_ROWS = {
  menu: ["slot_overlap", "slot_outside", "unreachable_menu", "undeclared_permission", "cost_loop", "arbitrage_loop", "economy_needs_vault"],
  quest: ["circular_prerequisites", "unreachable_quest", "unreachable_dialogue", "reward_farm", "progress_oversize"],
  boss: ["unresolved_ref", "undeclared_permission", "foreign_namespace"],
} as const;

const safe = <T,>(f: () => T, fb: T): T => { try { return f(); } catch { return fb; } };

function budgetsOf(files: readonly DesignFile[]): AbilityBudgetView[] {
  const out: AbilityBudgetView[] = [];
  for (const f of files) {
    if (fileKind(f) !== "item") continue;
    const d = f as ItemDesign;
    for (const ab of Array.isArray(d.abilities) ? d.abilities : []) {
      const b = safe(() => budgetOf(Array.isArray(ab.actions) ? ab.actions : []), null);
      if (!b) continue;
      out.push({ item: d.id, ability: ab.id, actions: b.actions, entities: b.entities, tasks: b.tasks, particles: Number.isFinite(b.particles) ? b.particles : 0, projectiles: b.projectiles, nodes: b.nodes + (ab.conditions?.length ?? 0), depth: b.depth });
    }
  }
  return out;
}

function rowsFor(kind: keyof typeof GAMEPLAY_ROWS, v: GameplayValidation, ran: boolean): CheckRow[] {
  const files = v.files.filter((f) => f.kind === kind);
  if (!files.length) return [];
  return GAMEPLAY_ROWS[kind].map((code) => {
    const errs = files.flatMap((f) => f.errors.filter((e) => e.code === code).map((e) => `${f.id}: ${e.path}: ${e.message}`));
    const warns = files.flatMap((f) => f.warnings.filter((e) => e.code === code).map((e) => `${f.id}: ${e.path}: ${e.message}`));
    const parsed = files.every((f) => !f.errors.some((e) => e.code === "schema"));
    return { id: code, status: errs.length ? "fail" : warns.length ? "warn" : ran && parsed ? "pass" : "not_run", items: [...errs, ...warns].slice(0, 12) };
  });
}

function compileOf(files: readonly DesignFile[], ctx: StudioCtx, previousConfig?: string) {
  return safe(() => compileMod([...files], { version: ctx.version, namespace: ctx.namespace, pluginName: ctx.pluginName, ...(previousConfig ? { previousConfig } : ctx.configVersion ? { configVersion: ctx.configVersion } : {}), ...(ctx.assets ? { assets: ctx.assets } : {}) }), { ok: false as const, errors: [{ path: "(mod)", code: "compile_error", message: "the compiler failed on this design" }], warnings: [] });
}
const CONFIG = "src/main/resources/config.yml";

/**
 * Analyse `files`; with `saved` (the stored designs) also compile those and diff: what an edit changes on disk.
 * The saved compile uses the stored config_version (ctx.configVersion); the working copy compiles on top of the saved
 * config.yml, so config_version goes up exactly when a value changed (the compiler's own rule).
 */
export function analyzeMod(files: readonly DesignFile[], ctx: StudioCtx, saved?: readonly DesignFile[]): Analysis {
  const v = validateGameplay([...files], { version: ctx.version, namespace: ctx.namespace, ...(ctx.assets ? { assets: ctx.assets } : {}) });
  const ranCross = !!v.features;
  const reports: FileReport[] = v.files.map((f, i) => ({ id: f.id, kind: fileKind(files[i]), ok: f.ok, errors: f.errors, warnings: f.warnings }));
  const itemIdx = files.map((f, i) => (fileKind(f) === "item" ? i : -1)).filter((i) => i >= 0);
  const itemChecks: Record<string, CheckRow[]> = {};
  v.itemResults.forEach((r, j) => { const id = files[itemIdx[j]]?.id; if (id) itemChecks[id] = r.checks.map((c: DzCheck) => ({ id: c.id, status: c.status, items: c.items })); });
  for (const i of itemIdx) if (!itemChecks[files[i].id]) itemChecks[files[i].id] = DESIGN_CHECKS.map((id) => ({ id, status: "not_run" as const, items: [] }));
  const items = files.filter((f) => fileKind(f) === "item") as ItemDesign[];
  const byKind = <T,>(k: FileKind) => files.filter((f) => fileKind(f) === k) as unknown as T[];
  const params = safe(() => modParams(items, byKind("menu"), byKind("quest"), byKind("boss"), byKind("encounter"), byKind("hud")), [] as Param[]);
  let compile: CompileSummary = { ok: false, errors: [] };
  let diff: DiffSummary | null = null;
  const base = saved ? compileOf(saved, ctx) : null;
  const work = compileOf(files, ctx, base && base.ok ? base.files.find((f) => f.path === CONFIG)?.content : undefined);
  if (work.ok) {
    compile = { ok: true, hash: work.hash, configVersion: work.configVersion, files: work.files.length, java: work.files.filter((f) => f.path.endsWith(".java")).length, command: work.command, mainClass: work.mainClass, javacVerified: work.javacVerified, configYml: work.files.find((f) => f.path === CONFIG)?.content ?? "" };
    if (base && base.ok) {
      const d = diffCompiled(base, work);
      diff = { configOnly: d.javaChanged.length === 0 && d.changed.every((c) => c.path === CONFIG || !c.path.endsWith(".java")) && !d.changed.some((c) => c.path.endsWith("plugin.yml")), javaChanged: d.javaChanged, changed: d.changed.map((c) => ({ path: c.path, status: c.status })), unchanged: d.unchanged, configVersion: { from: base.configVersion, to: work.configVersion }, readmeChanged: d.readmeChanged };
    }
  } else compile = { ok: false, errors: work.errors };
  return {
    ok: v.ok, ranCross, files: reports, modErrors: v.errors.filter((e) => !e.file), budgets: budgetsOf(files), itemChecks,
    gameplayChecks: { menu: rowsFor("menu", v, ranCross), quest: rowsFor("quest", v, ranCross), boss: rowsFor("boss", v, ranCross) },
    params, progressChars: v.progressChars, compile, diff,
  };
}

