// Cyrus designer studio UI: the SIMULATOR tab, server side. The editor sends its working copy plus a short script of
// player actions; this file turns the script into events for the real reference simulators (../simulate.ts for items,
// ../gameplay/simulate.ts for menus and quests) on a fixed sample world and returns a readable log and a timeline.
// Deterministic (seeded, fixed positions), so the client re-runs the whole script after each step. Logic only: the
// simulators do not model physics, ray tracing, protection plugins or the client, and the result says so.
import { DesignSimulator, type SimEntity, type SimEvent, type SimLog, type Vec } from "../simulate";
import { GameplaySimulator, type ProgressEntry } from "../gameplay/simulate";
import { questSteps, type MenuDesign, type QuestDesign } from "../gameplay/spec";
import type { ItemDesign, TriggerType } from "../spec";
import { fileKind, type DesignFile } from "./edit";

// ------------------------------------------------------------------------------------------------------ items
export type ItemStep =
  | { k: "hit"; who: "hostile" | "animal" } | { k: "kill" } | { k: "click" } | { k: "sneak_click" }
  | { k: "charge"; ticks: number } | { k: "wait"; ticks: number } | { k: "consume" } | { k: "projectile" } | { k: "join" } | { k: "die" };
export type SimButton = { label: string; step: ItemStep; icon: string };
export type TimelineBar = { lane: string; from: number; to: number; tone: "accent" | "warn" };
export type ItemSimResult = { end: number; log: { tick: number; text: string; tone: "fired" | "blocked" | "fx" | "note" }[]; bars: TimelineBar[]; dots: { tick: number; tone: "fired" | "blocked" }[]; lanes: string[]; marks: { tick: number; count: number }[]; markCap: number | null; notes: string[] };

/** The sample world: you at the origin looking +x, four hostiles and a cow at fixed distances (blocks). */
export const SAMPLE_MOBS: { id: string; type: string; kind: SimEntity["kind"]; d: number }[] = [
  { id: "zombie#1", type: "minecraft:zombie", kind: "hostile", d: 6.5 }, { id: "zombie#2", type: "minecraft:zombie", kind: "hostile", d: 9.2 },
  { id: "skeleton#1", type: "minecraft:skeleton", kind: "hostile", d: 12.8 }, { id: "husk#1", type: "minecraft:husk", kind: "hostile", d: 18.4 },
  { id: "cow#1", type: "minecraft:cow", kind: "animal", d: 4 },
];
export const MAX_SIM_STEPS = 40;

/** The buttons the Simulator offers for this item (from its triggers). */
export function itemButtons(d: ItemDesign): SimButton[] {
  const t = new Set<TriggerType>(d.abilities.map((a) => a.trigger.type));
  const out: SimButton[] = [];
  if (t.has("left_click_hit_entity")) out.push({ label: "Hit next mob", step: { k: "hit", who: "hostile" }, icon: "sword" }, { label: "Hit a cow", step: { k: "hit", who: "animal" }, icon: "sword" });
  if (t.has("kill_entity")) out.push({ label: "Kill next mob", step: { k: "kill" }, icon: "sword" });
  if (t.has("right_click")) out.push({ label: "Right-click", step: { k: "click" }, icon: "hand" });
  if (t.has("sneak_right_click")) out.push({ label: "Sneak + right-click", step: { k: "sneak_click" }, icon: "hand" });
  const ch = d.abilities.find((a) => a.trigger.type === "charge_release");
  if (ch && ch.trigger.type === "charge_release") {
    const full = Math.min(400, Math.max(ch.trigger.minChargeTicks, Math.round(ch.trigger.maxChargeTicks * 2 / 3 / 10) * 10 || ch.trigger.minChargeTicks));
    const short = Math.max(1, Math.floor(ch.trigger.minChargeTicks / 2));
    out.push({ label: `Charge ${+(full / 20).toFixed(1)} s + release`, step: { k: "charge", ticks: full }, icon: "bolt" }, { label: `Release at ${+(short / 20).toFixed(2)} s`, step: { k: "charge", ticks: short }, icon: "bolt" });
  }
  if (t.has("projectile_hit")) out.push({ label: "Projectile hits next mob", step: { k: "projectile" }, icon: "target" });
  if (t.has("item_consume")) out.push({ label: "Consume", step: { k: "consume" }, icon: "hand" });
  if (t.has("join")) out.push({ label: "Join", step: { k: "join" }, icon: "user" });
  if (t.has("death")) out.push({ label: "Die", step: { k: "die" }, icon: "heart" });
  out.push({ label: t.has("held_interval") ? "Hold +5 s" : "+2 s", step: { k: "wait", ticks: t.has("held_interval") ? 100 : 40 }, icon: "clock" });
  return out;
}

const fmt = (n: unknown) => (typeof n === "number" ? +n.toFixed(2) : String(n));
function line(l: SimLog, ns: string): { text: string; tone: ItemSimResult["log"][number]["tone"] } | null {
  const ab = l.ability.split(".").pop() ?? l.ability;
  const d = (l.detail ?? {}) as Record<string, unknown>;
  const key = (s: unknown) => String(s ?? "").replace(`${ns}:`, "");
  switch (l.kind) {
    case "fired": return { text: `${ab} fired${d.target ? ` → ${d.target}` : ""}${typeof d.charge === "number" && d.charge > 0 ? ` · charge ${fmt(d.charge)}` : ""}`, tone: "fired" };
    case "blocked": return { text: `${ab} blocked · ${String(d.by ?? "")}${d.held !== undefined ? ` (held ${d.held} ticks)` : ""}`, tone: "blocked" };
    case "feedback": return { text: `feedback “${String(d.text ?? "")}”`, tone: "blocked" };
    case "mark": return { text: `mark ${String(d.mark)} → ${l.subject}`, tone: "fx" };
    case "particles": return { text: `particles ${String(d.particle)} ×${d.count}`, tone: "fx" };
    case "sound": return { text: `sound ${key(d.key)} · vol ${fmt(d.volume)} · pitch ${fmt(d.pitch)}`, tone: "fx" };
    case "pull_to": case "push_from": case "knockback": return { text: `${l.kind} ${l.subject} · velocity ${(d.velocity as number[] | undefined)?.map(fmt).join(", ") ?? ""}`, tone: "fx" };
    case "damage": return { text: `damage ${l.subject} · ${fmt(d.amount)}`, tone: "fx" };
    case "heal": return { text: `heal ${l.subject} · ${fmt(d.amount)}`, tone: "fx" };
    case "potion": return { text: `potion ${String(d.effect)} on ${l.subject} · ${d.ticks} ticks`, tone: "fx" };
    case "actionbar": case "send_message": case "title": return { text: `${l.kind} “${String(d.text ?? "")}”`, tone: "fx" };
    case "query_marked": case "query_nearby": return { text: `${l.kind} found ${((d.found as string[]) ?? []).length ? (d.found as string[]).join(", ") : "nothing"}`, tone: "fx" };
    case "launch": return { text: `launch ${String(d.kind)} · speed ${fmt(d.speed)}`, tone: "fx" };
    case "teleport": return { text: `teleport up to ${fmt(d.range)} blocks`, tone: "fx" };
    case "give": return { text: `give ${String(d.item)} ×${d.count}`, tone: "fx" };
    case "branch": return { text: `branch took ${String(d.taken)}`, tone: "fx" };
    case "budget_exhausted": return { text: `budget exhausted at ${String(d.at ?? "")}: the rest of this activation is skipped`, tone: "blocked" };
    case "died": return { text: `${l.subject} died`, tone: "fx" };
    case "delayed_run": return { text: `delayed step runs`, tone: "fx" };
    default: return { text: `${l.kind}${l.subject ? ` ${l.subject}` : ""}`, tone: "fx" };
  }
}

export function simulateItem(files: readonly DesignFile[], itemId: string, steps: readonly ItemStep[], namespace: string): ItemSimResult {
  const items = files.filter((f) => fileKind(f) === "item") as ItemDesign[];
  const d = items.find((x) => x.id === itemId);
  if (!d) throw new Error(`no item ${itemId}`);
  const s = new DesignSimulator(items, { namespace });
  const perms = (d.permissions ?? []).map((p) => `${namespace}.${p.node}`);
  s.add({ id: "you", type: "minecraft:player", kind: "player", pos: [0, 64, 0], health: 20, maxHealth: 20, world: "world", alive: true, mainHand: d.id, inventory: [d.id], permissions: perms });
  for (const m of SAMPLE_MOBS) s.add({ id: m.id, type: m.type, kind: m.kind, pos: [m.d, 64, 0], health: 20, maxHealth: 20, world: "world", alive: true });
  const markDefs = d.marks ?? [];
  const markCount = () => markDefs.reduce((n, m) => n + s.marked("you", `${d.id}.${m.name}`, [0, 64, 0], 64, 64).length, 0);
  const marks: { tick: number; count: number }[] = [{ tick: 0, count: 0 }];
  const bars: TimelineBar[] = [];
  let t = 0, hitIdx = 0;
  const nextHostile = () => { const alive = SAMPLE_MOBS.filter((m) => m.kind === "hostile" && s.entities.get(m.id)?.alive); return alive.length ? alive[hitIdx++ % alive.length] : null; };
  const look = (): { target?: string; point: Vec } => { const m = SAMPLE_MOBS.find((x) => x.kind === "hostile" && s.entities.get(x.id)?.alive); return m ? { target: m.id, point: [m.d, 64, 0] } : { point: [12, 64, 0] }; };
  const ev = (e: SimEvent) => s.event(e);
  for (const st of steps.slice(0, MAX_SIM_STEPS)) {
    switch (st.k) {
      case "hit": { t += 14; const m = st.who === "animal" ? SAMPLE_MOBS.find((x) => x.kind === "animal")! : nextHostile(); if (m) ev({ tick: t, type: "hit", player: "you", target: m.id }); else s.notes.push("no hostile left to hit"); break; }
      case "kill": { t += 14; const m = nextHostile(); if (m) ev({ tick: t, type: "kill", player: "you", target: m.id }); break; }
      case "click": t += 10; ev({ tick: t, type: "right_click", player: "you", look: look() }); break;
      case "sneak_click": t += 10; ev({ tick: t, type: "sneak_start", player: "you" }); ev({ tick: t + 1, type: "right_click", player: "you", look: look() }); ev({ tick: t + 2, type: "sneak_stop", player: "you" }); t += 2; break;
      case "charge": {
        const held = Math.max(1, Math.min(400, Math.round(st.ticks)));
        t += 4; ev({ tick: t, type: "sneak_start", player: "you" }); bars.push({ lane: "Charge", from: t, to: t + held, tone: "accent" });
        const rel = d.abilities.find((a) => a.trigger.type === "charge_release");
        const byClick = rel?.trigger.type === "charge_release" && rel.trigger.release === "right_click";
        if (byClick) { ev({ tick: t + held, type: "right_click", player: "you", look: look() }); ev({ tick: t + held + 1, type: "sneak_stop", player: "you" }); t += held + 1; }
        else { ev({ tick: t + held, type: "sneak_stop", player: "you", look: look() }); t += held; }
        break;
      }
      case "wait": t += Math.max(1, Math.min(2400, Math.round(st.ticks))); ev({ tick: t, type: "advance" }); s.log.push({ tick: t, ability: "-", kind: "waited", detail: { ticks: st.ticks } }); break;
      case "consume": t += 32; ev({ tick: t, type: "consume", player: "you" }); break;
      case "projectile": { t += 6; const tag = d.abilities.find((a) => a.trigger.type === "projectile_hit")?.trigger; const m = nextHostile(); if (tag?.type === "projectile_hit") ev({ tick: t, type: "projectile_hit", player: "you", tag: tag.tag, item: d.id, target: m?.id, point: m ? [m.d, 64, 0] : [12, 64, 0] }); break; }
      case "join": t += 10; ev({ tick: t, type: "join", player: "you" }); break;
      case "die": t += 10; ev({ tick: t, type: "death", player: "you" }); break;
    }
    marks.push({ tick: t, count: markCount() });
  }
  // cooldown bars from the fired log + the ability's cooldown parameter as the simulator read it
  for (const l of s.log) {
    if (l.kind !== "fired") continue;
    const ab = d.abilities.find((a) => `${d.id}.${a.id}` === l.ability);
    if (!ab?.cooldownTicks || ab.manualCooldown) continue;
    const cd = Number(s.value(`items.${d.id}.abilities.${ab.id}.cooldown_ticks`));
    if (cd > 0) bars.push({ lane: d.abilities.length > 1 ? `${ab.name}` : "Cooldown", from: l.tick, to: l.tick + cd, tone: "warn" });
  }
  const log = s.log.flatMap((l) => (l.kind === "waited" ? [{ tick: l.tick, text: `waited ${+(Number((l.detail as { ticks: number }).ticks) / 20).toFixed(2)} s`, tone: "note" as const }] : (() => { const x = line(l, namespace); return x ? [{ tick: l.tick, ...x }] : []; })()));
  const lanes = [...new Set(["Charge", ...bars.map((b) => b.lane)])].filter((l) => l !== "Charge" || d.abilities.some((a) => a.trigger.type === "charge_release"));
  return {
    end: t, log, bars, lanes, marks, markCap: markDefs.length ? markDefs.reduce((n, m) => n + Number(s.value(`items.${d.id}.marks.${m.name}.max_per_owner`)), 0) : null,
    dots: s.log.filter((l) => l.kind === "fired" || l.kind === "blocked").map((l) => ({ tick: l.tick, tone: l.kind as "fired" | "blocked" })),
    notes: [...new Set(s.notes)].slice(0, 6),
  };
}

// --------------------------------------------------------------------------------------------- menus (Try it)
export type SamplePlayer = { currency: Record<string, number>; levels: number; vault: boolean; freeSlots: number; perms: boolean };
export const SAMPLE_PLAYER: SamplePlayer = { currency: { "minecraft:emerald": 9 }, levels: 7, vault: false, freeSlots: 6, perms: true };
export type TrySlot = { slot: number; label: string; nav?: "prev" | "next" };
export type TryClick = { slot: number; label: string; ran: boolean; reason: string; steps: { text: string; ok: boolean }[] };
export type TryResult = { open: { menu: string; page: number; slots: TrySlot[] } | null; clicks: TryClick[]; inventory: { item: string; count: number }[]; levels: number; log: { text: string; tone: "ok" | "bl" | "fx" }[] };

const REASON: Record<string, string> = { no_space: "no room for the given stacks", cannot_pay: "cannot pay", no_economy: "no Vault economy on this server", no_permission: "missing permission", rate_limited: "click cooldown", empty: "empty slot", outside: "outside the menu", no_menu: "no menu open" };

export function tryMenu(files: readonly DesignFile[], menuId: string, clicks: readonly number[], namespace: string, sp: SamplePlayer = SAMPLE_PLAYER): TryResult {
  const items = files.filter((f) => fileKind(f) === "item") as ItemDesign[];
  const menus = files.filter((f) => fileKind(f) === "menu") as MenuDesign[];
  const quests = files.filter((f) => fileKind(f) === "quest") as QuestDesign[];
  const s = new GameplaySimulator(items, menus, quests, { namespace, vault: sp.vault });
  const perms = new Set(sp.perms ? menus.flatMap((m) => [...(m.permissions ?? []).map((p) => `${namespace}.${p.node}`)]) : []);
  const p = s.join("ann", { levels: sp.levels, perms, money: sp.vault ? 100 : 0 });
  let used = 0;
  for (const [item, count] of Object.entries(sp.currency)) { s.give("ann", item, count); used++; }
  // fill all but `freeSlots` with a filler stack so "room for the given stacks" is real
  for (let i = 0; i < p.slots.length && p.slots.filter((x) => !x).length > sp.freeSlots; i++) if (!p.slots[i]) p.slots[i] = { item: "minecraft:cobblestone", count: 64 };
  void used;
  s.openMenu("ann", menuId);
  const out: TryClick[] = [];
  for (const slot of clicks.slice(0, MAX_SIM_STEPS)) {
    s.advance(6);
    const o = s.current("ann");
    const c = o?.slots.get(slot);
    const label = c?.label ?? `slot ${slot}`;
    const before = s.log.length;
    const r = s.click("ann", slot);
    const steps: TryClick["steps"] = [];
    if (c && !c.nav) {
      if (c.permission) steps.push({ text: `permission ${namespace}.${c.permission}`, ok: r.reason !== "no_permission" });
      const gives = c.actions.filter((a) => a.type === "give_item");
      if (r.reason !== "no_permission") steps.push({ text: gives.length ? "room for the given stacks" : "nothing to give", ok: r.reason !== "no_space" });
      if (c.cost && !["no_permission", "no_space"].includes(r.reason)) steps.push({ text: r.reason === "no_economy" ? "can pay: no Vault economy on this server" : `can pay ${costText(c.cost)}`, ok: r.ran });
      if (r.ran) { if (c.cost) steps.push({ text: "take (re-checked, all-or-nothing)", ok: true }); steps.push({ text: gives.length ? gives.map((g) => `give ${g.type === "give_item" ? `${g.count ?? 1} × ${g.item.replace(/^minecraft:/, "")}` : ""}`).join(", ") : `run ${c.actions.map((a) => a.type).join(", ") || "nothing"}`, ok: true }); }
    }
    out.push({ slot, label, ran: r.ran, reason: r.ran ? "ok" : REASON[r.reason] ?? r.reason, steps });
    void before;
  }
  const o = s.current("ann");
  const m = menus.find((x) => x.id === (o?.menu ?? menuId));
  const inv = new Map<string, number>();
  for (const x of p.slots) if (x && x.item !== "minecraft:cobblestone") inv.set(x.item, (inv.get(x.item) ?? 0) + x.count);
  const log = out.map((c) => ({ text: c.ran ? `${c.label}: ${c.reason === "ok" ? (c.steps.some((x) => x.text.startsWith("take")) ? "bought" : "done") : c.reason}` : `${c.label}: refused (${c.reason}), nothing taken`, tone: c.ran ? ("ok" as const) : ("bl" as const) }));
  return {
    open: o && m ? { menu: o.menu, page: o.page, slots: [...o.slots.entries()].map(([slot, c]) => ({ slot, label: c.label, ...(c.nav ? { nav: c.nav } : {}) })) } : null,
    clicks: out, inventory: [...inv.entries()].map(([item, count]) => ({ item, count })), levels: p.levels, log: log.reverse(),
  };
}
const costText = (c: { type: string; item?: string; count?: number; levels?: number; amount?: number }) => (c.type === "item" ? `${c.count} × ${String(c.item).replace(/^minecraft:/, "")}` : c.type === "xp_levels" ? `${c.levels} XP levels` : `${c.amount} money`);

// ------------------------------------------------------------------------------------------- quests (progress)
export type QuestStep = { k: "start"; quest: string } | { k: "kill"; entity: string; kinds?: string[] } | { k: "break"; block: string } | { k: "pickup"; item: string; count: number }
  | { k: "craft"; item: string; count: number } | { k: "visit"; world: string; pos: [number, number, number] } | { k: "talk"; menu: string } | { k: "survive"; seconds: number }
  | { k: "choose"; quest: string; branch: string } | { k: "day" } | { k: "die" };
export type QuestState = { id: string; title: string; status: "locked" | "available" | "active" | "choosing" | "done" | "cooldown"; text: string; cur: number; target: number };
export type QuestSimResult = { states: QuestState[]; buttons: { label: string; step: QuestStep }[]; log: { text: string; tone: "ok" | "bl" | "fx" }[]; active: number; maxActive: number; progressChars: number };

const bare = (s: string) => s.replace(/^minecraft:/, "");
export function simulateQuests(files: readonly DesignFile[], steps: readonly QuestStep[], namespace: string): QuestSimResult {
  const items = files.filter((f) => fileKind(f) === "item") as ItemDesign[];
  const menus = files.filter((f) => fileKind(f) === "menu") as MenuDesign[];
  const quests = (files.filter((f) => fileKind(f) === "quest") as QuestDesign[]);
  const s = new GameplaySimulator(items, menus, quests, { namespace });
  s.join("ann", { perms: new Set(quests.flatMap((q) => (q.permissions ?? []).map((p) => `${namespace}.${p.node}`))) });
  s.advance(10);
  const logFrom = (from: number) => s.log.slice(from).flatMap((e): QuestSimResult["log"] => {
    const d = e.detail ?? "";
    switch (e.kind) {
      case "quest_started": return [{ text: `${d} started`, tone: "fx" }];
      case "quest_refused": { const [id, why] = d.split(":"); return [{ text: `${id} refused · ${why === "menu_only" ? "starts only from a menu" : why?.startsWith("needs") ? `requires ${d.split(":")[2]}` : why === "cooldown" ? `again in ${Math.ceil(Number(d.split(":")[2]) / 3600)} h` : why}`, tone: "bl" }]; }
      case "progress": { const [id, step, c] = d.split(":"); return [{ text: `${id} ${step}: ${c.split(".").filter((_, i, a) => i < a.length).join(" · ")}`, tone: "fx" }]; }
      case "step": return [{ text: `${d.replace(":", " → step ")}`, tone: "fx" }];
      case "choose": return [{ text: `${d}: choice menu opens`, tone: "fx" }];
      case "branch_chosen": return [{ text: `${d.replace(":", " · path ")}`, tone: "fx" }];
      case "quest_complete": return [{ text: `${d.split(":")[0]} completed`, tone: "ok" }];
      case "reward": return [{ text: `reward ${bare(d)}`, tone: "ok" }];
      case "handed_in": return [{ text: `handed in ${bare(d)}`, tone: "fx" }];
      case "quest_failed": return [{ text: `${d.replace(":", " failed · ")}`, tone: "bl" }];
      case "nothing_to_choose": return [{ text: `choose refused · the choice is not open`, tone: "bl" }];
      default: return [];
    }
  });
  const log: QuestSimResult["log"] = [];
  for (const st of steps.slice(0, MAX_SIM_STEPS)) {
    const from = s.log.length;
    switch (st.k) {
      case "start": s.startQuest("ann", st.quest, true); break;
      case "kill": s.kill("ann", st.entity, st.kinds ?? ["hostile"]); break;
      case "break": s.breakBlock("ann", st.block, `b${from}`); break;
      case "pickup": s.pickup("ann", st.item, st.count); break;
      case "craft": s.craft("ann", st.item, st.count); break;
      case "visit": s.moveTo("ann", st.world, st.pos); s.recheck("ann"); s.advance(20); break;
      case "talk": s.openMenu("ann", st.menu); s.closeMenu("ann"); break;
      case "survive": s.advance(Math.min(7200, st.seconds) * 20 + 20); break;
      case "choose": s.chooseBranch("ann", st.quest, st.branch); break;
      case "day": s.clock += 86400; log.push({ text: "+24 h", tone: "fx" }); break;
      case "die": s.die("ann"); log.push({ text: "you died", tone: "fx" }); break;
    }
    s.advance(2);
    log.push(...logFrom(from));
  }
  // state per quest + the buttons that would move something
  const m = s.entries("ann");
  const buttons: QuestSimResult["buttons"] = [];
  const seen = new Set<string>();
  const btn = (label: string, step: QuestStep) => { if (!seen.has(label)) { seen.add(label); buttons.push({ label, step }); } };
  const states: QuestState[] = [...quests].sort((a, b) => order(quests, a) - order(quests, b)).map((q) => {
    const e: ProgressEntry | undefined = m.get(q.id);
    const why = s.startRefusal("ann", q.id, true);
    if (e?.state === "A") {
      const step = questSteps(q).find((x) => x.step.id === e.step && (x.branch ?? "") === e.branch)?.step ?? questSteps(q).find((x) => x.step.id === e.step)?.step;
      const o = step?.objectives[0];
      step?.objectives.forEach((ob) => {
        if (ob.type === "kill_entity") btn(`Kill ${ob.entity ? bare(ob.entity) : (ob.kinds ?? ["mob"]).join("/")}`, { k: "kill", entity: ob.entity ?? "minecraft:zombie", kinds: ob.kinds ?? ["hostile"] });
        if (ob.type === "break_block") btn(`Break ${bare(ob.block)}`, { k: "break", block: ob.block });
        if (ob.type === "collect_item") btn(`Pick up ${bare(ob.item)} ×${Math.min(ob.count, 64)}`, { k: "pickup", item: ob.item, count: Math.min(ob.count, 64) });
        if (ob.type === "craft_item") btn(`Craft ${bare(ob.item)} ×${ob.count}`, { k: "craft", item: ob.item, count: ob.count });
        if (ob.type === "visit_location") btn(`Reach ${ob.x} ${ob.y} ${ob.z}`, { k: "visit", world: ob.world, pos: [ob.x, ob.y, ob.z] });
        if (ob.type === "talk") btn(`Talk to ${ob.menu}`, { k: "talk", menu: ob.menu });
        if (ob.type === "survive") btn(`Survive ${ob.seconds} s`, { k: "survive", seconds: ob.seconds });
      });
      const target = o ? (o.type === "visit_location" || o.type === "talk" ? 1 : o.type === "survive" ? o.seconds : o.count) : 1;
      return { id: q.id, title: q.title, status: "active", text: `${step?.text ?? e.step} · ${e.counts[0]} / ${target}`, cur: e.counts[0], target };
    }
    if (e?.state === "C") { for (const b of q.branches?.options ?? []) btn(`Choose ${b.label.text}`, { k: "choose", quest: q.id, branch: b.id }); return { id: q.id, title: q.title, status: "choosing", text: q.branches?.prompt ?? "choice menu open", cur: 0, target: 1 }; }
    if (e && e.completions > 0 && why?.startsWith("cooldown")) return { id: q.id, title: q.title, status: "cooldown", text: `done · again in ${Math.ceil(Number(why.split(":")[1]) / 3600)} h`, cur: 1, target: 1 };
    if (e && e.completions > 0 && (q.repeat?.mode ?? "once") === "once") return { id: q.id, title: q.title, status: "done", text: "completed", cur: 1, target: 1 };
    if (!why) { btn(`Start ${q.title}`, { k: "start", quest: q.id }); return { id: q.id, title: q.title, status: "available", text: e?.completions ? "available again" : "available", cur: 0, target: 1 }; }
    if (why === "menu_only") { const opener = menus.find((mm) => JSON.stringify(mm).includes(`"start_quest","quest":"${q.id}"`) || JSON.stringify(mm).includes(`"quest":"${q.id}"`)); if (opener) btn(`Start ${q.title} (${opener.id})`, { k: "start", quest: q.id }); return { id: q.id, title: q.title, status: "available", text: `starts from ${opener?.id ?? "a menu"}`, cur: 0, target: 1 }; }
    return { id: q.id, title: q.title, status: "locked", text: why.startsWith("needs") ? `needs ${why.split(":")[1]}` : why.replace(/_/g, " "), cur: 0, target: 1 };
  });
  if (quests.some((q) => (q.repeat?.mode ?? "once") !== "once")) btn("+24 h", { k: "day" });
  return { states, buttons: buttons.slice(0, 12), log: log.reverse().slice(0, 40), active: s.active("ann"), maxActive: s.maxActive, progressChars: s.encoded("ann").length };
}
/** Chain order: prerequisites first (depth), then id. */
function order(all: QuestDesign[], q: QuestDesign, seen = new Set<string>()): number {
  if (seen.has(q.id)) return 0; seen.add(q.id);
  const depth = Math.max(0, ...(q.requires ?? []).map((r) => { const x = all.find((y) => y.id === r); return x ? order(all, x, seen) + 1 : 0; }));
  return depth * 100 + ((q.repeat?.mode ?? "once") !== "once" ? 50 : 0);
}

