// Cyrus designer studio UI (r27): pure + API tests with fakes (no DB, no network, no model). The client-side edit
// port agrees with the server's parameter edit paths for every fixture parameter; the analysis reports the validator's
// real codes, the budgets and "config.yml only" vs the Java files a structural edit changes; the simulators run the
// fixtures; the service saves a NEW revision (never an overwrite), refuses stale heads / invalid designs / design-set
// changes, keeps one autosaved draft per person; the handlers fail closed (404 without a viewer).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { applyGameplayEdits } from "../lib/cyrus/designer/gameplay/params";
import { modParams } from "../lib/cyrus/designer/gameplay/compile";
import type { ItemDesign } from "../lib/cyrus/designer/spec";
import type { MenuDesign, QuestDesign } from "../lib/cyrus/designer/gameplay/spec";
import { canonical, changedIds, insertAction, insertCondition, nodeParamPath, removeNode, replaceFile, setParamValue, ACTION_TEMPLATES, type DesignFile } from "../lib/cyrus/designer/studio/edit";
import { analyzeMod, type StudioCtx } from "../lib/cyrus/designer/studio/analyze";
import { itemButtons, simulateItem, simulateQuests, tryMenu } from "../lib/cyrus/designer/studio/sim";
import { designerView, resolveDesigns, saveDesigns, checkDesigns, putDraft, dropDraft, simulate, planEdit, DRAFT_KEY, type DesignerDeps } from "../lib/cyrus/designer/studio/service";
import * as H from "../lib/cyrus/designer/studio/http";
import { memoryDraftStore } from "../lib/cyrus/modelstudio/service";
import { StudioError, type AssetRow, type ChainInfo, type ProjectRow, type RevRow, type StudioStore } from "../lib/cyrus/studios/service";
import { goldenDesigns, GOLDEN_NS } from "../scripts/cyrus/designer-golden";
import { GP_NS, loadGameplayFixtures } from "../scripts/cyrus/gameplay-golden";
import { BOSS_NS, loadBossFixtures } from "../scripts/cyrus/boss-golden";
import { canonicalJson, sha256Hex } from "../lib/cyrus/assets/textures";
import { DESIGN_KIND_MIME } from "../lib/cyrus/designer/sync";

const items = () => goldenDesigns() as ItemDesign[];
const gp = () => loadGameplayFixtures() as DesignFile[];
const ctxOf = (namespace: string, pluginName = "VoidArsenal"): StudioCtx => ({ version: "1.21.11", namespace, pluginName });
const testValue = (p: { kind: string; min: number; max: number; value: number | string }) =>
  p.kind === "text" ? "Edited text" : p.kind === "sound" ? "minecraft:block.note_block.pling" : p.kind === "num" ? (Number(p.value) === p.min ? p.max : p.min) : Math.round(Number(p.value) === p.min ? p.max : p.min);

// ------------------------------------------------------------------------------------------------ edit port
describe("client edit port = the server's parameter paths", () => {
  it("setParamValue agrees with applyGameplayEdits for every parameter of the item, gameplay and boss fixtures", () => {
    const sets: DesignFile[][] = [items(), gp(), loadBossFixtures() as DesignFile[]];
    let n = 0;
    for (const files of sets) {
      const mod = { items: files.filter((f) => !("kind" in f) || f.kind === "item") as ItemDesign[], menus: files.filter((f) => (f as { kind?: string }).kind === "menu") as MenuDesign[], quests: files.filter((f) => (f as { kind?: string }).kind === "quest") as QuestDesign[], bosses: files.filter((f) => (f as { kind?: string }).kind === "boss") as never[], encounters: files.filter((f) => (f as { kind?: string }).kind === "encounter") as never[], huds: [] };
      for (const p of modParams(mod.items, mod.menus, mod.quests, mod.bosses, mod.encounters)) {
        const v = testValue(p);
        const server = applyGameplayEdits(mod, [{ path: p.path, value: v }]);
        assert.ok(server.ok, `${p.path}: ${!server.ok && server.errors.join(";")}`);
        const client = setParamValue(files, p.path, v, p.ptr);
        assert.ok(client.ok, `${p.path}: ${!client.ok && client.error}`);
        const want = [...server.mod.items, ...server.mod.menus, ...server.mod.quests, ...(server.mod.bosses ?? []), ...(server.mod.encounters ?? [])];
        for (const f of client.files) assert.equal(canonical(f), canonical(want.find((w) => w.id === f.id)), `${p.path} changed ${f.id} differently`);
        n++;
      }
    }
    assert.ok(n > 120, `checked ${n} parameters`);
  });
  it("graph field paths, structural helpers and the JSON view keep ids and refuse bad paths", () => {
    assert.equal(nodeParamPath("void_reaper", "void_pull", "a0.n1", "count"), "items.void_reaper.abilities.void_pull.a0.n1.count");
    assert.equal(nodeParamPath("void_reaper", "void_pull", "trigger", "minChargeTicks"), "items.void_reaper.abilities.void_pull.trigger.min_charge_ticks");
    const f = items();
    const add = insertAction(f, "void_reaper", "void_pull", "a0", ACTION_TEMPLATES.spawn_particles({ marks: [] }));
    assert.ok(add.ok && add.path === "a0.n2");
    const rm = add.ok ? removeNode(add.files, "void_reaper", "void_pull", "a0.n2") : null;
    assert.ok(rm?.ok && canonical(rm.files) === canonical(f), "remove undoes insert");
    assert.ok(insertCondition(f, "void_reaper", "void_pull", { type: "sneaking" }).ok);
    assert.equal(replaceFile(f, "void_reaper", { ...f[0], id: "other" }).ok, false);
    assert.equal(setParamValue(f, "items.void_reaper.nope", 1).ok, false);
    assert.deepEqual(changedIds(f, f), []);
  });
});

// ---------------------------------------------------------------------------------------------- analysis
describe("analysis: real codes, budgets, config.yml only vs Java", () => {
  const ctx = ctxOf(GOLDEN_NS);
  it("the Void Arsenal fixtures are valid, Void Pull's budget is the static worst case", () => {
    const a = analyzeMod(items(), ctx, items());
    assert.ok(a.ok && a.compile.ok, JSON.stringify(a.files.flatMap((f) => f.errors)));
    const vp = a.budgets.find((b) => b.ability === "void_pull")!;
    assert.deepEqual([vp.actions, vp.entities, vp.particles, vp.projectiles], [20, 8, 161, 0]);
    assert.ok(a.diff && a.diff.changed.length === 0 && a.diff.configVersion.from === a.diff.configVersion.to);
    assert.equal(a.itemChecks.void_reaper.find((c) => c.id === "budget")!.status, "pass");
  });
  it("a value edit changes config.yml only and bumps config_version", () => {
    const r = setParamValue(items(), "items.void_reaper.abilities.void_pull.cooldown_ticks", 100);
    assert.ok(r.ok);
    const a = analyzeMod(r.ok ? r.files : [], ctx, items());
    assert.ok(a.ok && a.diff);
    assert.equal(a.diff!.configOnly, true);
    assert.deepEqual(a.diff!.javaChanged, []);
    assert.deepEqual(a.diff!.configVersion, { from: 1, to: 2 });
  });
  it("an out-of-range value and a budget overrun show the validator's own codes", () => {
    let f = setParamValue(items(), "items.void_reaper.abilities.void_pull.a0.max", 16);
    f = f.ok ? setParamValue(f.files, "items.void_reaper.abilities.void_pull.a0.n1.count", 40) : f;
    const a = analyzeMod(f.ok ? f.files : [], ctx, items());
    assert.equal(a.ok, false);
    const vr = a.files.find((x) => x.id === "void_reaper")!;
    assert.ok(vr.errors.some((e) => e.code === "budget_particles" && /641/.test(e.message)), JSON.stringify(vr.errors));
    const b = setParamValue(items(), "items.void_reaper.abilities.void_pull.cooldown_ticks", 99999);
    const a2 = analyzeMod(b.ok ? b.files : [], ctx, items());
    assert.ok(a2.files.find((x) => x.id === "void_reaper")!.errors.some((e) => e.code === "schema"));
  });
  it("a structural edit names the Java files it rebuilds", () => {
    const add = insertAction(items(), "void_reaper", "void_pull", "", ACTION_TEMPLATES.actionbar({ marks: [] }));
    assert.ok(add.ok);
    const a = analyzeMod(add.ok ? add.files : [], ctx, items());
    assert.ok(a.ok && a.diff && !a.diff.configOnly && a.diff.javaChanged.some((p) => /VoidPull/.test(p)), JSON.stringify(a.diff));
  });
  it("menus and quests: gameplay rows pass, economy_needs_vault warns", () => {
    const a = analyzeMod(gp(), ctxOf(GP_NS, "GuildQuests"), gp());
    assert.ok(a.ok, JSON.stringify(a.files.flatMap((f) => f.errors)));
    assert.equal(a.gameplayChecks.menu.find((c) => c.id === "economy_needs_vault")!.status, "warn");
    assert.equal(a.gameplayChecks.quest.find((c) => c.id === "circular_prerequisites")!.status, "pass");
    assert.ok(a.progressChars > 0 && a.progressChars < 2048);
  });
});

// --------------------------------------------------------------------------------------------- simulators
describe("simulators on the fixtures", () => {
  it("Void Reaper: marks, a charged pull, then the cooldown blocks with feedback", () => {
    const vr = items().find((d) => d.id === "void_reaper")!;
    assert.deepEqual(itemButtons(vr).map((b) => b.step.k), ["hit", "hit", "charge", "charge", "wait"]);
    const r = simulateItem(items(), "void_reaper", [{ k: "hit", who: "hostile" }, { k: "hit", who: "hostile" }, { k: "hit", who: "animal" }, { k: "charge", ticks: 40 }, { k: "charge", ticks: 30 }], GOLDEN_NS);
    const t = r.log.map((l) => l.text);
    assert.ok(t.filter((x) => x.startsWith("mark void")).length === 2, t.join("\n"));
    assert.ok(t.some((x) => /void_mark blocked · condition target_is/.test(x)), "the cow is not hostile");
    assert.ok(t.some((x) => /void_pull fired/.test(x)) && t.some((x) => /void_pull blocked · cooldown/.test(x)) && t.some((x) => /feedback “Void Pull: /.test(x)), t.join("\n"));
    assert.ok(r.bars.some((b) => b.lane === "Cooldown" && b.to - b.from === 160));
    assert.equal(r.markCap, 8);
  });
  it("Guild Shop Try it: buys a list entry, refuses money without Vault, nothing taken", () => {
    const r = tryMenu(gp(), "shop", [10, 51], GP_NS);
    assert.equal(r.clicks[0].ran, true);
    assert.equal(r.clicks[1].ran, false);
    assert.match(r.clicks[1].reason, /Vault/);
    assert.ok(r.inventory.some((x) => x.item === "minecraft:bread"));
  });
  it("Quest chain: progress, the branch choice and the daily cooldown", () => {
    const start = simulateQuests(gp(), [], GP_NS);
    assert.ok(start.states.length === 4);
    const r = simulateQuests(gp(), [{ k: "start", quest: "trial_one", via: "menu" }, { k: "kill", entity: "minecraft:zombie" }], GP_NS);
    assert.ok(r.states.find((s) => s.id === "trial_one")!.status === "active", JSON.stringify(r.states));
    assert.ok(r.log.some((l) => /trial_one/.test(l.text)));
  });
});

// --------------------------------------------------------------------------------------------- the service
type Mem = { projects: Map<string, ProjectRow>; revs: (RevRow & { projectId: string })[]; assets: AssetRow[] };
function memStore(): StudioStore & { mem: Mem } {
  const mem: Mem = { projects: new Map(), revs: [], assets: [] };
  let t = Date.parse("2026-10-10T10:00:00Z");
  return {
    mem,
    projectForRoot: async (root) => [...mem.projects.values()].find((p) => p.rootBuildId === root) ?? null,
    project: async (id) => mem.projects.get(id) ?? null,
    assets: async (pid) => mem.assets.filter((a) => a.projectId === pid),
    assetById: async (id) => mem.assets.find((a) => a.id === id) ?? null,
    revisions: async (pid) => mem.revs.filter((r) => r.projectId === pid),
    async addRevision(pid, input) {
      const p = mem.projects.get(pid)!;
      if (input.expectedHeadId !== undefined && input.expectedHeadId !== p.headRevisionId) throw Object.assign(new Error("stale"), { code: "stale_head" });
      const seq = mem.revs.filter((r) => r.projectId === pid).length + 1;
      const r = { id: `rev${mem.revs.length + 1}`, projectId: pid, seq, kind: input.kind, status: input.status ?? "pending", message: input.message ?? null, createdAt: new Date(t += 1000), manifest: input.manifest as RevRow["manifest"], modBuildId: input.modBuildId ?? null };
      mem.revs.push(r); p.headRevisionId = r.id;
      return r;
    },
    async recordAsset(pid, a) {
      const row: AssetRow = { id: `as${mem.assets.length + 1}`, projectId: pid, revisionId: a.revisionId, assetKey: a.assetKey, kind: a.kind, sha256: a.sha256, size: a.size, origin: a.origin, mime: a.mime ?? null, path: a.path ?? null, provenance: a.provenance ?? null, createdAt: new Date(t += 1000) };
      mem.assets.push(row);
      return row;
    },
    async reserve() { return { fullId: "x" }; },
  };
}
const PID = "cp" + "2".repeat(20);
async function seeded(candidateBuilds: ChainInfo["candidateBuilds"] = []) {
  const store = memStore();
  store.mem.projects.set(PID, { id: PID, userId: "u1", namespace: GOLDEN_NS, rootBuildId: "mb1", headRevisionId: null, title: null });
  const designs = items();
  const rev = await store.addRevision(PID, { kind: "generated", status: "passed", modBuildId: "mb1", expectedHeadId: null, manifest: designs.map((d) => ({ path: `assets/designs/${d.id}.json`, sha256: sha256Hex(canonicalJson(d)), role: "asset" as const })) });
  for (const d of designs) await store.recordAsset(PID, { revisionId: rev.id, assetKey: d.id, kind: "design", sha256: sha256Hex(canonicalJson(d)), size: 10, origin: "generated", mime: DESIGN_KIND_MIME.item, path: `assets/designs/${d.id}.json`, provenance: { generator: "cyrus-designer", spec: d, modBuildId: "mb1", configVersion: 1 } });
  const chain: ChainInfo = { rootBuildId: "mb1", latestBuildId: "mb1", mcVersion: "1.21.11", pluginName: "VoidArsenal", assets: null, candidateBuilds };
  const drafts = memoryDraftStore();
  const deps: DesignerDeps = { store, planOf: async () => "saka", chain: async (u, r) => (u === "u1" && r === "mb1" ? chain : null), deliveryOn: () => false, drafts };
  return { store, deps, drafts, head: () => store.mem.projects.get(PID)!.headRevisionId };
}
const err = async (p: Promise<unknown>) => { try { await p; } catch (e) { return e as StudioError; } throw new Error("expected an error"); };

describe("designer service (in-memory store)", () => {
  it("view: the current designs, a valid analysis, the plan only for the asset chips", async () => {
    const s = await seeded();
    const v = await designerView(s.deps, "u1", "mb1");
    assert.deepEqual(v.designs.map((d) => d.id), ["storm_staff", "vigor_tonic", "void_reaper"]);
    assert.ok(v.analysis?.ok);
    assert.equal(v.access.edit.texture.ok, false, "saka cannot edit textures");
    assert.equal(v.access.edit.sound.ok, true);
    assert.equal(v.draft, null);
    await assert.rejects(designerView(s.deps, "u2", "mb1"));
  });
  it("save = a NEW pending revision of kind edited + one row per changed design; stale / invalid / unchanged are refused", async () => {
    const s = await seeded();
    const v = await designerView(s.deps, "u1", "mb1");
    const e = setParamValue(v.saved, "items.void_reaper.abilities.void_pull.cooldown_ticks", 100);
    assert.ok(e.ok);
    const files = e.ok ? e.files : [];
    assert.equal((await err(saveDesigns(s.deps, { userId: "u1", projectId: PID, files, expectedHeadId: "nope" }))).code, "stale_head");
    assert.equal((await err(saveDesigns(s.deps, { userId: "u1", projectId: PID, files: v.saved, expectedHeadId: v.headRevisionId }))).code, "no_changes");
    assert.equal((await err(saveDesigns(s.deps, { userId: "u1", projectId: PID, files: files.slice(1), expectedHeadId: v.headRevisionId }))).code, "design_set_changed");
    const bad = setParamValue(files, "items.void_reaper.abilities.void_pull.cooldown_ticks", 99999);
    assert.equal((await err(saveDesigns(s.deps, { userId: "u1", projectId: PID, files: bad.ok ? bad.files : [], expectedHeadId: v.headRevisionId }))).code, "invalid");
    await putDraft(s.deps, "u1", PID, files, v.headRevisionId);
    assert.ok(await s.drafts.get(PID, "u1", DRAFT_KEY));
    const r = await saveDesigns(s.deps, { userId: "u1", projectId: PID, files, expectedHeadId: v.headRevisionId });
    assert.deepEqual(r.changed, ["void_reaper"]);
    assert.equal(r.configOnly, true);
    assert.equal(r.seq, 2);
    const rev = s.store.mem.revs.at(-1)!;
    assert.equal(rev.kind, "edited"); assert.equal(rev.status, "pending");
    assert.equal(rev.manifest.filter((m) => m.path.startsWith("assets/designs/")).length, 3);
    const row = s.store.mem.assets.at(-1)!;
    assert.equal(row.origin, "edited"); assert.equal(row.kind, "design");
    assert.equal(await s.drafts.get(PID, "u1", DRAFT_KEY), null, "the draft is dropped on save");
    const v2 = await designerView(s.deps, "u1", "mb1");
    assert.equal(v2.designs.find((d) => d.id === "void_reaper")!.origin, "edited");
    assert.equal((v2.saved.find((d) => d.id === "void_reaper") as ItemDesign).abilities[1].cooldownTicks, 100);
    assert.equal(s.store.mem.assets.filter((a) => a.assetKey === "void_reaper").length, 2, "rows are append-only");
  });
  it("drafts: one per person, shown only when it differs, stale after another save", async () => {
    const s = await seeded();
    const v = await designerView(s.deps, "u1", "mb1");
    assert.deepEqual(await putDraft(s.deps, "u1", PID, v.saved, v.headRevisionId), { saved: false });
    const e = setParamValue(v.saved, "items.void_reaper.marks.void.duration_ticks", 300);
    await putDraft(s.deps, "u1", PID, e.ok ? e.files : [], v.headRevisionId);
    const v2 = await designerView(s.deps, "u1", "mb1");
    assert.ok(v2.draft && !v2.draft.stale);
    await dropDraft(s.deps, "u1", PID);
    assert.equal((await designerView(s.deps, "u1", "mb1")).draft, null);
  });
  it("rows from a studio candidate build are not the mod's designs", async () => {
    const s = await seeded([{ id: "cand1", key: "glock", status: "succeeded", error: null, createdAt: "x" }]);
    const d = { ...items()[0], name: { text: "Candidate name" } };
    await s.store.recordAsset(PID, { revisionId: "rev1", assetKey: d.id, kind: "design", sha256: "f".repeat(64), size: 1, origin: "generated", mime: DESIGN_KIND_MIME.item, path: "x", provenance: { spec: d, modBuildId: "cand1" } });
    const { files } = resolveDesigns(await s.store.assets(PID), new Set(["cand1"]), () => null);
    assert.notEqual((files.find((f) => f.id === d.id) as ItemDesign).name.text, "Candidate name");
  });
  it("check / simulate / plan run on the working copy and refuse other people's projects", async () => {
    const s = await seeded();
    const v = await designerView(s.deps, "u1", "mb1");
    assert.ok((await checkDesigns(s.deps, "u1", PID, v.saved)).ok);
    const sim = await simulate(s.deps, "u1", PID, { files: v.saved, mode: "item", item: "void_reaper", steps: [{ k: "hit", who: "hostile" }] });
    assert.equal(sim.mode, "item");
    const plan = await planEdit(s.deps, "u1", PID, "set the void pull cooldown to 5 seconds", v.saved);
    assert.equal(plan.kind, "parameters");
    assert.equal((await err(checkDesigns(s.deps, "u2", PID, v.saved))).status, 404);
  });
});

// --------------------------------------------------------------------------------------------- handlers
describe("handlers fail closed", () => {
  const api = async (viewer: string | null) => { const s = await seeded(); return { s, deps: { viewer: async () => (viewer ? { userId: viewer, preview: true } : null), service: s.deps, rateLimit: () => ({ ok: true }) } as H.DesignerApiDeps }; };
  const req = (url: string, body?: unknown, method = body ? "POST" : "GET") => new Request(`http://x${url}`, { method, ...(body ? { body: JSON.stringify(body), headers: { "content-type": "application/json" } } : {}) });
  it("no viewer (switch off, no studios access) = 404 on every route", async () => {
    const { deps } = await api(null);
    assert.equal((await H.handleView(req("/v?root=mb1"), deps)).status, 404);
    assert.equal((await H.handleCheck(req("/c", { files: [] }), { projectId: PID }, deps)).status, 404);
    assert.equal((await H.handleSave(req("/s", { files: [] }), { projectId: PID }, deps)).status, 404);
    assert.equal((await H.handleSimulate(req("/s", { mode: "item" }), { projectId: PID }, deps)).status, 404);
    assert.equal((await H.handleDraftPut(req("/d", { files: [] }, "PUT"), { projectId: PID }, deps)).status, 404);
  });
  it("validates input, maps ownership to 404, rate limits", async () => {
    const { deps } = await api("u1");
    assert.equal((await H.handleView(req("/v?root=../x"), deps)).status, 400);
    const v = await (await H.handleView(req("/v?root=mb1"), deps)).json() as { saved: unknown[]; headRevisionId: string };
    assert.equal((await H.handleCheck(req("/c", { files: v.saved }), { projectId: PID }, deps)).status, 200);
    assert.equal((await H.handleSimulate(req("/s", { files: v.saved, mode: "item", item: "void_reaper", steps: [{ k: "explode" }] }), { projectId: PID }, deps)).status, 400);
    assert.equal((await H.handleSave(req("/s", { files: v.saved, expectedHeadId: 5 }), { projectId: PID }, deps)).status, 400);
    const other = await api("u2");
    assert.equal((await H.handleCheck(req("/c", { files: v.saved }), { projectId: PID }, other.deps)).status, 404);
    const limited = { ...deps, rateLimit: () => ({ ok: false, retryAfterSec: 9 }) };
    assert.equal((await H.handleCheck(req("/c", { files: v.saved }), { projectId: PID }, limited)).status, 429);
  });
  it("the boss fixtures analyse too (the merged boss kind)", () => {
    const a = analyzeMod(loadBossFixtures() as DesignFile[], ctxOf(BOSS_NS, "BossTrials"), loadBossFixtures() as DesignFile[]);
    assert.ok(a.ok, JSON.stringify(a.files.flatMap((f) => f.errors).slice(0, 3)));
  });
});

