"use client";
// Client calls of the Cyrus designer studio API (/api/cyrus/designer/v1). The designer screens talk to nothing else
// (plus the studios' asset view for real texture icons, ../studios/api.ts).
import type { DesignerView, SaveDesignsResult } from "@/lib/cyrus/designer/studio/service";
import type { Analysis } from "@/lib/cyrus/designer/studio/analyze";
import type { DesignFile } from "@/lib/cyrus/designer/studio/edit";
import type { ItemSimResult, ItemStep, QuestSimResult, QuestStep, SimButton, TryResult } from "@/lib/cyrus/designer/studio/sim";
import type { EditPlan } from "@/lib/cyrus/designer/params";
import { ApiError } from "../studios/api";

export type { DesignerView, Analysis, DesignFile, ItemSimResult, ItemStep, QuestSimResult, QuestStep, SimButton, TryResult, EditPlan, SaveDesignsResult };
export const DAPI = "/api/cyrus/designer/v1";

async function call<T>(path: string, init?: RequestInit): Promise<T> {
  const r = await fetch(DAPI + path, { cache: "no-store", ...init, headers: { ...(init?.body ? { "content-type": "application/json" } : {}), ...(init?.headers ?? {}) } });
  const j = (await r.json().catch(() => ({}))) as Record<string, unknown>;
  if (!r.ok) throw new ApiError(r.status, String(j.code ?? r.status), String(j.error ?? "Something went wrong."), j);
  return j as T;
}
const send = <T,>(method: string, path: string, body: unknown) => call<T>(path, { method, body: JSON.stringify(body) });

export const designerApi = {
  view: (root: string) => call<DesignerView>(`/projects?root=${encodeURIComponent(root)}`),
  check: (projectId: string, files: DesignFile[]) => send<Analysis>("POST", `/projects/${projectId}/check`, { files }),
  save: (projectId: string, files: DesignFile[], expectedHeadId: string | null) => send<SaveDesignsResult>("POST", `/projects/${projectId}/revisions`, { files, expectedHeadId }),
  putDraft: (projectId: string, files: DesignFile[], baseHeadId: string | null) => send<{ saved: boolean; updatedAt?: string }>("PUT", `/projects/${projectId}/draft`, { files, baseHeadId }),
  dropDraft: (projectId: string) => call<{ dropped: true }>(`/projects/${projectId}/draft`, { method: "DELETE" }),
  simItem: (projectId: string, files: DesignFile[], item: string, steps: ItemStep[]) => send<{ mode: "item"; result: ItemSimResult; buttons: SimButton[] }>("POST", `/projects/${projectId}/simulate`, { files, mode: "item", item, steps }),
  tryMenu: (projectId: string, files: DesignFile[], menu: string, clicks: number[]) => send<{ mode: "menu"; result: TryResult }>("POST", `/projects/${projectId}/simulate`, { files, mode: "menu", menu, clicks }),
  simQuests: (projectId: string, files: DesignFile[], steps: QuestStep[]) => send<{ mode: "quests"; result: QuestSimResult }>("POST", `/projects/${projectId}/simulate`, { files, mode: "quests", steps }),
  plan: (projectId: string, files: DesignFile[], text: string) => send<EditPlan>("POST", `/projects/${projectId}/plan`, { files, text }),
};

