/* Cyrus designer studios (r27): Item Designer, Menu + Quest designers, Boss designer. Ported from the v2 mockups
   (/root/agent-notes/cyrus-designs/v2/src/item-designer.html, menu-quest.html, v2.css) onto the shipped studio tokens
   (./studios.css: .cys, cys-glass, cys-tag, ...). Every class is dz-*. One accent (violet = selected / primary); cyan only
   means "now" (the simulator playhead); green / amber / red only mean pass / warn / fail. */

.cys .dz-ws { flex: 1; min-height: 0; display: grid; grid-template-columns: 220px minmax(0, 1fr) 324px; gap: 12px; padding: 4px 14px 14px; }
.cys .dz-col { display: flex; flex-direction: column; gap: 12px; min-height: 0; min-width: 0; }
.cys .dz-col.scroll { overflow: auto; } .cys .dz-col.scroll > .cys-panel { flex: none; }
.cys .dz-scroll { overflow: auto; min-height: 0; }
.cys .dz-body { padding: 0 12px 12px; }
.cys .cys-ph .n { font: 500 10px/1 var(--mono); padding: 3px 6px; border-radius: 5px; border: 1px solid var(--line-2); color: var(--muted); }
.cys .dz-mono { font: 500 11px/1.3 var(--mono); color: var(--muted); }
.cys .dz-sub { font-size: 11.5px; color: var(--muted); }
.cys .mct { color: var(--mc); text-shadow: 1px 1px 0 color-mix(in srgb, var(--mc) 25%, #000); font-weight: 600; }
html[data-theme="light"] .cyrus-root .cys .mct { background: #1b1430; padding: 2px 7px; border-radius: 6px; text-shadow: 1px 1px 0 rgb(0 0 0 / .5); box-decoration-break: clone; -webkit-box-decoration-break: clone; }
.cys canvas.pxi { image-rendering: pixelated; flex: none; display: block; }

/* left lists */
.cys .dz-row { display: flex; align-items: center; gap: 10px; padding: 7px 8px; border-radius: var(--r); color: var(--ink-2); width: 100%; text-align: left; }
.cys button.dz-row:hover { background: rgb(var(--glow) / .07); }
.cys .dz-row.on { background: rgb(var(--glow) / .13); box-shadow: inset 0 0 0 1px rgb(var(--glow) / .22); color: var(--ink); }
.cys .dz-row .tx { flex: 1; min-width: 0; }
.cys .dz-row .tx b { display: block; font: 500 12.5px/1.2 var(--mono); color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cys .dz-row .tx b.sans { font-family: var(--font-inter), sans-serif; font-weight: 600; }
.cys .dz-row .tx small { display: block; font: 400 10.5px/1.3 var(--mono); color: var(--muted); margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cys .dz-thumb { flex: none; width: 32px; height: 32px; border-radius: 8px; display: grid; place-items: center; background: repeating-conic-gradient(var(--check-a) 0 25%, var(--check-b) 0 50%) 0 0 / 8px 8px; border: 1px solid var(--line); overflow: hidden; color: var(--muted); font-size: 15px; }
.cys .dz-thumb.plain { background: var(--well); }
.cys .dz-thumb canvas { width: 24px; height: 24px; }
.cys .dz-addb { display: flex; align-items: center; justify-content: center; gap: 6px; height: 30px; width: 100%; border-radius: 10px; border: 1px dashed var(--line-2); color: var(--muted); font-size: 11.5px; }
.cys .dz-addb:hover:not(:disabled) { color: var(--ink); border-color: var(--line-3); }
.cys .dz-addb:disabled { opacity: .5; cursor: not-allowed; }
.cys .dz-recipe { display: grid; grid-template-columns: repeat(3, 30px); gap: 3px; }
.cys .dz-recipe span { width: 30px; height: 30px; border-radius: 7px; background: var(--well); border: 1px solid var(--line); display: grid; place-items: center; }
