.cys .dz-ctab { width: 100%; border-collapse: collapse; font-size: 12px; }
.cys .dz-ctab th { text-align: left; font: 600 9.5px/1 var(--mono); letter-spacing: .14em; text-transform: uppercase; color: var(--faint); padding: 6px 8px; border-bottom: 1px solid var(--line); position: sticky; top: 0; background: var(--solid); }
.cys .dz-ctab td { padding: 5px 8px; border-bottom: 1px solid var(--line); color: var(--ink-2); } .cys .dz-ctab td.m { font-family: var(--mono); font-size: 11.5px; }
.cys .dz-ctab tr.on td { background: rgb(var(--glow) / .08); }
.cys .dz-ctab canvas { width: 18px; height: 18px; }
.cys .dz-ctab .dz-stp input { width: 40px; }
.cys .dz-insh { display: flex; gap: 12px; align-items: center; padding: 4px 14px 10px; }
.cys .dz-insh .big { width: 52px; height: 52px; border-radius: 12px; display: grid; place-items: center; background: var(--well); border: 1px solid var(--line-2); flex: none; }
.cys .dz-insh .big canvas { width: 36px; height: 36px; }
.cys .dz-insh .mct { font: 600 14px/1.2 var(--display); }
.cys .dz-sec { padding: 10px 14px; border-top: 1px solid var(--line); }
.cys .dz-sec > .cys-eyebrow { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.cys .dz-achip { display: inline-flex; align-items: center; gap: 6px; min-height: 26px; padding: 0 9px; border-radius: 8px; border: 1px solid var(--line-2); background: var(--surface-2); font-size: 11.5px; color: var(--ink-2); max-width: 100%; }
.cys .dz-achip code { font: 500 11px/1 var(--mono); color: var(--ink); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cys .dz-achip canvas { width: 16px; height: 16px; }
.cys .dz-achip.cost { border-color: color-mix(in srgb, var(--warn) 45%, transparent); background: var(--warn-soft); }
.cys .dz-flow { display: flex; flex-wrap: wrap; gap: 5px; align-items: center; }
.cys .dz-proto { list-style: none; margin: 0; padding: 0; counter-reset: p; display: grid; gap: 4px; }
.cys .dz-proto li { counter-increment: p; display: grid; grid-template-columns: 20px minmax(0, 1fr) auto; gap: 8px; align-items: center; font-size: 11.5px; color: var(--ink-2); padding: 5px 0; }
.cys .dz-proto li::before { content: counter(p); width: 20px; height: 20px; border-radius: 6px; display: grid; place-items: center; font: 600 10px/1 var(--mono); color: var(--accent-ink); background: var(--accent-soft); }
.cys .dz-proto li.ok::before { content: "✓"; color: var(--ok); background: var(--ok-soft); } .cys .dz-proto li.no::before { content: "×"; color: var(--bad); background: var(--bad-soft); }
.cys .dz-guard { display: flex; gap: 8px; align-items: flex-start; font-size: 11.5px; color: var(--ink-2); padding: 4px 0; } .cys .dz-guard > svg { color: var(--ok); margin-top: 2px; flex: none; }
.cys .dz-inv { display: flex; gap: 6px; flex-wrap: wrap; }
.cys .dz-chain { display: flex; align-items: center; padding: 4px 14px 12px; overflow-x: auto; }
.cys .dz-qnode { flex: none; width: 132px; padding: 9px 10px; border-radius: 11px; border: 1px solid var(--line-2); background: var(--surface-2); text-align: left; }
.cys .dz-qnode.on { border-color: var(--accent-line); box-shadow: 0 0 0 3px rgb(var(--glow) / .14); }
.cys .dz-qnode b { display: block; font-size: 12.5px; font-weight: 600; color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cys .dz-qnode small { display: block; font: 400 10.5px/1.35 var(--mono); color: var(--muted); margin-top: 3px; }
.cys .dz-qnode small.st-done { color: var(--ok); } .cys .dz-qnode small.st-active { color: var(--accent-ink); }
.cys .dz-qlink { flex: none; width: 20px; height: 1px; background: var(--line-3); position: relative; } .cys .dz-qlink::after { content: ""; position: absolute; right: -1px; top: -4px; border: 4.5px solid transparent; border-left: 6px solid var(--line-3); }
.cys .dz-qsep { width: 1px; align-self: stretch; background: var(--line-2); margin: 0 12px; flex: none; }
.cys .dz-qflow { padding: 6px 14px 14px; display: grid; }
.cys .dz-fstep { display: grid; grid-template-columns: 28px minmax(0, 1fr); gap: 10px; }
.cys .dz-rail { display: flex; flex-direction: column; align-items: center; }
.cys .dz-rail i { width: 26px; height: 26px; border-radius: 8px; display: grid; place-items: center; font-style: normal; font: 600 11px/1 var(--mono); color: var(--accent-ink); background: var(--accent-soft); box-shadow: inset 0 0 0 1px var(--accent-line); }
.cys .dz-rail::after { content: ""; flex: 1; width: 1px; background: var(--line-3); margin: 4px 0; min-height: 10px; }
.cys .dz-fstep:last-child .dz-rail::after { display: none; }
.cys .dz-fcard { padding: 8px 10px 10px; border-radius: 11px; border: 1px solid var(--line-2); background: var(--surface-2); margin-bottom: 10px; min-width: 0; }
.cys .dz-fcard h4 { margin: 0 0 6px; font-size: 12.5px; font-weight: 600; display: flex; gap: 8px; align-items: center; } .cys .dz-fcard h4 .dz-mono { margin-left: auto; }
.cys .dz-obj { display: flex; align-items: center; gap: 8px; padding: 6px 8px; border-radius: 8px; background: var(--well); border: 1px solid var(--line); font-size: 11.5px; color: var(--ink-2); margin-top: 4px; flex-wrap: wrap; }
.cys .dz-obj code { font: 500 11px/1 var(--mono); color: var(--ink); } .cys .dz-obj .cnt { margin-left: auto; display: flex; align-items: center; gap: 6px; font: 600 11px/1 var(--mono); color: var(--ink); }
.cys .dz-obj > svg { color: var(--muted); } .cys .dz-obj canvas { width: 18px; height: 18px; }
.cys .dz-branches { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 10px; }
.cys .dz-bcol { border-radius: 11px; border: 1px dashed var(--line-3); padding: 8px; background: rgb(var(--glow) / .03); min-width: 0; }
.cys .dz-bcol.on { border-color: var(--accent-line); }
.cys .dz-bcol h5 { margin: 0 0 6px; display: flex; align-items: center; gap: 8px; font-size: 12px; } .cys .dz-bcol h5 canvas { width: 18px; height: 18px; }
.cys .dz-rw { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 6px; }
.cys .dz-rwc { display: inline-flex; align-items: center; gap: 5px; height: 24px; padding: 0 8px; border-radius: 7px; font-size: 11px; color: var(--ink-2); border: 1px solid color-mix(in srgb, var(--ok) 35%, transparent); background: var(--ok-soft); } .cys .dz-rwc canvas { width: 14px; height: 14px; }
.cys .dz-qstate { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 2px 8px; padding: 8px 10px; border-radius: 10px; border: 1px solid var(--line); background: var(--well); margin-bottom: 6px; font-size: 12px; }
.cys .dz-qstate b { font-weight: 600; } .cys .dz-qstate small { grid-column: 1 / 3; font: 400 10.5px/1.3 var(--mono); color: var(--muted); }
.cys .dz-pbar { grid-column: 1 / 3; height: 5px; border-radius: 5px; background: var(--line-2); overflow: hidden; margin-top: 5px; } .cys .dz-pbar i { display: block; height: 100%; background: var(--accent); border-radius: 5px; transition: width .3s ease; }
.cys .dz-pbar.done i { background: var(--ok); }
.cys .dz-evbtns { display: flex; flex-wrap: wrap; gap: 4px; }

/* ═══ Boss designer ═══ */
.cys .dz-phases { display: flex; flex-direction: column; gap: 10px; padding: 6px 14px 14px; }
.cys .dz-hpbar { position: relative; height: 26px; border-radius: 8px; background: var(--well); border: 1px solid var(--line-2); overflow: hidden; margin: 2px 14px 10px; }
.cys .dz-hpbar .seg { position: absolute; top: 0; bottom: 0; display: flex; align-items: center; padding: 0 8px; font: 500 10.5px/1 var(--mono); color: var(--ink-2); border-right: 1px solid var(--line-3); white-space: nowrap; overflow: hidden; }
.cys .dz-hpbar .seg.on { background: var(--accent-soft); color: var(--ink); box-shadow: inset 0 -2px 0 var(--accent); }
.cys .dz-hpbar .thr { position: absolute; top: -2px; bottom: -2px; width: 2px; background: var(--accent); }
.cys .dz-atk { display: grid; grid-template-columns: minmax(0, 1fr); gap: 6px; }
.cys .dz-arena { position: relative; height: 150px; margin: 0 12px; border-radius: 12px; overflow: hidden; border: 1px solid var(--line); background: var(--well); }
.cys .dz-arena canvas { position: absolute; inset: 0; width: 100%; height: 100%; }

/* ═══ narrow: read-only review + approve ═══ */
.cys .dz-narrow { display: none; }
@container (max-width: 1180px) { .cys .dz-ws { grid-template-columns: 200px minmax(0, 1fr) 300px; } .cys .dz-graph { grid-template-columns: 186px minmax(0, 1fr); } .cys .dz-grid9 { grid-template-columns: repeat(9, 40px); } .cys .dz-slot { width: 40px; height: 40px; } .cys .dz-slot canvas { width: 28px; height: 28px; } }
@container (max-width: 760px) {
  .cys .dz-ws { display: none; }
  .cys .dz-narrow { display: block; padding: 0 14px 28px; }
  .cys .dz-narrow .n-card { border-radius: var(--r-lg); margin-top: 12px; overflow: hidden; }
  .cys .dz-narrow .n-h { display: flex; align-items: center; gap: 12px; padding: 14px; }
  .cys .dz-narrow .n-h h1 { margin: 0; font: 600 16px/1.15 var(--display); }
  .cys .dz-narrow .n-h p { margin: 3px 0 0; font-size: 12px; color: var(--muted); }
  .cys .dz-narrow .n-sec { padding: 12px 14px; border-top: 1px solid var(--line); }
  .cys .dz-narrow .n-sec > .cys-eyebrow { display: block; margin-bottom: 8px; }
  .cys .dz-narrow .n-sec p { margin: 0 0 6px; font-size: 13px; line-height: 1.45; }
  .cys .dz-narrow .n-note { display: flex; gap: 10px; align-items: flex-start; padding: 12px 14px; font-size: 12.5px; color: var(--ink-2); border-top: 1px solid var(--line); }
  .cys .dz-narrow .n-note svg { color: var(--accent-ink); margin-top: 2px; font-size: 15px; flex: none; }
  .cys .dz-narrow .n-act { display: flex; gap: 8px; padding: 12px 14px 14px; border-top: 1px solid var(--line); } .cys .dz-narrow .n-act .cys-btn { flex: 1; height: 38px; }
  .cys .dz-narrow .n-kv { display: flex; justify-content: space-between; gap: 10px; font-size: 12px; color: var(--muted); padding: 2px 0; } .cys .dz-narrow .n-kv b { font: 500 11.5px/1.3 var(--mono); color: var(--ink); text-align: right; }
  .cys .dz-narrow .n-tabs { display: flex; gap: 8px; overflow-x: auto; padding: 12px 0 2px; }
  .cys .dz-narrow .n-tabs button { flex: none; display: flex; align-items: center; gap: 8px; padding: 6px 12px 6px 6px; border-radius: 12px; font: 500 12px/1 var(--mono); }
  .cys .dz-narrow .n-tabs button.on { border-color: var(--accent-line); background: var(--accent-soft); }
  .cys .dz-narrow .dz-grid9 { grid-template-columns: repeat(9, 1fr); gap: 3px; } .cys .dz-narrow .dz-slot { width: auto; height: auto; aspect-ratio: 1; } .cys .dz-narrow .dz-slot canvas { width: 70%; height: 70%; }
}
@media (prefers-reduced-motion: reduce) { .cys .dz-glint { animation: none; opacity: .4; } }

toolu_018dCwXXEiawMGMiH93DFmkU.content:
/* Cyrus designer studios (r27): Item Designer, Menu + Quest designers, Boss designer. Ported from the v2 mockups
   (/root/agent-notes/cyrus-designs/v2/src/item-designer.html, menu-quest.html, v2.css) onto the shipped studio tokens
   (./studios.css: .cys, cys-glass, cys-tag, ...). Every class is dz-*. One accent (violet = selected / primary); cyan only
   means "now" (the simulator playhead); green / amber / red only mean pass / warn / fail. */

.cys .dz-ws { flex: 1; min-height: 0; display: grid; grid-template-columns: 220px minmax(0, 1fr) 324px; gap: 12px; padding: 4px 14px 14px; }
.cys .dz-col { display: flex; flex-direction: column; gap: 12px; min-height: 0; min-width: 0; }
.cys .dz-col.scroll { overflow: auto; } .cys .dz-col.scroll > .cys-panel { flex: none; }
.cys .dz-scroll { overflow: auto; min-height: 0; }
.cys .dz-body { padding: 0 12px 12px; }
.cys .cys-ph .n { font: 500 10px/1 var(--mono); padding: 3px 6px; border-radius: 5px; border: 1px solid var(--line-2); color: var(--muted); }
.cys .dz-mono { font: 500 11px/1.3 var(--mono); color: var(--muted); }
.cys .dz-sub { font-size: 11.5px; color: var(--muted); }
.cys .mct { color: var(--mc); text-shadow: 1px 1px 0 color-mix(in srgb, var(--mc) 25%, #000); font-weight: 600; }
html[data-theme="light"] .cyrus-root .cys .mct { background: #1b1430; padding: 2px 7px; border-radius: 6px; text-shadow: 1px 1px 0 rgb(0 0 0 / .5); box-decoration-break: clone; -webkit-box-decoration-break: clone; }
.cys canvas.pxi { image-rendering: pixelated; flex: none; display: block; }

/* left lists */
.cys .dz-row { display: flex; align-items: center; gap: 10px; padding: 7px 8px; border-radius: var(--r); color: var(--ink-2); width: 100%; text-align: left; }
.cys button.dz-row:hover { background: rgb(var(--glow) / .07); }
.cys .dz-row.on { background: rgb(var(--glow) / .13); box-shadow: inset 0 0 0 1px rgb(var(--glow) / .22); color: var(--ink); }
.cys .dz-row .tx { flex: 1; min-width: 0; }
.cys .dz-row .tx b { display: block; font: 500 12.5px/1.2 var(--mono); color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cys .dz-row .tx b.sans { font-family: var(--font-inter), sans-serif; font-weight: 600; }
.cys .dz-row .tx small { display: block; font: 400 10.5px/1.3 var(--mono); color: var(--muted); margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cys .dz-thumb { flex: none; width: 32px; height: 32px; border-radius: 8px; display: grid; place-items: center; background: repeating-conic-gradient(var(--check-a) 0 25%, var(--check-b) 0 50%) 0 0 / 8px 8px; border: 1px solid var(--line); overflow: hidden; color: var(--muted); font-size: 15px; }
.cys .dz-thumb.plain { background: var(--well); }
.cys .dz-thumb canvas { width: 24px; height: 24px; }
.cys .dz-addb { display: flex; align-items: center; justify-content: center; gap: 6px; height: 30px; width: 100%; border-radius: 10px; border: 1px dashed var(--line-2); color: var(--muted); font-size: 11.5px; }
.cys .dz-addb:hover:not(:disabled) { color: var(--ink); border-color: var(--line-3); }
.cys .dz-addb:disabled { opacity: .5; cursor: not-allowed; }
.cys .dz-recipe { display: grid; grid-template-columns: repeat(3, 30px); gap: 3px; }
.cys .dz-recipe span { width: 30px; height: 30px; border-radius: 7px; background: var(--well); border: 1px solid var(--line); display: grid; place-items: center; }
.cys .dz-recipe canvas { width: 20px; height: 20px; }
.cys .dz-aref { display: flex; flex-direction: column; gap: 6px; padding: 0 12px 12px; }
.cys .dz-arow { display: flex; align-items: center; gap: 9px; padding: 6px 8px 6px 6px; border-radius: var(--r); border: 1px solid var(--line); background: var(--well); }
.cys .dz-arow .dz-thumb { width: 34px; height: 34px; } .cys .dz-arow .dz-thumb canvas { width: 26px; height: 26px; }
.cys .dz-arow .tx { flex: 1; min-width: 0; } .cys .dz-arow .tx b { display: block; font: 500 11.5px/1.2 var(--mono); color: var(--ink); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cys .dz-arow .tx small { display: block; font-size: 10.5px; color: var(--muted); margin-top: 2px; }
.cys .dz-wave { width: 26px; height: 18px; color: var(--accent); }

/* item header */
.cys .dz-ihead { display: grid; grid-template-columns: 68px minmax(0, 1fr) auto; gap: 14px; padding: 12px 14px; align-items: center; }
.cys .dz-ibig { width: 68px; height: 68px; border-radius: 14px; display: grid; place-items: center; background: repeating-conic-gradient(var(--check-a) 0 25%, var(--check-b) 0 50%) 0 0 / 12px 12px; border: 1px solid var(--line-2); position: relative; overflow: hidden; }
.cys .dz-ibig canvas { width: 52px; height: 52px; }
.cys .dz-glint { position: absolute; inset: 0; background: linear-gradient(115deg, transparent 30%, rgb(196 120 255 / .45) 45%, transparent 60%); background-size: 260% 100%; mix-blend-mode: screen; animation: dz-glint 3.6s linear infinite; pointer-events: none; }
@keyframes dz-glint { from { background-position: 130% 0; } to { background-position: -130% 0; } }
.cys .dz-iname { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; } .cys .dz-iname .mct { font: 600 19px/1.1 var(--display); }
.cys .dz-ilore { margin: 4px 0 0; font-size: 11.5px; color: var(--muted); font-style: italic; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cys .dz-istats { display: grid; grid-template-columns: auto auto; gap: 4px 12px; font-size: 11.5px; color: var(--muted); padding-left: 14px; border-left: 1px solid var(--line); }
.cys .dz-istats b { font: 500 11.5px/1.2 var(--mono); color: var(--ink); text-align: right; }

/* meters */
.cys .dz-meters { display: grid; gap: 8px 14px; }
.cys .dz-meter-h { display: flex; justify-content: space-between; align-items: baseline; font-size: 11px; color: var(--muted); gap: 6px; white-space: nowrap; }
.cys .dz-meter-h b { font: 500 11px/1 var(--mono); color: var(--ink); } .cys .dz-meter-h b i { font-style: normal; color: var(--faint); }
.cys .dz-meter-t { height: 4px; border-radius: 4px; background: var(--line-2); margin-top: 5px; overflow: hidden; }
.cys .dz-meter-t i { display: block; height: 100%; border-radius: 4px; background: var(--accent); transition: width .25s var(--ease-out-expo, ease); }
.cys .dz-meter.warn .dz-meter-t i { background: var(--warn); } .cys .dz-meter.bad .dz-meter-t i { background: var(--bad); } .cys .dz-meter.bad .dz-meter-h b { color: var(--bad); }

/* issues */
.cys .dz-issues { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
.cys .dz-issue { display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; gap: 2px 10px; padding: 9px 10px; border-radius: var(--r); border: 1px solid var(--line); background: var(--well); }
.cys .dz-issue .ic { width: 18px; height: 18px; border-radius: 50%; display: grid; place-items: center; font-size: 11px; margin-top: 1px; }
.cys .dz-issue.err .ic { color: var(--bad); background: var(--bad-soft); } .cys .dz-issue.warn .ic { color: var(--warn); background: var(--warn-soft); }
.cys .dz-issue.ok .ic { color: var(--ok); background: var(--ok-soft); } .cys .dz-issue.info .ic { color: var(--muted); box-shadow: inset 0 0 0 1px var(--line-2); }
.cys .dz-issue code { font: 500 11.5px/1.3 var(--mono); color: var(--ink); overflow: hidden; text-overflow: ellipsis; }
.cys .dz-issue .path { font: 400 10.5px/1.3 var(--mono); color: var(--faint); text-align: right; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 180px; }
.cys .dz-issue .m { grid-column: 2 / 4; font-size: 11.5px; color: var(--muted); line-height: 1.45; }

/* stepper */
.cys .dz-stp { display: inline-flex; align-items: center; height: 26px; border-radius: 8px; border: 1px solid var(--line-2); background: var(--well); }
.cys .dz-stp button { width: 22px; height: 24px; display: grid; place-items: center; color: var(--muted); font-size: 12px; } .cys .dz-stp button:hover { color: var(--ink); }
.cys .dz-stp input { width: 50px; height: 24px; border: 0; background: transparent; text-align: center; font: 500 11.5px/1 var(--mono); color: var(--ink); outline: none; }
.cys .dz-stp.err { border-color: color-mix(in srgb, var(--bad) 60%, transparent); box-shadow: 0 0 0 3px var(--bad-soft); }
.cys .dz-stp.chg { border-color: var(--accent-line); }
.cys .dz-txt { height: 26px; border-radius: 8px; border: 1px solid var(--line-2); background: var(--well); padding: 0 8px; font: 500 11.5px/1 var(--mono); color: var(--ink); outline: none; width: 160px; }
.cys .dz-txt.chg { border-color: var(--accent-line); } .cys .dz-txt.err { border-color: var(--bad); }
.cys .dz-txt:focus, .cys .dz-stp:focus-within { box-shadow: 0 0 0 3px rgb(var(--glow) / .15); }

/* notes */
.cys .dz-note { display: flex; gap: 9px; align-items: flex-start; padding: 9px 11px; border-radius: var(--r); font-size: 11.5px; line-height: 1.45; color: var(--ink-2); border: 1px solid var(--line); background: rgb(var(--glow) / .04); }
.cys .dz-note > svg { margin-top: 1px; font-size: 14px; color: var(--muted); }
.cys .dz-note.warn { border-color: color-mix(in srgb, var(--warn) 35%, transparent); background: var(--warn-soft); } .cys .dz-note.warn > svg { color: var(--warn); }
.cys .dz-note.bad { border-color: color-mix(in srgb, var(--bad) 35%, transparent); background: var(--bad-soft); } .cys .dz-note.bad > svg { color: var(--bad); }
.cys .dz-note b { color: var(--ink); font-weight: 600; }
.cys .dz-banner { display: flex; align-items: center; gap: 10px; padding: 8px 12px; border-radius: var(--r-md); border: 1px solid var(--accent-line); background: var(--accent-soft); font-size: 12px; color: var(--ink-2); flex: none; }
.cys .dz-banner.warn { border-color: color-mix(in srgb, var(--warn) 40%, transparent); background: var(--warn-soft); }
.cys .dz-banner > svg { color: var(--accent-ink); font-size: 15px; flex: none; } .cys .dz-banner.warn > svg { color: var(--warn); }
