  .cys .dz-narrow .n-note svg { color: var(--accent-ink); margin-top: 2px; font-size: 15px; flex: none; }
  .cys .dz-narrow .n-act { display: flex; gap: 8px; padding: 12px 14px 14px; border-top: 1px solid var(--line); } .cys .dz-narrow .n-act .cys-btn { flex: 1; height: 38px; }
  .cys .dz-narrow .n-kv { display: flex; justify-content: space-between; gap: 10px; font-size: 12px; color: var(--muted); padding: 2px 0; } .cys .dz-narrow .n-kv b { font: 500 11.5px/1.3 var(--mono); color: var(--ink); text-align: right; }
  .cys .dz-narrow .n-tabs { display: flex; gap: 8px; overflow-x: auto; padding: 12px 0 2px; }
  .cys .dz-narrow .n-tabs button { flex: none; display: flex; align-items: center; gap: 8px; padding: 6px 12px 6px 6px; border-radius: 12px; font: 500 12px/1 var(--mono); }
  .cys .dz-narrow .n-tabs button.on { border-color: var(--accent-line); background: var(--accent-soft); }
  .cys .dz-narrow .dz-grid9 { grid-template-columns: repeat(9, 1fr); gap: 3px; } .cys .dz-narrow .dz-slot { width: auto; height: auto; aspect-ratio: 1; } .cys .dz-narrow .dz-slot canvas { width: 70%; height: 70%; }
}
@media (prefers-reduced-motion: reduce) { .cys .dz-glint { animation: none; opacity: .4; } }

