import { DI } from "./icons";
import "./designers.css";

export type DesignerTab = "items" | "menus" | "quests" | "bosses";
export const designerHref = (mod: Pick<StudioMod, "buildId">, t: DesignerTab, q = "") => `/dashboard/cyrus/${mod.buildId}/studio/${t === "quests" ? "menus" : t}${t === "quests" ? `?tab=quests${q ? `&${q.replace(/^\?/, "")}` : ""}` : q}`;

// ---------------------------------------------------------------------------------------------------- the shell
const TAB_ICON: Record<DesignerTab, string> = { items: "sword", menus: "slots", quests: "scroll", bosses: "skull" };
const TAB_LABEL: Record<DesignerTab, string> = { items: "Items", menus: "Menus", quests: "Quests", bosses: "Bosses" };
export function DesignerShell({ mod, tab, current, onTab, showBosses, children }: { mod: StudioMod; tab: DesignerTab; current: string; onTab?: (t: DesignerTab) => void; showBosses: boolean; children: ReactNode }) {
  const tabs: DesignerTab[] = ["items", "menus", "quests", ...(showBosses ? (["bosses"] as const) : [])];
  const seg = (
    <div className="cys-seg cys-soft hide-n" aria-label="Designer">
      {tabs.map((t) => (onTab && (t === "menus" || t === "quests") && (tab === "menus" || tab === "quests")
        ? <button key={t} type="button" className={tab === t ? "on" : ""} aria-pressed={tab === t} onClick={() => onTab(t)}><DI n={TAB_ICON[t]} />{TAB_LABEL[t]}</button>
        : <Link key={t} href={designerHref(mod, t)} className={tab === t ? "on" : ""} aria-current={tab === t ? "page" : undefined}><DI n={TAB_ICON[t]} />{TAB_LABEL[t]}</Link>))}
    </div>
  );
  return <StudioShell mod={mod} current={current} studio={null} seg={seg} icon={<DI n={TAB_ICON[tab]} />} kind={`designer-${tab}`}>{children}</StudioShell>;
}

// ------------------------------------------------------------------------------------------------- the working copy
export type Designer = ReturnType<typeof useDesigner>;
const CheckCtx = createContext<Analysis | null>(null);
export const useAnalysis = () => useContext(CheckCtx);

export function useDesigner(mod: StudioMod) {
  const toast = useToast();
  const [view, setView] = useState<DesignerView | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [files, setFiles] = useState<DesignFile[]>([]);
  const [analysis, setAnalysis] = useState<Analysis | null>(null);
  const [checking, setChecking] = useState(false);
  const [saving, setSaving] = useState(false);
  const [draftNote, setDraftNote] = useState<{ kind: "restored" | "stale"; at: string } | null>(null);
  const [autosave, setAutosave] = useState<{ state: "idle" | "saving" | "saved" | "off"; at?: string; reason?: string }>({ state: "idle" });
  const [textures, setTextures] = useState<Record<string, Raster>>({});
  const as = useRef<AutosaveState>(autosaveInit());
  const seq = useRef(0);

  const load = useCallback(async () => {
    try {
      const v = await designerApi.view(mod.rootId);
      setView(v);
      let work = v.saved;
      if (v.draft && !v.draft.stale) { work = v.draft.files; setDraftNote({ kind: "restored", at: v.draft.updatedAt }); }
      else if (v.draft?.stale) setDraftNote({ kind: "stale", at: v.draft.updatedAt });
      else setDraftNote(null);
      setFiles(work);
      as.current = autosaveInit(canonical(work));
      setAnalysis(v.analysis);
      if (v.draft && !v.draft.stale && v.project) setAnalysis(await designerApi.check(v.project.id, work).catch(() => v.analysis));
    } catch (e) { setErr((e as Error).message); }
    // the mod's real textures, for item icons (the studios' own view; never blocks the designer)
    studioApi.assets(mod.rootId).then((a) => setTextures(Object.fromEntries(a.textures.map((t) => [t.key, renderDoc(t.doc)])))).catch(() => undefined);
  }, [mod.rootId]);
  useEffect(() => { void load(); }, [load]);

  const pid = view?.project?.id ?? null;
  // server check of the working copy (debounced)
  useEffect(() => {
    if (!pid || !view) return;
    const n = ++seq.current;
    setChecking(true);
    const t = window.setTimeout(async () => {
      try { const a = await designerApi.check(pid, files); if (n === seq.current) setAnalysis(a); }
      catch (e) { if (n === seq.current) toast((e as Error).message, true); }
      finally { if (n === seq.current) setChecking(false); }
    }, 260);
    return () => window.clearTimeout(t);
  }, [files, pid]); // eslint-disable-line react-hooks/exhaustive-deps

  // autosave the draft
  useEffect(() => {
    if (!pid || !view || autosave.state === "off") return;
    as.current = autosaveEdit(as.current, Date.now(), canonical(files));
    const due = autosaveDueIn(as.current, Date.now());
    if (due === null) return;
    const t = window.setTimeout(async () => {
      const sha = canonical(files);
      setAutosave({ state: "saving" });
      try {
        const r = await designerApi.putDraft(pid, files, view.headRevisionId);
        as.current = autosaveDone(as.current, sha);
        setAutosave({ state: "saved", at: r.updatedAt ?? new Date().toISOString() });
      } catch (e) { setAutosave({ state: "off", reason: (e as Error).message }); }
    }, due);
    return () => window.clearTimeout(t);
  }, [files, pid]); // eslint-disable-line react-hooks/exhaustive-deps

  const saved = view?.saved ?? [];
  const changed = useMemo(() => changedIds(saved, files), [saved, files]);
  const savedParams = useMemo(() => new Map((view?.analysis?.params ?? []).map((p) => [p.path, p])), [view]);
  const params = analysis?.params ?? view?.analysis?.params ?? [];

  const save = useCallback(async (): Promise<boolean> => {
    if (!pid || !view) return false;
    setSaving(true);
    try {
      const r = await designerApi.save(pid, files, view.headRevisionId);
      toast(`Saved as revision ${r.seq}${r.configOnly ? " (config.yml only)" : ` (${r.javaChanged.length} Java files change)`}`);
      await load();
      return true;
    } catch (e) {
      if (e instanceof ApiError && e.body.analysis) setAnalysis(e.body.analysis as Analysis);
      toast((e as Error).message, true);
      return false;
    } finally { setSaving(false); }
  }, [pid, view, files, load, toast]);
  const discard = useCallback(async () => {
    setFiles(saved);
    as.current = autosaveInit(canonical(saved));
    setDraftNote(null);
    if (pid) await designerApi.dropDraft(pid).catch(() => undefined);
  }, [saved, pid]);

  return { view, err, files, setFiles, analysis, checking, saving, changed, saved, savedParams, params, save, discard, draftNote, setDraftNote, autosave, textures, pid, reload: load };
}

export function DesignerContext({ d, children }: { d: Designer; children: ReactNode }) {
  return <CheckCtx.Provider value={d.analysis}>{children}</CheckCtx.Provider>;
}

// ---------------------------------------------------------------------------------------------------- small parts
export const MC: Record<string, string> = { black: "#000000", dark_blue: "#0000AA", dark_green: "#00AA00", dark_aqua: "#00AAAA", dark_red: "#AA0000", dark_purple: "#AA00AA", gold: "#FFAA00", gray: "#AAAAAA", dark_gray: "#555555", blue: "#5555FF", green: "#55FF55", aqua: "#55FFFF", red: "#FF5555", light_purple: "#FF55FF", yellow: "#FFFF55", white: "#FFFFFF" };
export function McText({ t, className = "" }: { t: { text: string; color?: string } | undefined; className?: string }) {
  if (!t) return null;
  return <span className={`mct ${className}`} style={{ ["--mc" as string]: MC[t.color ?? "white"] ?? t.color ?? "#fff" }}>{t.text}</span>;
}

/** The icon of an item reference: the mod's own texture (by model key or design key) when it has one, else a placeholder. */
export function useIcon(textures: Record<string, Raster>) {
  return useCallback((ref: string | undefined, model?: string): Raster => {
    const k = (model ?? "").split(":")[1] ?? "";
    if (k && textures[k]) return textures[k];
    const id = String(ref ?? "").replace(/^minecraft:/, "");
    if (textures[id]) return textures[id];
    return placeholderIcon(ref ?? "");
  }, [textures]);
}
export function Ico({ r, size = 24, className }: { r: Raster; size?: number; className?: string }) {
  return <RasterCanvas raster={r} className={`pxi ${className ?? ""}`} style={{ width: size, height: size }} />;
}

export function Meter({ label, used, cap, title }: { label: string; used: number; cap: number; title?: string }) {
  const pct = Math.min(100, (used / Math.max(1, cap)) * 100);
  const tone = used > cap ? "bad" : pct >= 85 ? "warn" : "";
  return (
    <div className={`dz-meter ${tone}`} title={title}>
      <div className="dz-meter-h"><span>{label}</span><b>{used}<i>/{cap}</i></b></div>
      <div className="dz-meter-t" role="meter" aria-label={label} aria-valuenow={used} aria-valuemin={0} aria-valuemax={cap}><i style={{ width: `${pct}%` }} /></div>
    </div>
  );
}

export function IssueRow({ i, tone }: { i: GpIssue; tone: "err" | "warn" }) {
  return (
    <li className={`dz-issue ${tone}`}>
      <span className="ic"><DI n={tone === "err" ? "close" : "warn"} /></span><code>{i.code}</code><span className="path" title={i.path}>{i.path}</span>
      <span className="m">{i.message}</span>
    </li>
  );
}

/** A numeric parameter stepper (or a text field) bound to a config path. */
export function ParamField({ p, was, onSet, compact }: { p: Param; was?: number | string; onSet: (v: number | string) => void; compact?: boolean }) {
  const [txt, setTxt] = useState(String(p.value));
  useEffect(() => { setTxt(String(p.value)); }, [p.value]);
  const changed = was !== undefined && String(was) !== String(p.value);
  if (p.kind === "text" || p.kind === "sound") {
    const bad = !txt.length || txt.length > p.max;
    return <input className={`dz-txt ${bad ? "err" : changed ? "chg" : ""}`} value={txt} aria-label={p.label} maxLength={p.max + 20} onChange={(e) => setTxt(e.target.value)} onBlur={() => { if (txt !== String(p.value)) onSet(txt); }} onKeyDown={(e) => { if (e.key === "Enter") (e.target as HTMLInputElement).blur(); }} style={compact ? { width: 130 } : undefined} />;
  }
  const v = Number(p.value);
  const bad = !Number.isFinite(v) || v < p.min || v > p.max;
  const span = p.max - p.min;
  const step = p.kind === "num" ? (span <= 4 ? 0.1 : span <= 40 ? 0.5 : 1) : span > 2000 ? 20 : 1;
  const set = (n: number) => onSet(p.kind === "num" ? +n.toFixed(2) : Math.round(n));
  return (
    <span className={`dz-stp ${bad ? "err" : changed ? "chg" : ""}`}>
      <button type="button" aria-label={`decrease ${p.label}`} onClick={() => set(v - step)}><DI n="minus" /></button>
      <input value={txt} inputMode="decimal" aria-label={p.label} aria-invalid={bad} onChange={(e) => setTxt(e.target.value)} onBlur={() => { const n = Number(txt); if (txt.trim() !== "" && Number.isFinite(n) && n !== v) set(n); else setTxt(String(p.value)); }} onKeyDown={(e) => { if (e.key === "Enter") (e.target as HTMLInputElement).blur(); }} />
      <button type="button" aria-label={`increase ${p.label}`} onClick={() => set(v + step)}><DI n="plus" /></button>
    </span>
  );
}
export const rangeText = (p: Param) => (p.kind === "text" ? `1–${p.max} chars` : p.kind === "sound" ? "namespaced key" : `${p.min}–${p.max}${p.kind === "ticks" ? " ticks" : ""}`);

/** What saving does now (config.yml only, or the Java files a structural edit rebuilds) + Discard / Save. */
export function PendingBar({ d, labels }: { d: Designer; labels: (id: string) => string }) {
  const a = d.analysis;
  const errors = a ? a.files.reduce((n, f) => n + f.errors.length, 0) + a.modErrors.length + (a.compile.ok ? 0 : a.compile.errors.length) : 0;
  const nextSeq = (d.view?.headSeq ?? 0) + 1;
  if (!d.changed.length) {
    return <div className="dz-pend idle"><b>No changes.</b> Edit here or in the editor; value edits change only <span className="mono">config.yml</span>.</div>;
  }
  const diff = a?.diff;
  const valueEdits = diff ? diff.configOnly : false;
  return (
    <div className="dz-pend" role="status">
      <b>{d.changed.length === 1 ? labels(d.changed[0]) : `${d.changed.length} designs`} changed</b>{diff ? (valueEdits ? " · no Java change" : ` · ${diff.javaChanged.length} Java file${diff.javaChanged.length === 1 ? "" : "s"} change`) : ""}
      <div className="files" title="What the next build ships: the server recompiled the whole mod with your edit">
        {diff ? (
          valueEdits
            ? <><span className="ch">M config.yml</span> · config_version {diff.configVersion.from} → {diff.configVersion.to} · {diff.unchanged} files unchanged</>
            : <><span className="ch">{diff.javaChanged.slice(0, 3).map((p) => `M ${p.split("/").pop()}`).join(" · ")}{diff.javaChanged.length > 3 ? ` +${diff.javaChanged.length - 3}` : ""}</span> · config_version {diff.configVersion.from} → {diff.configVersion.to} · needs a rebuild</>
        ) : d.checking ? "checking…" : "not compiled (fix the errors first)"}
      </div>
      <div className="act">
        <button type="button" className="cys-btn sm" onClick={() => void d.discard()}>Discard</button>
        <button type="button" className="cys-btn sm primary" disabled={!!errors || d.checking || d.saving || !a} onClick={() => void d.save()}>
          <DI n="check" />{errors ? `Fix ${errors} error${errors === 1 ? "" : "s"} first` : d.saving ? "Saving…" : `Save as revision ${nextSeq}`}
        </button>
      </div>
      <p className="cys-hint" style={{ margin: "8px 0 0" }}>Saved revisions stay in Cyrus. Servers get designer edits once builds start from them (not wired yet).</p>
    </div>
  );
}

/** Autosave + restored-draft line under the header. */
export function DraftLine({ d }: { d: Designer }) {
  if (d.draftNote?.kind === "stale") {
    return (
      <div className="dz-banner warn" role="status"><DI n="warn" /><span><b>An older draft exists.</b> The mod changed after it was autosaved, so it was not restored.</span><span className="sp" />
        <button type="button" className="cys-btn xs" onClick={() => { void d.discard(); }}>Discard draft</button></div>
    );
  }
  if (d.draftNote?.kind === "restored" && d.changed.length) {
    return (
      <div className="dz-banner" role="status"><DI n="restore" /><span><b>Restored your unsaved edits</b> from {new Date(d.draftNote.at).toLocaleString()}.</span><span className="sp" />
        <button type="button" className="cys-btn xs" onClick={() => void d.discard()}>Discard</button></div>
    );
  }
  return null;
}
export const autosaveText = (d: Designer) => (d.autosave.state === "off" ? "autosave off" : d.autosave.state === "saving" ? "saving draft…" : d.autosave.state === "saved" && d.changed.length ? "draft saved" : d.changed.length ? "unsaved" : "saved");

export function Loading({ what }: { what: string }) { return <div className="cys-empty" style={{ margin: "auto" }} aria-busy="true">Loading {what}…</div>; }
export function Failed({ msg }: { msg: string }) { return <div className="cys-empty" style={{ margin: "auto" }}><DI n="warn" /><p>{msg}</p></div>; }
export function NoDesigns({ mod, what }: { mod: StudioMod; what: string }) {
  return (
    <main className="dz-ws" style={{ gridTemplateColumns: "minmax(0, 1fr)" }}>
      <section className="cys-panel cys-glass" style={{ flex: 1, display: "grid", placeItems: "center" }}>
        <div className="cys-empty" style={{ maxWidth: 420 }}><DI n="graph" />
          <p><b>This mod has no {what} yet.</b></p>
          <p className="cys-hint">Cyrus writes {what} when a build asks for them (for example “a staff that pulls marked mobs in”). The designer then lets you change every value without a rebuild.</p>
          <Link className="cys-btn sm" href={`/dashboard/cyrus/${mod.buildId}`}>Back to the mod</Link>
        </div>
      </section>
    </main>
  );
}

