"use client";
// Cyrus ITEM DESIGNER (r27), full page. Layout and anatomy follow the v2 mockup (cyrus-designs/v2/item-designer.html,
// not yet reviewed by the owner): left = the mod's item designs, the selected item's abilities, marks, asset chips
// (they follow the asset plan gates; the designer itself is not plan-gated) and recipe; centre = the item header, the
// ability graph (When -> Only if -> Do) with the per-activation budget meters and the validator's real codes, and the
// prompt dock (settings-only requests are applied without a model); right = the display-context preview and the
// Parameters (config.yml paths + ranges) / Simulator / Checks tabs, with the pending-change bar. Phones get the
// read-only summary + approve / reject (approving saves the autosaved draft as a revision).
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import Link from "next/link";
import type { Ability, Action, Condition, ItemDesign } from "@/lib/cyrus/designer/spec";
import type { Param } from "@/lib/cyrus/designer/compile";
import type { GpIssue } from "@/lib/cyrus/designer/gameplay/spec";
import { ACTION_TEMPLATES, CONDITION_TEMPLATES, childLists, insertAction, insertCondition, isItem, removeNode, replaceFile, setParamValue, type DesignFile } from "@/lib/cyrus/designer/studio/edit";
import { contextScene as _cs, PREVIEW_CONTEXTS, previewDisplays, previewModel, type PreviewContext } from "@/lib/cyrus/itemmodel/preview";
import { CyrusTokenEstimate } from "@/components/cyrus-tokens";
import { CyrusGlyph } from "@/components/cyrus/icons/CyrusLogo";
import { STUDIO_DEFAULTS } from "@/lib/cyrus/studios/access";
import { useToast, studioHref, type StudioMod } from "../studios/StudioShell";
import { ContextCanvas } from "../studios/TextureStudio";
import { designerApi, type EditPlan, type ItemSimResult, type ItemStep, type SimButton } from "./api";
import { DesignerContext, DesignerShell, DraftLine, Failed, Ico, IssueRow, Loading, McText, Meter, NoDesigns, ParamField, PendingBar, autosaveText, rangeText, useDesigner, useIcon, type Designer } from "./shared";
import { PLACEHOLDER_NOTE } from "./pixel-icons";
import { DI } from "./icons";

void _cs;
const camel = (s: string) => s.split("_").filter(Boolean).map((p) => p[0].toUpperCase() + p.slice(1)).join("");
const abilityFile = (item: string, ab: string) => `abilities/${camel(item)}${camel(ab)}.java`;
const itemFile = (item: string) => `items/${camel(item)}Item.java`;
const bare = (s: string) => String(s ?? "").replace(/^minecraft:/, "");
const secs = (t: number) => `${+(t / 20).toFixed(2)} s`;

// ------------------------------------------------------------------------------------------------- vocabulary
const TRIG: Record<string, [string, string]> = {
  right_click: ["Right-click", "Right-click with the item."], left_click_hit_entity: ["On hit", "Left-click hits an entity."], sneak_right_click: ["Sneak + right-click", "Right-click while sneaking."],
  kill_entity: ["On kill", "You kill an entity."], projectile_hit: ["Projectile hit", "This item's projectile hits something."], held_interval: ["While held", "Runs on a timer while held."],
  join: ["On join", "When you join with the item."], death: ["On death", "When you die with the item."], item_consume: ["On consume", "Eat or drink the item."], charge_release: ["Charge and release", "Hold sneak, then right-click."],
};
const ACT: Record<string, { label: string; ic: string; sum: (a: Action) => string }> = {
  damage: { label: "Damage", ic: "sword", sum: (a) => `the ${("target" in a && a.target) || "target"}` },
  heal: { label: "Heal", ic: "heart", sum: (a) => `the ${("target" in a && a.target) || "self"}` },
  potion_effect: { label: "Effect", ic: "flask", sum: (a) => (a.type === "potion_effect" ? `${a.effect} on the ${a.target ?? "self"}` : "") },
  knockback: { label: "Knockback", ic: "target", sum: (a) => `the ${("target" in a && a.target) || "target"}` },
  pull_to: { label: "Pull", ic: "target", sum: (a) => (a.type === "pull_to" ? `to the ${a.to === "point" ? "aim point" : "player"}` : "") },
  push_from: { label: "Push", ic: "target", sum: (a) => (a.type === "push_from" ? `away from the ${a.from === "point" ? "aim point" : "player"}` : "") },
  teleport_short: { label: "Blink", ic: "arrowR", sum: () => "you, along your look" },
  launch_projectile: { label: "Launch", ic: "target", sum: (a) => (a.type === "launch_projectile" ? `a ${a.kind.replace("_", " ")}` : "") },
  spawn_particles: { label: "Particles", ic: "sparkle", sum: (a) => (a.type === "spawn_particles" ? `at the ${a.at === "point" ? "point" : a.at ?? "self"}` : "") },
  play_sound: { label: "Sound", ic: "volume", sum: (a) => (a.type === "play_sound" ? `at the ${a.at === "point" ? "aim point" : a.at ?? "self"}` : "") },
  send_message: { label: "Message", ic: "note", sum: (a) => (a.type === "send_message" ? `“${a.text}”` : "") },
  title: { label: "Title", ic: "note", sum: (a) => (a.type === "title" ? `“${a.title}”` : "") },
  actionbar: { label: "Action bar", ic: "note", sum: (a) => (a.type === "actionbar" ? `“${a.text}”` : "") },
  give_item: { label: "Give", ic: "gift", sum: (a) => (a.type === "give_item" ? bare(a.item) : "") },
  set_cooldown: { label: "Set cooldown", ic: "clock", sum: (a) => (a.type === "set_cooldown" ? `of ${a.ability ?? "this ability"}` : "") },
  consume_charge: { label: "Spend charge", ic: "coin", sum: (a) => (a.type === "consume_charge" ? `of ${a.ability ?? "this ability"}` : "") },
  apply_mark: { label: "Apply mark", ic: "flag", sum: (a) => (a.type === "apply_mark" ? `mark the target "${a.mark}"` : "") },
  query_marked: { label: "For each marked", ic: "loopq", sum: (a) => (a.type === "query_marked" ? `each "${a.mark}" target near ${a.around === "point" ? "the point" : "you"}` : "") },
  query_nearby: { label: "For each nearby", ic: "loopq", sum: (a) => (a.type === "query_nearby" ? `each ${(a.kinds ?? ["living"]).join("/")} near ${a.around === "point" ? "the point" : "you"}` : "") },
  delayed: { label: "Later", ic: "clock", sum: () => "then run" },
  branch: { label: "If", ic: "branch", sum: (a) => (a.type === "branch" ? a.if.map(condText).join(" and ") : "") },
};
function condText(c: Condition): string {
  const n = c.negate ? "not " : "";
  switch (c.type) {
    case "cooldown_ready": return `${n}cooldown of ${c.ability ?? "this"} ready`;
    case "has_permission": return `${n}has permission ${c.node}`;
    case "target_is": return `target is ${n}${[...(c.kinds ?? []), ...(c.types ?? []).map(bare)].join(" or ")}`;
    case "world_in": return `${n}in ${c.worlds.join(", ")}`;
    case "health_below": return `${c.subject} health ${n}below ${Math.round(c.fraction * 100)}%`;
    case "health_above": return `${c.subject} health ${n}above ${Math.round(c.fraction * 100)}%`;
    case "item_identity": return `${n}${c.item} in ${c.slot.replace("_", " ")}`;
    case "sneaking": return `${n}sneaking`;
    case "charges_available": return `${n}${c.amount} charge${c.amount === 1 ? "" : "s"} left`;
    case "random_chance": return `${n}chance ${Math.round(c.chance * 100)}%`;
    case "time_of_day": return `${n}time ${c.from}–${c.to}`;
  }
}
const STRUCT_SKIP = new Set(["type", "actions", "then", "else", "if"]);

/** Block path of a validator issue inside ability `ai` ("trigger", "c0", "a0.n1", ...) or null. */
export function blockOfIssue(path: string, ai: number): string | null {
  const pre = `abilities[${ai}]`;
  if (!path.startsWith(pre)) return null;
  let rest = path.slice(pre.length).replace(/^\./, "");
  if (rest.startsWith("trigger")) return "trigger";
  const c = /^conditions\[(\d+)\]/.exec(rest);
  if (c) return `c${c[1]}`;
  if (/^actions\.a\d/.test(rest)) { const m = /^actions\.(a\d+(?:\.(?:n|then|else)\d+)*)/.exec(rest); return m ? m[1] : null; }
  // zod path: actions[0].actions[1].then[2]
  if (rest.startsWith("actions[")) {
    const out: string[] = [];
    let first = true;
    for (const m of rest.matchAll(/(actions|then|else)\[(\d+)\]/g)) { out.push(first ? `a${m[2]}` : m[1] === "actions" ? `n${m[2]}` : `${m[1]}${m[2]}`); first = false; }
    rest = out.join(".");
    return rest || null;
  }
  return null;
}

// --------------------------------------------------------------------------------------------------- the page
export function ItemDesigner({ mod, initialItem, showBosses }: { mod: StudioMod; initialItem: string | null; showBosses: boolean }) {
  return <DesignerShell mod={mod} tab="items" current="Item Designer" showBosses={showBosses}><Body mod={mod} initialItem={initialItem} /></DesignerShell>;
}

function Body({ mod, initialItem }: { mod: StudioMod; initialItem: string | null }) {
  const d = useDesigner(mod);
  const items = useMemo(() => d.files.filter(isItem) as ItemDesign[], [d.files]);
  const [cur, setCur] = useState<string | null>(initialItem);
  useEffect(() => { if (items.length && (!cur || !items.some((i) => i.id === cur))) setCur(items[0].id); }, [items, cur]);
  if (d.err) return <Failed msg={d.err} />;
  if (!d.view) return <Loading what="this mod's item designs" />;
  if (!d.view.project || !items.length) return <NoDesigns mod={mod} what="item designs" />;
  const item = items.find((i) => i.id === cur) ?? items[0];
  return <DesignerContext d={d}><Workspace d={d} mod={mod} items={items} item={item} setCur={setCur} /></DesignerContext>;
}

function Workspace({ d, mod, items, item, setCur }: { d: Designer; mod: StudioMod; items: ItemDesign[]; item: ItemDesign; setCur: (k: string) => void }) {
  const toast = useToast();
  const icon = useIcon(d.textures);
  const [abSel, setAbSel] = useState<string>(item.abilities[item.abilities.length - 1]?.id ?? "");
  const [blk, setBlk] = useState<string>("trigger");
  const [rtab, setRtab] = useState<"params" | "sim" | "checks">("params");
  const [view, setView] = useState<"graph" | "json">("graph");
  useEffect(() => { if (!item.abilities.some((a) => a.id === abSel)) { setAbSel(item.abilities[item.abilities.length - 1]?.id ?? ""); setBlk("trigger"); } }, [item, abSel]);
  const ab = item.abilities.find((a) => a.id === abSel) ?? null;
  const ai = ab ? item.abilities.indexOf(ab) : -1;
  const a = d.analysis;
  const rep = a?.files.find((f) => f.id === item.id);
  const itemParams = d.params.filter((p) => p.item === item.id && !p.owner);
  const apply = useCallback((r: { ok: true; files: DesignFile[] } | { ok: false; error: string }, ok?: string) => { if (r.ok) { d.setFiles(r.files); if (ok) toast(ok); } else toast(r.error, true); }, [d, toast]);
  const setParam = useCallback((path: string, v: number | string) => apply(setParamValue(d.files, path, v)), [apply, d.files]);
  const r = icon(item.base, item.assets?.model);
  const real = !!(item.assets?.model && d.textures[item.assets.model.split(":")[1] ?? ""]);

  return (
    <>
      <main className="dz-ws" aria-label="Item Designer">
        {/* LEFT */}
        <div className="dz-col scroll">
          <section className="cys-panel cys-glass cys-hairline">
            <div className="cys-ph"><span className="cys-eyebrow">Designs</span><span className="n">{items.length} / {d.view!.limits.maxItems}</span></div>
            <div className="dz-body">
              {items.map((it) => {
                const f = a?.files.find((x) => x.id === it.id);
                const tone = !f ? "" : f.errors.length ? "bad" : f.warnings.length ? "warn" : "ok";
                return (
                  <button key={it.id} type="button" className={`dz-row ${it.id === item.id ? "on" : ""}`} aria-current={it.id === item.id} onClick={() => { setCur(it.id); setBlk("trigger"); }}>
                    <span className="dz-thumb"><Ico r={icon(it.base, it.assets?.model)} /></span>
                    <span className="tx"><b>{it.id}</b><small>{bare(it.base).split("_").pop()} · {it.abilities.length} abilit{it.abilities.length === 1 ? "y" : "ies"}{d.changed.includes(it.id) ? " · edited" : ""}</small></span>
                    <span className={`cys-dot ${tone}`} title={tone === "bad" ? `${f!.errors.length} errors` : tone === "warn" ? `${f!.warnings.length} warnings` : "valid"} />
                  </button>
                );
              })}
            </div>
          </section>
          <AbilitiesPanel d={d} item={item} abSel={abSel} setAbSel={(id) => { setAbSel(id); setBlk("trigger"); }} apply={apply} />
          {!!item.marks?.length && (
            <section className="cys-panel cys-glass">
              <div className="cys-ph"><span className="cys-eyebrow">Marks</span><span className="n">{item.marks.length} / {d.view!.limits.maxMarks}</span></div>
              <div className="dz-body">{item.marks.map((m) => <div key={m.name} className="dz-row"><span className="dz-thumb plain" style={{ color: "var(--accent-ink)" }}><DI n="flag" /></span><span className="tx"><b>{m.name}</b><small>{secs(m.durationTicks)} · max {m.maxPerOwner}{m.glow ? " · glow" : ""}</small></span></div>)}</div>
            </section>
          )}
          <AssetsPanel d={d} mod={mod} item={item} icon={r} real={real} />
          {item.recipe && <RecipePanel item={item} icon={icon} />}
        </div>

        {/* CENTRE */}
        <div className="dz-col">
          <DraftLine d={d} />
          <section className="cys-panel cys-glass cys-hairline" aria-label="Item">
            <div className="dz-ihead">
              <div className="dz-ibig" title={real ? "This mod's texture" : PLACEHOLDER_NOTE}><Ico r={r} size={52} />{item.glint && <i className="dz-glint" />}</div>
              <div style={{ minWidth: 0 }}>
                <div className="dz-iname"><McText t={item.name} />{item.rarity && <span className="cys-tag acc">{item.rarity}</span>}{item.glint && <span className="cys-tag dim">glint</span>}</div>
                <div className="dz-mono" style={{ marginTop: 5, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{d.view!.project!.namespace}:{item.id} · {item.base}</div>
                {!!item.lore?.length && <p className="dz-ilore" title={item.lore.map((l) => l.text).join(" / ")}>{item.lore.map((l) => l.text).join(" ")}</p>}
              </div>
              {item.stats && (
                <div className="dz-istats" title="Stats are baked into an item when it is created; changing them later does not alter items players already hold (structure: rebuilds the item class)">
                  {item.stats.damage !== undefined && <><span>Damage</span><b>{item.stats.damage}</b></>}
                  {item.stats.attackSpeed !== undefined && <><span>Attack speed</span><b>{item.stats.attackSpeed}</b></>}
                  {item.stats.durability !== undefined && <><span>Durability</span><b>{item.stats.durability}</b></>}
                  {item.stats.unbreakable && <><span>Unbreakable</span><b>yes</b></>}
                </div>
              )}
            </div>
          </section>
          <section className="cys-panel cys-glass dz-gwrap" aria-label="Ability graph">
            {ab ? (
              <AbilityGraph d={d} item={item} ab={ab} ai={ai} blk={blk} setBlk={setBlk} view={view} setView={setView} setParam={setParam} apply={apply} issues={rep?.errors ?? []} warnings={rep?.warnings ?? []} params={itemParams} />
            ) : (
              <div className="cys-empty" style={{ margin: "auto" }}><DI n="bolt" /><p>This item has no abilities{item.passives?.length ? `; ${item.passives.length} passive effect${item.passives.length === 1 ? "" : "s"}` : ""}.</p></div>
            )}
          </section>
          <Dock d={d} item={item} ab={ab} />
        </div>

        {/* RIGHT */}
        <div className="dz-col">
          <Preview d={d} item={item} r={r} real={real} />
          <section className="cys-panel cys-glass dz-rtabs" style={{ flex: 1, minHeight: 0 }}>
            <div className="cys-tabs" role="tablist">
              <button type="button" role="tab" aria-selected={rtab === "params"} className={`cys-tab ${rtab === "params" ? "on" : ""}`} onClick={() => setRtab("params")}><DI n="sliders" />Parameters<span className="n">{itemParams.length}</span></button>
              <button type="button" role="tab" aria-selected={rtab === "sim"} className={`cys-tab ${rtab === "sim" ? "on" : ""}`} onClick={() => setRtab("sim")}><DI n="play" />Simulator</button>
              <button type="button" role="tab" aria-selected={rtab === "checks"} className={`cys-tab ${rtab === "checks" ? "on" : ""}`} onClick={() => setRtab("checks")}><DI n="check" />Checks{rep && (rep.errors.length ? <span className="n" style={{ color: "var(--bad)" }}>{rep.errors.length}</span> : rep.warnings.length ? <span className="n">{rep.warnings.length}</span> : null)}</button>
            </div>
            {rtab === "params" && <ParamsPane d={d} item={item} ab={ab} blk={blk} params={itemParams} setParam={setParam} />}
            {rtab === "sim" && <SimPane d={d} item={item} />}
            {rtab === "checks" && <ChecksPane d={d} item={item} />}
            {rtab === "params" && <PendingBar d={d} labels={(id) => id} />}
          </section>
        </div>
      </main>
      <Narrow d={d} items={items} item={item} setCur={setCur} icon={icon} />
    </>
  );
}

// ------------------------------------------------------------------------------------------------ left panels
function AbilitiesPanel({ d, item, abSel, setAbSel, apply }: { d: Designer; item: ItemDesign; abSel: string; setAbSel: (id: string) => void; apply: (r: { ok: true; files: DesignFile[] } | { ok: false; error: string }, ok?: string) => void }) {
  const max = d.view!.limits.maxAbilities;
  const add = () => {
    let n = item.abilities.length + 1; while (item.abilities.some((x) => x.id === `ability_${n}`)) n++;
    const ab: Ability = { id: `ability_${n}`, name: `Ability ${n}`, trigger: { type: "right_click" }, cooldownTicks: 40, actions: [{ type: "actionbar", text: "It works." }] };
    const next = d.files.map((f) => (f.id === item.id ? { ...(f as ItemDesign), abilities: [...(f as ItemDesign).abilities, ab] } : f));
    apply({ ok: true, files: next }, `Added ${ab.id} (a structure change: rebuilds ${abilityFile(item.id, ab.id)})`);
    setAbSel(ab.id);
  };
  return (
    <section className="cys-panel cys-glass">
      <div className="cys-ph"><span className="cys-eyebrow">Abilities</span><span className="n">{item.abilities.length} / {max}</span></div>
      <div className="dz-body">
        {item.abilities.map((ab) => (
          <button key={ab.id} type="button" className={`dz-row ${ab.id === abSel ? "on" : ""}`} aria-current={ab.id === abSel} onClick={() => setAbSel(ab.id)}>
            <span className="dz-thumb plain"><DI n={ab.trigger.type === "charge_release" ? "bolt" : ab.trigger.type.includes("click") ? "hand" : ab.trigger.type === "held_interval" ? "clock" : "sword"} /></span>
            <span className="tx"><b className="sans">{ab.name}</b><small>{ab.trigger.type}{ab.cooldownTicks ? ` · ${secs(ab.cooldownTicks)}` : ""}</small></span>
          </button>
        ))}
        <button type="button" className="dz-addb" style={{ marginTop: 4 }} disabled={item.abilities.length >= max} onClick={add} title="Adds a right-click ability; a structure change (its Java file is new)"><DI n="plus" />Add ability</button>
      </div>
    </section>
  );
}

function AssetsPanel({ d, mod, item, icon, real }: { d: Designer; mod: StudioMod; item: ItemDesign; icon: import("@/lib/cyrus/textures/render").Raster; real: boolean }) {
  const acc = d.view!.access;
  const ns = d.view!.project!.namespace;
  const rows: { kind: "texture" | "sound"; key: string }[] = [...(item.assets?.model ? [{ kind: "texture" as const, key: item.assets.model }] : []), ...(item.assets?.sounds ?? []).filter((s) => s.startsWith(`${ns}:`)).map((s) => ({ kind: "sound" as const, key: s }))];
  if (!rows.length) return null;
  return (
    <section className="cys-panel cys-glass">
      <div className="cys-ph"><span className="cys-eyebrow">Assets</span><span className="cys-tag dim" title="Designers are open on every plan; making or editing the assets they use follows the asset plan gates">follow plan gates</span></div>
      <div className="dz-aref">
        {rows.map((x) => {
          const g = acc.edit[x.kind];
          const has = x.kind === "texture" ? d.view!.assets.models.includes(x.key) : d.view!.assets.sounds.includes(x.key);
          const sub = !has ? (x.kind === "texture" ? "not in this mod: keeps the base look" : "not in this mod: plays nothing") : x.kind === "texture" ? (real ? "item model · this mod's texture" : "item model") : "sound";
          const href = x.kind === "texture" ? studioHref(mod, "texture", `?asset=${x.key.split(":")[1]}`) : studioHref(mod, "sound");
          return (
            <div key={x.key} className="dz-arow" title={g.ok ? "" : g.reason}>
              <span className="dz-thumb">{x.kind === "texture" ? <Ico r={icon} size={26} /> : <svg className="dz-wave" viewBox="0 0 26 18" aria-hidden>{[3, 7, 12, 16, 9, 14, 6, 10, 4, 7, 3, 2].map((h, i) => <rect key={i} x={1 + i * 2} y={9 - h / 2} width={1.2} height={h} rx={0.6} fill="currentColor" />)}</svg>}</span>
              <span className="tx"><b>{x.key.replace(`${ns}:`, "")}</b><small>{sub}</small></span>
              {g.ok ? <Link className="cys-ib sm" href={href} title={`Open in the ${x.kind === "texture" ? "Texture" : "Sound"} Studio`} aria-label={`Open ${x.key} in the studio`}><DI n="external" /></Link>
                : <span className="cys-tag warn" title={g.reason}><DI n="lock" />{g.needs === "all" ? "All models" : g.needs === "saka" ? "Saka" : g.code === "plan_unknown" ? "plan?" : "locked"}</span>}
            </div>
          );
        })}
      </div>
    </section>
  );
}

function RecipePanel({ item, icon }: { item: ItemDesign; icon: (ref: string | undefined, model?: string) => import("@/lib/cyrus/textures/render").Raster }) {
  const r = item.recipe!;
  const cells: (string | null)[] = r.kind === "shaped" ? Array.from({ length: 9 }, (_, i) => { const row = r.pattern[Math.floor(i / 3)] ?? ""; const ch = row[i % 3]; if (!ch || ch === " ") return null; const k = r.key[ch]; return typeof k === "string" ? k : Array.isArray(k) ? String(k[0]) : null; }) : Array.from({ length: 9 }, (_, i) => { const x = r.ingredients[i]; return x === undefined ? null : typeof x === "string" ? x : Array.isArray(x) ? String(x[0]) : null; });
  return (
    <section className="cys-panel cys-glass">
      <div className="cys-ph"><span className="cys-eyebrow">Recipe</span><span className="cys-tag dim">{r.kind}</span></div>
      <div className="dz-body">
        <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
          <div className="dz-recipe">{cells.map((c, i) => <span key={i} title={c ?? "empty"}>{c && <Ico r={icon(c)} size={20} />}</span>)}</div>
          <span style={{ color: "var(--faint)", fontSize: 16 }}><DI n="arrowR" /></span>
          <span className="dz-thumb"><Ico r={icon(item.base, item.assets?.model)} /></span>
        </div>
        <p className="cys-hint" style={{ margin: "8px 2px 0" }}>Structure: changing the recipe rebuilds {itemFile(item.id)}.</p>
      </div>
    </section>
  );
}

// ---------------------------------------------------------------------------------------------- ability graph
type ApplyFn = (r: { ok: true; files: DesignFile[] } | { ok: false; error: string }, ok?: string) => void;
function AbilityGraph({ d, item, ab, ai, blk, setBlk, view, setView, setParam, apply, issues, warnings, params }: {
  d: Designer; item: ItemDesign; ab: Ability; ai: number; blk: string; setBlk: (b: string) => void; view: "graph" | "json"; setView: (v: "graph" | "json") => void;
  setParam: (path: string, v: number | string) => void; apply: ApplyFn; issues: GpIssue[]; warnings: GpIssue[]; params: Param[];
}) {
  const L = d.view!.limits;
  const b = d.analysis?.budgets.find((x) => x.item === item.id && x.ability === ab.id);
  const mine = issues.filter((e) => e.path.startsWith(`abilities[${ai}]`) || e.path === "abilities");
  const myWarn = warnings.filter((e) => e.path.startsWith(`abilities[${ai}]`));
  const badBlocks = new Set(mine.map((e) => blockOfIssue(e.path, ai)).filter(Boolean) as string[]);
  const base = `items.${item.id}.abilities.${ab.id}.`;
  const pmap = new Map(params.filter((p) => p.path.startsWith(base)).map((p) => [p.path.slice(base.length), p]));
  const was = d.savedParams;
  const fieldsAt = (node: string) => [...pmap.entries()].filter(([rel]) => { const pre = node === "trigger" ? "trigger." : `${node}.`; return rel.startsWith(pre) && !rel.slice(pre.length).includes("."); });
  const F = (rel: string, p: Param, short: string) => <InlineField key={rel} p={p} was={was.get(p.path)?.value} short={short} onSet={(v) => setParam(p.path, v)} />;
  const t = ab.trigger;
  const tr = TRIG[t.type] ?? [t.type, ""];
  const javaFile = abilityFile(item.id, ab.id);

  return (
    <>
      <div className="dz-gh">
        <span className="cys-eyebrow">Ability graph</span><span className="aname">{ab.name}</span><span style={{ flex: 1 }} />
        {d.checking ? <span className="cys-tag dim">checking</span> : mine.length ? <span className="cys-tag bad">{mine.length} error{mine.length === 1 ? "" : "s"}</span> : <span className="cys-tag ok" title="Fits every cap and the per-activation budget. The runtime Budget component enforces the same numbers."><DI n="check" />valid</span>}
        {b && <span className="dz-mono" title="Structure limits" style={{ whiteSpace: "nowrap" }}>{b.nodes}/{L.maxNodes} nodes · depth {b.depth}/{L.maxDepth}</span>}
        <div className="cys-seg sm cys-soft"><button type="button" className={view === "graph" ? "on" : ""} aria-pressed={view === "graph"} onClick={() => setView("graph")}><DI n="graph" />Graph</button><button type="button" className={view === "json" ? "on" : ""} aria-pressed={view === "json"} onClick={() => setView("json")}><DI n="file" />JSON</button></div>
      </div>
      <div className="dz-budget dz-meters">
        <Meter label="Actions" used={b?.actions ?? 0} cap={L.budget.actions} title="Worst case per activation (a query's max multiplies its children)" />
        <Meter label="Entity effects" used={b?.entities ?? 0} cap={L.budget.entities} />
        <Meter label="Scheduled" used={b?.tasks ?? 0} cap={L.budget.tasks} />
        <Meter label="Particles" used={b?.particles ?? 0} cap={L.budget.particles} />
        <Meter label="Projectiles" used={b?.projectiles ?? 0} cap={L.budget.projectiles} />
      </div>
      {view === "json" ? <JsonView d={d} item={item} apply={apply} /> : (
        <div className="dz-graph">
          <div className="dz-gstack">
            <div className="dz-glabel"><DI n="bolt" /> When</div>
            <div role="button" tabIndex={0} className={`dz-blk trig ${blk === "trigger" ? "sel" : ""} ${badBlocks.has("trigger") ? "bad" : ""}`} onClick={() => setBlk("trigger")} onKeyDown={(e) => { if (e.key === "Enter") setBlk("trigger"); }}>
              <div className="dz-blk-h"><DI n="bolt" /><span className="ty">{t.type}</span></div>
              <div className="dz-blk-d"><b>{tr[0]}.</b> {t.type === "charge_release" && t.release === "unsneak" ? "Hold sneak, then let go." : tr[1]}</div>
              <div className="dz-fl">
                {fieldsAt("trigger").map(([rel, p]) => F(rel, p, rel.replace("trigger.", "").replace("_ticks", "").replace("target_", "").replace("min_charge", "min").replace("max_charge", "max").replace("period", "every")))}
                {t.type === "charge_release" && <Struct k="release" v={t.release} file={javaFile} />}
                {t.type === "projectile_hit" && <Struct k="tag" v={t.tag} file={javaFile} />}
                {t.type === "held_interval" && <Struct k="slot" v={t.slot ?? "main_hand"} file={javaFile} />}
              </div>
            </div>
            <div className="dz-glabel" style={{ marginTop: 8 }}><DI n="filter" /> Only if, in order</div>
            <div className="dz-gate fixed" title="An ability cannot re-trigger itself while it runs"><DI n="lock" /><span className="tx">Re-entry guard</span><span className="dz-mono">fixed</span></div>
            {ab.cooldownTicks !== undefined && pmap.get("cooldown_ticks") ? (
              <div className={`dz-gate ${blk === "ability" ? "sel" : ""}`} onClick={() => setBlk("ability")}><DI n="clock" /><span className="tx">Cooldown</span><span style={{ marginLeft: "auto" }}><InlineField p={pmap.get("cooldown_ticks")!} was={was.get(`${base}cooldown_ticks`)?.value} short="t" onSet={(v) => setParam(`${base}cooldown_ticks`, v)} /></span></div>
            ) : <div className="dz-gate none"><DI n="clock" /><span className="tx">No cooldown</span></div>}
            {ab.charges && pmap.get("charges.max") ? (
              <div className="dz-gate" onClick={() => setBlk("ability")}><DI n="coin" /><span className="tx">Charges</span><span style={{ marginLeft: "auto", display: "flex", gap: 4 }}><InlineField p={pmap.get("charges.max")!} was={was.get(`${base}charges.max`)?.value} short="max" onSet={(v) => setParam(`${base}charges.max`, v)} /></span></div>
            ) : <div className="dz-gate none"><DI n="coin" /><span className="tx">No charges</span></div>}
            {(ab.conditions ?? []).map((c, i) => (
              <div key={i} className={`dz-gate ${blk === `c${i}` ? "sel" : ""}`} style={badBlocks.has(`c${i}`) ? { borderColor: "var(--bad)" } : undefined} onClick={() => setBlk(`c${i}`)} title={`c${i}`}>
                <DI n="filter" /><span className="tx">{condText(c)}</span>
                {fieldsAt(`c${i}`).map(([rel, p]) => F(rel, p, rel.split(".").pop()!))}
                <span className="dz-mono">c{i}</span>
                <button type="button" className="cys-ib sm" aria-label={`Remove condition c${i}`} title="Remove (structure change)" onClick={(e) => { e.stopPropagation(); apply(removeNode(d.files, item.id, ab.id, `c${i}`)); setBlk("trigger"); }}><DI n="close" /></button>
              </div>
            ))}
            <Picker label="Condition" options={Object.keys(CONDITION_TEMPLATES).map((k) => ({ id: k, label: k.replace(/_/g, " ") }))} disabled={(ab.conditions?.length ?? 0) >= L.maxConditions} onPick={(k) => apply(insertCondition(d.files, item.id, ab.id, CONDITION_TEMPLATES[k]()), `Added a ${k.replace(/_/g, " ")} condition (structure change)`)} block />
            {t.type === "charge_release" && <p className="cys-hint" style={{ margin: "4px 2px 0" }}>Charge = held ticks ÷ max, 0 to 1. The cooldown starts only when the ability fires.</p>}
          </div>
          <div className="dz-gcol">
            <div className="dz-glabel"><DI n="play" /> Do <span className="lc">· {ab.actions.length} of {L.maxActions} · runs top to bottom</span>
              <span style={{ marginLeft: "auto" }}><Picker label="Action" options={Object.keys(ACTION_TEMPLATES).map((k) => ({ id: k, label: ACT[k]?.label ?? k, hint: k }))} disabled={ab.actions.length >= L.maxActions} onPick={(k) => {
                const container = blk !== "trigger" && blk !== "ability" && !blk.startsWith("c") ? containerOf(ab, blk) : "";
                const r = insertAction(d.files, item.id, ab.id, container, ACTION_TEMPLATES[k]({ marks: (item.marks ?? []).map((m) => m.name), sound: item.assets?.sounds?.[0] }));
                apply(r, r.ok ? `Added ${k} at ${r.path} (structure change: rebuilds ${javaFile})` : undefined);
                if (r.ok) setBlk(r.path);
              }} /></span>
            </div>
            {ab.actions.map((x, i) => <Block key={i} a={x} path={`a${i}`} sel={blk} setSel={setBlk} bad={badBlocks} fieldsAt={fieldsAt} F={F} file={javaFile} onRemove={(p) => { apply(removeNode(d.files, item.id, ab.id, p)); setBlk("trigger"); }} />)}
          </div>
        </div>
      )}
      <div className="dz-gval">
        {mine.length ? <ul className="dz-issues">{mine.slice(0, 6).map((e, i) => <IssueRow key={i} i={e} tone="err" />)}</ul>
          : myWarn.length ? <ul className="dz-issues">{myWarn.slice(0, 4).map((e, i) => <IssueRow key={i} i={e} tone="warn" />)}</ul>
            : <><span className="cys-dot ok" /><span><b>Valid.</b> Fits every cap and the per-activation budget. The runtime Budget component enforces the same numbers.</span><span className="dz-mono" style={{ marginLeft: "auto" }}>{autosaveText(d)}</span></>}
      </div>
    </>
  );
}
/** Where "+ Action" inserts: inside the selected container, else next to the selected block (its parent list). */
function containerOf(ab: Ability, blk: string): string {
  const segs = blk.split(".");
  let list: Action[] = ab.actions; let node: Action | undefined;
  for (const s of segs) { const m = /^(a|n|then|else)(\d+)$/.exec(s); if (!m) return ""; node = m[1] === "a" || m[1] === "n" ? list[Number(m[2])] : list[Number(m[2])]; if (!node) return ""; const kids = childLists(node); list = kids[0]?.list ?? []; }
  if (node && (node.type === "query_marked" || node.type === "query_nearby" || node.type === "delayed")) return blk;
  if (node && node.type === "branch") return `${blk}.then`;
  return segs.length > 1 ? segs.slice(0, -1).join(".") + (/^(then|else)/.test(segs[segs.length - 1]) ? `.${segs[segs.length - 1].replace(/\d+$/, "")}` : "") : "";
}

function Block({ a, path, sel, setSel, bad, fieldsAt, F, file, onRemove }: { a: Action; path: string; sel: string; setSel: (p: string) => void; bad: Set<string>; fieldsAt: (n: string) => [string, Param][]; F: (rel: string, p: Param, short: string) => React.ReactNode; file: string; onRemove: (p: string) => void }) {
  const info = ACT[a.type] ?? { label: a.type, ic: "play", sum: () => "" };
  const fields = fieldsAt(path);
  const paramKeys = new Set(fields.map(([rel]) => rel.split(".").pop()!.replace(/_([a-z])/g, (_, c: string) => c.toUpperCase())));
  const structs = Object.entries(a).filter(([k, v]) => !STRUCT_SKIP.has(k) && !paramKeys.has(k) && v !== undefined && typeof v !== "object").map(([k, v]) => <Struct key={k} k={k === "scaleWithCharge" ? "charge" : k === "color" ? "colour" : k} v={k === "scaleWithCharge" ? (v ? "scales" : "fixed") : String(v)} file={file} />);
  const arrs = Object.entries(a).filter(([k, v]) => (k === "kinds" || k === "types") && Array.isArray(v)).map(([k, v]) => <Struct key={k} k={k} v={(v as string[]).map(bare).join(", ")} file={file} />);
  const head = (
    <div role="button" tabIndex={0} className={`dz-blk ${sel === path ? "sel" : ""} ${bad.has(path) ? "bad" : ""}`} onClick={(e) => { e.stopPropagation(); setSel(path); }} onKeyDown={(e) => { if (e.key === "Enter") setSel(path); if (e.key === "Delete" && sel === path) onRemove(path); }} title={`${info.label}: ${info.sum(a)}`}>
      <div className="dz-blk-h">
        <DI n={info.ic} /><span className="ty">{a.type}</span><span className="lb">{info.sum(a)}</span>
        {(a.type === "query_marked" || a.type === "query_nearby") && <span className="dz-mult">× up to {a.max}</span>}
        <span className="pth">{path}</span>
        {sel === path && <button type="button" className="cys-ib sm del" aria-label={`Remove ${path}`} title="Remove (structure change)" onClick={(e) => { e.stopPropagation(); onRemove(path); }}><DI n="trash" /></button>}
      </div>
      {(fields.length > 0 || structs.length > 0 || arrs.length > 0) && <div className="dz-fl">{structs.filter((s) => (s.key as string) !== "text")}{arrs}{fields.map(([rel, p]) => F(rel, p, rel.split(".").pop()!.replace(/_ticks$/, "").replace(/_/g, " ")))}</div>}
    </div>
  );
  const kids = childLists(a);
  if (!kids.length) return head;
  return (
    <div className="dz-cont">
      {head}
      {kids.map((k) => (
        <div key={k.key} className="dz-kids">
          {a.type === "branch" && <span className="klabel">{k.key}</span>}
          {k.list.map((x, i) => <Block key={i} a={x} path={`${path}.${k.seg}${i}`} sel={sel} setSel={setSel} bad={bad} fieldsAt={fieldsAt} F={F} file={file} onRemove={onRemove} />)}
        </div>
      ))}
    </div>
  );
}
function Struct({ k, v, file }: { k: string; v: string; file: string }) {
  return <span className="dz-f s" title={`Structure: changing it rebuilds ${file}`}>{k} <b>{bare(v)}</b></span>;
}
function InlineField({ p, was, short, onSet }: { p: Param; was?: number | string; short: string; onSet: (v: number | string) => void }) {
  const [txt, setTxt] = useState(String(p.value));
  useEffect(() => { setTxt(String(p.value)); }, [p.value]);
  const isTxt = p.kind === "text" || p.kind === "sound";
  const n = Number(p.value);
  const bad = isTxt ? !String(p.value).length || String(p.value).length > p.max : !Number.isFinite(n) || n < p.min || n > p.max;
  const chg = was !== undefined && String(was) !== String(p.value);
  return (
    <label className={`dz-f ${bad ? "err" : chg ? "chg" : ""}`} title={`${p.label} · ${rangeText(p)} · config.yml: ${p.path}`} onClick={(e) => e.stopPropagation()}>
      {short}
      <input className={isTxt ? "w" : ""} value={txt} inputMode={isTxt ? "text" : "decimal"} aria-label={p.label} aria-invalid={bad}
        onChange={(e) => setTxt(e.target.value)}
        onBlur={() => { if (isTxt) { if (txt !== String(p.value)) onSet(txt); return; } const x = Number(txt); if (txt.trim() !== "" && Number.isFinite(x)) { if (x !== n) onSet(p.kind === "num" ? x : Math.round(x)); } else setTxt(String(p.value)); }}
        onKeyDown={(e) => { if (e.key === "Enter") (e.target as HTMLInputElement).blur(); if (e.key === "Escape") { setTxt(String(p.value)); (e.target as HTMLInputElement).blur(); } }} />
    </label>
  );
}
function Picker({ label, options, onPick, disabled, block }: { label: string; options: { id: string; label: string; hint?: string }[]; onPick: (id: string) => void; disabled?: boolean; block?: boolean }) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => { if (!open) return; const f = (e: MouseEvent) => { if (!ref.current?.contains(e.target as Node)) setOpen(false); }; document.addEventListener("mousedown", f); return () => document.removeEventListener("mousedown", f); }, [open]);
  return (
    <div className="dz-pick" ref={ref}>
      <button type="button" className={block ? "dz-addb" : "cys-btn xs ghost"} style={block ? undefined : { height: 18 }} disabled={disabled} aria-expanded={open} onClick={() => setOpen(!open)}><DI n="plus" />{label}</button>
      {open && <div className="dz-menu" role="menu">{options.map((o) => <button key={o.id} type="button" role="menuitem" onClick={() => { setOpen(false); onPick(o.id); }}>{o.label}{o.hint && <small>{o.hint}</small>}</button>)}</div>}
    </div>
  );
}
function JsonView({ d, item, apply }: { d: Designer; item: ItemDesign; apply: ApplyFn }) {
  const src = useMemo(() => JSON.stringify(item, null, 2), [item]);
  const [txt, setTxt] = useState(src);
  const [err, setErr] = useState<string | null>(null);
  useEffect(() => { setTxt(src); setErr(null); }, [src]);
  const go = () => { try { const v = JSON.parse(txt); const r = replaceFile(d.files, item.id, v); if (!r.ok) setErr(r.error); else { setErr(null); apply(r, "JSON applied; the checks below are the validator's"); } } catch (e) { setErr(`Not valid JSON: ${(e as Error).message}`); } };
  return (
    <div className="dz-json">
      <p className="cys-hint" style={{ margin: 0 }}>The design file itself (<span className="mono">assets/designs/{item.id}.json</span>). Values here are config.yml settings; kinds, targets and particles are structure.</p>
      <textarea value={txt} onChange={(e) => setTxt(e.target.value)} spellCheck={false} aria-label={`${item.id} design JSON`} />
      <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
        {err && <span className="dz-sub" style={{ color: "var(--bad)" }}>{err}</span>}
        <span style={{ flex: 1 }} />
        <button type="button" className="cys-btn sm" disabled={txt === src} onClick={() => { setTxt(src); setErr(null); }}>Reset</button>
        <button type="button" className="cys-btn sm primary" disabled={txt === src} onClick={go}><DI n="check" />Apply JSON</button>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------------------------------- the dock
function Dock({ d, item, ab }: { d: Designer; item: ItemDesign; ab: Ability | null }) {
  const toast = useToast();
  const [text, setText] = useState("");
  const [plan, setPlan] = useState<EditPlan | null>(null);
  useEffect(() => {
    if (!text.trim() || !d.pid) { setPlan(null); return; }
    const t = window.setTimeout(() => { designerApi.plan(d.pid!, d.files, text).then(setPlan).catch(() => setPlan(null)); }, 350);
    return () => window.clearTimeout(t);
  }, [text, d.pid, d.files]);
  const send = () => {
    if (!plan) return;
    if (plan.kind === "parameters") {
      let files = d.files;
      for (const e of plan.edits) { const r = setParamValue(files, e.path, e.value); if (!r.ok) { toast(r.error, true); return; } files = r.files; }
      d.setFiles(files); setText("");
      toast(`Applied ${plan.edits.length} setting${plan.edits.length === 1 ? "" : "s"} locally (no model call). Review, then save.`);
      return;
    }
    void navigator.clipboard?.writeText(text).catch(() => undefined);
    toast("Structure changes go through a change build: request copied, paste it in the mod's chat.");
  };
  const target = ab ? `Edit ${ab.name}` : `Edit ${item.id}`;
  return (
    <div>
      <div className="dz-dhint" aria-live="polite">
        {plan?.kind === "parameters" ? <><DI n="sliders" /><span><b>Settings change</b> · {plan.summary.join(" · ")} · config.yml only, no model call</span><span className="dz-mono" title="planDesignEdit applies it here in the editor. Skipping the model in builds is an owner decision">applied in the editor</span></>
          : plan?.kind === "model" ? <><DI n="sparkle" /><span><b>Needs a change build</b> · structure changes go to the model{plan.candidates?.length ? ` (matches ${plan.candidates.length} settings)` : ""}</span><span className="dz-mono">{STUDIO_DEFAULTS.showEditEstimate && <CyrusTokenEstimate text={text} model="saka" change />}</span></>
            : null}
      </div>
      <div className="cys-dock cys-glass" data-busy="false">
        <span className="route"><DI n="edit" />{target}</span>
        <input value={text} onChange={(e) => setText(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") send(); }} aria-label="Change request" placeholder={`Ask Cyrus to change ${ab?.name ?? item.id}…`} maxLength={400} />
        <span className="model"><CyrusGlyph size={16} />Saka</span>
        <button type="button" className="send" aria-label="Send" disabled={!plan} onClick={send}><DI n="send" /></button>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------------------------------- preview
function Preview({ d, item, r, real }: { d: Designer; item: ItemDesign; r: import("@/lib/cyrus/textures/render").Raster; real: boolean }) {
  const [ctx, setCtx] = useState<PreviewContext>("firstperson");
  const key = item.assets?.model?.split(":")[1] ?? item.id;
  const model = useMemo(() => previewModel(key, d.itemModels), [key, d.itemModels]);
  const disp = useMemo(() => previewDisplays(model, r), [model, r]);
  const meta = PREVIEW_CONTEXTS.find((c) => c.id === ctx)!;
  const t = (disp.idle ?? Object.values(disp)[0])[meta.display];
  const states = model.states.length > 1 ? `${model.states.length} model states (Texture Studio)` : "One look: this item has no model states.";
  return (
    <section className="cys-panel cys-glass cys-hairline">
      <div className="cys-ph"><span className="cys-eyebrow">Live preview</span><span className="cys-tag dim" title="The display transforms are the pack's (the game's own values for tools); the camera, hand, slot, frame and head are drawn by Cyrus">approximate</span></div>
      <div className="dz-ctx"><div className="cys-seg sm cys-soft" role="group" aria-label="Where the item is shown">{PREVIEW_CONTEXTS.map((c) => <button key={c.id} type="button" className={ctx === c.id ? "on" : ""} aria-pressed={ctx === c.id} onClick={() => setCtx(c.id)}>{c.label}</button>)}</div></div>
      <div className="dz-stage">{t && <ContextCanvas r={r} name={key} ctx={ctx} t={t} gun={model.spec.category === "gun"} />}</div>
      <p className="cys-hint" style={{ margin: "8px 14px 12px" }}>{meta.hint}. {real ? states : PLACEHOLDER_NOTE}</p>
    </section>
  );
}

// ----------------------------------------------------------------------------------------------------- params
function ParamsPane({ d, item, ab, blk, params, setParam }: { d: Designer; item: ItemDesign; ab: Ability | null; blk: string; params: Param[]; setParam: (path: string, v: number | string) => void }) {
  const groups = new Map<string, Param[]>();
  for (const p of params) { const g = p.ability ?? "item"; groups.set(g, [...(groups.get(g) ?? []), p]); }
  const order = [...groups.keys()].sort((x, y) => (x === "item" ? -1 : y === "item" ? 1 : item.abilities.findIndex((a) => a.id === x) - item.abilities.findIndex((a) => a.id === y)));
  const selBase = ab ? `items.${item.id}.abilities.${ab.id}.` : "";
  const hl = (p: Param) => !!ab && p.path.startsWith(selBase) && (blk === "trigger" ? p.path.startsWith(`${selBase}trigger.`) : blk === "ability" ? /cooldown_ticks$|charges\./.test(p.path.slice(selBase.length)) : p.path.slice(selBase.length).startsWith(`${blk}.`));
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => { ref.current?.querySelector(".dz-prow.hl")?.scrollIntoView({ block: "nearest" }); }, [blk, ab?.id]);
  return (
    <div className="dz-pane" ref={ref}>
      <p className="cys-hint" style={{ margin: "10px 6px 2px" }}>Every number, text and sound key is a <span className="mono">config.yml</span> setting. Changing one never touches Java and needs no rebuild of the design.</p>
      {order.map((g) => (
        <div key={g}>
          <div className="dz-pgrp">{g === "item" ? "Item" : item.abilities.find((a) => a.id === g)?.name ?? g}<span className="cys-tag dim">{groups.get(g)!.length}</span></div>
          {groups.get(g)!.map((p) => {
            const was = d.savedParams.get(p.path)?.value;
            const changed = was !== undefined && String(was) !== String(p.value);
            const label = p.label.includes(": ") ? p.label.slice(p.label.indexOf(": ") + 2) : p.label;
            return (
              <div key={p.path} className={`dz-prow ${hl(p) ? "hl" : ""}`}>
                <span className="pl">{label.replace(/^./, (c) => c.toUpperCase())}</span>
                <span className="pp" title={p.path}>{p.path.replace(`items.${item.id}.`, "").replace("abilities.", "")}</span>
                <span className="pv"><ParamField p={p} was={was} onSet={(v) => setParam(p.path, v)} compact /><span className="rg">{changed && <><span className="was">{String(was)}</span> · </>}{rangeText(p)}</span></span>
              </div>
            );
          })}
        </div>
      ))}
    </div>
  );
}

// ----------------------------------------------------------------------------------------------------- checks
const CHECK_TEXT: Record<string, string> = {
  schema: "Shape, types and every cap", namespace: "Own ids live in this mod's namespace", vanilla_ids: "Base, items and entities exist in this version", references: "Marks, sounds, models resolve",
  context: "Each trigger has the target its actions need", budget: "Static worst case fits the activation budget", version_features: "Features this Minecraft version has", limits: "Abilities, nodes, depth, actions per list",
};
function ChecksPane({ d, item }: { d: Designer; item: ItemDesign }) {
  const a = d.analysis;
  const rep = a?.files.find((f) => f.id === item.id);
  const rows = a?.itemChecks[item.id] ?? [];
  const ok = rep?.ok ?? false;
  return (
    <div className="dz-pane">
      <div className="cys-verdict">
        <span className={`cys-dot ${ok ? "ok" : "bad"}`} />
        <div><b>{ok ? "Valid design" : `${rep?.errors.length ?? 0} error${rep?.errors.length === 1 ? "" : "s"}`}</b><div className="cys-hint">{ok ? `Compiles to the reviewed component library for Minecraft ${d.view!.mcVersion}.` : "The design is refused until fixed."}</div></div>
        <span className="cys-tag dim badge">validateDesign</span>
      </div>
      <ul className="cys-checks">
        {rows.map((c) => (
          <li key={c.id} className={`cys-check ${c.status}`}>
            <span className="ic"><DI n={c.status === "pass" ? "check" : c.status === "fail" ? "close" : c.status === "warn" ? "warn" : "minus"} /></span>
            <span className="id">{c.id}</span><span className="val">{c.status.replace("_", " ")}</span>
            <span className="msg">{c.items.length ? c.items.slice(0, 3).join(" · ") : CHECK_TEXT[c.id] ?? ""}</span>
          </li>
        ))}
        <li className="cys-check not_run"><span className="ic"><DI n="minus" /></span><span className="id">real client</span><span className="val">not run</span><span className="msg">Gameplay has not been verified in a real game client. Validation, the TypeScript compile and the reference simulator ran here.</span></li>
        <li className={`cys-check ${a?.compile.ok ? "pass" : "fail"}`}><span className="ic"><DI n={a?.compile.ok ? "check" : "close"} /></span><span className="id">compile</span><span className="val">{a?.compile.ok ? "pass" : "fail"}</span><span className="msg">{a?.compile.ok ? `${a.compile.java} Java files, config_version ${a.compile.configVersion}; javac ${a.compile.javacVerified ? "verified for this version on the build host" : "not run for this version"}.` : "The whole mod did not compile."}</span></li>
      </ul>
      {!!rep?.warnings.length && <div style={{ padding: "0 12px 10px" }}><div className="cys-eyebrow" style={{ margin: "4px 0 6px" }}>Warnings</div><ul className="dz-issues">{rep.warnings.slice(0, 8).map((w, i) => <IssueRow key={i} i={w} tone="warn" />)}</ul></div>}
      <div className="dz-pgrp">Structure, not settings</div>
      <p className="cys-hint" style={{ margin: "0 6px 4px" }}>Changing one recompiles exactly the file named.</p>
      <ul className="dz-struct">
        {item.abilities.map((ab) => <li key={ab.id}><span>{ab.name}: trigger, conditions, action kinds</span><span className="cys-tag dim">rebuild</span><code>{abilityFile(item.id, ab.id)}</code></li>)}
        <li><span>Name, lore, rarity, glint, recipe, base item</span><span className="cys-tag dim">rebuild</span><code>{itemFile(item.id)}</code></li>
        <li><span>Damage, attack speed, durability</span><span className="cys-tag dim">new items only</span><code>{itemFile(item.id)}</code></li>
      </ul>
    </div>
  );
}

// -------------------------------------------------------------------------------------------------- simulator
function SimPane({ d, item }: { d: Designer; item: ItemDesign }) {
  const [steps, setSteps] = useState<ItemStep[]>([]);
  const [res, setRes] = useState<{ result: ItemSimResult; buttons: SimButton[] } | null>(null);
  const [err, setErr] = useState<string | null>(null);
  useEffect(() => { setSteps([]); }, [item.id]);
  useEffect(() => {
    if (!d.pid) return;
    const t = window.setTimeout(() => { designerApi.simItem(d.pid!, d.files, item.id, steps).then((r) => { setRes(r); setErr(null); }).catch((e) => setErr((e as Error).message)); }, 200);
    return () => window.clearTimeout(t);
  }, [d.pid, d.files, item.id, steps]);
  return (
    <div className="dz-pane" style={{ display: "flex", flexDirection: "column" }}>
      <div className="dz-simbtns">
        {(res?.buttons ?? []).map((b, i) => <button key={i} type="button" className="cys-btn xs" disabled={steps.length >= 40} onClick={() => setSteps([...steps, b.step])}><DI n={b.icon} />{b.label}</button>)}
        <button type="button" className="cys-btn xs ghost" style={{ marginLeft: "auto" }} onClick={() => setSteps([])} disabled={!steps.length}><DI n="rollback" />Reset</button>
      </div>
      {err ? <div className="dz-note warn" style={{ margin: "0 4px" }}><DI n="warn" /><span>{err}</span></div> : res && (
        <>
          <Timeline r={res.result} />
          <ul className="dz-slog" aria-live="polite">
            {res.result.log.length ? [...res.result.log].reverse().slice(0, 60).map((l, i) => <li key={i} className={l.tone}><i>{l.tick}</i><span>{l.text}</span></li>)
              : <li className="fx"><i>0</i><span>Ready. 20 ticks per second. The mobs are sample entities at fixed distances (4 to 18 blocks).</span></li>}
          </ul>
        </>
      )}
      <p className="cys-hint" style={{ margin: "8px 6px 12px" }} title="The reference simulator (simulate.ts): same activation order, ticks, marks and budget as the plugin">Logic only: no physics, ray tracing, protection plugins or client. Sample player has the item&apos;s permissions.</p>
    </div>
  );
}
function Timeline({ r }: { r: ItemSimResult }) {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const cv = ref.current; if (!cv) return;
    const draw = () => {
      const b = cv.getBoundingClientRect(), dpr = Math.min(2, window.devicePixelRatio || 1);
      cv.width = b.width * dpr; cv.height = b.height * dpr;
      const c = cv.getContext("2d")!; c.setTransform(dpr, 0, 0, dpr, 0, 0);
      const cs = getComputedStyle(cv);
      const v = (n: string) => cs.getPropertyValue(n).trim() || "#888";
      const W = b.width, H = b.height, span = Math.max(400, r.end + 60), x = (t: number) => 74 + ((W - 86) * t) / span;
      c.font = "500 10px ui-monospace, monospace"; c.textBaseline = "middle";
      const lanes = [...r.lanes, ...(r.markCap !== null ? ["Marks"] : [])].slice(0, 4);
      const y0 = 18, dy = 18;
      lanes.forEach((l, i) => { const y = y0 + i * dy; c.fillStyle = v("--muted"); const last = r.marks[r.marks.length - 1]?.count ?? 0; c.fillText(l === "Marks" ? `Marks ${last}/${r.markCap}` : l.slice(0, 10), 8, y); c.strokeStyle = v("--line-2"); c.beginPath(); c.moveTo(74, y); c.lineTo(W - 10, y); c.stroke(); });
      for (let t = 0; t <= span; t += span > 1200 ? 400 : 100) { c.fillStyle = v("--faint"); c.fillText(`${t / 20}s`, x(t) - 6, H - 9); }
      for (const bar of r.bars) { const li = lanes.indexOf(bar.lane); if (li < 0) continue; c.fillStyle = bar.tone === "warn" ? v("--warn") : v("--accent"); c.globalAlpha = bar.tone === "warn" ? 0.55 : 0.8; c.fillRect(x(bar.from), y0 + li * dy - 4, Math.max(2, x(bar.to) - x(bar.from)), 8); c.globalAlpha = 1; }
      const mi = lanes.indexOf("Marks");
      if (mi >= 0 && r.markCap) { c.fillStyle = v("--accent"); c.globalAlpha = 0.4; for (let i = 1; i < r.marks.length; i++) { const a = r.marks[i - 1], bb = r.marks[i]; const h = (a.count / r.markCap) * 10; c.fillRect(x(a.tick), y0 + mi * dy + 5 - h, Math.max(1, x(bb.tick) - x(a.tick)), h); } c.globalAlpha = 1; }
      for (const dt of r.dots) { c.fillStyle = dt.tone === "blocked" ? v("--warn") : v("--ink"); c.beginPath(); c.arc(x(dt.tick), 6, 2.2, 0, 7); c.fill(); }
      c.strokeStyle = v("--cyan"); c.lineWidth = 1.5; c.beginPath(); c.moveTo(x(r.end), 3); c.lineTo(x(r.end), H - 18); c.stroke();
    };
    draw();
    const ro = new ResizeObserver(draw); ro.observe(cv);
    return () => ro.disconnect();
  }, [r]);
  return <div className="dz-tl"><canvas ref={ref} role="img" aria-label={`Timeline: ${r.dots.filter((x) => x.tone === "fired").length} activations, ${r.dots.filter((x) => x.tone === "blocked").length} blocked, ${r.end} ticks`} /></div>;
}

// ------------------------------------------------------------------------------------------- narrow (phone)
function abilitySentence(item: ItemDesign, ab: Ability): string {
  const t = ab.trigger;
  const when = t.type === "charge_release" ? `Hold sneak ${secs(t.minChargeTicks)}–${secs(t.maxChargeTicks)}, ${t.release === "right_click" ? "right-click" : "let go"}` : TRIG[t.type]?.[1].replace(/\.$/, "") ?? t.type;
  const did = ab.actions.slice(0, 3).map((a) => `${ACT[a.type]?.label.toLowerCase() ?? a.type} ${ACT[a.type]?.sum(a) ?? ""}`.trim()).join(", ");
  const mk = item.marks?.find((m) => ab.actions.some((a) => a.type === "apply_mark" && a.mark === m.name));
  return `${when}: ${did}${mk ? ` (for ${secs(mk.durationTicks)}, up to ${mk.maxPerOwner})` : ""}.${ab.cooldownTicks ? ` ${secs(ab.cooldownTicks)} cooldown.` : ""}`;
}
function Narrow({ d, items, item, setCur, icon }: { d: Designer; items: ItemDesign[]; item: ItemDesign; setCur: (k: string) => void; icon: (ref: string | undefined, model?: string) => import("@/lib/cyrus/textures/render").Raster }) {
  const rep = d.analysis?.files.find((f) => f.id === item.id);
  const top = [...(d.analysis?.budgets.filter((b) => b.item === item.id) ?? [])].sort((a, b) => b.actions - a.actions)[0];
  const L = d.view!.limits;
  const seq = d.view!.designs.find((x) => x.id === item.id)?.seq;
  const changes = d.params.filter((p) => p.item === item.id && !p.owner).flatMap((p) => { const w = d.savedParams.get(p.path)?.value; return w !== undefined && String(w) !== String(p.value) ? [{ p, w }] : []; });
  return (
    <main className="dz-narrow" aria-label="Item design review">
      {items.length > 1 && <div className="dz-narrow n-tabs" style={{ display: "flex" }}>{items.map((it) => <button key={it.id} type="button" className={`cys-soft ${it.id === item.id ? "on" : ""}`} onClick={() => setCur(it.id)}><span className="dz-thumb" style={{ width: 26, height: 26 }}><Ico r={icon(it.base, it.assets?.model)} size={18} /></span>{it.id}</button>)}</div>}
      <section className="n-card cys-glass">
        <div className="n-h">
          <div className="dz-ibig" style={{ width: 56, height: 56 }}><Ico r={icon(item.base, item.assets?.model)} size={44} />{item.glint && <i className="dz-glint" />}</div>
          <div style={{ minWidth: 0 }}><h1><McText t={item.name} /></h1><p>{bare(item.base)} · {item.abilities.length} abilit{item.abilities.length === 1 ? "y" : "ies"}{seq ? ` · revision ${seq}` : ""}</p></div>
          <span className={`cys-tag ${rep?.ok ? "ok" : "bad"}`} style={{ marginLeft: "auto" }}>{rep?.ok ? "valid" : `${rep?.errors.length ?? 0} errors`}</span>
        </div>
        <div className="n-sec"><span className="cys-eyebrow">What it does</span>{item.abilities.map((ab) => <p key={ab.id}><b>{ab.name}.</b> {abilitySentence(item, ab)}</p>)}{!item.abilities.length && <p className="cys-hint">No abilities.</p>}</div>
        {top && <div className="n-sec"><span className="cys-eyebrow">Budget per activation</span><div className="dz-meters" style={{ gridTemplateColumns: "1fr 1fr" }}><Meter label="Actions" used={top.actions} cap={L.budget.actions} /><Meter label="Entity effects" used={top.entities} cap={L.budget.entities} /><Meter label="Particles" used={top.particles} cap={L.budget.particles} /><Meter label="Projectiles" used={top.projectiles} cap={L.budget.projectiles} /></div></div>}
        <div className="n-sec"><span className="cys-eyebrow">Settings changed</span>{changes.length ? changes.map(({ p, w }) => <div key={p.path} className="n-kv"><span>{p.label}</span><b>{String(w)} → {String(p.value)}</b></div>) : <p className="cys-hint" style={{ margin: 0 }}>None waiting. Settings change only config.yml.</p>}</div>
        <div className="n-note"><DI n="info" /><span>Checked by the validator and the simulator. Not verified in a real game client.</span></div>
        {STUDIO_DEFAULTS.mobile === "review_and_approve" && d.changed.length > 0 && (
          <div className="n-act"><button type="button" className="cys-btn" onClick={() => void d.discard()}>Reject</button><button type="button" className="cys-btn primary" disabled={!d.analysis?.ok || d.saving} onClick={() => void d.save()}><DI n="check" />Approve revision</button></div>
        )}
      </section>
      <section className="n-card cys-glass"><div className="n-note" style={{ borderTop: 0 }}><DI n="info" /><span>Editing the graph needs a larger screen. Here you can review and approve; approving saves the pending edits as a new revision.</span></div></section>
    </main>
  );
}

