"use client";
// Cyrus MENU + QUEST DESIGNER (r27), full page, tabs Menus / Quests. Layout from the v2 mockup
// (cyrus-designs/v2/menu-quest.html, not yet reviewed by the owner). Menus: the slot grid in Edit (select a slot, its
// inspector edits the click's price / texts / counts as config.yml values) and Try it (a sample player buys through the
// fixed click protocol: room -> pay -> take -> give, run by the reference simulator); the owner-editable shop list.
// Quests: the prerequisite chain, the step flow (objectives, branches, rewards; counts editable) and the progress
// simulator driven by player events. Phones: read-only summary + approve / reject.
import { useCallback, useEffect, useMemo, useState } from "react";
import Link from "next/link";
import type { Param } from "@/lib/cyrus/designer/compile";
import type { ChestMenu, Cost, DialogueMenu, MenuAction, MenuDesign, Objective, QuestDesign, Reward } from "@/lib/cyrus/designer/gameplay/spec";
import { isItem, isMenu, isQuest, setParamValue, type DesignFile } from "@/lib/cyrus/designer/studio/edit";
import type { Raster } from "@/lib/cyrus/textures/render";
import { STUDIO_DEFAULTS } from "@/lib/cyrus/studios/access";
import { useToast, type StudioMod } from "../studios/StudioShell";
import { designerApi, type QuestSimResult, type QuestStep, type TryResult } from "./api";
import { DesignerContext, DesignerShell, DraftLine, Failed, Ico, IssueRow, Loading, McText, Meter, NoDesigns, ParamField, PendingBar, designerHref, rangeText, useDesigner, useIcon, type Designer } from "./shared";
import { PLACEHOLDER_NOTE } from "./pixel-icons";
import { DI } from "./icons";

type Tab = "menus" | "quests";
const bare = (s: string) => String(s ?? "").replace(/^minecraft:/, "");
const costText = (c?: Cost) => (!c ? "free" : c.type === "item" ? `${c.count} × ${bare(c.item)}` : c.type === "xp_levels" ? `${c.levels} XP levels` : `${c.amount} money (Vault)`);
const ACT_IC: Record<string, string> = { back: "chevL", close: "close", send_message: "note", actionbar: "note", play_sound: "volume", run_ability: "bolt", open_quest_log: "scroll", open_menu: "slots", start_quest: "flag", abandon_quest: "flag", choose_branch: "branch", give_item: "gift", potion_effect: "flask", heal: "heart", next_page: "arrowR", prev_page: "chevL" };
const DIALOGUE_POS = [[], [22], [20, 24], [20, 22, 24], [19, 21, 23, 25], [18, 20, 22, 24, 26]];

export function MenuQuestDesigner({ mod, initialTab, initialMenu, initialQuest }: { mod: StudioMod; initialTab: Tab; initialMenu: string | null; initialQuest: string | null }) {
  const [tab, setTab] = useState<Tab>(initialTab);
  const go = (t: Tab) => { setTab(t); try { history.replaceState(null, "", designerHref(mod, t)); } catch { /* the tab still switches */ } };
  return (
    <DesignerShell mod={mod} tab={tab} current={tab === "quests" ? "Quest Designer" : "Menu Designer"} onTab={(t) => (t === "menus" || t === "quests" ? go(t) : undefined)} showBosses>
      <Body mod={mod} tab={tab} setTab={go} initialMenu={initialMenu} initialQuest={initialQuest} />
    </DesignerShell>
  );
}

function Body({ mod, tab, setTab, initialMenu, initialQuest }: { mod: StudioMod; tab: Tab; setTab: (t: Tab) => void; initialMenu: string | null; initialQuest: string | null }) {
  const d = useDesigner(mod);
  const menus = useMemo(() => d.files.filter(isMenu) as MenuDesign[], [d.files]);
  const quests = useMemo(() => d.files.filter(isQuest) as QuestDesign[], [d.files]);
  const [menu, setMenu] = useState<string | null>(initialMenu);
  const [quest, setQuest] = useState<string | null>(initialQuest);
  useEffect(() => { if (menus.length && (!menu || !menus.some((m) => m.id === menu))) setMenu(menus[0].id); }, [menus, menu]);
  useEffect(() => { if (quests.length && (!quest || !quests.some((q) => q.id === quest))) setQuest(quests.find((q) => q.branches)?.id ?? quests[0].id); }, [quests, quest]);
  if (d.err) return <Failed msg={d.err} />;
  if (!d.view) return <Loading what="this mod's menus and quests" />;
  if (!d.view.project || (!menus.length && !quests.length)) return <NoDesigns mod={mod} what="menus or quests" />;
  const m = menus.find((x) => x.id === menu) ?? menus[0] ?? null;
  const q = quests.find((x) => x.id === quest) ?? quests[0] ?? null;
  return (
    <DesignerContext d={d}>
      <Workspace d={d} mod={mod} tab={tab} setTab={setTab} menus={menus} quests={quests} m={m} q={q} setMenu={setMenu} setQuest={setQuest} />
    </DesignerContext>
  );
}

type WS = { d: Designer; mod: StudioMod; tab: Tab; setTab: (t: Tab) => void; menus: MenuDesign[]; quests: QuestDesign[]; m: MenuDesign | null; q: QuestDesign | null; setMenu: (k: string) => void; setQuest: (k: string) => void };
function Workspace(p: WS) {
  const { d } = p;
  const toast = useToast();
  const icon = useIcon(d.textures);
  const apply = useCallback((r: { ok: true; files: DesignFile[] } | { ok: false; error: string }) => { if (r.ok) d.setFiles(r.files); else toast(r.error, true); }, [d, toast]);
  const setParam = useCallback((path: string, v: number | string) => apply(setParamValue(d.files, path, v)), [apply, d.files]);
  // quest progress simulator (shared by the chain status and the right column)
  const [qsteps, setQsteps] = useState<QuestStep[]>([]);
  const [qsim, setQsim] = useState<QuestSimResult | null>(null);
  const [qerr, setQerr] = useState<string | null>(null);
  useEffect(() => {
    if (!d.pid || !p.quests.length) return;
    const t = window.setTimeout(() => { designerApi.simQuests(d.pid!, d.files, qsteps).then((r) => { setQsim(r.result); setQerr(null); }).catch((e) => setQerr((e as Error).message)); }, 200);
    return () => window.clearTimeout(t);
  }, [d.pid, d.files, qsteps, p.quests.length]);
  return (
    <>
      <main className="dz-ws" aria-label={p.tab === "quests" ? "Quest Designer" : "Menu Designer"}>
        <LeftColumn {...p} icon={icon} />
        {p.tab === "menus" && p.m ? <MenuEditor {...p} m={p.m} icon={icon} setParam={setParam} /> : p.tab === "quests" && p.q ? <QuestEditor {...p} q={p.q} icon={icon} setParam={setParam} qsim={qsim} qerr={qerr} qsteps={qsteps} setQsteps={setQsteps} /> : (
          <div className="dz-col" style={{ gridColumn: "2 / 4" }}><div className="cys-panel cys-glass" style={{ flex: 1, display: "grid", placeItems: "center" }}><div className="cys-empty"><DI n={p.tab === "menus" ? "slots" : "scroll"} /><p>This mod has no {p.tab} yet.</p></div></div></div>
        )}
      </main>
      <Narrow {...p} icon={icon} qsim={qsim} />
    </>
  );
}

// ----------------------------------------------------------------------------------------------------- left
function LeftColumn({ d, tab, setTab, menus, quests, m, q, setMenu, setQuest, mod, icon }: WS & { icon: (r?: string, m?: string) => Raster }) {
  const a = d.analysis;
  const tone = (id: string) => { const f = a?.files.find((x) => x.id === id); return !f ? "" : f.errors.length ? "bad" : f.warnings.length ? "warn" : "ok"; };
  const items = d.files.filter(isItem);
  const used = items.filter((it) => menus.some((mm) => JSON.stringify(mm).includes(`"${it.id}"`)) || quests.some((qq) => JSON.stringify(qq).includes(`"${it.id}"`)));
  const qIcon = (x: QuestDesign) => x.icon?.material ?? x.icon?.item ?? (x.steps[0]?.objectives[0] && "item" in x.steps[0].objectives[0] ? String((x.steps[0].objectives[0] as { item: string }).item) : x.steps[0]?.objectives[0]?.type === "break_block" ? (x.steps[0].objectives[0] as { block: string }).block : "minecraft:paper");
  return (
    <div className="dz-col scroll">
      <section className="cys-panel cys-glass cys-hairline">
        <div className="cys-ph"><span className="cys-eyebrow">Menus</span><span className="n">{menus.length} / {d.view!.limits.maxMenus}</span></div>
        <div className="dz-body">
          {menus.map((x) => (
            <button key={x.id} type="button" className={`dz-row ${tab === "menus" && m?.id === x.id ? "on" : ""}`} onClick={() => { setMenu(x.id); setTab("menus"); }}>
              <span className="dz-thumb"><Ico r={icon(x.style === "chest" ? x.buttons?.[0]?.icon.material ?? "minecraft:chest" : x.speakerIcon?.material ?? "minecraft:compass")} size={22} /></span>
              <span className="tx"><b>{x.id}</b><small>{x.style === "chest" ? `chest · ${x.rows} rows${x.list ? " · list" : ""}` : `dialogue · ${x.choices.length} choices`}</small></span>
              <span className={`cys-dot ${tone(x.id)}`} />
            </button>
          ))}
        </div>
      </section>
      <section className="cys-panel cys-glass">
        <div className="cys-ph"><span className="cys-eyebrow">Quests</span><span className="n">{quests.length} / {d.view!.limits.maxQuests}</span></div>
        <div className="dz-body">
          {quests.map((x) => (
            <button key={x.id} type="button" className={`dz-row ${tab === "quests" && q?.id === x.id ? "on" : ""}`} onClick={() => { setQuest(x.id); setTab("quests"); }}>
              <span className="dz-thumb"><Ico r={icon(qIcon(x))} size={22} /></span>
              <span className="tx"><b>{x.id}</b><small>{x.repeat && x.repeat.mode !== "once" ? x.repeat.mode : x.requires?.length ? `after ${x.requires[0]}` : x.start === "menu" ? "starts from a menu" : "first"}{x.branches ? " · branch" : ""}</small></span>
              <span className={`cys-dot ${tone(x.id)}`} />
            </button>
          ))}
        </div>
      </section>
      {!!used.length && (
        <section className="cys-panel cys-glass">
          <div className="cys-ph"><span className="cys-eyebrow">Items used</span></div>
          <div className="dz-body">
            {used.map((it) => <div key={it.id} className="dz-row"><span className="dz-thumb"><Ico r={icon(it.base, it.assets?.model)} size={22} /></span><span className="tx"><b>{it.id}</b><small>{menus.some((mm) => mm.style === "chest" && mm.openWith?.item === it.id) ? "opens a menu" : it.abilities.length ? `ability ${it.abilities[0].id}` : "a design item"}</small></span></div>)}
            <Link className="cys-btn xs ghost" href={designerHref(mod, "items")} style={{ marginTop: 4 }}><DI n="sword" />Open the Item Designer</Link>
          </div>
        </section>
      )}
    </div>
  );
}

// ------------------------------------------------------------------------------------------------- menu editor
type SlotModel = { kind: "button"; i: number; path: string; c: { icon: { material?: string; item?: string; name?: { text: string; color?: string }; lore?: { text: string }[]; amount?: number }; actions?: MenuAction[]; cost?: Cost; permission?: string } }
  | { kind: "list"; li: number; idx: number; e: { material: string; amount: number; price: number; name?: string } | null; fixed?: { icon: { material?: string; item?: string; name?: { text: string; color?: string } }; actions?: MenuAction[]; cost?: Cost; permission?: string } | null }
  | { kind: "nav"; dir: "prev" | "next" } | { kind: "filler" } | { kind: "choice"; i: number; c: DialogueMenu["choices"][number] };

function slotModel(m: MenuDesign, slot: number, page: number): SlotModel {
  if (m.style === "dialogue") { const pos = DIALOGUE_POS[Math.min(5, m.choices.length)]; const i = pos.indexOf(slot); return i >= 0 ? { kind: "choice", i, c: m.choices[i] } : { kind: "filler" }; }
  const bi = (m.buttons ?? []).findIndex((b) => b.slot === slot);
  if (bi >= 0) return { kind: "button", i: bi, path: `b${slot}`, c: m.buttons![bi] };
  const L = m.list;
  if (L) {
    const li = L.slots.indexOf(slot);
    if (li >= 0) {
      const idx = page * L.slots.length + li;
      if (L.source.type === "config") return { kind: "list", li, idx, e: L.source.entries[idx] ?? null };
      return { kind: "list", li, idx, e: null, fixed: L.source.entries[idx] ?? null };
    }
    if (slot === L.prev.slot) return { kind: "nav", dir: "prev" };
    if (slot === L.next.slot) return { kind: "nav", dir: "next" };
  }
  return { kind: "filler" };
}
const pagesOf = (m: ChestMenu) => (m.list ? Math.max(1, Math.ceil((m.list.source.type === "config" ? m.list.source.entries.length : m.list.source.entries.length) / m.list.slots.length)) : 1);
const currencyOf = (m: ChestMenu): Cost["type"] | "free" => (m.list?.source.type === "config" ? m.list.source.currency.type : "free");
const listCost = (m: ChestMenu, e: { price: number }): Cost | undefined => { const c = m.list?.source.type === "config" ? m.list.source.currency : null; return !c ? undefined : c.type === "item" ? { type: "item", item: c.item, count: Math.round(e.price) } : c.type === "xp_levels" ? { type: "xp_levels", levels: Math.round(e.price) } : c.type === "economy" ? { type: "economy", amount: e.price } : undefined; };

function MenuEditor({ d, m, icon, setParam }: WS & { m: MenuDesign; icon: (r?: string, mm?: string) => Raster; setParam: (path: string, v: number | string) => void }) {
  const toast = useToast();
  const [mode, setMode] = useState<"edit" | "try">("edit");
  const [page, setPage] = useState(0);
  const [sel, setSel] = useState<number>(() => (m.style === "chest" ? (m.buttons?.find((b) => b.cost)?.slot ?? m.buttons?.[0]?.slot ?? 0) : DIALOGUE_POS[Math.min(5, m.choices.length)][0]));
  const [clicks, setClicks] = useState<number[]>([]);
  const [tryRes, setTryRes] = useState<TryResult | null>(null);
  const [flash, setFlash] = useState<{ slot: number; ok: boolean } | null>(null);
  useEffect(() => { setPage(0); setClicks([]); setTryRes(null); }, [m.id]);
  useEffect(() => {
    if (mode !== "try" || !d.pid) return;
    let live = true;
    designerApi.tryMenu(d.pid, d.files, m.id, clicks).then((r) => { if (!live) return; setTryRes(r.result); const last = r.result.clicks[r.result.clicks.length - 1]; if (last) { setFlash({ slot: last.slot, ok: last.ran }); if (r.result.open && r.result.open.menu === m.id) setPage(r.result.open.page); } }).catch((e) => toast((e as Error).message, true));
    return () => { live = false; };
  }, [mode, clicks, d.pid, d.files, m.id, toast]);
  useEffect(() => { if (!flash) return; const t = window.setTimeout(() => setFlash(null), 650); return () => window.clearTimeout(t); }, [flash]);
  const size = m.style === "chest" ? m.rows * 9 : 27;
  const params = d.params.filter((p) => p.owner === "menu" && p.item === m.id);
  const cmd = d.analysis?.compile.ok ? d.analysis.compile.command : d.view!.pluginName.toLowerCase();
  const opener = m.style === "chest" ? [m.openWith?.command !== false ? `/${cmd} menu ${m.id}` : null, m.openWith?.item ? `right-click ${m.openWith.item}` : null, m.openWith?.npc ? "an NPC" : null].filter(Boolean).join(" · ") : `/${cmd} menu ${m.id}${m.openWith?.npc ? " · an NPC" : ""}`;
  const pages = m.style === "chest" ? pagesOf(m) : 1;
  const click = (slot: number) => {
    if (mode === "edit") { setSel(slot); return; }
    if (clicks.length >= 40) { toast("Reset the sample player first (40 clicks max)", true); return; }
    setClicks([...clicks, slot]); setSel(slot);
  };
  const rowsP: Param = { path: "", field: "", kind: "int", min: 1, max: 6, value: m.style === "chest" ? m.rows : 3, label: "rows (1 to 6)", item: m.id, role: "count" };
  const setRows = (v: number | string) => {
    if (m.style !== "chest") return;
    const rows = Math.max(1, Math.min(6, Math.round(Number(v))));
    d.setFiles(d.files.map((f) => (f.id === m.id ? { ...(f as ChestMenu), rows } : f)));
    toast(`Rows ${rows}: a structure change (the menu's Java file). The validator checks slots still fit.`);
  };
  const setEntry = (idx: number, field: "amount" | "price", v: number | string) => {
    d.setFiles(d.files.map((f) => {
      if (f.id !== m.id || (f as MenuDesign).style !== "chest") return f;
      const c = structuredClone(f) as ChestMenu;
      if (c.list?.source.type === "config") { const e = c.list.source.entries[idx]; if (e) e[field] = Number(v); }
      return c;
    }));
  };
  const rep = d.analysis?.files.find((f) => f.id === m.id);
  return (
    <>
      <div className="dz-col">
        <DraftLine d={d} />
        <section className="cys-panel cys-glass cys-hairline" style={{ flex: 1, minHeight: 0, display: "flex", flexDirection: "column" }}>
          <div className="dz-mhead">
            <span className="cys-eyebrow">Menu</span><McText t={{ text: m.title, color: m.style === "chest" ? m.buttons?.find((b) => b.icon.name?.text === m.title)?.icon.name?.color ?? "gold" : m.speaker.color ?? "gold" }} /><span className="cys-tag dim">{m.style}</span><span style={{ flex: 1 }} />
            {m.style === "chest" && <><span className="dz-sub">Rows</span><ParamField p={rowsP} onSet={setRows} /></>}
            <div className="cys-seg sm cys-soft"><button type="button" className={mode === "edit" ? "on" : ""} aria-pressed={mode === "edit"} onClick={() => setMode("edit")}><DI n="edit" />Edit</button><button type="button" className={mode === "try" ? "on" : ""} aria-pressed={mode === "try"} onClick={() => setMode("try")}><DI n="play" />Try it</button></div>
          </div>
          <div className="dz-scroll" style={{ flex: 1, padding: "0 0 14px" }}>
            <div className="dz-gui">
              <div className="dz-gui-t"><McText t={{ text: m.title, color: "gold" }} /><span className="dz-mono" style={{ marginLeft: "auto" }}>{opener}</span></div>
              <div className="dz-grid9" role="grid" aria-label={`${m.title}: ${size} slots`}>
                {Array.from({ length: size }, (_, i) => {
                  const sm = slotModel(m, i, page);
                  const live = mode === "try" && tryRes?.open?.menu === m.id ? tryRes.open.slots.find((s) => s.slot === i) : undefined;
                  let inner: React.ReactNode = null, cls = "";
                  if (sm.kind === "button") inner = <><Ico r={icon(sm.c.icon.material ?? sm.c.icon.item)} size={32} />{sm.c.cost && <span className="cst" title="has a cost" />}{sm.c.permission && <span className="lk" title={`needs ${d.view!.project!.namespace}.${sm.c.permission}`}><DI n="lock" /></span>}{(sm.c.icon.amount ?? 1) > 1 && <span className="amt">{sm.c.icon.amount}</span>}</>;
                  else if (sm.kind === "list") { cls = "list"; const mat = sm.e?.material ?? sm.fixed?.icon.material ?? sm.fixed?.icon.item; if (mat) inner = <><Ico r={icon(mat)} size={32} />{sm.e && sm.e.amount > 1 && <span className="amt">{sm.e.amount}</span>}</>; }
                  else if (sm.kind === "nav") { const dis = mode === "try" ? !live : (sm.dir === "prev" && page === 0) || (sm.dir === "next" && page >= pages - 1); inner = <span style={{ opacity: dis ? 0.35 : 1, display: "grid" }}><Ico r={icon("minecraft:arrow")} size={32} /></span>; }
                  else if (sm.kind === "choice") inner = <Ico r={icon(sm.c.icon.material ?? sm.c.icon.item)} size={32} />;
                  else { cls = "filler"; if (m.style === "chest" && m.filler) inner = <Ico r={icon(m.filler)} size={32} />; }
                  const fl = flash?.slot === i ? (flash.ok ? "flash" : "deny") : "";
                  return (
                    <button key={i} type="button" role="gridcell" className={`dz-slot ${cls} ${sel === i && mode === "edit" ? "sel" : ""} ${fl}`} onClick={() => click(i)} aria-label={`slot ${i}${sm.kind === "button" ? `: ${sm.c.icon.name?.text ?? ""}` : sm.kind === "list" ? ": list" : ""}`} aria-selected={sel === i}>
                      {inner}{mode === "edit" && sm.kind !== "filler" && <span className="no">{i}</span>}
                    </button>
                  );
                })}
              </div>
              {m.style === "chest" && m.list && (
                <div className="dz-pager">
                  <button type="button" className="cys-ib sm" aria-label="Previous page" disabled={page === 0 || mode === "try"} onClick={() => setPage(page - 1)}><DI n="chevL" /></button>
                  <span>Page {page + 1} of {pages}</span>·<span>{m.list.slots.length} list slots per page</span>·<span>{m.list.source.entries.length} entries{m.list.source.type === "config" ? " from config.yml" : ""}</span>
                  <button type="button" className="cys-ib sm" aria-label="Next page" disabled={page >= pages - 1 || mode === "try"} onClick={() => setPage(page + 1)}><DI n="chevR" /></button>
                </div>
              )}
            </div>
            {m.style === "dialogue" && (
              <div style={{ maxWidth: 520, margin: "12px auto 0", padding: "0 14px" }}>
                <div className="dz-note"><DI n="user" /><span><McText t={m.speaker} />: {m.lines.join(" ")}</span></div>
              </div>
            )}
            <div className="dz-legend"><span><i />Button</span>{m.style === "chest" && m.list && <span><i className="l" />List slot (page)</span>}<span><i className="c" />Has a cost{m.style === "chest" && m.list?.source.type === "config" ? " (list entries always cost)" : ""}</span><span><DI n="lock" /> Needs a permission</span></div>
            <p className="cys-hint" style={{ textAlign: "center", margin: "6px 0 0" }}>{PLACEHOLDER_NOTE}</p>
            {m.style === "chest" && m.list?.source.type === "config" && (
              <div style={{ padding: "12px 14px 0" }}>
                <div className="cys-eyebrow" style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 6 }}>Shop list <span className="cys-tag dim">lists.{m.id}</span><span className="cys-hint" style={{ letterSpacing: 0, textTransform: "none", fontFamily: "var(--font-inter), sans-serif", fontWeight: 400, marginLeft: "auto" }}>The server owner edits this in config.yml ({d.view!.limits.maxConfigEntries} entries max). No rebuild.</span></div>
                <div style={{ border: "1px solid var(--line)", borderRadius: 10, maxHeight: 260, overflow: "auto" }}>
                  <table className="dz-ctab"><thead><tr><th>#</th><th>Item</th><th>Amount</th><th>Price</th><th>Name</th></tr></thead><tbody>
                    {m.list.source.entries.map((e, i) => {
                      const s = slotModel(m, sel, page);
                      const pa: Param = { path: "", field: "", kind: "int", min: 1, max: 64, value: e.amount, label: `entry ${i + 1} amount`, item: m.id, role: "count" };
                      const pp: Param = { path: "", field: "", kind: currencyOf(m) === "economy" ? "num" : "int", min: 0, max: 1000000, value: e.price, label: `entry ${i + 1} price`, item: m.id, role: "price" };
                      const saved = (d.saved.find((f) => f.id === m.id) as ChestMenu | undefined)?.list?.source;
                      const se = saved?.type === "config" ? saved.entries[i] : undefined;
                      return (
                        <tr key={i} className={s.kind === "list" && s.idx === i ? "on" : ""}>
                          <td className="m">{i + 1}</td>
                          <td><span style={{ display: "inline-flex", gap: 8, alignItems: "center" }}><Ico r={icon(e.material)} size={18} /><span className="dz-mono" style={{ color: "var(--ink-2)" }}>{bare(e.material)}</span></span></td>
                          <td><ParamField p={pa} was={se?.amount} onSet={(v) => setEntry(i, "amount", v)} /></td>
                          <td><span style={{ display: "inline-flex", gap: 5, alignItems: "center" }}>{m.list!.source.type === "config" && m.list!.source.currency.type === "item" && <Ico r={icon(m.list!.source.currency.item)} size={14} />}<ParamField p={pp} was={se?.price} onSet={(v) => setEntry(i, "price", v)} /></span></td>
                          <td>{e.name ?? <span style={{ color: "var(--faint)" }}>item name</span>}</td>
                        </tr>
                      );
                    })}
                  </tbody></table>
                </div>
              </div>
            )}
          </div>
        </section>
      </div>
      <div className="dz-col">
        <section className="cys-panel cys-glass cys-hairline" style={{ flex: 1, minHeight: 0 }}>
          <div className="cys-ph"><span className="cys-eyebrow">{mode === "try" ? "Try it" : "Slot"}</span>{mode === "try" && <span className="cys-tag dim">simulated</span>}</div>
          <div className="dz-scroll" style={{ flex: 1 }}>
            <SlotInspector d={d} m={m} slot={sel} page={page} icon={icon} params={params} setParam={setParam} mode={mode} tryRes={tryRes} onReset={() => setClicks([])} />
            <div className="dz-sec">
              <span className="cys-eyebrow"><DI n="shield" /> Anti-dupe, built in</span>
              <ol className="dz-proto"><li>Room for the given stacks</li><li>Can the player pay</li><li>Take, re-checked, all-or-nothing</li><li>Give</li></ol>
              <div className="dz-guard"><DI n="check" /><span>Every click and drag in a menu is cancelled. Only plain left and right clicks act.</span></div>
              <div className="dz-guard"><DI n="check" /><span>Click cooldown <code className="mono">general.menu_click_cooldown_ticks</code>, 2–40 ticks. Icons are flagged and swept on close or drop.</span></div>
            </div>
            <div className="dz-sec">
              <span className="cys-eyebrow">Checks · {m.id}</span>
              <ul className="dz-issues">
                {(rep?.errors ?? []).map((e, i) => <IssueRow key={`e${i}`} i={e} tone="err" />)}
                {(rep?.warnings ?? []).map((e, i) => <IssueRow key={`w${i}`} i={e} tone="warn" />)}
                {(d.analysis?.gameplayChecks.menu ?? []).filter((c) => c.status === "pass" || c.status === "not_run").map((c) => (
                  <li key={c.id} className={`dz-issue ${c.status === "pass" ? "ok" : "info"}`}><span className="ic"><DI n={c.status === "pass" ? "check" : "minus"} /></span><code>{c.id}</code><span className="path">{c.status === "pass" ? "pass, all menus" : "not run"}</span></li>
                ))}
              </ul>
            </div>
            <div className="dz-sec"><div className="dz-note"><DI n="info" /><span>Validated, compiled and simulated. Menus and the dupe rules have not been verified with a real player in a game client.</span></div></div>
          </div>
          <PendingBar d={d} labels={(id) => id} />
        </section>
      </div>
    </>
  );
}

function CostChip({ c, icon }: { c?: Cost; icon: (r?: string) => Raster }) {
  if (!c) return <span className="dz-achip">free</span>;
  return <span className="dz-achip cost">{c.type === "item" ? <Ico r={icon(c.item)} size={16} /> : <DI n={c.type === "xp_levels" ? "sparkle" : "coin"} />}<code>{costText(c)}</code></span>;
}
function ActChip({ a, icon }: { a: MenuAction; icon: (r?: string) => Raster }) {
  const extra = a.type === "give_item" ? ` ${bare(a.item)} ×${a.count ?? 1}` : a.type === "run_ability" ? ` ${a.item}.${a.ability}` : a.type === "play_sound" ? ` ${bare(a.sound).split(".").pop()}` : a.type === "open_menu" ? ` ${a.menu}` : a.type === "start_quest" || a.type === "abandon_quest" ? ` ${a.quest}` : a.type === "choose_branch" ? ` ${a.quest}.${a.branch}` : a.type === "potion_effect" ? ` ${a.effect}` : "";
  return <span className="dz-achip">{a.type === "give_item" ? <Ico r={icon(a.item)} size={16} /> : <DI n={ACT_IC[a.type] ?? "play"} />}<code>{a.type}</code>{extra}</span>;
}

function SlotInspector({ d, m, slot, page, icon, params, setParam, mode, tryRes, onReset }: { d: Designer; m: MenuDesign; slot: number; page: number; icon: (r?: string) => Raster; params: Param[]; setParam: (p: string, v: number | string) => void; mode: "edit" | "try"; tryRes: TryResult | null; onReset: () => void }) {
  const sm = slotModel(m, slot, page);
  const ns = d.view!.project!.namespace;
  const node = sm.kind === "button" ? `b${slot}` : sm.kind === "choice" ? `c${sm.i}` : sm.kind === "list" && sm.fixed ? `e${sm.idx}` : null;
  const mine = node ? params.filter((p) => p.path.startsWith(`menus.${m.id}.${node}.`)) : [];
  let head: React.ReactNode, body: React.ReactNode = null;
  const click = sm.kind === "button" ? sm.c : sm.kind === "choice" ? sm.c : sm.kind === "list" ? sm.fixed ?? null : null;
  if (click) {
    head = <><div className="big"><Ico r={icon(click.icon.material ?? click.icon.item)} size={36} /></div><div style={{ minWidth: 0 }}><div><McText t={click.icon.name ?? { text: bare(click.icon.material ?? click.icon.item ?? ""), color: "white" }} /></div><div className="dz-mono" style={{ marginTop: 4 }}>slot {slot} · {sm.kind === "choice" ? `choice ${sm.i + 1}` : sm.kind === "list" ? `list entry ${sm.idx + 1}` : "button"}{click.icon.item ? " · design item icon" : ""}</div></div></>;
    body = (
      <>
        {!!click.icon.lore?.length && <div className="dz-sec"><span className="cys-eyebrow">Lore</span>{click.icon.lore.map((l, i) => <div key={i} className="cys-hint" style={{ fontStyle: "italic" }}>{l.text}</div>)}</div>}
        <div className="dz-sec">
          <span className="cys-eyebrow">On click <span className="cys-tag dim">{(click.actions ?? []).length} / {d.view!.limits.maxClickActions}</span></span>
          <ol className="dz-proto">{click.cost && <li><span>Pays <CostChip c={click.cost} icon={icon} /></span></li>}{(click.actions ?? []).map((a, i) => <li key={i}><span><ActChip a={a} icon={icon} /></span></li>)}{!click.cost && !(click.actions ?? []).length && <li><span className="dz-sub">shows only (no action)</span></li>}</ol>
        </div>
        {!!mine.length && <div className="dz-sec"><span className="cys-eyebrow">Settings <span className="cys-tag dim">config.yml</span></span>{mine.map((p) => <ParamRow key={p.path} d={d} p={p} strip={`menus.${m.id}.`} setParam={setParam} />)}</div>}
        {click.permission && <div className="dz-sec"><span className="cys-eyebrow">Permission</span><div className="dz-flow"><span className="dz-achip"><DI n="key" /><code>{ns}.{click.permission}</code></span><span className="dz-achip">default {m.permissions?.find((x) => x.node === click.permission)?.default ?? "op"}</span><span className="dz-achip"><DI n="lock" />{"hideWithoutPermission" in click && click.hideWithoutPermission ? "hidden without it" : "shown locked"}</span></div></div>}
        {click.cost?.type === "economy" && <div className="dz-sec"><div className="dz-note warn"><DI n="warn" /><span><code className="mono">economy_needs_vault</code> · money costs work only when Vault and an economy plugin are on the server. Otherwise the click is refused with a clear message.</span></div></div>}
      </>
    );
  } else if (sm.kind === "list" && m.style === "chest") {
    const c = sm.e ? listCost(m, sm.e) : undefined;
    head = sm.e ? <><div className="big"><Ico r={icon(sm.e.material)} size={36} /></div><div><div className="mct" style={{ ["--mc" as string]: "#fff" }}>{sm.e.name ?? bare(sm.e.material).replace(/_/g, " ")}</div><div className="dz-mono" style={{ marginTop: 4 }}>slot {slot} · list entry {sm.idx + 1} of {m.list!.source.entries.length}</div></div></> : <><div className="big" /><div><b>Empty list slot</b><div className="dz-mono">page {page + 1}</div></div></>;
    body = sm.e ? <div className="dz-sec"><span className="cys-eyebrow">On click</span><ol className="dz-proto"><li><span>Pays <CostChip c={c} icon={icon} /></span></li><li><span><ActChip a={{ type: "give_item", item: sm.e.material, count: sm.e.amount }} icon={icon} /></span></li></ol><p className="cys-hint" style={{ margin: "8px 0 0" }}>Every list entry is “buy amount × item for the price”. The owner changes prices in config.yml without a rebuild.</p></div> : null;
  } else if (sm.kind === "nav" && m.style === "chest") {
    head = <><div className="big"><Ico r={icon("minecraft:arrow")} size={36} /></div><div><b>{sm.dir === "prev" ? "Previous" : "Next"} page</b><div className="dz-mono">slot {slot} · list {sm.dir}</div></div></>;
    const navP = params.filter((p) => p.path.startsWith(`menus.${m.id}.${sm.dir}.`));
    body = <div className="dz-sec"><div className="dz-flow"><ActChip a={{ type: sm.dir === "prev" ? "prev_page" : "next_page" }} icon={icon} /></div>{navP.map((p) => <ParamRow key={p.path} d={d} p={p} strip={`menus.${m.id}.`} setParam={setParam} />)}</div>;
  } else {
    head = <><div className="big">{m.style === "chest" && m.filler && <Ico r={icon(m.filler)} size={36} />}</div><div><b>{m.style === "chest" && m.filler ? "Filler" : "Empty"}</b><div className="dz-mono">slot {slot}{m.style === "chest" && m.filler ? ` · ${bare(m.filler)}` : ""}</div></div></>;
    if (m.style === "dialogue") body = <div className="dz-sec">{params.filter((p) => /\.(title|speaker|line\d)$/.test(p.path)).map((p) => <ParamRow key={p.path} d={d} p={p} strip={`menus.${m.id}.`} setParam={setParam} />)}</div>;
  }
  if (mode === "try") {
    const last = tryRes?.clicks[tryRes.clicks.length - 1];
    const cur = tryRes?.inventory ?? [];
    return (
      <>
        <div className="dz-insh">{head}</div>
        <div className="dz-sec">
          <span className="cys-eyebrow">Sample player <button type="button" className="cys-btn xs ghost" style={{ marginLeft: "auto" }} onClick={onReset}><DI n="rollback" />Reset</button></span>
          <div className="dz-inv">
            {cur.slice(0, 6).map((x) => <span key={x.item} className="dz-achip"><Ico r={icon(x.item)} size={16} /><code>{x.count}</code></span>)}
            <span className="dz-achip"><DI n="sparkle" /><code>level {tryRes?.levels ?? 7}</code></span><span className="dz-achip"><DI n="coin" /><code>no Vault</code></span>
          </div>
          {last ? <ol className="dz-proto" style={{ marginTop: 10 }}>{last.steps.map((s, i) => <li key={i} className={s.ok ? "ok" : "no"}><span>{s.text}</span></li>)}{!last.steps.length && <li className={last.ran ? "ok" : "no"}><span>{last.reason}</span></li>}</ol>
            : <p className="cys-hint" style={{ margin: "8px 0 0" }}>Click any item in the menu to buy it with the fixed click protocol. The sample player starts with 9 emeralds, level 7, 6 free slots and every permission of this menu.</p>}
          <ul className="dz-slog" style={{ marginTop: 8, maxHeight: 140 }}>{(tryRes?.log ?? []).slice(0, 10).map((l, i) => <li key={i} className={l.tone} style={{ gridTemplateColumns: "1fr" }}><span>{l.text}</span></li>)}{!tryRes?.log.length && <li className="fx" style={{ gridTemplateColumns: "1fr" }}><span>no clicks yet</span></li>}</ul>
        </div>
      </>
    );
  }
  return <><div className="dz-insh">{head}</div>{body}</>;
}

function ParamRow({ d, p, strip, setParam }: { d: Designer; p: Param; strip: string; setParam: (path: string, v: number | string) => void }) {
  const was = d.savedParams.get(p.path)?.value;
  const changed = was !== undefined && String(was) !== String(p.value);
  return (
    <div className="dz-prow">
      <span className="pl">{p.label.replace(/^./, (c) => c.toUpperCase())}</span>
      <span className="pp" title={p.path}>{p.path.replace(strip, "")}</span>
      <span className="pv"><ParamField p={p} was={was} onSet={(v) => setParam(p.path, v)} compact /><span className="rg">{changed && <><span className="was">{String(was)}</span> · </>}{rangeText(p)}</span></span>
    </div>
  );
}

// ------------------------------------------------------------------------------------------------ quest editor
const OBJ_IC: Record<string, string> = { kill_entity: "sword", collect_item: "package", break_block: "pickaxe", craft_item: "wrench", visit_location: "globe", talk: "note", survive: "heart" };
function objText(o: Objective): string {
  switch (o.type) {
    case "kill_entity": return o.entity ? bare(o.entity) : (o.kinds ?? []).join(" or ");
    case "collect_item": return `${bare(o.item)}${o.take ? " · taken" : ""}${o.mode === "pickup" ? " · pick up" : ""}`;
    case "craft_item": return bare(o.item);
    case "break_block": return bare(o.block);
    case "visit_location": return `${o.world} ${o.x} ${o.y} ${o.z} · r ${o.radius}`;
    case "talk": return `dialogue ${o.menu}`;
    case "survive": return "stay alive";
  }
}
function RewardChip({ r, icon }: { r: Reward; icon: (x?: string) => Raster }) {
  return <span className="dz-rwc">{r.type === "give_item" ? <Ico r={icon(r.item)} size={14} /> : <DI n={r.type === "xp" ? "sparkle" : r.type === "send_message" ? "note" : r.type === "potion_effect" ? "flask" : r.type === "run_ability" ? "bolt" : "gift"} />}{r.type === "give_item" ? `${bare(r.item)} ×${r.count ?? 1}` : r.type === "xp" ? (r.points !== undefined ? `${r.points} xp` : `${r.levels} levels`) : r.type === "send_message" ? "message" : r.type === "potion_effect" ? `${r.effect} ${Math.round(r.durationTicks / 20)} s` : r.type === "advancement" ? "advancement" : `${r.item}.${r.ability}`}</span>;
}

function QuestEditor({ d, quests, q, setQuest, icon, setParam, qsim, qerr, qsteps, setQsteps }: WS & { q: QuestDesign; icon: (r?: string) => Raster; setParam: (p: string, v: number | string) => void; qsim: QuestSimResult | null; qerr: string | null; qsteps: QuestStep[]; setQsteps: (s: QuestStep[]) => void }) {
  const params = d.params.filter((p) => p.owner === "quest" && p.item === q.id);
  const pAt = (rel: string) => params.find((p) => p.path === `quests.${q.id}.${rel}`);
  const st = (id: string) => qsim?.states.find((s) => s.id === id);
  // chain order: by prerequisite depth, repeats last
  const depth = (x: QuestDesign, seen = new Set<string>()): number => { if (seen.has(x.id)) return 0; seen.add(x.id); return Math.max(0, ...(x.requires ?? []).map((r) => { const y = quests.find((z) => z.id === r); return y ? depth(y, seen) + 1 : 0; })); };
  const once = quests.filter((x) => (x.repeat?.mode ?? "once") === "once").sort((a, b) => depth(a) - depth(b) || (a.id < b.id ? -1 : 1));
  const rep = quests.filter((x) => (x.repeat?.mode ?? "once") !== "once");
  const node = (x: QuestDesign) => { const s = st(x.id); return (
    <button key={x.id} type="button" className={`dz-qnode ${x.id === q.id ? "on" : ""}`} onClick={() => setQuest(x.id)} aria-current={x.id === q.id}>
      <b>{x.title}</b><small>{x.id}{x.branches ? ` · ${x.branches.options.length} paths` : ""}{x.repeat && x.repeat.mode !== "once" ? ` · ${x.repeat.mode}` : ""}</small>
      <small className={s?.status === "done" ? "st-done" : s?.status === "active" || s?.status === "choosing" ? "st-active" : ""}>{s?.status ?? "…"}</small>
    </button>
  ); };
  const objRow = (stepId: string, o: Objective, j: number) => {
    const cnt = o.type === "survive" ? pAt(`steps.${stepId}.o${j}.seconds`) : o.type === "visit_location" || o.type === "talk" ? undefined : pAt(`steps.${stepId}.o${j}.count`);
    const s = st(q.id);
    const live = s && s.status === "active" && s.text.startsWith(q.steps.concat(...(q.branches?.options.map((b) => b.steps) ?? [])).find((x) => x.id === stepId)?.text ?? "\u0000") && j === 0 ? s.cur : null;
    const ref = o.type === "collect_item" || o.type === "craft_item" ? o.item : o.type === "break_block" ? o.block : undefined;
    return (
      <div key={j} className="dz-obj">
        {ref ? <Ico r={icon(ref)} size={18} /> : <DI n={OBJ_IC[o.type] ?? "flag"} />}<code>{o.type}</code><span>{objText(o)}</span>
        <span className="cnt">{live !== null && <span title="sample player progress">{live} /</span>}{cnt ? <ParamField p={cnt} was={d.savedParams.get(cnt.path)?.value} onSet={(v) => setParam(cnt.path, v)} /> : o.type === "visit_location" || o.type === "talk" ? "once" : ""}{o.type === "survive" && " s"}</span>
      </div>
    );
  };
  const chosen = qsteps.filter((x) => x.k === "choose" && x.quest === q.id).map((x) => (x as { branch: string }).branch).pop();
  const allRows = d.analysis?.gameplayChecks.quest ?? [];
  const L = d.view!.limits;
  return (
    <>
      <div className="dz-col">
        <DraftLine d={d} />
        <section className="cys-panel cys-glass cys-hairline">
          <div className="cys-ph"><span className="cys-eyebrow">Quest chain</span><span className="cys-hint">prerequisites, left to right</span></div>
          <div className="dz-chain">{once.map((x, i) => <span key={x.id} style={{ display: "contents" }}>{i > 0 && <span className="dz-qlink" />}{node(x)}</span>)}{!!rep.length && <span className="dz-qsep" />}{rep.map((x, i) => <span key={x.id} style={{ display: "contents" }}>{i > 0 && <span style={{ width: 8 }} />}{node(x)}</span>)}</div>
        </section>
        <section className="cys-panel cys-glass" style={{ flex: 1, minHeight: 0, display: "flex", flexDirection: "column" }}>
          <div className="dz-mhead">
            <span className="cys-eyebrow">Quest</span><span style={{ font: "600 16px/1 var(--display)" }}>{q.title}</span><span className="dz-mono">{q.id}</span><span style={{ flex: 1 }} />
            <span className="dz-achip"><DI n="flag" />{q.requires?.length ? <>requires <code>{q.requires.join(", ")}</code></> : "no prerequisite"}</span>
            <span className="dz-achip"><DI n="loopq" />{q.repeat && q.repeat.mode !== "once" ? <><code>{q.repeat.mode}</code>{pAt("repeat.cooldown_seconds") ? ` · ${Math.round(Number(pAt("repeat.cooldown_seconds")!.value) / 3600)} h` : ""}</> : "once"}</span>
            <span className="dz-achip"><DI n="play" />start: <code>{q.start ?? "command"}</code></span>
          </div>
          <div className="dz-qflow dz-scroll" style={{ flex: 1 }}>
            {q.steps.map((s, i) => (
              <div key={s.id} className="dz-fstep"><div className="dz-rail"><i>{i + 1}</i></div>
                <div className="dz-fcard"><h4>{s.text}<span className="dz-mono">{s.id}</span></h4>{s.objectives.map((o, j) => objRow(s.id, o, j))}</div></div>
            ))}
            {q.branches && (
              <div className="dz-fstep"><div className="dz-rail"><i><DI n="branch" /></i></div>
                <div className="dz-fcard"><h4>{q.branches.prompt ?? "Choose a path"}<span className="dz-mono">choice menu · {q.branches.options.length} of {L.maxBranches}</span></h4>
                  <div className="dz-branches">{q.branches.options.map((b) => (
                    <div key={b.id} className={`dz-bcol ${chosen === b.id ? "on" : ""}`}>
                      <h5>{b.icon && <Ico r={icon(b.icon.material ?? b.icon.item)} size={18} />}<McText t={b.label} /><span className="dz-mono" style={{ marginLeft: "auto" }}>{b.id}</span></h5>
                      {b.steps.map((s) => <div key={s.id}><div className="cys-hint" style={{ color: "var(--ink-2)", margin: "2px 0" }}>{s.text}</div>{s.objectives.map((o, j) => objRow(s.id, o, j))}</div>)}
                      {!!b.rewards?.length && <div className="dz-rw">{b.rewards.map((r, i) => <RewardChip key={i} r={r} icon={icon} />)}</div>}
                    </div>
                  ))}</div>
                </div></div>
            )}
            <div className="dz-fstep"><div className="dz-rail"><i><DI n="gift" /></i></div>
              <div className="dz-fcard"><h4>Rewards<span className="dz-mono">{q.rewards?.length ?? 0} of {L.maxRewards}</span></h4><div className="dz-rw">{(q.rewards ?? []).map((r, i) => <RewardChip key={i} r={r} icon={icon} />)}{!q.rewards?.length && <span className="dz-sub">none</span>}</div></div></div>
            <div className="dz-note" style={{ marginTop: 2 }}><DI n="info" /><span>{q.failure?.onDeath && q.failure.onDeath !== "keep" ? <><b>On death:</b> {q.failure.onDeath === "fail" ? "the quest fails" : "the current step resets"}. </> : null}{q.failure?.timeLimitSeconds ? <><b>Time limit:</b> {Math.round(q.failure.timeLimitSeconds / 60)} min. </> : null}Steps run in order; each step&apos;s objectives count only while it is active. Progress is stored per player on the player (a bounded string), never in a file.</span></div>
            {!!params.length && (
              <div style={{ marginTop: 12 }}><div className="cys-eyebrow" style={{ marginBottom: 4 }}>Settings · config.yml</div>{params.filter((p) => p.kind === "text").map((p) => <ParamRow key={p.path} d={d} p={p} strip={`quests.${q.id}.`} setParam={setParam} />)}</div>
            )}
          </div>
        </section>
      </div>
      <div className="dz-col">
        <section className="cys-panel cys-glass cys-hairline" style={{ flex: 1, minHeight: 0 }}>
          <div className="cys-ph"><span className="cys-eyebrow">Progress simulator</span><span className="cys-tag dim">sample player</span></div>
          <div className="dz-scroll" style={{ flex: 1, padding: "0 12px 12px" }}>
            {qerr ? <div className="dz-note warn"><DI n="warn" /><span>{qerr}</span></div> : (
              <>
                {(qsim?.states ?? []).map((s) => (
                  <div key={s.id} className="dz-qstate"><b>{s.title}</b><span className={`cys-tag ${s.status === "done" ? "ok" : s.status === "active" || s.status === "choosing" ? "acc" : "dim"}`}>{s.status}</span><small>{s.text}</small><div className={`dz-pbar ${s.status === "done" ? "done" : ""}`}><i style={{ width: `${Math.min(100, (s.cur / Math.max(1, s.target)) * 100)}%` }} /></div></div>
                ))}
                <div className="cys-eyebrow" style={{ margin: "10px 0 6px", display: "flex" }}>Player events<button type="button" className="cys-btn xs ghost" style={{ marginLeft: "auto" }} disabled={!qsteps.length} onClick={() => setQsteps([])}><DI n="rollback" />Reset</button></div>
                <div className="dz-evbtns">{(qsim?.buttons ?? []).map((b, i) => <button key={i} type="button" className="cys-btn xs" disabled={qsteps.length >= 40} onClick={() => setQsteps([...qsteps, b.step])}>{b.label}</button>)}</div>
                <ul className="dz-slog" style={{ marginTop: 8, maxHeight: 150 }}>{(qsim?.log ?? []).slice(0, 14).map((l, i) => <li key={i} className={l.tone} style={{ gridTemplateColumns: "1fr" }}><span>{l.text}</span></li>)}{!qsim?.log.length && <li className="fx" style={{ gridTemplateColumns: "1fr" }}><span>No events yet. Start a quest.</span></li>}</ul>
                <div className="cys-eyebrow" style={{ margin: "12px 0 6px" }}>Limits</div>
                <Meter label="Stored progress per player (worst case)" used={d.analysis?.progressChars ?? 0} cap={L.maxProgressChars} title="characters of the player's progress string, every quest at its longest" />
                <div style={{ height: 8 }} />
                <Meter label="Active quests (max_active_quests)" used={qsim?.active ?? 0} cap={qsim?.maxActive ?? L.activeQuests[1]} />
                <div className="cys-eyebrow" style={{ margin: "12px 0 6px" }}>Checks · all quests</div>
                <ul className="dz-issues">
                  {quests.flatMap((x) => d.analysis?.files.find((f) => f.id === x.id)?.errors ?? []).map((e, i) => <IssueRow key={`e${i}`} i={e} tone="err" />)}
                  {allRows.map((c) => <li key={c.id} className={`dz-issue ${c.status === "pass" ? "ok" : c.status === "fail" ? "err" : c.status === "warn" ? "warn" : "info"}`}><span className="ic"><DI n={c.status === "pass" ? "check" : c.status === "fail" ? "close" : c.status === "warn" ? "warn" : "minus"} /></span><code>{c.id}</code><span className="path">{c.status.replace("_", " ")}</span>{!!c.items.length && <span className="m">{c.items[0]}</span>}</li>)}
                </ul>
                <div className="dz-note" style={{ marginTop: 10 }}><DI n="info" /><span>The simulator follows the quest engine&apos;s rules. Kills, pickups and crafting in a real game have not been verified with a real client.</span></div>
              </>
            )}
          </div>
          <PendingBar d={d} labels={(id) => id} />
        </section>
      </div>
    </>
  );
}

// --------------------------------------------------------------------------------------------- narrow (phone)
function Narrow({ d, menus, quests, m, icon, qsim }: WS & { icon: (r?: string) => Raster; qsim: QuestSimResult | null }) {
  const ok = d.analysis?.ok ?? false;
  const act = STUDIO_DEFAULTS.mobile === "review_and_approve" && d.changed.length > 0;
  const mrep = m ? d.analysis?.files.find((f) => f.id === m.id) : null;
  return (
    <main className="dz-narrow" aria-label="Menu and quest review">
      {m && (
        <section className="n-card cys-glass">
          <div className="n-h"><div className="dz-thumb" style={{ width: 48, height: 48 }}><Ico r={icon(m.style === "chest" ? m.buttons?.[0]?.icon.material ?? "minecraft:chest" : "minecraft:compass")} size={34} /></div>
            <div><h1><McText t={{ text: m.title, color: "gold" }} /></h1><p>{m.style === "chest" ? `menu · ${m.rows} rows${m.list ? ` · ${pagesOf(m)} pages · ${m.list.source.entries.length} entries` : ""}` : `dialogue · ${m.choices.length} choices`}</p></div>
            <span className={`cys-tag ${mrep?.errors.length ? "bad" : mrep?.warnings.length ? "warn" : "ok"}`} style={{ marginLeft: "auto" }}>{mrep?.errors.length ? `${mrep.errors.length} errors` : mrep?.warnings.length ? `${mrep.warnings.length} warn` : "valid"}</span></div>
          <div className="n-sec"><div className="dz-grid9">{Array.from({ length: m.style === "chest" ? m.rows * 9 : 27 }, (_, i) => { const s = slotModel(m, i, 0); const id = s.kind === "button" ? s.c.icon.material ?? s.c.icon.item : s.kind === "list" ? s.e?.material ?? s.fixed?.icon.material : s.kind === "nav" ? "minecraft:arrow" : s.kind === "choice" ? s.c.icon.material ?? s.c.icon.item : m.style === "chest" ? m.filler : undefined; return <span key={i} className={`dz-slot ${s.kind === "list" ? "list" : s.kind === "filler" ? "filler" : ""}`}>{id && <Ico r={icon(id)} size={22} />}</span>; })}</div></div>
          <div className="n-sec"><span className="cys-eyebrow">Checks</span>{(mrep?.warnings ?? []).slice(0, 3).map((w, i) => <div key={i} className="dz-note warn" style={{ marginBottom: 6 }}><DI n="warn" /><span>{w.message}</span></div>)}<p className="cys-hint" style={{ margin: "8px 0 0" }}>Every click and drag is cancelled; buying is room → pay → take → give.</p></div>
        </section>
      )}
      {!!quests.length && (
        <section className="n-card cys-glass">
          <div className="n-h"><div><h1>Quests</h1><p>{quests.length} quests · {quests.filter((q) => q.branches).length} with a branch · {quests.filter((q) => (q.repeat?.mode ?? "once") !== "once").length} repeating</p></div></div>
          <div className="n-sec">{quests.map((q) => <div key={q.id} className="dz-qstate"><b>{q.title}</b><span className="cys-tag dim">{q.requires?.length ? `after ${q.requires[0]}` : q.repeat && q.repeat.mode !== "once" ? q.repeat.mode : "first"}</span><small>{q.steps.map((s) => s.text).join(" → ")}{q.branches ? ` → ${q.branches.options.map((b) => b.label.text).join(" or ")}` : ""}</small></div>)}</div>
          <div className="n-note"><DI n="info" /><span>Validated and simulated{qsim ? "" : ""}. Not verified with a real player.</span></div>
        </section>
      )}
      {!menus.length && !quests.length && <p className="cys-hint">No menus or quests.</p>}
      <section className="n-card cys-glass">
        <div className="n-sec" style={{ borderTop: 0 }}><span className="cys-eyebrow">Waiting for approval</span>{d.changed.length ? <p>{d.changed.join(", ")} changed (autosaved draft).</p> : <p className="cys-hint" style={{ margin: 0 }}>Nothing waiting. Edit menus and quests on a larger screen.</p>}</div>
        {act && <div className="n-act"><button type="button" className="cys-btn" onClick={() => void d.discard()}>Reject</button><button type="button" className="cys-btn primary" disabled={!ok || d.saving} onClick={() => void d.save()}><DI n="check" />Approve revision</button></div>}
      </section>
    </main>
  );
}

toolu_01W9UaURu9E3MEviECDRAwyp.content:
"use client";
// Cyrus MENU + QUEST DESIGNER (r27), full page, tabs Menus / Quests. Layout from the v2 mockup
// (cyrus-designs/v2/menu-quest.html, not yet reviewed by the owner). Menus: the slot grid in Edit (select a slot, its
// inspector edits the click's price / texts / counts as config.yml values) and Try it (a sample player buys through the
// fixed click protocol: room -> pay -> take -> give, run by the reference simulator); the owner-editable shop list.
// Quests: the prerequisite chain, the step flow (objectives, branches, rewards; counts editable) and the progress
// simulator driven by player events. Phones: read-only summary + approve / reject.
import { useCallback, useEffect, useMemo, useState } from "react";
import Link from "next/link";
import type { Param } from "@/lib/cyrus/designer/compile";
import type { ChestMenu, Cost, DialogueMenu, MenuAction, MenuDesign, Objective, QuestDesign, Reward } from "@/lib/cyrus/designer/gameplay/spec";
import { isItem, isMenu, isQuest, setParamValue, type DesignFile } from "@/lib/cyrus/designer/studio/edit";
import type { Raster } from "@/lib/cyrus/textures/render";
import { STUDIO_DEFAULTS } from "@/lib/cyrus/studios/access";
import { useToast, type StudioMod } from "../studios/StudioShell";
import { designerApi, type QuestSimResult, type QuestStep, type TryResult } from "./api";
import { DesignerContext, DesignerShell, DraftLine, Failed, Ico, IssueRow, Loading, McText, Meter, NoDesigns, ParamField, PendingBar, designerHref, rangeText, useDesigner, useIcon, type Designer } from "./shared";
import { PLACEHOLDER_NOTE } from "./pixel-icons";
import { DI } from "./icons";

type Tab = "menus" | "quests";
const bare = (s: string) => String(s ?? "").replace(/^minecraft:/, "");
const costText = (c?: Cost) => (!c ? "free" : c.type === "item" ? `${c.count} × ${bare(c.item)}` : c.type === "xp_levels" ? `${c.levels} XP levels` : `${c.amount} money (Vault)`);
const ACT_IC: Record<string, string> = { back: "chevL", close: "close", send_message: "note", actionbar: "note", play_sound: "volume", run_ability: "bolt", open_quest_log: "scroll", open_menu: "slots", start_quest: "flag", abandon_quest: "flag", choose_branch: "branch", give_item: "gift", potion_effect: "flask", heal: "heart", next_page: "arrowR", prev_page: "chevL" };
const DIALOGUE_POS = [[], [22], [20, 24], [20, 22, 24], [19, 21, 23, 25], [18, 20, 22, 24, 26]];

export function MenuQuestDesigner({ mod, initialTab, initialMenu, initialQuest }: { mod: StudioMod; initialTab: Tab; initialMenu: string | null; initialQuest: string | null }) {
  const [tab, setTab] = useState<Tab>(initialTab);
  const go = (t: Tab) => { setTab(t); try { history.replaceState(null, "", designerHref(mod, t)); } catch { /* the tab still switches */ } };
  return (
    <DesignerShell mod={mod} tab={tab} current={tab === "quests" ? "Quest Designer" : "Menu Designer"} onTab={(t) => (t === "menus" || t === "quests" ? go(t) : undefined)} showBosses>
      <Body mod={mod} tab={tab} setTab={go} initialMenu={initialMenu} initialQuest={initialQuest} />
    </DesignerShell>
  );
}

function Body({ mod, tab, setTab, initialMenu, initialQuest }: { mod: StudioMod; tab: Tab; setTab: (t: Tab) => void; initialMenu: string | null; initialQuest: string | null }) {
  const d = useDesigner(mod);
  const menus = useMemo(() => d.files.filter(isMenu) as MenuDesign[], [d.files]);
  const quests = useMemo(() => d.files.filter(isQuest) as QuestDesign[], [d.files]);
  const [menu, setMenu] = useState<string | null>(initialMenu);
  const [quest, setQuest] = useState<string | null>(initialQuest);
  useEffect(() => { if (menus.length && (!menu || !menus.some((m) => m.id === menu))) setMenu(menus[0].id); }, [menus, menu]);
  useEffect(() => { if (quests.length && (!quest || !quests.some((q) => q.id === quest))) setQuest(quests.find((q) => q.branches)?.id ?? quests[0].id); }, [quests, quest]);
  if (d.err) return <Failed msg={d.err} />;
  if (!d.view) return <Loading what="this mod's menus and quests" />;
  if (!d.view.project || (!menus.length && !quests.length)) return <NoDesigns mod={mod} what="menus or quests" />;
  const m = menus.find((x) => x.id === menu) ?? menus[0] ?? null;
  const q = quests.find((x) => x.id === quest) ?? quests[0] ?? null;
  return (
    <DesignerContext d={d}>
      <Workspace d={d} mod={mod} tab={tab} setTab={setTab} menus={menus} quests={quests} m={m} q={q} setMenu={setMenu} setQuest={setQuest} />
    </DesignerContext>
  );
}

type WS = { d: Designer; mod: StudioMod; tab: Tab; setTab: (t: Tab) => void; menus: MenuDesign[]; quests: QuestDesign[]; m: MenuDesign | null; q: QuestDesign | null; setMenu: (k: string) => void; setQuest: (k: string) => void };
function Workspace(p: WS) {
  const { d } = p;
  const toast = useToast();
  const icon = useIcon(d.textures);
  const apply = useCallback((r: { ok: true; files: DesignFile[] } | { ok: false; error: string }) => { if (r.ok) d.setFiles(r.files); else toast(r.error, true); }, [d, toast]);
  const setParam = useCallback((path: string, v: number | string) => apply(setParamValue(d.files, path, v)), [apply, d.files]);
  // quest progress simulator (shared by the chain status and the right column)
  const [qsteps, setQsteps] = useState<QuestStep[]>([]);
  const [qsim, setQsim] = useState<QuestSimResult | null>(null);
  const [qerr, setQerr] = useState<string | null>(null);
  useEffect(() => {
    if (!d.pid || !p.quests.length) return;
    const t = window.setTimeout(() => { designerApi.simQuests(d.pid!, d.files, qsteps).then((r) => { setQsim(r.result); setQerr(null); }).catch((e) => setQerr((e as Error).message)); }, 200);
    return () => window.clearTimeout(t);
  }, [d.pid, d.files, qsteps, p.quests.length]);
  return (
    <>
      <main className="dz-ws" aria-label={p.tab === "quests" ? "Quest Designer" : "Menu Designer"}>
        <LeftColumn {...p} icon={icon} />
        {p.tab === "menus" && p.m ? <MenuEditor {...p} m={p.m} icon={icon} setParam={setParam} /> : p.tab === "quests" && p.q ? <QuestEditor {...p} q={p.q} icon={icon} setParam={setParam} qsim={qsim} qerr={qerr} qsteps={qsteps} setQsteps={setQsteps} /> : (
          <div className="dz-col" style={{ gridColumn: "2 / 4" }}><div className="cys-panel cys-glass" style={{ flex: 1, display: "grid", placeItems: "center" }}><div className="cys-empty"><DI n={p.tab === "menus" ? "slots" : "scroll"} /><p>This mod has no {p.tab} yet.</p></div></div></div>
        )}
      </main>
      <Narrow {...p} icon={icon} qsim={qsim} />
    </>
  );
}

// ----------------------------------------------------------------------------------------------------- left
function LeftColumn({ d, tab, setTab, menus, quests, m, q, setMenu, setQuest, mod, icon }: WS & { icon: (r?: string, m?: string) => Raster }) {
  const a = d.analysis;
  const tone = (id: string) => { const f = a?.files.find((x) => x.id === id); return !f ? "" : f.errors.length ? "bad" : f.warnings.length ? "warn" : "ok"; };
  const items = d.files.filter(isItem);
  const used = items.filter((it) => menus.some((mm) => JSON.stringify(mm).includes(`"${it.id}"`)) || quests.some((qq) => JSON.stringify(qq).includes(`"${it.id}"`)));
  const qIcon = (x: QuestDesign) => x.icon?.material ?? x.icon?.item ?? (x.steps[0]?.objectives[0] && "item" in x.steps[0].objectives[0] ? String((x.steps[0].objectives[0] as { item: string }).item) : x.steps[0]?.objectives[0]?.type === "break_block" ? (x.steps[0].objectives[0] as { block: string }).block : "minecraft:paper");
  return (
    <div className="dz-col scroll">
      <section className="cys-panel cys-glass cys-hairline">
        <div className="cys-ph"><span className="cys-eyebrow">Menus</span><span className="n">{menus.length} / {d.view!.limits.maxMenus}</span></div>
        <div className="dz-body">
          {menus.map((x) => (
            <button key={x.id} type="button" className={`dz-row ${tab === "menus" && m?.id === x.id ? "on" : ""}`} onClick={() => { setMenu(x.id); setTab("menus"); }}>
              <span className="dz-thumb"><Ico r={icon(x.style === "chest" ? x.buttons?.[0]?.icon.material ?? "minecraft:chest" : x.speakerIcon?.material ?? "minecraft:compass")} size={22} /></span>
              <span className="tx"><b>{x.id}</b><small>{x.style === "chest" ? `chest · ${x.rows} rows${x.list ? " · list" : ""}` : `dialogue · ${x.choices.length} choices`}</small></span>
              <span className={`cys-dot ${tone(x.id)}`} />
            </button>
          ))}
        </div>
      </section>
      <section className="cys-panel cys-glass">
        <div className="cys-ph"><span className="cys-eyebrow">Quests</span><span className="n">{quests.length} / {d.view!.limits.maxQuests}</span></div>
        <div className="dz-body">
          {quests.map((x) => (
            <button key={x.id} type="button" className={`dz-row ${tab === "quests" && q?.id === x.id ? "on" : ""}`} onClick={() => { setQuest(x.id); setTab("quests"); }}>
              <span className="dz-thumb"><Ico r={icon(qIcon(x))} size={22} /></span>
              <span className="tx"><b>{x.id}</b><small>{x.repeat && x.repeat.mode !== "once" ? x.repeat.mode : x.requires?.length ? `after ${x.requires[0]}` : x.start === "menu" ? "starts from a menu" : "first"}{x.branches ? " · branch" : ""}</small></span>
              <span className={`cys-dot ${tone(x.id)}`} />
            </button>
          ))}
        </div>
      </section>
      {!!used.length && (
        <section className="cys-panel cys-glass">
          <div className="cys-ph"><span className="cys-eyebrow">Items used</span></div>
          <div className="dz-body">
            {used.map((it) => <div key={it.id} className="dz-row"><span className="dz-thumb"><Ico r={icon(it.base, it.assets?.model)} size={22} /></span><span className="tx"><b>{it.id}</b><small>{menus.some((mm) => mm.style === "chest" && mm.openWith?.item === it.id) ? "opens a menu" : it.abilities.length ? `ability ${it.abilities[0].id}` : "a design item"}</small></span></div>)}
            <Link className="cys-btn xs ghost" href={designerHref(mod, "items")} style={{ marginTop: 4 }}><DI n="sword" />Open the Item Designer</Link>
          </div>
        </section>
      )}
    </div>
  );
}

// ------------------------------------------------------------------------------------------------- menu editor
type SlotModel = { kind: "button"; i: number; path: string; c: { icon: { material?: string; item?: string; name?: { text: string; color?: string }; lore?: { text: string }[]; amount?: number }; actions?: MenuAction[]; cost?: Cost; permission?: string } }
  | { kind: "list"; li: number; idx: number; e: { material: string; amount: number; price: number; name?: string } | null; fixed?: { icon: { material?: string; item?: string; name?: { text: string; color?: string } }; actions?: MenuAction[]; cost?: Cost; permission?: string } | null }
  | { kind: "nav"; dir: "prev" | "next" } | { kind: "filler" } | { kind: "choice"; i: number; c: DialogueMenu["choices"][number] };

function slotModel(m: MenuDesign, slot: number, page: number): SlotModel {
  if (m.style === "dialogue") { const pos = DIALOGUE_POS[Math.min(5, m.choices.length)]; const i = pos.indexOf(slot); return i >= 0 ? { kind: "choice", i, c: m.choices[i] } : { kind: "filler" }; }
  const bi = (m.buttons ?? []).findIndex((b) => b.slot === slot);
  if (bi >= 0) return { kind: "button", i: bi, path: `b${slot}`, c: m.buttons![bi] };
  const L = m.list;
  if (L) {
    const li = L.slots.indexOf(slot);
    if (li >= 0) {
      const idx = page * L.slots.length + li;
      if (L.source.type === "config") return { kind: "list", li, idx, e: L.source.entries[idx] ?? null };
      return { kind: "list", li, idx, e: null, fixed: L.source.entries[idx] ?? null };
    }
    if (slot === L.prev.slot) return { kind: "nav", dir: "prev" };
    if (slot === L.next.slot) return { kind: "nav", dir: "next" };
  }
  return { kind: "filler" };
}
const pagesOf = (m: ChestMenu) => (m.list ? Math.max(1, Math.ceil((m.list.source.type === "config" ? m.list.source.entries.length : m.list.source.entries.length) / m.list.slots.length)) : 1);
const currencyOf = (m: ChestMenu): Cost["type"] | "free" => (m.list?.source.type === "config" ? m.list.source.currency.type : "free");
const listCost = (m: ChestMenu, e: { price: number }): Cost | undefined => { const c = m.list?.source.type === "config" ? m.list.source.currency : null; return !c ? undefined : c.type === "item" ? { type: "item", item: c.item, count: Math.round(e.price) } : c.type === "xp_levels" ? { type: "xp_levels", levels: Math.round(e.price) } : c.type === "economy" ? { type: "economy", amount: e.price } : undefined; };

function MenuEditor({ d, m, icon, setParam }: WS & { m: MenuDesign; icon: (r?: string, mm?: string) => Raster; setParam: (path: string, v: number | string) => void }) {
  const toast = useToast();
  const [mode, setMode] = useState<"edit" | "try">("edit");
  const [page, setPage] = useState(0);
  const [sel, setSel] = useState<number>(() => (m.style === "chest" ? (m.buttons?.find((b) => b.cost)?.slot ?? m.buttons?.[0]?.slot ?? 0) : DIALOGUE_POS[Math.min(5, m.choices.length)][0]));
  const [clicks, setClicks] = useState<number[]>([]);
  const [tryRes, setTryRes] = useState<TryResult | null>(null);
  const [flash, setFlash] = useState<{ slot: number; ok: boolean } | null>(null);
  useEffect(() => { setPage(0); setClicks([]); setTryRes(null); }, [m.id]);
  useEffect(() => {
    if (mode !== "try" || !d.pid) return;
    let live = true;
    designerApi.tryMenu(d.pid, d.files, m.id, clicks).then((r) => { if (!live) return; setTryRes(r.result); const last = r.result.clicks[r.result.clicks.length - 1]; if (last) { setFlash({ slot: last.slot, ok: last.ran }); if (r.result.open && r.result.open.menu === m.id) setPage(r.result.open.page); } }).catch((e) => toast((e as Error).message, true));
    return () => { live = false; };
  }, [mode, clicks, d.pid, d.files, m.id, toast]);
  useEffect(() => { if (!flash) return; const t = window.setTimeout(() => setFlash(null), 650); return () => window.clearTimeout(t); }, [flash]);
  const size = m.style === "chest" ? m.rows * 9 : 27;
  const params = d.params.filter((p) => p.owner === "menu" && p.item === m.id);
  const cmd = d.analysis?.compile.ok ? d.analysis.compile.command : d.view!.pluginName.toLowerCase();
  const opener = m.style === "chest" ? [m.openWith?.command !== false ? `/${cmd} menu ${m.id}` : null, m.openWith?.item ? `right-click ${m.openWith.item}` : null, m.openWith?.npc ? "an NPC" : null].filter(Boolean).join(" · ") : `/${cmd} menu ${m.id}${m.openWith?.npc ? " · an NPC" : ""}`;
  const pages = m.style === "chest" ? pagesOf(m) : 1;
  const click = (slot: number) => {
    if (mode === "edit") { setSel(slot); return; }
    if (clicks.length >= 40) { toast("Reset the sample player first (40 clicks max)", true); return; }
    setClicks([...clicks, slot]); setSel(slot);
  };
  const rowsP: Param = { path: "", field: "", kind: "int", min: 1, max: 6, value: m.style === "chest" ? m.rows : 3, label: "rows (1 to 6)", item: m.id, role: "count" };
  const setRows = (v: number | string) => {
    if (m.style !== "chest") return;
    const rows = Math.max(1, Math.min(6, Math.round(Number(v))));
    d.setFiles(d.files.map((f) => (f.id === m.id ? { ...(f as ChestMenu), rows } : f)));
    toast(`Rows ${rows}: a structure change (the menu's Java file). The validator checks slots still fit.`);
  };
  const setEntry = (idx: number, field: "amount" | "price", v: number | string) => {
    d.setFiles(d.files.map((f) => {
      if (f.id !== m.id || (f as MenuDesign).style !== "chest") return f;
      const c = structuredClone(f) as ChestMenu;
      if (c.list?.source.type === "config") { const e = c.list.source.entries[idx]; if (e) e[field] = Number(v); }
      return c;
    }));
  };
  const rep = d.analysis?.files.find((f) => f.id === m.id);
  return (
    <>
      <div className="dz-col">
        <DraftLine d={d} />
        <section className="cys-panel cys-glass cys-hairline" style={{ flex: 1, minHeight: 0, display: "flex", flexDirection: "column" }}>
          <div className="dz-mhead">
            <span className="cys-eyebrow">Menu</span><McText t={{ text: m.title, color: m.style === "chest" ? m.buttons?.find((b) => b.icon.name?.text === m.title)?.icon.name?.color ?? "gold" : m.speaker.color ?? "gold" }} /><span className="cys-tag dim">{m.style}</span><span style={{ flex: 1 }} />
            {m.style === "chest" && <><span className="dz-sub">Rows</span><ParamField p={rowsP} onSet={setRows} /></>}
            <div className="cys-seg sm cys-soft"><button type="button" className={mode === "edit" ? "on" : ""} aria-pressed={mode === "edit"} onClick={() => setMode("edit")}><DI n="edit" />Edit</button><button type="button" className={mode === "try" ? "on" : ""} aria-pressed={mode === "try"} onClick={() => setMode("try")}><DI n="play" />Try it</button></div>
          </div>
          <div className="dz-scroll" style={{ flex: 1, padding: "0 0 14px" }}>
            <div className="dz-gui">
              <div className="dz-gui-t"><McText t={{ text: m.title, color: "gold" }} /><span className="dz-mono" style={{ marginLeft: "auto" }}>{opener}</span></div>
              <div className="dz-grid9" role="grid" aria-label={`${m.title}: ${size} slots`}>
                {Array.from({ length: size }, (_, i) => {
                  const sm = slotModel(m, i, page);
                  const live = mode === "try" && tryRes?.open?.menu === m.id ? tryRes.open.slots.find((s) => s.slot === i) : undefined;
                  let inner: React.ReactNode = null, cls = "";
                  if (sm.kind === "button") inner = <><Ico r={icon(sm.c.icon.material ?? sm.c.icon.item)} size={32} />{sm.c.cost && <span className="cst" title="has a cost" />}{sm.c.permission && <span className="lk" title={`needs ${d.view!.project!.namespace}.${sm.c.permission}`}><DI n="lock" /></span>}{(sm.c.icon.amount ?? 1) > 1 && <span className="amt">{sm.c.icon.amount}</span>}</>;
                  else if (sm.kind === "list") { cls = "list"; const mat = sm.e?.material ?? sm.fixed?.icon.material ?? sm.fixed?.icon.item; if (mat) inner = <><Ico r={icon(mat)} size={32} />{sm.e && sm.e.amount > 1 && <span className="amt">{sm.e.amount}</span>}</>; }
                  else if (sm.kind === "nav") { const dis = mode === "try" ? !live : (sm.dir === "prev" && page === 0) || (sm.dir === "next" && page >= pages - 1); inner = <span style={{ opacity: dis ? 0.35 : 1, display: "grid" }}><Ico r={icon("minecraft:arrow")} size={32} /></span>; }
                  else if (sm.kind === "choice") inner = <Ico r={icon(sm.c.icon.material ?? sm.c.icon.item)} size={32} />;
                  else { cls = "filler"; if (m.style === "chest" && m.filler) inner = <Ico r={icon(m.filler)} size={32} />; }
                  const fl = flash?.slot === i ? (flash.ok ? "flash" : "deny") : "";
                  return (
                    <button key={i} type="button" role="gridcell" className={`dz-slot ${cls} ${sel === i && mode === "edit" ? "sel" : ""} ${fl}`} onClick={() => click(i)} aria-label={`slot ${i}${sm.kind === "button" ? `: ${sm.c.icon.name?.text ?? ""}` : sm.kind === "list" ? ": list" : ""}`} aria-selected={sel === i}>
                      {inner}{mode === "edit" && sm.kind !== "filler" && <span className="no">{i}</span>}
                    </button>
                  );
                })}
              </div>
              {m.style === "chest" && m.list && (
                <div className="dz-pager">
                  <button type="button" className="cys-ib sm" aria-label="Previous page" disabled={page === 0 || mode === "try"} onClick={() => setPage(page - 1)}><DI n="chevL" /></button>
                  <span>Page {page + 1} of {pages}</span>·<span>{m.list.slots.length} list slots per page</span>·<span>{m.list.source.entries.length} entries{m.list.source.type === "config" ? " from config.yml" : ""}</span>
                  <button type="button" className="cys-ib sm" aria-label="Next page" disabled={page >= pages - 1 || mode === "try"} onClick={() => setPage(page + 1)}><DI n="chevR" /></button>
                </div>
              )}
            </div>
            {m.style === "dialogue" && (
              <div style={{ maxWidth: 520, margin: "12px auto 0", padding: "0 14px" }}>
                <div className="dz-note"><DI n="user" /><span><McText t={m.speaker} />: {m.lines.join(" ")}</span></div>
              </div>
            )}
            <div className="dz-legend"><span><i />Button</span>{m.style === "chest" && m.list && <span><i className="l" />List slot (page)</span>}<span><i className="c" />Has a cost{m.style === "chest" && m.list?.source.type === "config" ? " (list entries always cost)" : ""}</span><span><DI n="lock" /> Needs a permission</span></div>
            <p className="cys-hint" style={{ textAlign: "center", margin: "6px 0 0" }}>{PLACEHOLDER_NOTE}</p>
            {m.style === "chest" && m.list?.source.type === "config" && (
              <div style={{ padding: "12px 14px 0" }}>
                <div className="cys-eyebrow" style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 6 }}>Shop list <span className="cys-tag dim">lists.{m.id}</span><span className="cys-hint" style={{ letterSpacing: 0, textTransform: "none", fontFamily: "var(--font-inter), sans-serif", fontWeight: 400, marginLeft: "auto" }}>The server owner edits this in config.yml ({d.view!.limits.maxConfigEntries} entries max). No rebuild.</span></div>
                <div style={{ border: "1px solid var(--line)", borderRadius: 10, maxHeight: 260, overflow: "auto" }}>
                  <table className="dz-ctab"><thead><tr><th>#</th><th>Item</th><th>Amount</th><th>Price</th><th>Name</th></tr></thead><tbody>
                    {m.list.source.entries.map((e, i) => {
                      const s = slotModel(m, sel, page);
                      const pa: Param = { path: "", field: "", kind: "int", min: 1, max: 64, value: e.amount, label: `entry ${i + 1} amount`, item: m.id, role: "count" };
                      const pp: Param = { path: "", field: "", kind: currencyOf(m) === "economy" ? "num" : "int", min: 0, max: 1000000, value: e.price, label: `entry ${i + 1} price`, item: m.id, role: "price" };
                      const saved = (d.saved.find((f) => f.id === m.id) as ChestMenu | undefined)?.list?.source;
                      const se = saved?.type === "config" ? saved.entries[i] : undefined;
                      return (
                        <tr key={i} className={s.kind === "list" && s.idx === i ? "on" : ""}>
                          <td className="m">{i + 1}</td>
                          <td><span style={{ display: "inline-flex", gap: 8, alignItems: "center" }}><Ico r={icon(e.material)} size={18} /><span className="dz-mono" style={{ color: "var(--ink-2)" }}>{bare(e.material)}</span></span></td>
                          <td><ParamField p={pa} was={se?.amount} onSet={(v) => setEntry(i, "amount", v)} /></td>
                          <td><span style={{ display: "inline-flex", gap: 5, alignItems: "center" }}>{m.list!.source.type === "config" && m.list!.source.currency.type === "item" && <Ico r={icon(m.list!.source.currency.item)} size={14} />}<ParamField p={pp} was={se?.price} onSet={(v) => setEntry(i, "price", v)} /></span></td>
                          <td>{e.name ?? <span style={{ color: "var(--faint)" }}>item name</span>}</td>
                        </tr>
                      );
                    })}
                  </tbody></table>
                </div>
              </div>
            )}
          </div>
        </section>
      </div>
      <div className="dz-col">
        <section className="cys-panel cys-glass cys-hairline" style={{ flex: 1, minHeight: 0 }}>
          <div className="cys-ph"><span className="cys-eyebrow">{mode === "try" ? "Try it" : "Slot"}</span>{mode === "try" && <span className="cys-tag dim">simulated</span>}</div>
          <div className="dz-scroll" style={{ flex: 1 }}>
            <SlotInspector d={d} m={m} slot={sel} page={page} icon={icon} params={params} setParam={setParam} mode={mode} tryRes={tryRes} onReset={() => setClicks([])} />
            <div className="dz-sec">
              <span className="cys-eyebrow"><DI n="shield" /> Anti-dupe, built in</span>
              <ol className="dz-proto"><li>Room for the given stacks</li><li>Can the player pay</li><li>Take, re-checked, all-or-nothing</li><li>Give</li></ol>
              <div className="dz-guard"><DI n="check" /><span>Every click and drag in a menu is cancelled. Only plain left and right clicks act.</span></div>
              <div className="dz-guard"><DI n="check" /><span>Click cooldown <code className="mono">general.menu_click_cooldown_ticks</code>, 2–40 ticks. Icons are flagged and swept on close or drop.</span></div>
            </div>
            <div className="dz-sec">
              <span className="cys-eyebrow">Checks · {m.id}</span>
              <ul className="dz-issues">
                {(rep?.errors ?? []).map((e, i) => <IssueRow key={`e${i}`} i={e} tone="err" />)}
                {(rep?.warnings ?? []).map((e, i) => <IssueRow key={`w${i}`} i={e} tone="warn" />)}
                {(d.analysis?.gameplayChecks.menu ?? []).filter((c) => c.status === "pass" || c.status === "not_run").map((c) => (
                  <li key={c.id} className={`dz-issue ${c.status === "pass" ? "ok" : "info"}`}><span className="ic"><DI n={c.status === "pass" ? "check" : "minus"} /></span><code>{c.id}</code><span className="path">{c.status === "pass" ? "pass, all menus" : "not run"}</span></li>
                ))}
              </ul>
            </div>
            <div className="dz-sec"><div className="dz-note"><DI n="info" /><span>Validated, compiled and simulated. Menus and the dupe rules have not been verified with a real player in a game client.</span></div></div>
          </div>
          <PendingBar d={d} labels={(id) => id} />
        </section>
      </div>
    </>
  );
}

function CostChip({ c, icon }: { c?: Cost; icon: (r?: string) => Raster }) {
  if (!c) return <span className="dz-achip">free</span>;
  return <span className="dz-achip cost">{c.type === "item" ? <Ico r={icon(c.item)} size={16} /> : <DI n={c.type === "xp_levels" ? "sparkle" : "coin"} />}<code>{costText(c)}</code></span>;
}
function ActChip({ a, icon }: { a: MenuAction; icon: (r?: string) => Raster }) {
  const extra = a.type === "give_item" ? ` ${bare(a.item)} ×${a.count ?? 1}` : a.type === "run_ability" ? ` ${a.item}.${a.ability}` : a.type === "play_sound" ? ` ${bare(a.sound).split(".").pop()}` : a.type === "open_menu" ? ` ${a.menu}` : a.type === "start_quest" || a.type === "abandon_quest" ? ` ${a.quest}` : a.type === "choose_branch" ? ` ${a.quest}.${a.branch}` : a.type === "potion_effect" ? ` ${a.effect}` : "";
  return <span className="dz-achip">{a.type === "give_item" ? <Ico r={icon(a.item)} size={16} /> : <DI n={ACT_IC[a.type] ?? "play"} />}<code>{a.type}</code>{extra}</span>;
}

function SlotInspector({ d, m, slot, page, icon, params, setParam, mode, tryRes, onReset }: { d: Designer; m: MenuDesign; slot: number; page: number; icon: (r?: string) => Raster; params: Param[]; setParam: (p: string, v: number | string) => void; mode: "edit" | "try"; tryRes: TryResult | null; onReset: () => void }) {
  const sm = slotModel(m, slot, page);
  const ns = d.view!.project!.namespace;
  const node = sm.kind === "button" ? `b${slot}` : sm.kind === "choice" ? `c${sm.i}` : sm.kind === "list" && sm.fixed ? `e${sm.idx}` : null;
  const mine = node ? params.filter((p) => p.path.startsWith(`menus.${m.id}.${node}.`)) : [];
  let head: React.ReactNode, body: React.ReactNode = null;
  const click = sm.kind === "button" ? sm.c : sm.kind === "choice" ? sm.c : sm.kind === "list" ? sm.fixed ?? null : null;
  if (click) {
    head = <><div className="big"><Ico r={icon(click.icon.material ?? click.icon.item)} size={36} /></div><div style={{ minWidth: 0 }}><div><McText t={click.icon.name ?? { text: bare(click.icon.material ?? click.icon.item ?? ""), color: "white" }} /></div><div className="dz-mono" style={{ marginTop: 4 }}>slot {slot} · {sm.kind === "choice" ? `choice ${sm.i + 1}` : sm.kind === "list" ? `list entry ${sm.idx + 1}` : "button"}{click.icon.item ? " · design item icon" : ""}</div></div></>;
    body = (
      <>
        {!!click.icon.lore?.length && <div className="dz-sec"><span className="cys-eyebrow">Lore</span>{click.icon.lore.map((l, i) => <div key={i} className="cys-hint" style={{ fontStyle: "italic" }}>{l.text}</div>)}</div>}
        <div className="dz-sec">
          <span className="cys-eyebrow">On click <span className="cys-tag dim">{(click.actions ?? []).length} / {d.view!.limits.maxClickActions}</span></span>
          <ol className="dz-proto">{click.cost && <li><span>Pays <CostChip c={click.cost} icon={icon} /></span></li>}{(click.actions ?? []).map((a, i) => <li key={i}><span><ActChip a={a} icon={icon} /></span></li>)}{!click.cost && !(click.actions ?? []).length && <li><span className="dz-sub">shows only (no action)</span></li>}</ol>
        </div>
        {!!mine.length && <div className="dz-sec"><span className="cys-eyebrow">Settings <span className="cys-tag dim">config.yml</span></span>{mine.map((p) => <ParamRow key={p.path} d={d} p={p} strip={`menus.${m.id}.`} setParam={setParam} />)}</div>}
        {click.permission && <div className="dz-sec"><span className="cys-eyebrow">Permission</span><div className="dz-flow"><span className="dz-achip"><DI n="key" /><code>{ns}.{click.permission}</code></span><span className="dz-achip">default {m.permissions?.find((x) => x.node === click.permission)?.default ?? "op"}</span><span className="dz-achip"><DI n="lock" />{"hideWithoutPermission" in click && click.hideWithoutPermission ? "hidden without it" : "shown locked"}</span></div></div>}
        {click.cost?.type === "economy" && <div className="dz-sec"><div className="dz-note warn"><DI n="warn" /><span><code className="mono">economy_needs_vault</code> · money costs work only when Vault and an economy plugin are on the server. Otherwise the click is refused with a clear message.</span></div></div>}
      </>
    );
  } else if (sm.kind === "list" && m.style === "chest") {
    const c = sm.e ? listCost(m, sm.e) : undefined;
    head = sm.e ? <><div className="big"><Ico r={icon(sm.e.material)} size={36} /></div><div><div className="mct" style={{ ["--mc" as string]: "#fff" }}>{sm.e.name ?? bare(sm.e.material).replace(/_/g, " ")}</div><div className="dz-mono" style={{ marginTop: 4 }}>slot {slot} · list entry {sm.idx + 1} of {m.list!.source.entries.length}</div></div></> : <><div className="big" /><div><b>Empty list slot</b><div className="dz-mono">page {page + 1}</div></div></>;
    body = sm.e ? <div className="dz-sec"><span className="cys-eyebrow">On click</span><ol className="dz-proto"><li><span>Pays <CostChip c={c} icon={icon} /></span></li><li><span><ActChip a={{ type: "give_item", item: sm.e.material, count: sm.e.amount }} icon={icon} /></span></li></ol><p className="cys-hint" style={{ margin: "8px 0 0" }}>Every list entry is “buy amount × item for the price”. The owner changes prices in config.yml without a rebuild.</p></div> : null;
  } else if (sm.kind === "nav" && m.style === "chest") {
    head = <><div className="big"><Ico r={icon("minecraft:arrow")} size={36} /></div><div><b>{sm.dir === "prev" ? "Previous" : "Next"} page</b><div className="dz-mono">slot {slot} · list {sm.dir}</div></div></>;
    const navP = params.filter((p) => p.path.startsWith(`menus.${m.id}.${sm.dir}.`));
    body = <div className="dz-sec"><div className="dz-flow"><ActChip a={{ type: sm.dir === "prev" ? "prev_page" : "next_page" }} icon={icon} /></div>{navP.map((p) => <ParamRow key={p.path} d={d} p={p} strip={`menus.${m.id}.`} setParam={setParam} />)}</div>;
  } else {
    head = <><div className="big">{m.style === "chest" && m.filler && <Ico r={icon(m.filler)} size={36} />}</div><div><b>{m.style === "chest" && m.filler ? "Filler" : "Empty"}</b><div className="dz-mono">slot {slot}{m.style === "chest" && m.filler ? ` · ${bare(m.filler)}` : ""}</div></div></>;
    if (m.style === "dialogue") body = <div className="dz-sec">{params.filter((p) => /\.(title|speaker|line\d)$/.test(p.path)).map((p) => <ParamRow key={p.path} d={d} p={p} strip={`menus.${m.id}.`} setParam={setParam} />)}</div>;
  }
  if (mode === "try") {
    const last = tryRes?.clicks[tryRes.clicks.length - 1];
    const cur = tryRes?.inventory ?? [];
    return (
      <>
        <div className="dz-insh">{head}</div>
        <div className="dz-sec">
          <span className="cys-eyebrow">Sample player <button type="button" className="cys-btn xs ghost" style={{ marginLeft: "auto" }} onClick={onReset}><DI n="rollback" />Reset</button></span>
          <div className="dz-inv">
            {cur.slice(0, 6).map((x) => <span key={x.item} className="dz-achip"><Ico r={icon(x.item)} size={16} /><code>{x.count}</code></span>)}
            <span className="dz-achip"><DI n="sparkle" /><code>level {tryRes?.levels ?? 7}</code></span><span className="dz-achip"><DI n="coin" /><code>no Vault</code></span>
          </div>
          {last ? <ol className="dz-proto" style={{ marginTop: 10 }}>{last.steps.map((s, i) => <li key={i} className={s.ok ? "ok" : "no"}><span>{s.text}</span></li>)}{!last.steps.length && <li className={last.ran ? "ok" : "no"}><span>{last.reason}</span></li>}</ol>
            : <p className="cys-hint" style={{ margin: "8px 0 0" }}>Click any item in the menu to buy it with the fixed click protocol. The sample player starts with 9 emeralds, level 7, 6 free slots and every permission of this menu.</p>}
          <ul className="dz-slog" style={{ marginTop: 8, maxHeight: 140 }}>{(tryRes?.log ?? []).slice(0, 10).map((l, i) => <li key={i} className={l.tone} style={{ gridTemplateColumns: "1fr" }}><span>{l.text}</span></li>)}{!tryRes?.log.length && <li className="fx" style={{ gridTemplateColumns: "1fr" }}><span>no clicks yet</span></li>}</ul>
        </div>
      </>
    );
  }
  return <><div className="dz-insh">{head}</div>{body}</>;
}

function ParamRow({ d, p, strip, setParam }: { d: Designer; p: Param; strip: string; setParam: (path: string, v: number | string) => void }) {
  const was = d.savedParams.get(p.path)?.value;
  const changed = was !== undefined && String(was) !== String(p.value);
  return (
    <div className="dz-prow">
      <span className="pl">{p.label.replace(/^./, (c) => c.toUpperCase())}</span>
      <span className="pp" title={p.path}>{p.path.replace(strip, "")}</span>
      <span className="pv"><ParamField p={p} was={was} onSet={(v) => setParam(p.path, v)} compact /><span className="rg">{changed && <><span className="was">{String(was)}</span> · </>}{rangeText(p)}</span></span>
    </div>
  );
}

// ------------------------------------------------------------------------------------------------ quest editor
const OBJ_IC: Record<string, string> = { kill_entity: "sword", collect_item: "package", break_block: "pickaxe", craft_item: "wrench", visit_location: "globe", talk: "note", survive: "heart" };
function objText(o: Objective): string {
  switch (o.type) {
    case "kill_entity": return o.entity ? bare(o.entity) : (o.kinds ?? []).join(" or ");
    case "collect_item": return `${bare(o.item)}${o.take ? " · taken" : ""}${o.mode === "pickup" ? " · pick up" : ""}`;
    case "craft_item": return bare(o.item);
    case "break_block": return bare(o.block);
    case "visit_location": return `${o.world} ${o.x} ${o.y} ${o.z} · r ${o.radius}`;
    case "talk": return `dialogue ${o.menu}`;
    case "survive": return "stay alive";
  }
}
function RewardChip({ r, icon }: { r: Reward; icon: (x?: string) => Raster }) {
  return <span className="dz-rwc">{r.type === "give_item" ? <Ico r={icon(r.item)} size={14} /> : <DI n={r.type === "xp" ? "sparkle" : r.type === "send_message" ? "note" : r.type === "potion_effect" ? "flask" : r.type === "run_ability" ? "bolt" : "gift"} />}{r.type === "give_item" ? `${bare(r.item)} ×${r.count ?? 1}` : r.type === "xp" ? (r.points !== undefined ? `${r.points} xp` : `${r.levels} levels`) : r.type === "send_message" ? "message" : r.type === "potion_effect" ? `${r.effect} ${Math.round(r.durationTicks / 20)} s` : r.type === "advancement" ? "advancement" : `${r.item}.${r.ability}`}</span>;
}

function QuestEditor({ d, quests, q, setQuest, icon, setParam, qsim, qerr, qsteps, setQsteps }: WS & { q: QuestDesign; icon: (r?: string) => Raster; setParam: (p: string, v: number | string) => void; qsim: QuestSimResult | null; qerr: string | null; qsteps: QuestStep[]; setQsteps: (s: QuestStep[]) => void }) {
  const params = d.params.filter((p) => p.owner === "quest" && p.item === q.id);
  const pAt = (rel: string) => params.find((p) => p.path === `quests.${q.id}.${rel}`);
  const st = (id: string) => qsim?.states.find((s) => s.id === id);
  // chain order: by prerequisite depth, repeats last
  const depth = (x: QuestDesign, seen = new Set<string>()): number => { if (seen.has(x.id)) return 0; seen.add(x.id); return Math.max(0, ...(x.requires ?? []).map((r) => { const y = quests.find((z) => z.id === r); return y ? depth(y, seen) + 1 : 0; })); };
  const once = quests.filter((x) => (x.repeat?.mode ?? "once") === "once").sort((a, b) => depth(a) - depth(b) || (a.id < b.id ? -1 : 1));
  const rep = quests.filter((x) => (x.repeat?.mode ?? "once") !== "once");
  const node = (x: QuestDesign) => { const s = st(x.id); return (
    <button key={x.id} type="button" className={`dz-qnode ${x.id === q.id ? "on" : ""}`} onClick={() => setQuest(x.id)} aria-current={x.id === q.id}>
      <b>{x.title}</b><small>{x.id}{x.branches ? ` · ${x.branches.options.length} paths` : ""}{x.repeat && x.repeat.mode !== "once" ? ` · ${x.repeat.mode}` : ""}</small>
      <small className={s?.status === "done" ? "st-done" : s?.status === "active" || s?.status === "choosing" ? "st-active" : ""}>{s?.status ?? "…"}</small>
    </button>
  ); };
  const objRow = (stepId: string, o: Objective, j: number) => {
    const cnt = o.type === "survive" ? pAt(`steps.${stepId}.o${j}.seconds`) : o.type === "visit_location" || o.type === "talk" ? undefined : pAt(`steps.${stepId}.o${j}.count`);
    const s = st(q.id);
    const live = s && s.status === "active" && s.text.startsWith(q.steps.concat(...(q.branches?.options.map((b) => b.steps) ?? [])).find((x) => x.id === stepId)?.text ?? "\u0000") && j === 0 ? s.cur : null;
    const ref = o.type === "collect_item" || o.type === "craft_item" ? o.item : o.type === "break_block" ? o.block : undefined;
    return (
      <div key={j} className="dz-obj">
        {ref ? <Ico r={icon(ref)} size={18} /> : <DI n={OBJ_IC[o.type] ?? "flag"} />}<code>{o.type}</code><span>{objText(o)}</span>
        <span className="cnt">{live !== null && <span title="sample player progress">{live} /</span>}{cnt ? <ParamField p={cnt} was={d.savedParams.get(cnt.path)?.value} onSet={(v) => setParam(cnt.path, v)} /> : o.type === "visit_location" || o.type === "talk" ? "once" : ""}{o.type === "survive" && " s"}</span>
      </div>
    );
  };
  const chosen = qsteps.filter((x) => x.k === "choose" && x.quest === q.id).map((x) => (x as { branch: string }).branch).pop();
  const allRows = d.analysis?.gameplayChecks.quest ?? [];
  const L = d.view!.limits;
  return (
    <>
      <div className="dz-col">
        <DraftLine d={d} />
        <section className="cys-panel cys-glass cys-hairline">
          <div className="cys-ph"><span className="cys-eyebrow">Quest chain</span><span className="cys-hint">prerequisites, left to right</span></div>
          <div className="dz-chain">{once.map((x, i) => <span key={x.id} style={{ display: "contents" }}>{i > 0 && <span className="dz-qlink" />}{node(x)}</span>)}{!!rep.length && <span className="dz-qsep" />}{rep.map((x, i) => <span key={x.id} style={{ display: "contents" }}>{i > 0 && <span style={{ width: 8 }} />}{node(x)}</span>)}</div>
        </section>
        <section className="cys-panel cys-glass" style={{ flex: 1, minHeight: 0, display: "flex", flexDirection: "column" }}>
          <div className="dz-mhead">
            <span className="cys-eyebrow">Quest</span><span style={{ font: "600 16px/1 var(--display)" }}>{q.title}</span><span className="dz-mono">{q.id}</span><span style={{ flex: 1 }} />
            <span className="dz-achip"><DI n="flag" />{q.requires?.length ? <>requires <code>{q.requires.join(", ")}</code></> : "no prerequisite"}</span>
            <span className="dz-achip"><DI n="loopq" />{q.repeat && q.repeat.mode !== "once" ? <><code>{q.repeat.mode}</code>{pAt("repeat.cooldown_seconds") ? ` · ${Math.round(Number(pAt("repeat.cooldown_seconds")!.value) / 3600)} h` : ""}</> : "once"}</span>
            <span className="dz-achip"><DI n="play" />start: <code>{q.start ?? "command"}</code></span>
          </div>
          <div className="dz-qflow dz-scroll" style={{ flex: 1 }}>
            {q.steps.map((s, i) => (
              <div key={s.id} className="dz-fstep"><div className="dz-rail"><i>{i + 1}</i></div>
                <div className="dz-fcard"><h4>{s.text}<span className="dz-mono">{s.id}</span></h4>{s.objectives.map((o, j) => objRow(s.id, o, j))}</div></div>
            ))}
            {q.branches && (
              <div className="dz-fstep"><div className="dz-rail"><i><DI n="branch" /></i></div>
                <div className="dz-fcard"><h4>{q.branches.prompt ?? "Choose a path"}<span className="dz-mono">choice menu · {q.branches.options.length} of {L.maxBranches}</span></h4>
                  <div className="dz-branches">{q.branches.options.map((b) => (
                    <div key={b.id} className={`dz-bcol ${chosen === b.id ? "on" : ""}`}>
                      <h5>{b.icon && <Ico r={icon(b.icon.material ?? b.icon.item)} size={18} />}<McText t={b.label} /><span className="dz-mono" style={{ marginLeft: "auto" }}>{b.id}</span></h5>
                      {b.steps.map((s) => <div key={s.id}><div className="cys-hint" style={{ color: "var(--ink-2)", margin: "2px 0" }}>{s.text}</div>{s.objectives.map((o, j) => objRow(s.id, o, j))}</div>)}
                      {!!b.rewards?.length && <div className="dz-rw">{b.rewards.map((r, i) => <RewardChip key={i} r={r} icon={icon} />)}</div>}
                    </div>
                  ))}</div>
                </div></div>
            )}
            <div className="dz-fstep"><div className="dz-rail"><i><DI n="gift" /></i></div>
              <div className="dz-fcard"><h4>Rewards<span className="dz-mono">{q.rewards?.length ?? 0} of {L.maxRewards}</span></h4><div className="dz-rw">{(q.rewards ?? []).map((r, i) => <RewardChip key={i} r={r} icon={icon} />)}{!q.rewards?.length && <span className="dz-sub">none</span>}</div></div></div>
            <div className="dz-note" style={{ marginTop: 2 }}><DI n="info" /><span>{q.failure?.onDeath && q.failure.onDeath !== "keep" ? <><b>On death:</b> {q.failure.onDeath === "fail" ? "the quest fails" : "the current step resets"}. </> : null}{q.failure?.timeLimitSeconds ? <><b>Time limit:</b> {Math.round(q.failure.timeLimitSeconds / 60)} min. </> : null}Steps run in order; each step&apos;s objectives count only while it is active. Progress is stored per player on the player (a bounded string), never in a file.</span></div>
            {!!params.length && (
              <div style={{ marginTop: 12 }}><div className="cys-eyebrow" style={{ marginBottom: 4 }}>Settings · config.yml</div>{params.filter((p) => p.kind === "text").map((p) => <ParamRow key={p.path} d={d} p={p} strip={`quests.${q.id}.`} setParam={setParam} />)}</div>
            )}
          </div>
        </section>
      </div>
      <div className="dz-col">
        <section className="cys-panel cys-glass cys-hairline" style={{ flex: 1, minHeight: 0 }}>
          <div className="cys-ph"><span className="cys-eyebrow">Progress simulator</span><span className="cys-tag dim">sample player</span></div>
          <div className="dz-scroll" style={{ flex: 1, padding: "0 12px 12px" }}>
            {qerr ? <div className="dz-note warn"><DI n="warn" /><span>{qerr}</span></div> : (
              <>
                {(qsim?.states ?? []).map((s) => (
                  <div key={s.id} className="dz-qstate"><b>{s.title}</b><span className={`cys-tag ${s.status === "done" ? "ok" : s.status === "active" || s.status === "choosing" ? "acc" : "dim"}`}>{s.status}</span><small>{s.text}</small><div className={`dz-pbar ${s.status === "done" ? "done" : ""}`}><i style={{ width: `${Math.min(100, (s.cur / Math.max(1, s.target)) * 100)}%` }} /></div></div>
                ))}
                <div className="cys-eyebrow" style={{ margin: "10px 0 6px", display: "flex" }}>Player events<button type="button" className="cys-btn xs ghost" style={{ marginLeft: "auto" }} disabled={!qsteps.length} onClick={() => setQsteps([])}><DI n="rollback" />Reset</button></div>
                <div className="dz-evbtns">{(qsim?.buttons ?? []).map((b, i) => <button key={i} type="button" className="cys-btn xs" disabled={qsteps.length >= 40} onClick={() => setQsteps([...qsteps, b.step])}>{b.label}</button>)}</div>
                <ul className="dz-slog" style={{ marginTop: 8, maxHeight: 150 }}>{(qsim?.log ?? []).slice(0, 14).map((l, i) => <li key={i} className={l.tone} style={{ gridTemplateColumns: "1fr" }}><span>{l.text}</span></li>)}{!qsim?.log.length && <li className="fx" style={{ gridTemplateColumns: "1fr" }}><span>No events yet. Start a quest.</span></li>}</ul>
                <div className="cys-eyebrow" style={{ margin: "12px 0 6px" }}>Limits</div>
                <Meter label="Stored progress per player (worst case)" used={d.analysis?.progressChars ?? 0} cap={L.maxProgressChars} title="characters of the player's progress string, every quest at its longest" />
                <div style={{ height: 8 }} />
                <Meter label="Active quests (max_active_quests)" used={qsim?.active ?? 0} cap={qsim?.maxActive ?? L.activeQuests[1]} />
                <div className="cys-eyebrow" style={{ margin: "12px 0 6px" }}>Checks · all quests</div>
                <ul className="dz-issues">
                  {quests.flatMap((x) => d.analysis?.files.find((f) => f.id === x.id)?.errors ?? []).map((e, i) => <IssueRow key={`e${i}`} i={e} tone="err" />)}
                  {allRows.map((c) => <li key={c.id} className={`dz-issue ${c.status === "pass" ? "ok" : c.status === "fail" ? "err" : c.status === "warn" ? "warn" : "info"}`}><span className="ic"><DI n={c.status === "pass" ? "check" : c.status === "fail" ? "close" : c.status === "warn" ? "warn" : "minus"} /></span><code>{c.id}</code><span className="path">{c.status.replace("_", " ")}</span>{!!c.items.length && <span className="m">{c.items[0]}</span>}</li>)}
                </ul>
                <div className="dz-note" style={{ marginTop: 10 }}><DI n="info" /><span>The simulator follows the quest engine&apos;s rules. Kills, pickups and crafting in a real game have not been verified with a real client.</span></div>
              </>
            )}
          </div>
          <PendingBar d={d} labels={(id) => id} />
        </section>
      </div>
    </>
  );
}

// --------------------------------------------------------------------------------------------- narrow (phone)
function Narrow({ d, menus, quests, m, icon, qsim }: WS & { icon: (r?: string) => Raster; qsim: QuestSimResult | null }) {
  const ok = d.analysis?.ok ?? false;
  const act = STUDIO_DEFAULTS.mobile === "review_and_approve" && d.changed.length > 0;
  const mrep = m ? d.analysis?.files.find((f) => f.id === m.id) : null;
  return (
    <main className="dz-narrow" aria-label="Menu and quest review">
      {m && (
        <section className="n-card cys-glass">
          <div className="n-h"><div className="dz-thumb" style={{ width: 48, height: 48 }}><Ico r={icon(m.style === "chest" ? m.buttons?.[0]?.icon.material ?? "minecraft:chest" : "minecraft:compass")} size={34} /></div>
            <div><h1><McText t={{ text: m.title, color: "gold" }} /></h1><p>{m.style === "chest" ? `menu · ${m.rows} rows${m.list ? ` · ${pagesOf(m)} pages · ${m.list.source.entries.length} entries` : ""}` : `dialogue · ${m.choices.length} choices`}</p></div>
            <span className={`cys-tag ${mrep?.errors.length ? "bad" : mrep?.warnings.length ? "warn" : "ok"}`} style={{ marginLeft: "auto" }}>{mrep?.errors.length ? `${mrep.errors.length} errors` : mrep?.warnings.length ? `${mrep.warnings.length} warn` : "valid"}</span></div>
          <div className="n-sec"><div className="dz-grid9">{Array.from({ length: m.style === "chest" ? m.rows * 9 : 27 }, (_, i) => { const s = slotModel(m, i, 0); const id = s.kind === "button" ? s.c.icon.material ?? s.c.icon.item : s.kind === "list" ? s.e?.material ?? s.fixed?.icon.material : s.kind === "nav" ? "minecraft:arrow" : s.kind === "choice" ? s.c.icon.material ?? s.c.icon.item : m.style === "chest" ? m.filler : undefined; return <span key={i} className={`dz-slot ${s.kind === "list" ? "list" : s.kind === "filler" ? "filler" : ""}`}>{id && <Ico r={icon(id)} size={22} />}</span>; })}</div></div>
          <div className="n-sec"><span className="cys-eyebrow">Checks</span>{(mrep?.warnings ?? []).slice(0, 3).map((w, i) => <div key={i} className="dz-note warn" style={{ marginBottom: 6 }}><DI n="warn" /><span>{w.message}</span></div>)}<p className="cys-hint" style={{ margin: "8px 0 0" }}>Every click and drag is cancelled; buying is room → pay → take → give.</p></div>
        </section>
      )}
      {!!quests.length && (
        <section className="n-card cys-glass">
          <div className="n-h"><div><h1>Quests</h1><p>{quests.length} quests · {quests.filter((q) => q.branches).length} with a branch · {quests.filter((q) => (q.repeat?.mode ?? "once") !== "once").length} repeating</p></div></div>
          <div className="n-sec">{quests.map((q) => <div key={q.id} className="dz-qstate"><b>{q.title}</b><span className="cys-tag dim">{q.requires?.length ? `after ${q.requires[0]}` : q.repeat && q.repeat.mode !== "once" ? q.repeat.mode : "first"}</span><small>{q.steps.map((s) => s.text).join(" → ")}{q.branches ? ` → ${q.branches.options.map((b) => b.label.text).join(" or ")}` : ""}</small></div>)}</div>
          <div className="n-note"><DI n="info" /><span>Validated and simulated{qsim ? "" : ""}. Not verified with a real player.</span></div>
        </section>
      )}
      {!menus.length && !quests.length && <p className="cys-hint">No menus or quests.</p>}
      <section className="n-card cys-glass">
        <div className="n-sec" style={{ borderTop: 0 }}><span className="cys-eyebrow">Waiting for approval</span>{d.changed.length ? <p>{d.changed.join(", ")} changed (autosaved draft).</p> : <p className="cys-hint" style={{ margin: 0 }}>Nothing waiting. Edit menus and quests on a larger screen.</p>}</div>
        {act && <div className="n-act"><button type="button" className="cys-btn" onClick={() => void d.discard()}>Reject</button><button type="button" className="cys-btn primary" disabled={!ok || d.saving} onClick={() => void d.save()}><DI n="check" />Approve revision</button></div>}
      </section>
    </main>
  );
}

