const capNum = (c: BossCapName) => z.number().min(BOSS_CAPS[c][0]).max(BOSS_CAPS[c][1]);
const capInt = (c: BossCapName) => z.number().int().min(BOSS_CAPS[c][0]).max(BOSS_CAPS[c][1]);
const ItemRef = z.union([VanillaRef, Key]);

// ------------------------------------------------------------------------------------------------------- actions
/** Who a text action goes to: each target, or every participant of the fight. */
const To = z.enum(["target", "arena"]);
/** Where a particle / sound action happens: at the boss (once) or at each target. */
const At = z.enum(["boss", "target"]);
export type BossAction =
  | { type: "damage"; amount: number }
  | { type: "knockback"; strength: number; vertical?: number }
  | { type: "pull"; strength: number; vertical?: number }
  | { type: "potion_effect"; effect: (typeof EFFECTS)[number]; durationTicks: number; amplifier?: number }
  | { type: "launch_projectile"; kind: (typeof PROJECTILES)[number]; speed: number; damage?: number }
  | { type: "spawn_particles"; particle: (typeof PARTICLES)[number]; count: number; spread?: number; speed?: number; at?: "boss" | "target" }
  | { type: "play_sound"; sound: string; volume?: number; pitch?: number; at?: "boss" | "target" }
  | { type: "send_message"; text: string; color?: string; to?: "target" | "arena" }
  | { type: "actionbar"; text: string; color?: string; to?: "target" | "arena" }
  | { type: "title"; title: string; subtitle?: string; color?: string; to?: "target" | "arena" }
  | { type: "leap"; strength: number; vertical?: number }
  | { type: "summon"; entity: string; count: number; health?: number }
  | { type: "heal_self"; amount: number }
  | { type: "self_effect"; effect: (typeof EFFECTS)[number]; durationTicks: number; amplifier?: number }
  | { type: "delayed"; delayTicks: number; actions: BossAction[] };
export type BossActionType = BossAction["type"];
/** Actions that run once per target (the others run once per attack, at the boss). */
export const PER_TARGET: ReadonlySet<BossActionType> = new Set(["damage", "knockback", "pull", "potion_effect", "launch_projectile"]);
export const isPerTarget = (a: BossAction): boolean => PER_TARGET.has(a.type) || ((a.type === "spawn_particles" || a.type === "play_sound") && a.at === "target") || ((a.type === "send_message" || a.type === "actionbar" || a.type === "title") && (a.to ?? "target") === "target");

const BossActions: z.ZodType<BossAction[]> = z.lazy(() => z.array(BossActionSchema).min(1).max(BOSS_LIMITS.maxActions));
export const BossActionSchema: z.ZodType<BossAction> = z.lazy(() => z.discriminatedUnion("type", [
  /** Damage each target (the boss is the source: PvP-style protections and armor apply); scaled by difficulty and players. */
  z.strictObject({ type: z.literal("damage"), amount: capNum("damage") }),
  z.strictObject({ type: z.literal("knockback"), strength: capNum("strength"), vertical: capNum("vertical").optional() }),
  z.strictObject({ type: z.literal("pull"), strength: capNum("strength"), vertical: capNum("vertical").optional() }),
  z.strictObject({ type: z.literal("potion_effect"), effect: z.enum(EFFECTS), durationTicks: capInt("potionTicks"), amplifier: capInt("amplifier").optional() }),
  /** One projectile from the boss's eyes at each target; `damage` is added on hit (scaled like damage); removed after 5 s. */
  z.strictObject({ type: z.literal("launch_projectile"), kind: z.enum(PROJECTILES), speed: capNum("projectileSpeed"), damage: capNum("projectileDamage").optional() }),
  z.strictObject({ type: z.literal("spawn_particles"), particle: z.enum(PARTICLES), count: capInt("particleCount"), spread: capNum("particleSpread").optional(), speed: capNum("particleSpeed").optional(), at: At.optional() }),
  z.strictObject({ type: z.literal("play_sound"), sound: SoundKey, volume: capNum("volume").optional(), pitch: capNum("pitch").optional(), at: At.optional() }),
  z.strictObject({ type: z.literal("send_message"), text: Text(120), color: Color.optional(), to: To.optional() }),
  z.strictObject({ type: z.literal("actionbar"), text: Text(120), color: Color.optional(), to: To.optional() }),
  z.strictObject({ type: z.literal("title"), title: Text(40), subtitle: Text(60).optional(), color: Color.optional(), to: To.optional() }),
  /** The boss jumps toward its first target. */
  z.strictObject({ type: z.literal("leap"), strength: capNum("strength"), vertical: capNum("vertical").optional() }),
  /** Minions next to the boss (minion allowlist): they drop nothing, are removed with the boss, capped by minions.maxAlive. */
  z.strictObject({ type: z.literal("summon"), entity: VanillaRef, count: capInt("summonCount"), health: capNum("minionHealth").optional() }),
  z.strictObject({ type: z.literal("heal_self"), amount: capNum("heal") }),
  /** A helpful effect on the boss itself (resistance, speed, regeneration...). */
  z.strictObject({ type: z.literal("self_effect"), effect: z.enum(EFFECTS), durationTicks: capInt("potionTicks"), amplifier: capInt("selfAmplifier").optional() }),
  /** Run later (one scheduled task; skipped when the boss is gone; the targets are re-checked: still alive and in the arena). */
  z.strictObject({ type: z.literal("delayed"), delayTicks: capInt("delayTicks"), actions: BossActions }),
]));
export const BOSS_ACTION_TYPES = ["damage", "knockback", "pull", "potion_effect", "launch_projectile", "spawn_particles", "play_sound", "send_message", "actionbar", "title", "leap", "summon", "heal_self", "self_effect", "delayed"] as const;

// ------------------------------------------------------------------------------------------------------- attacks
export const TelegraphSchema = z.strictObject({
  /** Warning time before the actions run (the boss shows the particle / sound / text, then strikes). */
  ticks: capInt("telegraphTicks"),
  particle: z.enum(PARTICLES).optional(),
  sound: SoundKey.optional(),
  text: Text(60).optional(),
});
export const AttackSchema = z.strictObject({
  id: Key,
  name: Text(32).optional(),
  telegraph: TelegraphSchema.optional(),
  /** This attack cannot be picked again for this many ticks. */
  cooldownTicks: capInt("cooldownTicks").optional(),
  /** Which participants it hits: nearest / random / farthest first (at most max), every one in range (at most max), or none ("self"). */
  targets: z.strictObject({ select: z.enum(SELECT_MODES), max: capInt("targetMax"), range: capNum("targetRange") }),
  actions: BossActions,
});
export type Attack = z.infer<typeof AttackSchema>;

export const PhaseSchema = z.strictObject({
  id: Key,
  name: Text(24).optional(),
  /** Enter this phase when the boss's health fraction drops below this (the first phase: 1). Phases never go back. */
  below: capNum("below"),
  attacks: z.array(z.strictObject({ attack: Key, weight: capInt("weight").optional() })).min(1).max(BOSS_LIMITS.maxPhaseAttacks),
  /** Ticks between two attacks in this phase. */
  intervalTicks: capInt("intervalTicks"),
  /** Runs once when the phase starts (targets: every participant). */
  onEnter: z.array(BossActionSchema).max(BOSS_LIMITS.maxEnterActions).optional(),
  /** Helpful effects the boss keeps during this phase (refreshed). */
  selfEffects: z.array(z.strictObject({ effect: z.enum(EFFECTS), amplifier: capInt("selfAmplifier").optional() })).max(BOSS_LIMITS.maxSelfEffects).optional(),
});
export type Phase = z.infer<typeof PhaseSchema>;

// --------------------------------------------------------------------------------------------------------- drops
export const DropsSchema = z.strictObject({
  /** "participants": every player who did at least minDamageShare of the damage gets their own rolls (anti-steal; nobody
   * qualified = nothing drops); "ground": one roll set at the boss's position. */
  mode: z.enum(["participants", "ground"]),
  minDamageShare: capNum("damageShare").optional(),
  xp: capInt("xp").optional(),
  items: z.array(z.strictObject({ item: ItemRef, count: capInt("dropCount"), chance: capNum("dropChance") })).max(BOSS_LIMITS.maxDrops).optional(),
  /** A loot table of THIS project's data pack (`<ns>:<path>`), rolled once per roll set. */
  lootTable: NsRef.optional(),
});
export type Drops = z.infer<typeof DropsSchema>;

const BarSchema = z.strictObject({ color: z.enum(BAR_COLORS).optional(), overlay: z.enum(BAR_OVERLAYS).optional(), showPhase: z.boolean().optional(), darkenSky: z.boolean().optional() });
const SpawnSchema = z.strictObject({
  /** `/<mod> boss spawn <id> [world x y z | spawn]` (operators, <ns>.boss.spawn). Default true. */
  command: z.boolean().optional(),
  /** Right-click with this design item of the mod (consumed) spawns it at the player. The item must have no right-click abilities. */
  item: Key.optional(),
  cooldownSeconds: capInt("spawnCooldownSeconds").optional(),
  /** Alive at once (this boss); the plugin-wide cap is 4 bosses. */
  maxAlive: capInt("maxAlive").optional(),
});
const MessagesSchema = z.strictObject({ spawn: Text(120).optional(), defeat: Text(120).optional(), despawn: Text(120).optional(), enrage: Text(120).optional() });

export const BossDesignSchema = z.strictObject({
  schemaVersion: z.literal(BOSS_SPEC_VERSION),
  kind: z.literal("boss"),
  id: Key,
  name: StyledText,
  entity: VanillaRef,
  stats: z.strictObject({ health: capNum("health"), armor: capNum("armor").optional(), attackDamage: capNum("attackDamage").optional(), speed: capNum("speed").optional(), knockbackResistance: capNum("knockbackResistance").optional(), followRange: capNum("followRange").optional() }),
  /** Display equipment (vanilla items or this mod's design items; never dropped). */
  equipment: z.strictObject(Object.fromEntries(EQUIP_SLOTS.map((s) => [s, ItemRef.optional()])) as Record<(typeof EQUIP_SLOTS)[number], z.ZodOptional<typeof ItemRef>>).optional(),
  immune: z.array(z.enum(IMMUNITIES)).max(IMMUNITIES.length).optional(),
  bossBar: BarSchema.optional(),
  arena: z.strictObject({
    /** Blocks around the spawn point: players inside are participants (boss bar, targets); the boss is pulled back when it leaves. */
    radius: capNum("arenaRadius"),
    /** No participant for this long: the boss despawns (no drops). */
    emptyDespawnSeconds: capInt("emptyDespawnSeconds"),
    maxDurationSeconds: capInt("maxDurationSeconds").optional(),
    /** At maxDurationSeconds: despawn (default) or enrage (damage x1.5, attacks twice as often, until defeated or empty). */
    onTimeout: z.enum(["despawn", "enrage"]).optional(),
  }),
  spawn: SpawnSchema.optional(),
  phases: z.array(PhaseSchema).min(1).max(BOSS_LIMITS.maxPhases),
  attacks: z.array(AttackSchema).min(1).max(BOSS_LIMITS.maxAttacks),
  minions: z.strictObject({ maxAlive: capInt("minionsMax") }).optional(),
  /** Per extra participant at spawn (health) / per attack (damage), up to maxPlayers counted. */
  scaling: z.strictObject({ healthPerPlayer: capNum("healthPerPlayer").optional(), damagePerPlayer: capNum("damagePerPlayer").optional(), maxPlayers: capInt("maxPlayers").optional() }).optional(),
  /** Attack damage multiplier by world difficulty (peaceful: the boss is removed by the game; Cyrus refuses to spawn it). */
  difficulty: z.strictObject({ easy: capNum("difficulty").optional(), normal: capNum("difficulty").optional(), hard: capNum("difficulty").optional() }).optional(),
  drops: DropsSchema.optional(),
  messages: MessagesSchema.optional(),
});
export type BossDesign = z.infer<typeof BossDesignSchema>;

// ---------------------------------------------------------------------------------------------------- encounters
export const WaveSpawnSchema = z.strictObject({
  /** A minion-class vanilla mob, OR `boss`: one of this mod's bosses (count 1). */
  entity: VanillaRef.optional(),
  boss: Key.optional(),
  count: capInt("waveCount"),
});
export const WaveSchema = z.strictObject({
  delaySeconds: capInt("waveDelaySeconds").optional(),
  spawns: z.array(WaveSpawnSchema).min(1).max(BOSS_LIMITS.maxWaveSpawns),
  /** "cleared": the next wave starts when every mob of this wave is dead (seconds = optional time limit: the encounter fails);
   * "timer": the next wave starts after seconds. */
  advance: z.enum(["cleared", "timer"]),
  seconds: capInt("waveSeconds").optional(),
  message: Text(120).optional(),
});
export type Wave = z.infer<typeof WaveSchema>;
export const EncounterDesignSchema = z.strictObject({
  schemaVersion: z.literal(BOSS_SPEC_VERSION),
  kind: z.literal("encounter"),
  id: Key,
  title: Text(40),
  arena: z.strictObject({ radius: capNum("arenaRadius") }),
  start: z.strictObject({ command: z.boolean().optional(), item: Key.optional(), cooldownSeconds: capInt("spawnCooldownSeconds").optional() }).optional(),
  waves: z.array(WaveSchema).min(1).max(BOSS_LIMITS.maxWaves),
  /** Mobs of this encounter alive at once (every wave's total must fit). */
  maxAlive: capInt("encounterMaxAlive"),
  failure: z.strictObject({ emptySeconds: capInt("emptyDespawnSeconds"), timeLimitSeconds: capInt("encounterTimeLimit").optional() }),
  rewards: DropsSchema.optional(),
  bossBar: BarSchema.optional(),
  messages: z.strictObject({ start: Text(120).optional(), complete: Text(120).optional(), fail: Text(120).optional() }).optional(),
});
export type EncounterDesign = z.infer<typeof EncounterDesignSchema>;

export function bossJsonSchema(): Record<string, unknown> {
  return {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    title: "Cyrus boss and encounter designs v1; item designs: designer.v1.schema.json, menus/quests: gameplay.v1.schema.json",
    oneOf: [z.toJSONSchema(BossDesignSchema, { io: "input", reused: "ref" }), z.toJSONSchema(EncounterDesignSchema, { io: "input", reused: "ref" })],
  };
}

