// ------------------------------------------------------------------------------------------------ bosses (fight)
import { BossFight, type FightEvent } from "../boss/simulate";
import type { BossDesign } from "../boss/spec";
export type BossStep = { k: "hit"; pct: number } | { k: "wait"; seconds: number } | { k: "join" } | { k: "leave" };
export type BossSimResult = { t: number; health: number; max: number; phase: number; phaseId: string; enraged: boolean; ended: string | null; participants: number; log: { t: number; kind: string; text: string }[]; drops: { player: string; items: string[] }[] };

/** One fight of the reference simulator: you (and, after "join", a second player) inside the arena, scripted damage. */
export function simulateBoss(files: readonly DesignFile[], bossId: string, steps: readonly BossStep[], namespace: string): BossSimResult {
  const b = files.find((f) => f.id === bossId && fileKind(f) === "boss") as BossDesign | undefined;
  if (!b) throw new Error(`no boss ${bossId}`);
  const f = new BossFight(b, [{ id: "you", pos: [3, 64, 0], health: 1000 }, { id: "ally", pos: [5, 64, 2], health: 1000, online: false }], { namespace, seed: 7 });
  const ev: FightEvent[] = [];
  let t = 0;
  for (const s of steps.slice(0, MAX_SIM_STEPS)) {
    if (s.k === "hit") { t += 10; ev.push({ t, kind: "damage", by: "you", amount: Math.max(1, Math.round((f.max * Math.max(1, Math.min(100, s.pct))) / 100)) }); }
    if (s.k === "wait") t += Math.max(1, Math.min(600, s.seconds)) * 20;
    if (s.k === "join") { t += 10; ev.push({ t, kind: "join", player: "ally" }); }
    if (s.k === "leave") { t += 10; ev.push({ t, kind: "move", player: "you", pos: [b.arena.radius + 20, 64, 0] }, { t, kind: "move", player: "ally", pos: [b.arena.radius + 20, 64, 0] }); }
  }
  f.run(ev, t);
  const items = (counts: number[]) => (b.drops?.items ?? []).flatMap((x, i) => (counts[i] ? [`${counts[i]} × ${x.item.replace(/^minecraft:/, "")}`] : []));
  return {
    t: f.t, health: Math.round(f.health), max: Math.round(f.max), phase: f.phase, phaseId: b.phases[f.phase]?.id ?? "", enraged: f.enraged, ended: f.ended, participants: f.participants().length,
    log: f.log.slice(-60).map((l) => ({ t: l.t, kind: l.kind, text: `${l.kind} ${l.detail}`.trim() })), drops: f.drops.map((d) => ({ player: d.player, items: items(d.counts) })),
  };
}
