4	import type { DesignerView, SaveDesignsResult } from "@/lib/cyrus/designer/studio/service";
5	import type { Analysis } from "@/lib/cyrus/designer/studio/analyze";
6	import type { DesignFile } from "@/lib/cyrus/designer/studio/edit";
7	import type { BossSimResult, BossStep, ItemSimResult, ItemStep, QuestSimResult, QuestStep, SimButton, TryResult } from "@/lib/cyrus/designer/studio/sim";
8	import type { EditPlan } from "@/lib/cyrus/designer/params";
9	import { ApiError } from "../studios/api";
10	
11	export type { BossSimResult, BossStep, DesignerView, Analysis, DesignFile, ItemSimResult, ItemStep, QuestSimResult, QuestStep, SimButton, TryResult, EditPlan, SaveDesignsResult };
12	export const DAPI = "/api/cyrus/designer/v1";
13	
14	async function call<T>(path: string, init?: RequestInit): Promise<T> {
15	  const r = await fetch(DAPI + path, { cache: "no-store", ...init, headers: { ...(init?.body ? { "content-type": "application/json" } : {}), ...(init?.headers ?? {}) } });
16	  const j = (await r.json().catch(() => ({}))) as Record<string, unknown>;
17	  if (!r.ok) throw new ApiError(r.status, String(j.code ?? r.status), String(j.error ?? "Something went wrong."), j);
18	  return j as T;
19	}
