"use client";
// Cyrus BOSS + ENCOUNTER DESIGNER (r27), full page. There is no v2 mockup for this screen: it reuses the Item
// Designer's anatomy and tokens (left = the mod's bosses and encounters, the selected boss's attacks, spawn and drops;
// centre = the boss header with its boss bar, the phase ladder on the health bar (thresholds, intervals, attack
// weights, phase start actions) and the selected attack with its per-attack budget; right = the arena and the
// Parameters / Fight / Checks tabs). Every number is a config.yml value (Param.ptr into the design); the fight runs the
// reference simulator (lib/cyrus/designer/boss/simulate.ts). Phones get the read-only summary + approve / reject.
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { Param } from "@/lib/cyrus/designer/compile";
import type { Attack, BossAction, BossDesign, EncounterDesign, Phase } from "@/lib/cyrus/designer/boss/spec";
import { fileKind, setParamValue, type DesignFile } from "@/lib/cyrus/designer/studio/edit";
import type { Raster } from "@/lib/cyrus/textures/render";
import { STUDIO_DEFAULTS } from "@/lib/cyrus/studios/access";
import { useToast, type StudioMod } from "../studios/StudioShell";
import { designerApi, type BossSimResult, type BossStep } from "./api";
import { DesignerContext, DesignerShell, DraftLine, Failed, Ico, IssueRow, Loading, McText, Meter, NoDesigns, ParamField, PendingBar, rangeText, useDesigner, useIcon, type Designer } from "./shared";
import { PLACEHOLDER_NOTE } from "./pixel-icons";
import { DI } from "./icons";

type Sel = { kind: "boss" | "encounter"; id: string };
const bare = (s: string) => String(s ?? "").replace(/^minecraft:/, "");
const ACT_IC: Record<string, string> = { damage: "sword", knockback: "target", pull: "target", potion_effect: "flask", launch_projectile: "target", spawn_particles: "sparkle", play_sound: "volume", send_message: "note", actionbar: "note", title: "note", leap: "arrowR", summon: "user", heal_self: "heart", self_effect: "shield", delayed: "clock" };
const actSum = (a: BossAction): string => {
  switch (a.type) {
    case "damage": return `${a.amount} per target`;
    case "knockback": case "pull": case "leap": return `strength ${a.strength}`;
    case "potion_effect": case "self_effect": return `${a.effect} ${Math.round(a.durationTicks / 20)} s`;
    case "launch_projectile": return `${a.kind.replace("_", " ")}${a.damage ? ` +${a.damage}` : ""}`;
    case "spawn_particles": return `${a.particle} ×${a.count} at ${a.at ?? "boss"}`;
    case "play_sound": return bare(a.sound).split(".").slice(-2).join(".");
    case "send_message": case "actionbar": return `“${a.text}” to ${a.to ?? "target"}`;
    case "title": return `“${a.title}” to ${a.to ?? "target"}`;
    case "summon": return `${a.count} × ${bare(a.entity)}`;
    case "heal_self": return `${a.amount} health`;
    case "delayed": return `after ${a.delayTicks} ticks: ${a.actions.length} actions`;
  }
};

export function BossDesigner({ mod, initialBoss }: { mod: StudioMod; initialBoss: string | null }) {
  return <DesignerShell mod={mod} tab="bosses" current="Boss Designer" showBosses><Body mod={mod} initialBoss={initialBoss} /></DesignerShell>;
}

function Body({ mod, initialBoss }: { mod: StudioMod; initialBoss: string | null }) {
  const d = useDesigner(mod);
  const bosses = useMemo(() => d.files.filter((f) => fileKind(f) === "boss") as unknown as BossDesign[], [d.files]);
  const encs = useMemo(() => d.files.filter((f) => fileKind(f) === "encounter") as unknown as EncounterDesign[], [d.files]);
  const [sel, setSel] = useState<Sel | null>(initialBoss ? { kind: "boss", id: initialBoss } : null);
  useEffect(() => {
    if (sel && (sel.kind === "boss" ? bosses : encs).some((x) => x.id === sel.id)) return;
    if (bosses.length) setSel({ kind: "boss", id: bosses[0].id }); else if (encs.length) setSel({ kind: "encounter", id: encs[0].id });
  }, [bosses, encs, sel]);
  if (d.err) return <Failed msg={d.err} />;
  if (!d.view) return <Loading what="this mod's bosses" />;
  if (!d.view.project || (!bosses.length && !encs.length)) return <NoDesigns mod={mod} what="bosses or encounters" />;
  if (!sel) return <Loading what="this mod's bosses" />;
  return <DesignerContext d={d}><Workspace d={d} bosses={bosses} encs={encs} sel={sel} setSel={setSel} /></DesignerContext>;
}

function Workspace({ d, bosses, encs, sel, setSel }: { d: Designer; bosses: BossDesign[]; encs: EncounterDesign[]; sel: Sel; setSel: (s: Sel) => void }) {
  const toast = useToast();
  const icon = useIcon(d.textures);
  const boss = sel.kind === "boss" ? bosses.find((b) => b.id === sel.id) ?? null : null;
  const enc = sel.kind === "encounter" ? encs.find((e) => e.id === sel.id) ?? null : null;
  const [atk, setAtk] = useState<string>(boss?.attacks[0]?.id ?? "");
  const [rtab, setRtab] = useState<"params" | "fight" | "checks">("params");
  useEffect(() => { if (boss && !boss.attacks.some((a) => a.id === atk)) setAtk(boss.attacks[0]?.id ?? ""); }, [boss, atk]);
  const params = d.params.filter((p) => p.item === sel.id && (p.owner === "boss" || p.owner === "encounter"));
  const setParam = useCallback((p: Param, v: number | string) => { const r = setParamValue(d.files, p.path, v, p.ptr); if (r.ok) d.setFiles(r.files); else toast(r.error, true); }, [d, toast]);
  const pAt = (rel: string) => params.find((p) => p.path === `${sel.kind === "boss" ? "bosses" : "encounters"}.${sel.id}.${rel}`);
  const rep = d.analysis?.files.find((f) => f.id === sel.id);
  const attack = boss?.attacks.find((a) => a.id === atk) ?? null;
  return (
    <>
      <main className="dz-ws" aria-label="Boss Designer">
        <div className="dz-col scroll">
          <section className="cys-panel cys-glass cys-hairline">
            <div className="cys-ph"><span className="cys-eyebrow">Bosses</span><span className="n">{bosses.length} / {d.view!.limits.maxBosses}</span></div>
            <div className="dz-body">
              {bosses.map((b) => { const f = d.analysis?.files.find((x) => x.id === b.id); return (
                <button key={b.id} type="button" className={`dz-row ${sel.kind === "boss" && sel.id === b.id ? "on" : ""}`} onClick={() => setSel({ kind: "boss", id: b.id })}>
                  <span className="dz-thumb plain"><DI n="skull" /></span>
                  <span className="tx"><b>{b.id}</b><small>{bare(b.entity)} · {b.phases.length} phases · {b.attacks.length} attacks</small></span>
                  <span className={`cys-dot ${!f ? "" : f.errors.length ? "bad" : f.warnings.length ? "warn" : "ok"}`} />
                </button>
              ); })}
              {encs.map((e) => { const f = d.analysis?.files.find((x) => x.id === e.id); return (
                <button key={e.id} type="button" className={`dz-row ${sel.kind === "encounter" && sel.id === e.id ? "on" : ""}`} onClick={() => setSel({ kind: "encounter", id: e.id })}>
                  <span className="dz-thumb plain"><DI n="arena" /></span>
                  <span className="tx"><b>{e.id}</b><small>encounter · {e.waves.length} waves</small></span>
                  <span className={`cys-dot ${!f ? "" : f.errors.length ? "bad" : f.warnings.length ? "warn" : "ok"}`} />
                </button>
              ); })}
            </div>
          </section>
          {boss && (
            <section className="cys-panel cys-glass">
              <div className="cys-ph"><span className="cys-eyebrow">Attacks</span><span className="n">{boss.attacks.length} / {d.view!.limits.maxAttacks}</span></div>
              <div className="dz-body">{boss.attacks.map((a) => (
                <button key={a.id} type="button" className={`dz-row ${a.id === atk ? "on" : ""}`} onClick={() => setAtk(a.id)}>
                  <span className="dz-thumb plain"><DI n={ACT_IC[a.actions[0]?.type] ?? "bolt"} /></span>
                  <span className="tx"><b className="sans">{a.name ?? a.id}</b><small>{a.targets.select}{a.targets.select !== "self" ? ` · ${a.targets.max} in ${a.targets.range}` : ""}{a.telegraph ? ` · ${a.telegraph.ticks}t warning` : ""}</small></span>
                </button>
              ))}</div>
            </section>
          )}
          {boss && (
            <section className="cys-panel cys-glass">
              <div className="cys-ph"><span className="cys-eyebrow">Spawn and loot</span></div>
              <div className="dz-body" style={{ display: "grid", gap: 6 }}>
                <div className="dz-flow">{boss.spawn?.command !== false && <span className="dz-achip"><DI n="terminal" /><code>boss spawn</code></span>}{boss.spawn?.item && <span className="dz-achip"><Ico r={icon(boss.spawn.item)} size={16} /><code>{boss.spawn.item}</code></span>}</div>
                <div className="dz-flow">{(boss.drops?.items ?? []).map((x, i) => <span key={i} className="dz-rwc"><Ico r={icon(x.item)} size={14} />{bare(x.item)} ×{x.count} · {Math.round(x.chance * 100)}%</span>)}{boss.drops?.xp ? <span className="dz-rwc"><DI n="sparkle" />{boss.drops.xp} xp</span> : null}</div>
                {boss.drops?.mode === "participants" && <p className="cys-hint" style={{ margin: 0 }}>Each player with at least {Math.round((boss.drops.minDamageShare ?? 0.1) * 100)}% of the damage gets their own rolls. Minions drop nothing.</p>}
              </div>
            </section>
          )}
        </div>

        <div className="dz-col">
          <DraftLine d={d} />
          {boss ? <BossCenter d={d} boss={boss} attack={attack} setAtk={setAtk} pAt={pAt} setParam={setParam} icon={icon} issues={rep?.errors ?? []} /> : enc ? <EncounterCenter d={d} enc={enc} pAt={pAt} setParam={setParam} icon={icon} /> : null}
        </div>

        <div className="dz-col">
          {boss && <ArenaPanel boss={boss} attack={attack} />}
          <section className="cys-panel cys-glass dz-rtabs" style={{ flex: 1, minHeight: 0 }}>
            <div className="cys-tabs" role="tablist">
              <button type="button" role="tab" aria-selected={rtab === "params"} className={`cys-tab ${rtab === "params" ? "on" : ""}`} onClick={() => setRtab("params")}><DI n="sliders" />Parameters<span className="n">{params.length}</span></button>
              {boss && <button type="button" role="tab" aria-selected={rtab === "fight"} className={`cys-tab ${rtab === "fight" ? "on" : ""}`} onClick={() => setRtab("fight")}><DI n="play" />Fight</button>}
              <button type="button" role="tab" aria-selected={rtab === "checks"} className={`cys-tab ${rtab === "checks" ? "on" : ""}`} onClick={() => setRtab("checks")}><DI n="check" />Checks{rep?.errors.length ? <span className="n" style={{ color: "var(--bad)" }}>{rep.errors.length}</span> : rep?.warnings.length ? <span className="n">{rep.warnings.length}</span> : null}</button>
            </div>
            {rtab === "params" && <ParamsList d={d} params={params} strip={`${sel.kind === "boss" ? "bosses" : "encounters"}.${sel.id}.`} focus={attack ? `attacks.${attack.id}.` : ""} setParam={setParam} />}
            {rtab === "fight" && boss && <FightPane d={d} boss={boss} />}
            {rtab === "checks" && (
              <div className="dz-pane" style={{ padding: "10px 12px" }}>
                <div className="cys-verdict" style={{ margin: "0 0 8px" }}><span className={`cys-dot ${rep?.ok ? "ok" : "bad"}`} /><div><b>{rep?.ok ? "Valid design" : `${rep?.errors.length ?? 0} errors`}</b><div className="cys-hint">{rep?.ok ? "Fits every cap, the per-attack budget and the plugin-wide limits." : "The design is refused until fixed."}</div></div></div>
                <ul className="dz-issues">
                  {(rep?.errors ?? []).map((e, i) => <IssueRow key={`e${i}`} i={e} tone="err" />)}
                  {(rep?.warnings ?? []).map((e, i) => <IssueRow key={`w${i}`} i={e} tone="warn" />)}
                  {(d.analysis?.gameplayChecks.boss ?? []).filter((c) => c.status === "pass").map((c) => <li key={c.id} className="dz-issue ok"><span className="ic"><DI n="check" /></span><code>{c.id}</code><span className="path">pass</span></li>)}
                  <li className="dz-issue info"><span className="ic"><DI n="minus" /></span><code>real client</code><span className="path">not run</span><span className="m">The boss bar on screen, projectiles hitting players, several players and telegraph timing as seen in game are not verified. A scripted player passed 5 of 5 fight checks on 1.21.11 (bosses part 2 report).</span></li>
                </ul>
              </div>
            )}
            {rtab === "params" && <PendingBar d={d} labels={(id) => id} />}
          </section>
        </div>
      </main>
      <Narrow d={d} boss={boss} enc={enc} />
    </>
  );
}

function BossCenter({ d, boss, attack, setAtk, pAt, setParam, icon, issues }: { d: Designer; boss: BossDesign; attack: Attack | null; setAtk: (a: string) => void; pAt: (rel: string) => Param | undefined; setParam: (p: Param, v: number | string) => void; icon: (r?: string) => Raster; issues: import("@/lib/cyrus/designer/gameplay/spec").GpIssue[] }) {
  const L = d.view!.limits;
  const health = Number(pAt("stats.health")?.value ?? boss.stats.health);
  const field = (rel: string) => { const p = pAt(rel); return p ? <ParamField p={p} was={d.savedParams.get(p.path)?.value} onSet={(v) => setParam(p, v)} /> : null; };
  const phases = boss.phases;
  const bb = attack ? d.analysis?.bossBudgets.find((x) => x.boss === boss.id && x.attack === attack.id) : null;
  const ai = attack ? boss.attacks.indexOf(attack) : -1;
  const atkIssues = issues.filter((e) => e.path.startsWith(`attacks[${ai}]`));
  return (
    <>
      <section className="cys-panel cys-glass cys-hairline" aria-label="Boss">
        <div className="dz-ihead">
          <div className="dz-ibig" title={PLACEHOLDER_NOTE}><Ico r={icon(boss.equipment?.mainHand ?? boss.entity)} size={52} /></div>
          <div style={{ minWidth: 0 }}>
            <div className="dz-iname"><McText t={boss.name} /><span className="cys-tag dim">{bare(boss.entity)}</span>{(boss.immune ?? []).map((x) => <span key={x} className="cys-tag dim">no {x}</span>)}</div>
            <div className="dz-mono" style={{ marginTop: 5 }}>{d.view!.project!.namespace}:{boss.id} · arena {boss.arena.radius} blocks{boss.arena.maxDurationSeconds ? ` · ${Math.round(boss.arena.maxDurationSeconds / 60)} min then ${boss.arena.onTimeout ?? "despawn"}` : ""}</div>
            <div className="dz-flow" style={{ marginTop: 6 }}><span className="dz-sub">Health</span>{field("stats.health")}{pAt("stats.armor") && <><span className="dz-sub">Armor</span>{field("stats.armor")}</>}{pAt("stats.attack_damage") && <><span className="dz-sub">Melee</span>{field("stats.attack_damage")}</>}</div>
          </div>
          <div className="dz-istats" title="The boss bar (vanilla): colour and notches are structure">
            <span>Bar</span><b>{boss.bossBar?.color ?? "purple"}</b><span>Notches</span><b>{(boss.bossBar?.overlay ?? "progress").replace("notched_", "")}</b><span>Max alive</span><b>{boss.spawn?.maxAlive ?? 1}</b>
          </div>
        </div>
      </section>
      <section className="cys-panel cys-glass dz-gwrap" aria-label="Phases">
        <div className="dz-gh"><span className="cys-eyebrow">Phases</span><span className="aname">{phases.length} of {L.maxPhases}</span><span style={{ flex: 1 }} /><span className="dz-mono">health {health} · enter when below the line · never back</span></div>
        <div className="dz-hpbar" role="img" aria-label="Phase thresholds on the health bar">
          {phases.map((ph, i) => { const from = i === 0 ? 1 : Number(pAt(`phases.${ph.id}.below`)?.value ?? ph.below); const to = i + 1 < phases.length ? Number(pAt(`phases.${phases[i + 1].id}.below`)?.value ?? phases[i + 1].below) : 0; return <span key={ph.id} className={`seg ${attack && ph.attacks.some((x) => x.attack === attack.id) ? "on" : ""}`} style={{ left: `${(1 - from) * 100}%`, width: `${Math.max(0, from - to) * 100}%` }}>{ph.name ?? ph.id} · {Math.round(from * 100)}%</span>; })}
        </div>
        <div className="dz-scroll" style={{ flex: 1 }}>
          <div className="dz-phases">
            {phases.map((ph: Phase, i) => (
              <div key={ph.id} className="dz-fcard" style={{ marginBottom: 0 }}>
                <h4><span className="dz-rail" style={{ display: "inline-flex" }}><i>{i + 1}</i></span>{ph.name ?? ph.id}<span className="dz-mono">{ph.id}</span></h4>
                <div className="dz-flow" style={{ marginBottom: 6 }}>
                  {i > 0 && <><span className="dz-sub">below</span>{field(`phases.${ph.id}.below`)}</>}
                  <span className="dz-sub">every</span>{field(`phases.${ph.id}.interval_ticks`)}<span className="dz-sub">ticks</span>
                  {(ph.selfEffects ?? []).map((e) => <span key={e.effect} className="dz-achip"><DI n="shield" /><code>{e.effect}</code></span>)}
                </div>
                <div className="dz-flow">{ph.attacks.map((x) => { const p = pAt(`phases.${ph.id}.weights.${x.attack}`); return (
                  <span key={x.attack} className="dz-achip" style={attack?.id === x.attack ? { borderColor: "var(--accent-line)" } : undefined}>
                    <button type="button" onClick={() => setAtk(x.attack)} style={{ display: "inline-flex", gap: 6, alignItems: "center" }}><DI n="bolt" /><code>{x.attack}</code></button>
                    <span className="dz-sub">weight</span>{p && <ParamField p={p} was={d.savedParams.get(p.path)?.value} onSet={(v) => setParam(p, v)} />}
                  </span>
                ); })}</div>
                {!!ph.onEnter?.length && <div className="dz-flow" style={{ marginTop: 6 }}><span className="dz-sub">On start</span>{ph.onEnter.map((a, j) => <span key={j} className="dz-achip"><DI n={ACT_IC[a.type] ?? "play"} /><code>{a.type}</code> {actSum(a)}</span>)}</div>}
              </div>
            ))}
          </div>
          {attack && (
            <div style={{ padding: "0 14px 14px" }}>
              <div className="dz-cont">
                <div className="dz-blk sel" style={{ cursor: "default" }}>
                  <div className="dz-blk-h"><DI n="bolt" /><span className="ty">{attack.id}</span><span className="lb">{attack.name ?? ""}</span><span className="pth">attacks[{ai}]</span></div>
                  <div className="dz-fl">
                    <span className="dz-f s" title="Structure: who it hits">targets <b>{attack.targets.select}</b></span>
                    {pAt(`attacks.${attack.id}.targets.max`) && <label className="dz-f">max {field(`attacks.${attack.id}.targets.max`)}</label>}
                    {pAt(`attacks.${attack.id}.targets.range`) && <label className="dz-f">range {field(`attacks.${attack.id}.targets.range`)}</label>}
                    <label className="dz-f">cooldown {field(`attacks.${attack.id}.cooldown_ticks`)}</label>
                    {attack.telegraph && <label className="dz-f">warning {field(`attacks.${attack.id}.telegraph.ticks`)}</label>}
                  </div>
                </div>
                <div className="dz-budget dz-meters" style={{ padding: "8px 2px", borderBottom: 0 }}>
                  <Meter label="Actions" used={bb?.actions ?? 0} cap={L.budget.actions} /><Meter label="Entity effects" used={bb?.entities ?? 0} cap={L.budget.entities} /><Meter label="Particles" used={bb?.particles ?? 0} cap={L.budget.particles} /><Meter label="Projectiles" used={bb?.projectiles ?? 0} cap={L.budget.projectiles} /><Meter label="Summons" used={bb?.summons ?? 0} cap={L.summonsPerAttack} />
                </div>
                <div className="dz-kids" style={{ marginTop: 0 }}>
                  {attack.actions.map((a, j) => {
                    const mine = d.params.filter((p) => p.item === boss.id && p.path.startsWith(`bosses.${boss.id}.attacks.${attack.id}.a${j}.`));
                    return (
                      <div key={j} className="dz-blk" style={{ cursor: "default" }}>
                        <div className="dz-blk-h"><DI n={ACT_IC[a.type] ?? "play"} /><span className="ty">{a.type}</span><span className="lb">{actSum(a)}</span><span className="pth">a{j}</span></div>
                        {!!mine.length && <div className="dz-fl">{mine.map((p) => <label key={p.path} className="dz-f">{p.path.split(".").pop()!.replace(/_/g, " ")} <ParamField p={p} was={d.savedParams.get(p.path)?.value} onSet={(v) => setParam(p, v)} /></label>)}</div>}
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          )}
        </div>
        <div className="dz-gval">{atkIssues.length ? <ul className="dz-issues">{atkIssues.slice(0, 5).map((e, i) => <IssueRow key={i} i={e} tone="err" />)}</ul> : issues.length ? <ul className="dz-issues">{issues.slice(0, 4).map((e, i) => <IssueRow key={i} i={e} tone="err" />)}</ul> : <><span className="cys-dot ok" /><span><b>Valid.</b> Every attack fits the per-attack budget; one 10-tick AI timer per mod drives the fight.</span></>}</div>
      </section>
    </>
  );
}

function EncounterCenter({ d, enc, pAt, setParam, icon }: { d: Designer; enc: EncounterDesign; pAt: (rel: string) => Param | undefined; setParam: (p: Param, v: number | string) => void; icon: (r?: string) => Raster }) {
  const params = d.params.filter((p) => p.item === enc.id && p.owner === "encounter");
  return (
    <section className="cys-panel cys-glass cys-hairline" style={{ flex: 1, minHeight: 0, display: "flex", flexDirection: "column" }}>
      <div className="dz-mhead"><span className="cys-eyebrow">Encounter</span><span style={{ font: "600 16px/1 var(--display)" }}>{enc.title}</span><span className="dz-mono">{enc.id}</span><span style={{ flex: 1 }} /><span className="dz-achip"><DI n="arena" />radius <code>{enc.arena.radius}</code></span><span className="dz-achip"><DI n="user" />max alive <code>{enc.maxAlive}</code></span></div>
      <div className="dz-qflow dz-scroll" style={{ flex: 1 }}>
        {enc.waves.map((w, i) => (
          <div key={i} className="dz-fstep"><div className="dz-rail"><i>{i + 1}</i></div>
            <div className="dz-fcard"><h4>Wave {i + 1}<span className="dz-mono">{w.advance === "cleared" ? "next when cleared" : `next after ${w.seconds ?? "?"} s`}</span></h4>
              {w.spawns.map((s, j) => <div key={j} className="dz-obj">{s.boss ? <DI n="skull" /> : <Ico r={icon(s.entity)} size={18} />}<code>{s.boss ? `boss ${s.boss}` : bare(s.entity ?? "")}</code><span className="cnt">×{s.count}</span></div>)}
              {w.message && <p className="cys-hint" style={{ margin: "6px 0 0" }}>“{w.message}”</p>}
            </div></div>
        ))}
        {!!params.length && <div style={{ marginTop: 4 }}><div className="cys-eyebrow" style={{ marginBottom: 4 }}>Settings · config.yml</div>{params.slice(0, 12).map((p) => <div key={p.path} className="dz-prow"><span className="pl">{p.label}</span><span className="pp">{p.path.replace(`encounters.${enc.id}.`, "")}</span><span className="pv"><ParamField p={p} was={d.savedParams.get(p.path)?.value} onSet={(v) => setParam(p, v)} compact /><span className="rg">{rangeText(p)}</span></span></div>)}</div>}
        {pAt("arena.radius") ? null : null}
      </div>
    </section>
  );
}

function ParamsList({ d, params, strip, focus, setParam }: { d: Designer; params: Param[]; strip: string; focus: string; setParam: (p: Param, v: number | string) => void }) {
  const groups = new Map<string, Param[]>();
  for (const p of params) { const rel = p.path.replace(strip, ""); const g = /^(attacks|phases)\.[a-z0-9_]+/.exec(rel)?.[0] ?? "boss"; groups.set(g, [...(groups.get(g) ?? []), p]); }
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => { if (focus) ref.current?.querySelector(`[data-g="${focus.replace(/\.$/, "")}"]`)?.scrollIntoView({ block: "nearest" }); }, [focus]);
  return (
    <div className="dz-pane" ref={ref}>
      <p className="cys-hint" style={{ margin: "10px 6px 2px" }}>Every number and text is a <span className="mono">config.yml</span> setting: changing one never touches Java.</p>
      {[...groups.entries()].map(([g, list]) => (
        <div key={g} data-g={g}>
          <div className="dz-pgrp">{g === "boss" ? "Boss" : g.replace(".", " ")}<span className="cys-tag dim">{list.length}</span></div>
          {list.map((p) => { const was = d.savedParams.get(p.path)?.value; const chg = was !== undefined && String(was) !== String(p.value); return (
            <div key={p.path} className={`dz-prow ${focus && p.path.replace(strip, "").startsWith(focus) ? "hl" : ""}`}>
              <span className="pl">{p.label.replace(/^(attack|phase) [a-z0-9_]+ /, "").replace(/^./, (c) => c.toUpperCase())}</span>
              <span className="pp" title={p.path}>{p.path.replace(strip, "")}</span>
              <span className="pv"><ParamField p={p} was={was} onSet={(v) => setParam(p, v)} compact /><span className="rg">{chg && <><span className="was">{String(was)}</span> · </>}{rangeText(p)}</span></span>
            </div>
          ); })}
        </div>
      ))}
    </div>
  );
}

function ArenaPanel({ boss, attack }: { boss: BossDesign; attack: Attack | null }) {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const cv = ref.current; if (!cv) return;
    const draw = () => {
      const b = cv.getBoundingClientRect(), dpr = Math.min(2, window.devicePixelRatio || 1);
      cv.width = b.width * dpr; cv.height = b.height * dpr;
      const c = cv.getContext("2d")!; c.setTransform(dpr, 0, 0, dpr, 0, 0);
      const cs = getComputedStyle(cv); const v = (n: string) => cs.getPropertyValue(n).trim() || "#888";
      const W = b.width, H = b.height, cx = W / 2, cy = H / 2, R = Math.min(W, H) / 2 - 12, s = R / boss.arena.radius;
      c.strokeStyle = v("--line-3"); c.setLineDash([4, 4]); c.beginPath(); c.arc(cx, cy, R, 0, 7); c.stroke(); c.setLineDash([]);
      if (attack && attack.targets.select !== "self") { c.fillStyle = v("--accent"); c.globalAlpha = 0.14; c.beginPath(); c.arc(cx, cy, Math.min(R, attack.targets.range * s), 0, 7); c.fill(); c.globalAlpha = 1; }
      c.fillStyle = v("--bad"); c.beginPath(); c.arc(cx, cy, 5, 0, 7); c.fill();
      [[3, 0], [5, 2]].forEach(([x, z], i) => { c.fillStyle = i === 0 ? v("--cyan") : v("--muted"); c.beginPath(); c.arc(cx + x * s, cy + z * s, 3.5, 0, 7); c.fill(); });
      c.fillStyle = v("--muted"); c.font = "500 10px ui-monospace, monospace"; c.fillText(`${boss.arena.radius} blocks`, cx + R * 0.72, cy - R * 0.72);
    };
    draw(); const ro = new ResizeObserver(draw); ro.observe(cv); return () => ro.disconnect();
  }, [boss, attack]);
  return (
    <section className="cys-panel cys-glass cys-hairline">
      <div className="cys-ph"><span className="cys-eyebrow">Arena</span><span className="cys-tag dim">top-down, to scale</span></div>
      <div className="dz-arena"><canvas ref={ref} role="img" aria-label={`Arena radius ${boss.arena.radius} blocks${attack ? `, ${attack.id} range ${attack.targets.range}` : ""}`} /></div>
      <p className="cys-hint" style={{ margin: "8px 14px 12px" }}>Red: the boss at its spawn point; cyan: you in the fight simulator. {attack && attack.targets.select !== "self" ? `Shaded: ${attack.id} reaches ${attack.targets.range} blocks.` : "Players inside the circle are participants."}</p>
    </section>
  );
}

function FightPane({ d, boss }: { d: Designer; boss: BossDesign }) {
  const [steps, setSteps] = useState<BossStep[]>([]);
  const [res, setRes] = useState<BossSimResult | null>(null);
  const [err, setErr] = useState<string | null>(null);
  useEffect(() => { setSteps([]); }, [boss.id]);
  useEffect(() => {
    if (!d.pid) return;
    const t = window.setTimeout(() => { designerApi.simBoss(d.pid!, d.files, boss.id, steps).then((r) => { setRes(r.result); setErr(null); }).catch((e) => setErr((e as Error).message)); }, 200);
    return () => window.clearTimeout(t);
  }, [d.pid, d.files, boss.id, steps]);
  const add = (s: BossStep) => setSteps([...steps, s]);
  return (
    <div className="dz-pane" style={{ display: "flex", flexDirection: "column" }}>
      <div className="dz-simbtns">
        <button type="button" className="cys-btn xs" onClick={() => add({ k: "hit", pct: 10 })}><DI n="sword" />Hit 10%</button>
        <button type="button" className="cys-btn xs" onClick={() => add({ k: "hit", pct: 25 })}><DI n="sword" />Hit 25%</button>
        <button type="button" className="cys-btn xs" onClick={() => add({ k: "wait", seconds: 5 })}><DI n="clock" />+5 s</button>
        <button type="button" className="cys-btn xs" onClick={() => add({ k: "join" })}><DI n="user" />2nd player</button>
        <button type="button" className="cys-btn xs" onClick={() => add({ k: "leave" })}><DI n="arrowR" />Leave arena</button>
        <button type="button" className="cys-btn xs ghost" style={{ marginLeft: "auto" }} disabled={!steps.length} onClick={() => setSteps([])}><DI n="rollback" />Reset</button>
      </div>
      {err ? <div className="dz-note warn" style={{ margin: "0 4px" }}><DI n="warn" /><span>{err}</span></div> : res && (
        <>
          <div className="dz-qstate"><b>{boss.name.text}</b><span className={`cys-tag ${res.ended === "defeated" ? "ok" : res.ended ? "warn" : "acc"}`}>{res.ended ?? (res.enraged ? "enraged" : `phase ${res.phase + 1}`)}</span><small>{res.health} / {res.max} health · {res.participants} in the arena · t {res.t} ({Math.round(res.t / 20)} s)</small><div className="dz-pbar"><i style={{ width: `${(res.health / Math.max(1, res.max)) * 100}%` }} /></div></div>
          <ul className="dz-slog">{[...res.log].reverse().slice(0, 40).map((l, i) => <li key={i} className={l.kind === "attack" || l.kind === "phase" ? "" : l.kind === "enrage" ? "blocked" : "fx"}><i>{l.t}</i><span>{l.text}</span></li>)}</ul>
          {!!res.drops.length && <div className="dz-note" style={{ marginTop: 8 }}><DI n="gift" /><span>{res.drops.map((x) => `${x.player}: ${x.items.join(", ") || "nothing rolled"}`).join(" · ")}</span></div>}
        </>
      )}
      <p className="cys-hint" style={{ margin: "8px 6px 12px" }}>The reference fight simulator: phases, attack choice, cooldowns, summons, despawn and loot share. No pathfinding, physics or client.</p>
    </div>
  );
}

function Narrow({ d, boss, enc }: { d: Designer; boss: BossDesign | null; enc: EncounterDesign | null }) {
  const rep = d.analysis?.files.find((f) => f.id === (boss?.id ?? enc?.id));
  return (
    <main className="dz-narrow" aria-label="Boss review">
      <section className="n-card cys-glass">
        <div className="n-h"><div className="dz-thumb" style={{ width: 48, height: 48 }}><DI n={boss ? "skull" : "arena"} /></div><div><h1>{boss ? <McText t={boss.name} /> : enc?.title}</h1><p>{boss ? `${bare(boss.entity)} · ${boss.stats.health} health · ${boss.phases.length} phases · ${boss.attacks.length} attacks` : `${enc?.waves.length ?? 0} waves`}</p></div><span className={`cys-tag ${rep?.ok ? "ok" : "bad"}`} style={{ marginLeft: "auto" }}>{rep?.ok ? "valid" : "errors"}</span></div>
        {boss && <div className="n-sec"><span className="cys-eyebrow">Phases</span>{boss.phases.map((p, i) => <p key={p.id}><b>{p.name ?? p.id}.</b> {i === 0 ? "From full health" : `Below ${Math.round(p.below * 100)}%`}: {p.attacks.map((x) => x.attack).join(", ")} every {Math.round(p.intervalTicks / 20 * 10) / 10} s.</p>)}</div>}
        <div className="n-sec"><span className="cys-eyebrow">Waiting for approval</span>{d.changed.length ? <p>{d.changed.join(", ")} changed (autosaved draft).</p> : <p className="cys-hint" style={{ margin: 0 }}>Nothing waiting. Edit on a larger screen.</p>}</div>
        <div className="n-note"><DI n="info" /><span>Validated and simulated. The boss bar, projectiles and several players are not verified in a real client.</span></div>
        {STUDIO_DEFAULTS.mobile === "review_and_approve" && d.changed.length > 0 && <div className="n-act"><button type="button" className="cys-btn" onClick={() => void d.discard()}>Reject</button><button type="button" className="cys-btn primary" disabled={!d.analysis?.ok || d.saving} onClick={() => void d.save()}><DI n="check" />Approve revision</button></div>}
      </section>
    </main>
  );
}

export type { DesignFile };

toolu_01XHWtejSqEPBic4doy8xtB3.content:
"use client";
// Cyrus BOSS + ENCOUNTER DESIGNER (r27), full page. There is no v2 mockup for this screen: it reuses the Item
// Designer's anatomy and tokens (left = the mod's bosses and encounters, the selected boss's attacks, spawn and drops;
// centre = the boss header with its boss bar, the phase ladder on the health bar (thresholds, intervals, attack
// weights, phase start actions) and the selected attack with its per-attack budget; right = the arena and the
// Parameters / Fight / Checks tabs). Every number is a config.yml value (Param.ptr into the design); the fight runs the
// reference simulator (lib/cyrus/designer/boss/simulate.ts). Phones get the read-only summary + approve / reject.
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { Param } from "@/lib/cyrus/designer/compile";
import type { Attack, BossAction, BossDesign, EncounterDesign, Phase } from "@/lib/cyrus/designer/boss/spec";
import { fileKind, setParamValue, type DesignFile } from "@/lib/cyrus/designer/studio/edit";
import type { Raster } from "@/lib/cyrus/textures/render";
import { STUDIO_DEFAULTS } from "@/lib/cyrus/studios/access";
import { useToast, type StudioMod } from "../studios/StudioShell";
import { designerApi, type BossSimResult, type BossStep } from "./api";
import { DesignerContext, DesignerShell, DraftLine, Failed, Ico, IssueRow, Loading, McText, Meter, NoDesigns, ParamField, PendingBar, rangeText, useDesigner, useIcon, type Designer } from "./shared";
import { PLACEHOLDER_NOTE } from "./pixel-icons";
import { DI } from "./icons";

type Sel = { kind: "boss" | "encounter"; id: string };
const bare = (s: string) => String(s ?? "").replace(/^minecraft:/, "");
const ACT_IC: Record<string, string> = { damage: "sword", knockback: "target", pull: "target", potion_effect: "flask", launch_projectile: "target", spawn_particles: "sparkle", play_sound: "volume", send_message: "note", actionbar: "note", title: "note", leap: "arrowR", summon: "user", heal_self: "heart", self_effect: "shield", delayed: "clock" };
const actSum = (a: BossAction): string => {
  switch (a.type) {
    case "damage": return `${a.amount} per target`;
    case "knockback": case "pull": case "leap": return `strength ${a.strength}`;
    case "potion_effect": case "self_effect": return `${a.effect} ${Math.round(a.durationTicks / 20)} s`;
    case "launch_projectile": return `${a.kind.replace("_", " ")}${a.damage ? ` +${a.damage}` : ""}`;
    case "spawn_particles": return `${a.particle} ×${a.count} at ${a.at ?? "boss"}`;
    case "play_sound": return bare(a.sound).split(".").slice(-2).join(".");
    case "send_message": case "actionbar": return `“${a.text}” to ${a.to ?? "target"}`;
    case "title": return `“${a.title}” to ${a.to ?? "target"}`;
    case "summon": return `${a.count} × ${bare(a.entity)}`;
    case "heal_self": return `${a.amount} health`;
    case "delayed": return `after ${a.delayTicks} ticks: ${a.actions.length} actions`;
  }
};

export function BossDesigner({ mod, initialBoss }: { mod: StudioMod; initialBoss: string | null }) {
  return <DesignerShell mod={mod} tab="bosses" current="Boss Designer" showBosses><Body mod={mod} initialBoss={initialBoss} /></DesignerShell>;
}

function Body({ mod, initialBoss }: { mod: StudioMod; initialBoss: string | null }) {
  const d = useDesigner(mod);
  const bosses = useMemo(() => d.files.filter((f) => fileKind(f) === "boss") as unknown as BossDesign[], [d.files]);
  const encs = useMemo(() => d.files.filter((f) => fileKind(f) === "encounter") as unknown as EncounterDesign[], [d.files]);
  const [sel, setSel] = useState<Sel | null>(initialBoss ? { kind: "boss", id: initialBoss } : null);
  useEffect(() => {
    if (sel && (sel.kind === "boss" ? bosses : encs).some((x) => x.id === sel.id)) return;
    if (bosses.length) setSel({ kind: "boss", id: bosses[0].id }); else if (encs.length) setSel({ kind: "encounter", id: encs[0].id });
  }, [bosses, encs, sel]);
  if (d.err) return <Failed msg={d.err} />;
  if (!d.view) return <Loading what="this mod's bosses" />;
  if (!d.view.project || (!bosses.length && !encs.length)) return <NoDesigns mod={mod} what="bosses or encounters" />;
  if (!sel) return <Loading what="this mod's bosses" />;
  return <DesignerContext d={d}><Workspace d={d} bosses={bosses} encs={encs} sel={sel} setSel={setSel} /></DesignerContext>;
}

function Workspace({ d, bosses, encs, sel, setSel }: { d: Designer; bosses: BossDesign[]; encs: EncounterDesign[]; sel: Sel; setSel: (s: Sel) => void }) {
  const toast = useToast();
  const icon = useIcon(d.textures);
