function ParamsList({ d, params, strip, focus, setParam }: { d: Designer; params: Param[]; strip: string; focus: string; setParam: (p: Param, v: number | string) => void }) {
  const groups = new Map<string, Param[]>();
  for (const p of params) { const rel = p.path.replace(strip, ""); const g = /^(attacks|phases)\.[a-z0-9_]+/.exec(rel)?.[0] ?? "boss"; groups.set(g, [...(groups.get(g) ?? []), p]); }
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => { if (focus) ref.current?.querySelector(`[data-g="${focus.replace(/\.$/, "")}"]`)?.scrollIntoView({ block: "nearest" }); }, [focus]);
  return (
    <div className="dz-pane" ref={ref}>
      <p className="cys-hint" style={{ margin: "10px 6px 2px" }}>Every number and text is a <span className="mono">config.yml</span> setting: changing one never touches Java.</p>
      {[...groups.entries()].map(([g, list]) => (
        <div key={g} data-g={g}>
          <div className="dz-pgrp">{g === "boss" ? "Boss" : g.replace(".", " ")}<span className="cys-tag dim">{list.length}</span></div>
          {list.map((p) => { const was = d.savedParams.get(p.path)?.value; const chg = was !== undefined && String(was) !== String(p.value); return (
            <div key={p.path} className={`dz-prow ${focus && p.path.replace(strip, "").startsWith(focus) ? "hl" : ""}`}>
              <span className="pl">{p.label.replace(/^(attack|phase) [a-z0-9_]+ /, "").replace(/^./, (c) => c.toUpperCase())}</span>
              <span className="pp" title={p.path}>{p.path.replace(strip, "")}</span>
              <span className="pv"><ParamField p={p} was={was} onSet={(v) => setParam(p, v)} compact /><span className="rg">{chg && <><span className="was">{String(was)}</span> · </>}{rangeText(p)}</span></span>
            </div>
          ); })}
        </div>
      ))}
    </div>
  );
}

function ArenaPanel({ boss, attack }: { boss: BossDesign; attack: Attack | null }) {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const cv = ref.current; if (!cv) return;
    const draw = () => {
      const b = cv.getBoundingClientRect(), dpr = Math.min(2, window.devicePixelRatio || 1);
      cv.width = b.width * dpr; cv.height = b.height * dpr;
      const c = cv.getContext("2d")!; c.setTransform(dpr, 0, 0, dpr, 0, 0);
      const cs = getComputedStyle(cv); const v = (n: string) => cs.getPropertyValue(n).trim() || "#888";
      const W = b.width, H = b.height, cx = W / 2, cy = H / 2, R = Math.min(W, H) / 2 - 12, s = R / boss.arena.radius;
      c.strokeStyle = v("--line-3"); c.setLineDash([4, 4]); c.beginPath(); c.arc(cx, cy, R, 0, 7); c.stroke(); c.setLineDash([]);
      if (attack && attack.targets.select !== "self") { c.fillStyle = v("--accent"); c.globalAlpha = 0.14; c.beginPath(); c.arc(cx, cy, Math.min(R, attack.targets.range * s), 0, 7); c.fill(); c.globalAlpha = 1; }
      c.fillStyle = v("--bad"); c.beginPath(); c.arc(cx, cy, 5, 0, 7); c.fill();
      [[3, 0], [5, 2]].forEach(([x, z], i) => { c.fillStyle = i === 0 ? v("--cyan") : v("--muted"); c.beginPath(); c.arc(cx + x * s, cy + z * s, 3.5, 0, 7); c.fill(); });
      c.fillStyle = v("--muted"); c.font = "500 10px ui-monospace, monospace"; c.fillText(`${boss.arena.radius} blocks`, cx + R * 0.72, cy - R * 0.72);
    };
    draw(); const ro = new ResizeObserver(draw); ro.observe(cv); return () => ro.disconnect();
  }, [boss, attack]);
  return (
    <section className="cys-panel cys-glass cys-hairline">
      <div className="cys-ph"><span className="cys-eyebrow">Arena</span><span className="cys-tag dim">top-down, to scale</span></div>
      <div className="dz-arena"><canvas ref={ref} role="img" aria-label={`Arena radius ${boss.arena.radius} blocks${attack ? `, ${attack.id} range ${attack.targets.range}` : ""}`} /></div>
      <p className="cys-hint" style={{ margin: "8px 14px 12px" }}>Red: the boss at its spawn point; cyan: you in the fight simulator. {attack && attack.targets.select !== "self" ? `Shaded: ${attack.id} reaches ${attack.targets.range} blocks.` : "Players inside the circle are participants."}</p>
    </section>
  );
}

function FightPane({ d, boss }: { d: Designer; boss: BossDesign }) {
  const [steps, setSteps] = useState<BossStep[]>([]);
  const [res, setRes] = useState<BossSimResult | null>(null);
  const [err, setErr] = useState<string | null>(null);
  useEffect(() => { setSteps([]); }, [boss.id]);
  useEffect(() => {
    if (!d.pid) return;
    const t = window.setTimeout(() => { designerApi.simBoss(d.pid!, d.files, boss.id, steps).then((r) => { setRes(r.result); setErr(null); }).catch((e) => setErr((e as Error).message)); }, 200);
    return () => window.clearTimeout(t);
  }, [d.pid, d.files, boss.id, steps]);
  const add = (s: BossStep) => setSteps([...steps, s]);
  return (
    <div className="dz-pane" style={{ display: "flex", flexDirection: "column" }}>
      <div className="dz-simbtns">
        <button type="button" className="cys-btn xs" onClick={() => add({ k: "hit", pct: 10 })}><DI n="sword" />Hit 10%</button>
        <button type="button" className="cys-btn xs" onClick={() => add({ k: "hit", pct: 25 })}><DI n="sword" />Hit 25%</button>
        <button type="button" className="cys-btn xs" onClick={() => add({ k: "wait", seconds: 5 })}><DI n="clock" />+5 s</button>
        <button type="button" className="cys-btn xs" onClick={() => add({ k: "join" })}><DI n="user" />2nd player</button>
        <button type="button" className="cys-btn xs" onClick={() => add({ k: "leave" })}><DI n="arrowR" />Leave arena</button>
        <button type="button" className="cys-btn xs ghost" style={{ marginLeft: "auto" }} disabled={!steps.length} onClick={() => setSteps([])}><DI n="rollback" />Reset</button>
      </div>
      {err ? <div className="dz-note warn" style={{ margin: "0 4px" }}><DI n="warn" /><span>{err}</span></div> : res && (
        <>
          <div className="dz-qstate"><b>{boss.name.text}</b><span className={`cys-tag ${res.ended === "defeated" ? "ok" : res.ended ? "warn" : "acc"}`}>{res.ended ?? (res.enraged ? "enraged" : `phase ${res.phase + 1}`)}</span><small>{res.health} / {res.max} health · {res.participants} in the arena · t {res.t} ({Math.round(res.t / 20)} s)</small><div className="dz-pbar"><i style={{ width: `${(res.health / Math.max(1, res.max)) * 100}%` }} /></div></div>
          <ul className="dz-slog">{[...res.log].reverse().slice(0, 40).map((l, i) => <li key={i} className={l.kind === "attack" || l.kind === "phase" ? "" : l.kind === "enrage" ? "blocked" : "fx"}><i>{l.t}</i><span>{l.text}</span></li>)}</ul>
          {!!res.drops.length && <div className="dz-note" style={{ marginTop: 8 }}><DI n="gift" /><span>{res.drops.map((x) => `${x.player}: ${x.items.join(", ") || "nothing rolled"}`).join(" · ")}</span></div>}
        </>
      )}
      <p className="cys-hint" style={{ margin: "8px 6px 12px" }}>The reference fight simulator: phases, attack choice, cooldowns, summons, despawn and loot share. No pathfinding, physics or client.</p>
    </div>
  );
}

function Narrow({ d, boss, enc }: { d: Designer; boss: BossDesign | null; enc: EncounterDesign | null }) {
  const rep = d.analysis?.files.find((f) => f.id === (boss?.id ?? enc?.id));
  return (
    <main className="dz-narrow" aria-label="Boss review">
      <section className="n-card cys-glass">
        <div className="n-h"><div className="dz-thumb" style={{ width: 48, height: 48 }}><DI n={boss ? "skull" : "arena"} /></div><div><h1>{boss ? <McText t={boss.name} /> : enc?.title}</h1><p>{boss ? `${bare(boss.entity)} · ${boss.stats.health} health · ${boss.phases.length} phases · ${boss.attacks.length} attacks` : `${enc?.waves.length ?? 0} waves`}</p></div><span className={`cys-tag ${rep?.ok ? "ok" : "bad"}`} style={{ marginLeft: "auto" }}>{rep?.ok ? "valid" : "errors"}</span></div>
        {boss && <div className="n-sec"><span className="cys-eyebrow">Phases</span>{boss.phases.map((p, i) => <p key={p.id}><b>{p.name ?? p.id}.</b> {i === 0 ? "From full health" : `Below ${Math.round(p.below * 100)}%`}: {p.attacks.map((x) => x.attack).join(", ")} every {Math.round(p.intervalTicks / 20 * 10) / 10} s.</p>)}</div>}
        <div className="n-sec"><span className="cys-eyebrow">Waiting for approval</span>{d.changed.length ? <p>{d.changed.join(", ")} changed (autosaved draft).</p> : <p className="cys-hint" style={{ margin: 0 }}>Nothing waiting. Edit on a larger screen.</p>}</div>
        <div className="n-note"><DI n="info" /><span>Validated and simulated. The boss bar, projectiles and several players are not verified in a real client.</span></div>
        {STUDIO_DEFAULTS.mobile === "review_and_approve" && d.changed.length > 0 && <div className="n-act"><button type="button" className="cys-btn" onClick={() => void d.discard()}>Reject</button><button type="button" className="cys-btn primary" disabled={!d.analysis?.ok || d.saving} onClick={() => void d.save()}><DI n="check" />Approve revision</button></div>}
      </section>
    </main>
  );
}

