export const str = (p: ParamValues, k: string) => p[k] as string;
/** Round to 1e-3 (preset numbers stay readable in JSON). */
export const q3 = (v: number) => { const x = Math.round(v * 1000) / 1000; return Object.is(x, -0) ? 0 : x; };
