input.content:
"use client";
// Cyrus MOTION panel (r27) in the studio shell (Texture / Sound / Model / Motion). Layout from the v4 mockups
// (cyrus-designs/v4-motion/motion.html + presets.html, not yet reviewed by the owner). Everything on screen comes from
// the real motion core, run in the browser: the design's MotionSpec (a preset built with its knobs, or the inline spec),
// the state machine run with the scripted inputs (simulate), the software preview renderer (renderFrame) and the
// timeline drawn where the tracks played. Minecraft fit (caps, what the lowering leaves out) comes from the server's
// check of the same design. Edits: the preset knobs (saved as a revision through the designer pipeline); keyframes of a
// preset come from its knobs, so they are read-only here. Phones: read-only preview + approve / reject.
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import Link from "next/link";
import { MOTION_PRESETS, presetById, resolveParams, type ParamDef } from "@/lib/cyrus/motion/presets";
import { eventLog, simulate, type SimFrame } from "@/lib/cyrus/motion/simulate";
import { autoCamera, renderFrame, type ThemeName } from "@/lib/cyrus/motion/preview";
import type { MotionSpec } from "@/lib/cyrus/motion/spec";
import type { MotionDesign } from "@/lib/cyrus/designer/motion/spec";
import { fileKind, type DesignFile } from "@/lib/cyrus/designer/studio/edit";
import { STUDIO_DEFAULTS } from "@/lib/cyrus/studios/access";
import { StudioShell, studioHref, useToast, type StudioMod } from "../studios/StudioShell";
import { DesignerContext, DraftLine, Failed, Loading, Meter, PendingBar, useDesigner, type Designer } from "./shared";
import { DI } from "./icons";
import { SI } from "../studios/icons";
import "./designers.css";

const MOTION_ICON = '<path d="M3 17c3 0 4-10 7-10s4 10 7 10 3-6 4-6"/>';
function MI() { return <svg className="cys-i" viewBox="0 0 24 24" aria-hidden dangerouslySetInnerHTML={{ __html: MOTION_ICON }} />; }

type Input = { tick: number; event: string };
const TICKS = 120;

/** The MotionSpec a design stands for, in the browser (the preset built with its knobs, or the inline spec). */
export function specOf(d: MotionDesign): { spec: MotionSpec | null; preset: string | null; issues: string[] } {
  const m = d.motion as { preset?: string; params?: Record<string, unknown> } | null;
  if (m && typeof m === "object" && typeof m.preset === "string") {
    const p = presetById(m.preset);
    if (!p) return { spec: null, preset: m.preset, issues: [`no preset ${m.preset}`] };
    try { const b = p.build(m.params ?? {}); return { spec: { ...b.spec, id: d.id }, preset: p.id, issues: b.issues.map((i) => i.message) }; } catch (e) { return { spec: null, preset: p.id, issues: [(e as Error).message] }; }
  }
  return m && typeof m === "object" && "rig" in (m as object) ? { spec: m as unknown as MotionSpec, preset: null, issues: [] } : { spec: null, preset: null, issues: ["no motion"] };
}

export function MotionStudio({ mod, initialMotion, initialView, showModel }: { mod: StudioMod; initialMotion: string | null; initialView: "motion" | "presets"; showModel: boolean }) {
  const [view, setView] = useState<"motion" | "presets">(initialView);
  const seg = (
    <div className="cys-seg cys-soft hide-n" aria-label="Studio">
      <Link href={studioHref(mod, "texture")}><SI n="image" />Texture</Link>
      <Link href={studioHref(mod, "sound")}><SI n="wave" />Sound</Link>
      {showModel && <Link href={studioHref(mod, "model")}><SI n="cube" />Model</Link>}
      <button type="button" className="on" aria-current="page" onClick={() => setView("motion")}><MI />Motion</button>
    </div>
  );
  return (
    <StudioShell mod={mod} current={view === "presets" ? "Presets" : "Motion"} studio={null} seg={seg} icon={<MI />} kind="motion">
      <Body mod={mod} initialMotion={initialMotion} view={view} setView={setView} />
    </StudioShell>
  );
}

function Body({ mod, initialMotion, view, setView }: { mod: StudioMod; initialMotion: string | null; view: "motion" | "presets"; setView: (v: "motion" | "presets") => void }) {
  const d = useDesigner(mod);
  const motions = useMemo(() => d.files.filter((f) => fileKind(f) === "motion") as unknown as MotionDesign[], [d.files]);
  const [cur, setCur] = useState<string | null>(initialMotion);
  useEffect(() => { if (motions.length && (!cur || !motions.some((m) => m.id === cur))) setCur(motions[0].id); }, [motions, cur]);
  if (d.err) return <Failed msg={d.err} />;
  if (!d.view) return <Loading what="this mod's motions" />;
  const m = motions.find((x) => x.id === cur) ?? null;
  return (
    <DesignerContext d={d}>
      {view === "presets" || !m ? <Presets d={d} motion={m} onBack={m ? () => setView("motion") : null} /> : <Workspace d={d} motions={motions} m={m} setCur={setCur} openPresets={() => setView("presets")} />}
      {m && <Narrow d={d} m={m} />}
    </DesignerContext>
  );
}

function useTheme(): ThemeName {
  const [t, setT] = useState<ThemeName>("dark");
  useEffect(() => {
    const read = () => setT(document.documentElement.getAttribute("data-theme") === "light" ? "light" : "dark");
    read();
    const o = new MutationObserver(read); o.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
    return () => o.disconnect();
  }, []);
  return t;
}

function Frame({ spec, frame, theme, className, label }: { spec: MotionSpec; frame: SimFrame | undefined; theme: ThemeName; className?: string; label: string }) {
  const ref = useRef<HTMLCanvasElement>(null);
  const cam = useMemo(() => autoCamera(spec, { yaw: 58, pitch: 16, pad: 1.05 }), [spec]);
  useEffect(() => {
    const cv = ref.current; if (!cv || !frame?.pose) return;
    const b = cv.getBoundingClientRect();
    const w = Math.max(160, Math.min(720, Math.round(b.width))), h = Math.max(100, Math.min(420, Math.round(b.height)));
    const r = renderFrame(spec, frame.pose, frame.particles ?? [], { w, h, camera: cam, theme });
    cv.width = r.w; cv.height = r.h;
    cv.getContext("2d")!.putImageData(new ImageData(new Uint8ClampedArray(r.px), r.w, r.h), 0, 0);
  }, [spec, frame, theme, cam]);
  return <canvas ref={ref} className={className} role="img" aria-label={label} />;
}

function Workspace({ d, motions, m, setCur, openPresets }: { d: Designer; motions: MotionDesign[]; m: MotionDesign; setCur: (id: string) => void; openPresets: () => void }) {
  const theme = useTheme();
  const toast = useToast();
  const { spec, preset } = useMemo(() => specOf(m), [m]);
  const machine = spec?.machines?.[0] ?? null;
  const [inputs, setInputs] = useState<Input[]>([]);
  const [mode, setMode] = useState<"sim" | "clip">("sim");
  const [clip, setClip] = useState<string>("");
  const [tick, setTick] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [speed, setSpeed] = useState(1);
  const [rtab, setRtab] = useState<"knobs" | "export" | "checks">("knobs");
  useEffect(() => { setInputs([]); setTick(0); setClip(spec?.clips[0]?.name ?? ""); setMode(spec?.machines?.length ? "sim" : "clip"); }, [m.id]); // eslint-disable-line react-hooks/exhaustive-deps
  const ticks = mode === "clip" ? Math.max(1, spec?.clips.find((c) => c.name === clip)?.length ?? 40) + 1 : Math.max(TICKS, (inputs.at(-1)?.tick ?? 0) + 60);
  const sim = useMemo(() => { if (!spec) return null; try { return simulate(spec, { ...(mode === "clip" && clip ? { clip } : {}), inputs: mode === "sim" ? inputs : [], ticks, withPose: true, withParticles: true }); } catch (e) { return { frames: [], log: [], error: (e as Error).message } as unknown as ReturnType<typeof simulate>; } }, [spec, mode, clip, inputs, ticks]);
  const frames = sim?.frames ?? [];
  const f = frames[Math.min(tick, frames.length - 1)];
  // playback: the clock steps whole ticks (20 per second x speed); the renderer draws that tick
  useEffect(() => {
    if (!playing) return;
    let last = performance.now(), acc = 0, raf = 0;
    const loop = (now: number) => { acc += ((now - last) / 1000) * 20 * speed; last = now; const n = Math.floor(acc); if (n) { acc -= n; setTick((t) => (t + n >= frames.length ? (mode === "clip" ? 0 : (setPlaying(false), frames.length - 1)) : t + n)); } raf = requestAnimationFrame(loop); };
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, [playing, speed, frames.length, mode]);
  const events = machine ? [...new Set(machine.transitions.map((t) => t.on))] : [];
  const fire = (ev: string) => { const t = Math.max(tick, (inputs.at(-1)?.tick ?? -1) + 1); setInputs([...inputs, { tick: t, event: ev }]); setTick(t); };
  const log = useMemo(() => eventLog(frames), [frames]);
  const rep = d.analysis?.motions.find((x) => x.id === m.id);
  const fileRep = d.analysis?.files.find((x) => x.id === m.id);
  const setKnob = useCallback((name: string, v: number | string) => {
    d.setFiles(d.files.map((x) => { if (x.id !== m.id) return x; const c = structuredClone(x) as unknown as MotionDesign; const mo = c.motion as { preset: string; params?: Record<string, unknown> }; mo.params = { ...(mo.params ?? {}), [name]: v }; return c as unknown as DesignFile; }));
  }, [d, m.id]);
  if (!spec) return <main className="dz-ws mo-ws"><div className="dz-col" style={{ gridColumn: "1 / 4" }}><div className="cys-empty"><DI n="warn" /><p>This motion design does not resolve to a motion ({fileRep?.errors[0]?.message ?? "unknown"}).</p></div></div></main>;
  const pdef = preset ? presetById(preset) : null;
  const params = (m.motion as { params?: Record<string, unknown> }).params ?? {};
  const savedM = d.saved.find((x) => x.id === m.id) as unknown as MotionDesign | undefined;
  const savedParams = (savedM?.motion as { params?: Record<string, unknown> } | undefined)?.params ?? {};
  const resolved = pdef ? resolveParams(pdef.params, params).values : {};
  const savedResolved = pdef ? resolveParams(pdef.params, savedParams).values : {};
  return (
    <main className="dz-ws mo-ws" aria-label="Motion">
      <div className="dz-col scroll">
        <section className="cys-panel cys-glass cys-hairline">
          <div className="cys-ph"><span className="cys-eyebrow">Motions</span><span className="n">{motions.length} / 4</span><button type="button" className="cys-ib sm" title="Preset browser" aria-label="Open the preset browser" onClick={openPresets}><SI n="library" /></button></div>
          <div className="dz-body">{motions.map((x) => <button key={x.id} type="button" className={`dz-row ${x.id === m.id ? "on" : ""}`} onClick={() => setCur(x.id)}><span className="dz-thumb plain"><MI /></span><span className="tx"><b>{x.id}</b><small>{(x.motion as { preset?: string }).preset ?? "custom spec"}</small></span></button>)}</div>
        </section>
        <section className="cys-panel cys-glass">
          <div className="cys-ph"><span className="cys-eyebrow">Rig</span><span className="n">{spec.rig.nodes.length} nodes</span></div>
          <ul className="mo-nodes">{spec.rig.nodes.map((n) => { let dep = 0, p = n.parent; while (p && dep < 8) { dep++; p = spec.rig.nodes.find((x) => x.name === p)?.parent ?? null; } return <li key={n.name} style={{ paddingLeft: 8 + dep * 12 }}><SI n={n.kind === "emitter" ? "sparkle" : "cube"} />{n.name}<span className="k">{n.kind}{n.hinge ? ` ${n.hinge.axis} ${n.hinge.min}..${n.hinge.max}` : ""}</span></li>; })}</ul>
        </section>
        {machine && (
          <section className="cys-panel cys-glass">
            <div className="cys-ph"><span className="cys-eyebrow">State machine</span><span className="n">{machine.states.length} states</span></div>
            <div className="mo-states">{machine.states.map((s) => <span key={s.name} className={`mo-state ${f?.state === s.name ? "now" : ""}`}>{s.name}</span>)}</div>
            {f?.vars && <div className="mo-vars">{Object.entries(f.vars).map(([k, v]) => { const def = machine.vars?.find((x) => x.name === k); return <span key={k} className="mo-var">{k} <b>{v}</b>{def ? `/${def.max}` : ""}</span>; })}<span className="mo-var">in state <b>{f.clipTick}</b> ticks</span></div>}
          </section>
        )}
        <section className="cys-panel cys-glass">
          <div className="cys-ph"><span className="cys-eyebrow">Simulate</span><span className="cys-tag dim">scripted</span></div>
          {machine ? <div className="mo-ev">{events.map((e) => <button key={e} type="button" className="cys-btn sm" onClick={() => { setMode("sim"); fire(e); }}><DI n="bolt" />{e}</button>)}<button type="button" className="cys-btn sm" onClick={() => { setInputs([]); setTick(0); }}><DI n="rollback" />Reset</button></div> : <p className="cys-hint" style={{ margin: "0 12px 10px" }}>No state machine: right-click plays the first clip.</p>}
          <div className="mo-log">{log.slice(-40).map((l, i) => <div key={i} className={l.startsWith(`t${f?.tick} `) ? "now" : ""}>{l}</div>)}{!log.length && <div>Fire an event to run the machine.</div>}</div>
        </section>
      </div>

      <div className="dz-col">
        <DraftLine d={d} />
        <div className="mo-bar cys-soft">
          <MI /><b>{m.id}</b>{preset && <span className="cys-tag">{preset}</span>}
          {machine?.vars?.map((v) => <span key={v.name} className="cys-tag dim">{v.name} {v.max}</span>)}
          <span style={{ flex: 1 }} />
          <span className="cys-tag dim" title="The server checks the lowering to Minecraft (display entities)">Minecraft {d.view!.mcVersion}</span>
          <span className="dz-mono">{d.changed.includes(m.id) ? "unsaved" : `saved${d.view!.designs.find((x) => x.id === m.id)?.seq ? ` · r${d.view!.designs.find((x) => x.id === m.id)!.seq}` : ""}`}</span>
        </div>
        <div className="mo-vp">
          <Frame spec={spec} frame={f} theme={theme} label={`${m.id} at tick ${f?.tick ?? 0}${f?.state ? `, state ${f.state}` : ""}`} />
          <span className="hud tl"><span className="cys-dot live" />{f?.state ? <>state <b>{f.state}</b> · </> : null}clip {f?.clip ?? "none"} tick {f?.clipTick ?? 0}</span>
          <span className="hud br"><DI n="info" />Cyrus preview renderer, approximate look</span>
        </div>
        <section className="cys-panel cys-glass mo-tl" aria-label="Timeline">
          <div className="mo-tlh">
            <button type="button" className="cys-ib sm" aria-label="Back one tick" onClick={() => setTick(Math.max(0, tick - 1))}><DI n="chevL" /></button>
            <button type="button" className="mo-play" aria-label={playing ? "Pause" : "Play"} onClick={() => { if (!playing && tick >= frames.length - 1) setTick(0); setPlaying(!playing); }}><SI n={playing ? "pause" : "play"} /></button>
            <button type="button" className="cys-ib sm" aria-label="Forward one tick" onClick={() => setTick(Math.min(frames.length - 1, tick + 1))}><DI n="chevR" /></button>
            <div className="cys-seg sm cys-soft">{[0.25, 0.5, 1].map((s) => <button key={s} type="button" className={speed === s ? "on" : ""} onClick={() => setSpeed(s)}>{s}x</button>)}</div>
            <div className="cys-seg sm cys-soft">{machine && <button type="button" className={mode === "sim" ? "on" : ""} onClick={() => { setMode("sim"); setTick(0); }}><SI n="play" />Simulation</button>}<button type="button" className={mode === "clip" ? "on" : ""} onClick={() => { setMode("clip"); setTick(0); }}><SI n="loop" />Clip</button></div>
            {mode === "clip" && <select className="cys-field" style={{ width: 150, height: 26 }} value={clip} onChange={(e) => { setClip(e.target.value); setTick(0); }} aria-label="Clip">{spec.clips.map((c) => <option key={c.name} value={c.name}>{c.name} · {c.length}t</option>)}</select>}
            <span className="mo-tcode">t <b>{f?.tick ?? 0}</b> · {((f?.tick ?? 0) / 20).toFixed(2)}s · 20 tps</span>
          </div>
          <Timeline spec={spec} frames={frames} tick={tick} setTick={(t) => { setPlaying(false); setTick(t); }} inputs={mode === "sim" ? inputs : []} />
        </section>
      </div>

      <div className="dz-col">
        <section className="cys-panel cys-glass dz-rtabs" style={{ flex: 1, minHeight: 0 }}>
          <div className="cys-tabs" role="tablist">
            <button type="button" role="tab" aria-selected={rtab === "knobs"} className={`cys-tab ${rtab === "knobs" ? "on" : ""}`} onClick={() => setRtab("knobs")}><DI n="sliders" />Knobs{pdef && <span className="n">{pdef.params.length}</span>}</button>
            <button type="button" role="tab" aria-selected={rtab === "export"} className={`cys-tab ${rtab === "export" ? "on" : ""}`} onClick={() => setRtab("export")}><DI n="external" />Export{!!rep?.dropped.length && <span className="n">{rep.dropped.length}</span>}</button>
            <button type="button" role="tab" aria-selected={rtab === "checks"} className={`cys-tab ${rtab === "checks" ? "on" : ""}`} onClick={() => setRtab("checks")}><DI n="check" />Checks</button>
          </div>
          <div className="dz-pane" style={{ padding: 0 }}>
            {rtab === "knobs" && (pdef ? (
              <>
                <p className="cys-hint" style={{ margin: "10px 14px 4px" }}>{pdef.title}: the keyframes come from these knobs, so change a knob rather than a key. Every change is a revision.</p>
                {pdef.params.map((p) => <Knob key={p.name} p={p} v={resolved[p.name]} was={savedResolved[p.name]} onSet={(v) => setKnob(p.name, v)} />)}
                <div style={{ padding: "4px 14px 12px" }}><button type="button" className="cys-btn xs ghost" onClick={() => { d.setFiles(d.files.map((x) => { if (x.id !== m.id) return x; const c = structuredClone(x) as unknown as MotionDesign; (c.motion as { params?: unknown }).params = {}; return c as unknown as DesignFile; })); toast("Knobs back to the preset defaults"); }}><DI n="rollback" />Defaults</button></div>
              </>
            ) : <p className="cys-hint" style={{ margin: "10px 14px" }}>A custom MotionSpec: its keys are edited in Model Studio&apos;s timeline (layer 2). Here you can preview, simulate and check it.</p>)}
            {rtab === "export" && <ExportPane rep={rep} />}
            {rtab === "checks" && (
              <div style={{ padding: "10px 12px" }}>
                <ul className="dz-issues">
                  {(fileRep?.errors ?? []).map((e, i) => <li key={`e${i}`} className="dz-issue err"><span className="ic"><DI n="close" /></span><code>{e.code}</code><span className="path">{e.path}</span><span className="m">{e.message}</span></li>)}
                  {(rep?.issues ?? []).map((e, i) => <li key={`i${i}`} className={`dz-issue ${e.severity === "error" ? "err" : "warn"}`}><span className="ic"><DI n={e.severity === "error" ? "close" : "warn"} /></span><code>{e.code}</code><span className="path">{e.path}</span><span className="m">{e.message}</span></li>)}
                  {rep?.ok && !rep.issues.length && <li className="dz-issue ok"><span className="ic"><DI n="check" /></span><code>minecraft caps</code><span className="path">pass</span></li>}
                  <li className="dz-issue info"><span className="ic"><DI n="minus" /></span><code>real client</code><span className="path">not run</span><span className="m">Interpolation smoothness, the vanilla particle stand-ins and sound timing have not been judged in a real client.</span></li>
                </ul>
              </div>
            )}
          </div>
          <PendingBar d={d} labels={(id) => id} />
        </section>
      </div>
    </main>
  );
}

function Knob({ p, v, was, onSet }: { p: ParamDef; v: number | string | undefined; was: number | string | undefined; onSet: (v: number | string) => void }) {
  const chg = was !== undefined && String(was) !== String(v);
  if (p.type === "number") return (
    <label className="mo-knob"><span>{p.label}{p.unit ? <span className="dz-sub"> {p.unit}</span> : null}</span><b className={chg ? "chg" : ""}>{String(v)}{chg ? <span className="dz-sub" style={{ textDecoration: "line-through", marginLeft: 6 }}>{String(was)}</span> : null}</b>
      <input type="range" min={p.min} max={p.max} step={p.step ?? (p.max - p.min <= 4 ? 0.05 : 1)} value={Number(v)} onChange={(e) => onSet(Number(e.target.value))} aria-label={p.label} /></label>
  );
  if (p.type === "enum") return <div className="mo-knob"><span>{p.label}</span><b className={chg ? "chg" : ""}>{String(v)}</b><div className="cys-seg sm cys-soft">{p.options.map((o) => <button key={o} type="button" className={o === v ? "on" : ""} onClick={() => onSet(o)}>{o}</button>)}</div></div>;
  return <div className="mo-knob"><span>{p.label}</span><b className="dz-mono" style={{ maxWidth: 160, overflow: "hidden", textOverflow: "ellipsis" }} title="Pick sounds in the Sound Studio">{String(v)}</b></div>;
}

function ExportPane({ rep }: { rep: NonNullable<import("./api").Analysis["motions"]>[number] | undefined }) {
  if (!rep) return <p className="cys-hint" style={{ margin: "10px 14px" }}>Checking the Minecraft lowering…</p>;
  const s = rep.stats, c = rep.caps;
  return (
    <>
      <div className="cys-eyebrow" style={{ margin: "12px 14px 8px" }}>Minecraft (display entities)</div>
      {s && <div className="dz-meters" style={{ gridTemplateColumns: "1fr 1fr", padding: "0 14px 12px" }}>
        <Meter label="Entities per prop" used={s.liveEntities} cap={c.liveEntities} /><Meter label="Particles per tick" used={s.particlesPerTick} cap={c.particlesPerTick} />
        <Meter label="Clips" used={s.clips} cap={c.clips} /><Meter label="Keys" used={s.keysTotal} cap={c.keysTotal} />
      </div>}
      {rep.program && <table className="mo-gtable"><tbody><tr><td>Parts</td><td>{rep.program.parts} display entities</td></tr><tr><td>Segments</td><td>{rep.program.segments} interpolation segments ({rep.program.snaps} snaps)</td></tr><tr><td>Cues</td><td>{rep.program.cues} sound / particle cues</td></tr></tbody></table>}
      <div className="cys-eyebrow" style={{ margin: "4px 14px 6px" }}>Left out on Minecraft</div>
      {rep.dropped.length ? <ul className="mo-drops">{rep.dropped.map((x, i) => <li key={i}><DI n="warn" /><span><code className="mono">{x.path}</code> {x.reason}</span></li>)}</ul> : <p className="cys-hint" style={{ margin: "0 14px 12px" }}>Nothing: every track lowers.</p>}
      <div className="dz-note" style={{ margin: "0 14px 14px" }}><DI n="info" /><span>Client smoothness is not verified: Minecraft interpolates linearly between segments, so eases are chained short segments.</span></div>
    </>
  );
}

function Timeline({ spec, frames, tick, setTick, inputs }: { spec: MotionSpec; frames: SimFrame[]; tick: number; setTick: (t: number) => void; inputs: Input[] }) {
  const ref = useRef<HTMLCanvasElement>(null);
  const rows = useMemo(() => {
    const tracks = new Map<string, { label: string; kind: string }>();
    for (const c of spec.clips) for (const t of c.tracks) { const k = t.kind === "transform" ? `${t.node}.${t.channel}` : t.kind === "material" ? `${t.node}.${t.channel}` : t.kind; if (!tracks.has(k)) tracks.set(k, { label: t.kind === "transform" || t.kind === "material" ? k : t.kind === "particle" ? "particles" : t.kind === "sound" ? "sound" : "events", kind: t.kind }); }
    return [...tracks.entries()].sort((a, b) => ["transform", "material", "particle", "sound", "event"].indexOf(a[1].kind) - ["transform", "material", "particle", "sound", "event"].indexOf(b[1].kind)).slice(0, 14);
  }, [spec]);
  useEffect(() => {
    const cv = ref.current; if (!cv) return;
    const draw = () => {
      const W = cv.parentElement!.clientWidth, H = 22 + 18 * (rows.length + 1) + 14, dpr = Math.min(2, window.devicePixelRatio || 1);
      cv.style.height = `${H}px`; cv.width = W * dpr; cv.height = H * dpr;
      const c = cv.getContext("2d")!; c.setTransform(dpr, 0, 0, dpr, 0, 0);
      const cs = getComputedStyle(cv); const v = (n: string) => cs.getPropertyValue(n).trim() || "#888";
      const L = 130, n = Math.max(1, frames.length - 1), x = (t: number) => L + ((W - L - 10) * t) / n;
      c.font = "500 10px ui-monospace, monospace"; c.textBaseline = "middle";
      for (let t = 0; t <= n; t += n > 200 ? 40 : 10) { c.fillStyle = v("--faint"); c.fillText(String(t), x(t) - 4, 10); }
      // state band
      const y0 = 30; c.fillStyle = v("--muted"); c.fillText("state machine", 8, y0);
      let s0 = 0;
      for (let i = 1; i <= frames.length; i++) if (i === frames.length || frames[i].state !== frames[s0].state) { const st = frames[s0].state; if (st) { c.fillStyle = v("--accent"); c.globalAlpha = 0.16 + (st === frames[Math.min(tick, n)]?.state ? 0.14 : 0); c.fillRect(x(s0), y0 - 7, Math.max(1, x(i - 1) - x(s0) + 1), 14); c.globalAlpha = 1; c.fillStyle = v("--ink-2"); if (x(i - 1) - x(s0) > 40) c.fillText(st, x(s0) + 4, y0); } s0 = i; }
      for (const inp of inputs) { c.fillStyle = v("--ink"); c.fillRect(x(inp.tick) - 1, y0 - 9, 2, 4); }
      rows.forEach(([key, r], i) => {
        const y = y0 + 18 * (i + 1);
        c.fillStyle = v("--muted"); c.fillText(r.label.slice(0, 18), 8, y);
        c.strokeStyle = v("--line"); c.beginPath(); c.moveTo(L, y); c.lineTo(W - 10, y); c.stroke();
        frames.forEach((f, ti) => {
          if (!f.clip) return;
          const clip = spec.clips.find((cl) => cl.name === f.clip);
          for (const t of clip?.tracks ?? []) {
            const k = t.kind === "transform" || t.kind === "material" ? `${t.node}.${t.channel}` : t.kind;
            if (k !== key) continue;
            const hitKey = (t.kind === "transform" ? (t.keys ?? []) : t.kind === "material" ? t.keys : []).some((kk) => Math.round(kk.t) === f.clipTick);
            const at = t.kind === "particle" || t.kind === "sound" || t.kind === "event" ? t.at === f.clipTick : false;
            if (hitKey) { c.fillStyle = v("--accent-ink"); c.beginPath(); c.moveTo(x(ti), y - 4); c.lineTo(x(ti) + 4, y); c.lineTo(x(ti), y + 4); c.lineTo(x(ti) - 4, y); c.closePath(); c.fill(); }
            if (at) { c.fillStyle = t.kind === "particle" ? v("--warn") : t.kind === "sound" ? v("--cyan") : v("--accent"); c.fillRect(x(ti) - 3, y - 4, 6, 8); }
            if (t.kind === "transform" && t.wave) { c.fillStyle = v("--accent"); c.globalAlpha = 0.25; c.fillRect(x(ti), y - 2, Math.max(1, x(1) - x(0)), 4); c.globalAlpha = 1; }
          }
        });
      });
      c.strokeStyle = v("--cyan"); c.lineWidth = 1.5; c.beginPath(); c.moveTo(x(tick), 16); c.lineTo(x(tick), H - 4); c.stroke(); c.lineWidth = 1;
    };
    draw(); const ro = new ResizeObserver(draw); ro.observe(cv.parentElement!); return () => ro.disconnect();
  }, [spec, frames, tick, rows, inputs]);
  const scrub = (e: React.PointerEvent<HTMLCanvasElement>) => { const b = e.currentTarget.getBoundingClientRect(); const L = 130; const t = Math.round(((e.clientX - b.left - L) / (b.width - L - 10)) * Math.max(1, frames.length - 1)); setTick(Math.max(0, Math.min(frames.length - 1, t))); };
  return (
    <div className="mo-tlb">
      <canvas ref={ref} role="slider" tabIndex={0} aria-label="Timeline" aria-valuemin={0} aria-valuemax={frames.length - 1} aria-valuenow={tick}
        onPointerDown={(e) => { e.currentTarget.setPointerCapture(e.pointerId); scrub(e); }} onPointerMove={(e) => { if (e.buttons) scrub(e); }}
        onKeyDown={(e) => { if (e.key === "ArrowLeft") setTick(Math.max(0, tick - 1)); if (e.key === "ArrowRight") setTick(Math.min(frames.length - 1, tick + 1)); }} />
    </div>
  );
}

// -------------------------------------------------------------------------------------------- preset browser
function Presets({ d, motion, onBack }: { d: Designer; motion: MotionDesign | null; onBack: (() => void) | null }) {
  const theme = useTheme();
  const toast = useToast();
  const [kind, setKind] = useState<"all" | "motion" | "effect" | "gen">("all");
  const [q, setQ] = useState("");
  const [sel, setSel] = useState<string>(MOTION_PRESETS[1]?.id ?? MOTION_PRESETS[0].id);
  const list = MOTION_PRESETS.filter((p) => (kind === "all" || (kind === "gen" ? p.generator : p.kind === kind && !p.generator)) && (!q.trim() || `${p.title} ${p.summary} ${p.tags.join(" ")}`.toLowerCase().includes(q.toLowerCase())));
  const p = presetById(sel) ?? MOTION_PRESETS[0];
  const fits = (id: string) => d.analysis?.motions.find((x) => (x.id && (d.files.find((f) => f.id === x.id) as unknown as MotionDesign | undefined)?.motion as { preset?: string } | undefined)?.preset === id);
  const use = () => {
    if (!motion) { toast("This mod has no motion design to change. Ask Cyrus for an animated prop first.", true); return; }
    d.setFiles(d.files.map((x) => (x.id !== motion.id ? x : ({ ...(x as unknown as MotionDesign), motion: { preset: p.id, params: {} } } as unknown as DesignFile))));
    toast(`${motion.id} now uses ${p.id} (a structure change; review, then save)`);
    onBack?.();
  };
  return (
    <main className="dz-ws" style={{ gridTemplateColumns: "220px minmax(0, 1fr) 340px" }} aria-label="Preset browser">
      <div className="dz-col">
        <section className="cys-panel cys-glass cys-hairline">
          <div className="cys-ph"><span className="cys-eyebrow">Kind</span></div>
          <div className="dz-body">{([["all", "All", MOTION_PRESETS.length], ["motion", "Motion", MOTION_PRESETS.filter((x) => x.kind === "motion" && !x.generator).length], ["effect", "Effects", MOTION_PRESETS.filter((x) => x.kind === "effect").length], ["gen", "Generators", MOTION_PRESETS.filter((x) => x.generator).length]] as const).map(([k, l, n]) => <button key={k} type="button" className={`dz-row ${kind === k ? "on" : ""}`} onClick={() => setKind(k)}><span className="tx"><b className="sans">{l}</b></span><span className="dz-mono">{n}</span></button>)}</div>
        </section>
        <section className="cys-panel cys-glass"><div className="cys-ph"><span className="cys-eyebrow">How Cyrus uses these</span></div><p className="cys-hint" style={{ margin: "0 14px 14px" }}>Cyrus picks a preset and sets its knobs first, then a generator, and writes a full motion spec only for simple mechanical motion. Plan gating for motion and effects is an open owner decision; keeping, installing and exporting are never gated.</p></section>
        {onBack && <button type="button" className="cys-btn sm" onClick={onBack}><DI n="chevL" />Back to {motion?.id}</button>}
      </div>
      <div className="dz-col">
        <div className="mo-search cys-soft"><SI n="search" /><input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search presets: reload, door, fire, walk…" aria-label="Search presets" /><span className="cys-tag dim">{list.length} presets</span></div>
        <div className="dz-scroll" style={{ flex: 1 }}>
          <div className="mo-grid">{list.map((x) => <PresetCard key={x.id} id={x.id} on={x.id === sel} theme={theme} onClick={() => setSel(x.id)} fit={fits(x.id)?.ok} />)}</div>
        </div>
      </div>
      <div className="dz-col">
        <section className="cys-panel cys-glass cys-hairline" style={{ flex: 1, minHeight: 0, overflow: "auto" }}>
          <div className="cys-ph"><span className="cys-eyebrow">{p.kind}</span><span className="cys-tag dim">{p.id}</span></div>
          <div className="mo-det-poster"><Poster id={p.id} theme={theme} /></div>
          <h2 style={{ margin: "0 14px 4px", font: "600 18px/1.2 var(--display)" }}>{p.title}</h2>
          <p style={{ margin: "0 14px 12px", fontSize: 12.5, lineHeight: 1.5, color: "var(--ink-2)" }}>{p.summary}</p>
          <div className="mo-kv"><span>tags</span><span className="dz-flow">{p.tags.map((t) => <span key={t} className="cys-tag dim">{t}</span>)}</span><span>source</span><span className="dz-flow"><span className="cys-tag acc">{p.provenance}</span><span className="cys-tag dim">licence {p.licence}</span></span></div>
          <div className="cys-eyebrow" style={{ margin: "4px 14px 4px" }}>Knobs <span className="cys-tag dim">{p.params.length}</span></div>
          {p.params.map((x) => <div key={x.name} className="mo-knob"><span>{x.label}</span><b>{String(x.default)}{x.type === "number" && x.unit ? ` ${x.unit}` : ""}</b></div>)}
          <div style={{ display: "flex", gap: 8, padding: "8px 14px 14px" }}><button type="button" className="cys-btn sm primary" style={{ flex: 1 }} disabled={!motion} onClick={use}><DI n="check" />{motion ? `Use for ${motion.id}` : "No motion design in this mod"}</button></div>
        </section>
      </div>
    </main>
  );
}
const POSTER: Record<string, { tick: number; inputs: Input[]; clip?: string }> = {
  "motion:gun_fire": { tick: 1, inputs: [], clip: "fire" }, "motion:gun_reload": { tick: 12, inputs: [{ tick: 1, event: "fire" }, { tick: 3, event: "reload" }] }, "motion:door_hinge": { tick: 9, inputs: [{ tick: 3, event: "toggle" }] },
  "gen:gait": { tick: 14, inputs: [{ tick: 1, event: "move" }] }, "effect:muzzle_flash": { tick: 1, inputs: [], clip: "play" }, "effect:explosion": { tick: 3, inputs: [], clip: "play" }, "effect:fire": { tick: 50, inputs: [], clip: "play" }, "effect:smoke": { tick: 70, inputs: [], clip: "play" }, "effect:water_splash": { tick: 5, inputs: [], clip: "play" },
};
function Poster({ id, theme }: { id: string; theme: ThemeName }) {
  const data = useMemo(() => { const p = presetById(id); if (!p) return null; const spec = p.build().spec; const pc = POSTER[id] ?? { tick: 10, inputs: [] }; try { const s = simulate(spec, { ...(pc.clip && spec.clips.some((c) => c.name === pc.clip) ? { clip: pc.clip } : {}), inputs: pc.inputs, ticks: pc.tick + 1, withPose: true, withParticles: true }); return { spec, frame: s.frames[Math.min(pc.tick, s.frames.length - 1)] }; } catch { return null; } }, [id]);
  if (!data) return null;
  return <Frame spec={data.spec} frame={data.frame} theme={theme} label={`${id} poster frame`} />;
}
function PresetCard({ id, on, theme, onClick, fit }: { id: string; on: boolean; theme: ThemeName; onClick: () => void; fit?: boolean }) {
  const p = presetById(id)!;
  const spec = useMemo(() => p.build().spec, [p]);
  return (
    <button type="button" className={`mo-card cys-glass ${on ? "on" : ""}`} onClick={onClick} aria-pressed={on}>
      <div className="poster"><Poster id={id} theme={theme} /><span className="cys-tag">{p.generator ? "generator" : p.kind}</span></div>
      <div className="body"><h3>{p.title}</h3><p>{p.summary}</p>
        <div className="dz-flow"><span className="cys-tag dim">{spec.clips.length} clip{spec.clips.length === 1 ? "" : "s"}</span>{spec.machines?.[0] && <span className="cys-tag dim">{spec.machines[0].states.length} states</span>}{fit !== undefined && <span className={`cys-tag ${fit ? "ok" : "warn"}`}>{fit ? "fits minecraft" : "check minecraft"}</span>}</div>
      </div>
    </button>
  );
}

// ------------------------------------------------------------------------------------------------ narrow (phone)
function Narrow({ d, m }: { d: Designer; m: MotionDesign }) {
  const theme = useTheme();
  const { spec, preset } = useMemo(() => specOf(m), [m]);
  const [tick, setTick] = useState(0);
  const [playing, setPlaying] = useState(false);
  const frames = useMemo(() => { if (!spec) return []; try { const evs = spec.machines?.[0] ? [...new Set(spec.machines[0].transitions.map((t) => t.on))] : []; return simulate(spec, { inputs: evs.slice(0, 2).map((e, i) => ({ tick: 2 + i * 20, event: e })), ticks: 60, withPose: true, withParticles: true }).frames; } catch { return []; } }, [spec]);
  useEffect(() => { if (!playing) return; const t = window.setInterval(() => setTick((x) => (x + 1) % Math.max(1, frames.length)), 50); return () => window.clearInterval(t); }, [playing, frames.length]);
  const rep = d.analysis?.motions.find((x) => x.id === m.id);
  const savedM = d.saved.find((x) => x.id === m.id) as unknown as MotionDesign | undefined;
  const pdef = preset ? presetById(preset) : null;
  const now = pdef ? resolveParams(pdef.params, (m.motion as { params?: Record<string, unknown> }).params ?? {}).values : {};
  const was = pdef ? resolveParams(pdef.params, ((savedM?.motion as { params?: Record<string, unknown> } | undefined)?.params) ?? {}).values : {};
  const changes = pdef ? pdef.params.filter((p) => String(now[p.name]) !== String(was[p.name])) : [];
  if (!spec) return null;
  return (
    <main className="dz-narrow mo-narrow" aria-label="Motion review">
      <section className="n-card cys-glass">
        <div className="n-h"><span className="dz-thumb plain" style={{ width: 44, height: 44 }}><MI /></span><div><h1>{m.id} motion</h1><p>{preset ?? "custom"}{spec.machines?.[0] ? `, ${spec.machines[0].states.length} states` : ""}{d.view!.designs.find((x) => x.id === m.id)?.seq ? `, revision r${d.view!.designs.find((x) => x.id === m.id)!.seq}` : ""}</p></div><span className="cys-tag dim" style={{ marginLeft: "auto" }}><SI n="eye" />read only</span></div>
        <div className="mo-vp"><Frame spec={spec} frame={frames[tick]} theme={theme} label={`${m.id} preview`} /></div>
        <div className="n-sec" style={{ display: "flex", alignItems: "center", gap: 10 }}><button type="button" className="mo-play" aria-label={playing ? "Pause" : "Play"} onClick={() => setPlaying(!playing)}><SI n={playing ? "pause" : "play"} /></button><span className="mo-tcode" style={{ marginLeft: 0 }}>t <b>{tick}</b> · {(tick / 20).toFixed(2)}s</span>{frames[tick]?.state && <span className="cys-tag acc" style={{ marginLeft: "auto" }}>{frames[tick].state}</span>}</div>
        <div className="n-sec"><span className="cys-eyebrow">What changed</span>{changes.length ? changes.map((p) => <div key={p.name} className="n-kv"><span>{p.label}</span><b>{String(was[p.name])} → {String(now[p.name])}</b></div>) : <p className="cys-hint" style={{ margin: 0 }}>Nothing waiting.</p>}</div>
        <div className="n-sec"><span className="cys-eyebrow">Checks</span>{rep?.stats && <p className="cys-hint" style={{ margin: "0 0 4px" }}>Fits Minecraft caps ({rep.stats.liveEntities}/{rep.caps.liveEntities} entities, {rep.stats.particlesPerTick}/{rep.caps.particlesPerTick} particles per tick).</p>}{(rep?.dropped ?? []).slice(0, 3).map((x, i) => <p key={i} className="cys-hint" style={{ margin: "0 0 4px" }}>{x.reason}</p>)}</div>
        <div className="n-note"><DI n="info" /><span>Approving keeps this motion in the mod as a revision; nothing is installed until you rebuild.</span></div>
        {STUDIO_DEFAULTS.mobile === "review_and_approve" && d.changed.length > 0 && <div className="n-act"><button type="button" className="cys-btn" onClick={() => void d.discard()}>Reject</button><button type="button" className="cys-btn primary" disabled={!d.analysis?.ok || d.saving} onClick={() => void d.save()}><DI n="check" />Approve revision</button></div>}
      </section>
    </main>
  );
}

toolu_01PV6qURrPAq9mEo7gyc1Bvk.content:
"use client";
// Cyrus MOTION panel (r27) in the studio shell (Texture / Sound / Model / Motion). Layout from the v4 mockups
// (cyrus-designs/v4-motion/motion.html + presets.html, not yet reviewed by the owner). Everything on screen comes from
// the real motion core, run in the browser: the design's MotionSpec (a preset built with its knobs, or the inline spec),
// the state machine run with the scripted inputs (simulate), the software preview renderer (renderFrame) and the
// timeline drawn where the tracks played. Minecraft fit (caps, what the lowering leaves out) comes from the server's
// check of the same design. Edits: the preset knobs (saved as a revision through the designer pipeline); keyframes of a
// preset come from its knobs, so they are read-only here. Phones: read-only preview + approve / reject.
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import Link from "next/link";
import { MOTION_PRESETS, presetById, resolveParams, type ParamDef } from "@/lib/cyrus/motion/presets";
import { eventLog, simulate, type SimFrame } from "@/lib/cyrus/motion/simulate";
import { autoCamera, renderFrame, type ThemeName } from "@/lib/cyrus/motion/preview";
import type { MotionSpec } from "@/lib/cyrus/motion/spec";
import type { MotionDesign } from "@/lib/cyrus/designer/motion/spec";
import { fileKind, type DesignFile } from "@/lib/cyrus/designer/studio/edit";
import { STUDIO_DEFAULTS } from "@/lib/cyrus/studios/access";
import { StudioShell, studioHref, useToast, type StudioMod } from "../studios/StudioShell";
import { DesignerContext, DraftLine, Failed, Loading, Meter, PendingBar, useDesigner, type Designer } from "./shared";
import { DI } from "./icons";
import { SI } from "../studios/icons";
import "./designers.css";

const MOTION_ICON = '<path d="M3 17c3 0 4-10 7-10s4 10 7 10 3-6 4-6"/>';
function MI() { return <svg className="cys-i" viewBox="0 0 24 24" aria-hidden dangerouslySetInnerHTML={{ __html: MOTION_ICON }} />; }

type Input = { tick: number; event: string };
const TICKS = 120;

/** The MotionSpec a design stands for, in the browser (the preset built with its knobs, or the inline spec). */
export function specOf(d: MotionDesign): { spec: MotionSpec | null; preset: string | null; issues: string[] } {
  const m = d.motion as { preset?: string; params?: Record<string, unknown> } | null;
  if (m && typeof m === "object" && typeof m.preset === "string") {
    const p = presetById(m.preset);
    if (!p) return { spec: null, preset: m.preset, issues: [`no preset ${m.preset}`] };
    try { const b = p.build(m.params ?? {}); return { spec: { ...b.spec, id: d.id }, preset: p.id, issues: b.issues.map((i) => i.message) }; } catch (e) { return { spec: null, preset: p.id, issues: [(e as Error).message] }; }
  }
  return m && typeof m === "object" && "rig" in (m as object) ? { spec: m as unknown as MotionSpec, preset: null, issues: [] } : { spec: null, preset: null, issues: ["no motion"] };
}

export function MotionStudio({ mod, initialMotion, initialView, showModel }: { mod: StudioMod; initialMotion: string | null; initialView: "motion" | "presets"; showModel: boolean }) {
  const [view, setView] = useState<"motion" | "presets">(initialView);
  const seg = (
    <div className="cys-seg cys-soft hide-n" aria-label="Studio">
      <Link href={studioHref(mod, "texture")}><SI n="image" />Texture</Link>
      <Link href={studioHref(mod, "sound")}><SI n="wave" />Sound</Link>
      {showModel && <Link href={studioHref(mod, "model")}><SI n="cube" />Model</Link>}
      <button type="button" className="on" aria-current="page" onClick={() => setView("motion")}><MI />Motion</button>
    </div>
  );
  return (
    <StudioShell mod={mod} current={view === "presets" ? "Presets" : "Motion"} studio={null} seg={seg} icon={<MI />} kind="motion">
      <Body mod={mod} initialMotion={initialMotion} view={view} setView={setView} />
    </StudioShell>
  );
}

function Body({ mod, initialMotion, view, setView }: { mod: StudioMod; initialMotion: string | null; view: "motion" | "presets"; setView: (v: "motion" | "presets") => void }) {
  const d = useDesigner(mod);
  const motions = useMemo(() => d.files.filter((f) => fileKind(f) === "motion") as unknown as MotionDesign[], [d.files]);
  const [cur, setCur] = useState<string | null>(initialMotion);
  useEffect(() => { if (motions.length && (!cur || !motions.some((m) => m.id === cur))) setCur(motions[0].id); }, [motions, cur]);
  if (d.err) return <Failed msg={d.err} />;
  if (!d.view) return <Loading what="this mod's motions" />;
  const m = motions.find((x) => x.id === cur) ?? null;
  return (
    <DesignerContext d={d}>
      {view === "presets" || !m ? <Presets d={d} motion={m} onBack={m ? () => setView("motion") : null} /> : <Workspace d={d} motions={motions} m={m} setCur={setCur} openPresets={() => setView("presets")} />}
      {m && <Narrow d={d} m={m} />}
    </DesignerContext>
  );
}

function useTheme(): ThemeName {
  const [t, setT] = useState<ThemeName>("dark");
  useEffect(() => {
    const read = () => setT(document.documentElement.getAttribute("data-theme") === "light" ? "light" : "dark");
    read();
    const o = new MutationObserver(read); o.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
    return () => o.disconnect();
  }, []);
  return t;
}

function Frame({ spec, frame, theme, className, label }: { spec: MotionSpec; frame: SimFrame | undefined; theme: ThemeName; className?: string; label: string }) {
  const ref = useRef<HTMLCanvasElement>(null);
  const cam = useMemo(() => autoCamera(spec, { yaw: 58, pitch: 16, pad: 1.05 }), [spec]);
  useEffect(() => {
    const cv = ref.current; if (!cv || !frame?.pose) return;
    const b = cv.getBoundingClientRect();
    const w = Math.max(160, Math.min(720, Math.round(b.width))), h = Math.max(100, Math.min(420, Math.round(b.height)));
    const r = renderFrame(spec, frame.pose, frame.particles ?? [], { w, h, camera: cam, theme });
    cv.width = r.w; cv.height = r.h;
    cv.getContext("2d")!.putImageData(new ImageData(new Uint8ClampedArray(r.px), r.w, r.h), 0, 0);
  }, [spec, frame, theme, cam]);
  return <canvas ref={ref} className={className} role="img" aria-label={label} />;
}

function Workspace({ d, motions, m, setCur, openPresets }: { d: Designer; motions: MotionDesign[]; m: MotionDesign; setCur: (id: string) => void; openPresets: () => void }) {
  const theme = useTheme();
  const toast = useToast();
  const { spec, preset } = useMemo(() => specOf(m), [m]);
  const machine = spec?.machines?.[0] ?? null;
  const [inputs, setInputs] = useState<Input[]>([]);
  const [mode, setMode] = useState<"sim" | "clip">("sim");
  const [clip, setClip] = useState<string>("");
  const [tick, setTick] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [speed, setSpeed] = useState(1);
  const [rtab, setRtab] = useState<"knobs" | "export" | "checks">("knobs");
  useEffect(() => { setInputs([]); setTick(0); setClip(spec?.clips[0]?.name ?? ""); setMode(spec?.machines?.length ? "sim" : "clip"); }, [m.id]); // eslint-disable-line react-hooks/exhaustive-deps
  const ticks = mode === "clip" ? Math.max(1, spec?.clips.find((c) => c.name === clip)?.length ?? 40) + 1 : Math.max(TICKS, (inputs.at(-1)?.tick ?? 0) + 60);
  const sim = useMemo(() => { if (!spec) return null; try { return simulate(spec, { ...(mode === "clip" && clip ? { clip } : {}), inputs: mode === "sim" ? inputs : [], ticks, withPose: true, withParticles: true }); } catch (e) { return { frames: [], log: [], error: (e as Error).message } as unknown as ReturnType<typeof simulate>; } }, [spec, mode, clip, inputs, ticks]);
  const frames = sim?.frames ?? [];
  const f = frames[Math.min(tick, frames.length - 1)];
  // playback: the clock steps whole ticks (20 per second x speed); the renderer draws that tick
  useEffect(() => {
    if (!playing) return;
    let last = performance.now(), acc = 0, raf = 0;
    const loop = (now: number) => { acc += ((now - last) / 1000) * 20 * speed; last = now; const n = Math.floor(acc); if (n) { acc -= n; setTick((t) => (t + n >= frames.length ? (mode === "clip" ? 0 : (setPlaying(false), frames.length - 1)) : t + n)); } raf = requestAnimationFrame(loop); };
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, [playing, speed, frames.length, mode]);
  const events = machine ? [...new Set(machine.transitions.map((t) => t.on))] : [];
  const fire = (ev: string) => { const t = Math.max(tick, (inputs.at(-1)?.tick ?? -1) + 1); setInputs([...inputs, { tick: t, event: ev }]); setTick(t); };
  const log = useMemo(() => eventLog(frames), [frames]);
  const rep = d.analysis?.motions.find((x) => x.id === m.id);
  const fileRep = d.analysis?.files.find((x) => x.id === m.id);
  const setKnob = useCallback((name: string, v: number | string) => {
    d.setFiles(d.files.map((x) => { if (x.id !== m.id) return x; const c = structuredClone(x) as unknown as MotionDesign; const mo = c.motion as { preset: string; params?: Record<string, unknown> }; mo.params = { ...(mo.params ?? {}), [name]: v }; return c as unknown as DesignFile; }));
  }, [d, m.id]);
  if (!spec) return <main className="dz-ws mo-ws"><div className="dz-col" style={{ gridColumn: "1 / 4" }}><div className="cys-empty"><DI n="warn" /><p>This motion design does not resolve to a motion ({fileRep?.errors[0]?.message ?? "unknown"}).</p></div></div></main>;
  const pdef = preset ? presetById(preset) : null;
  const params = (m.motion as { params?: Record<string, unknown> }).params ?? {};
  const savedM = d.saved.find((x) => x.id === m.id) as unknown as MotionDesign | undefined;
  const savedParams = (savedM?.motion as { params?: Record<string, unknown> } | undefined)?.params ?? {};
  const resolved = pdef ? resolveParams(pdef.params, params).values : {};
  const savedResolved = pdef ? resolveParams(pdef.params, savedParams).values : {};
  return (
    <main className="dz-ws mo-ws" aria-label="Motion">
      <div className="dz-col scroll">
        <section className="cys-panel cys-glass cys-hairline">
          <div className="cys-ph"><span className="cys-eyebrow">Motions</span><span className="n">{motions.length} / 4</span><button type="button" className="cys-ib sm" title="Preset browser" aria-label="Open the preset browser" onClick={openPresets}><SI n="library" /></button></div>
          <div className="dz-body">{motions.map((x) => <button key={x.id} type="button" className={`dz-row ${x.id === m.id ? "on" : ""}`} onClick={() => setCur(x.id)}><span className="dz-thumb plain"><MI /></span><span className="tx"><b>{x.id}</b><small>{(x.motion as { preset?: string }).preset ?? "custom spec"}</small></span></button>)}</div>
        </section>
        <section className="cys-panel cys-glass">
          <div className="cys-ph"><span className="cys-eyebrow">Rig</span><span className="n">{spec.rig.nodes.length} nodes</span></div>
          <ul className="mo-nodes">{spec.rig.nodes.map((n) => { let dep = 0, p = n.parent; while (p && dep < 8) { dep++; p = spec.rig.nodes.find((x) => x.name === p)?.parent ?? null; } return <li key={n.name} style={{ paddingLeft: 8 + dep * 12 }}><SI n={n.kind === "emitter" ? "sparkle" : "cube"} />{n.name}<span className="k">{n.kind}{n.hinge ? ` ${n.hinge.axis} ${n.hinge.min}..${n.hinge.max}` : ""}</span></li>; })}</ul>
        </section>
        {machine && (
          <section className="cys-panel cys-glass">
            <div className="cys-ph"><span className="cys-eyebrow">State machine</span><span className="n">{machine.states.length} states</span></div>
            <div className="mo-states">{machine.states.map((s) => <span key={s.name} className={`mo-state ${f?.state === s.name ? "now" : ""}`}>{s.name}</span>)}</div>
            {f?.vars && <div className="mo-vars">{Object.entries(f.vars).map(([k, v]) => { const def = machine.vars?.find((x) => x.name === k); return <span key={k} className="mo-var">{k} <b>{v}</b>{def ? `/${def.max}` : ""}</span>; })}<span className="mo-var">in state <b>{f.clipTick}</b> ticks</span></div>}
          </section>
        )}
        <section className="cys-panel cys-glass">
          <div className="cys-ph"><span className="cys-eyebrow">Simulate</span><span className="cys-tag dim">scripted</span></div>
          {machine ? <div className="mo-ev">{events.map((e) => <button key={e} type="button" className="cys-btn sm" onClick={() => { setMode("sim"); fire(e); }}><DI n="bolt" />{e}</button>)}<button type="button" className="cys-btn sm" onClick={() => { setInputs([]); setTick(0); }}><DI n="rollback" />Reset</button></div> : <p className="cys-hint" style={{ margin: "0 12px 10px" }}>No state machine: right-click plays the first clip.</p>}
          <div className="mo-log">{log.slice(-40).map((l, i) => <div key={i} className={l.startsWith(`t${f?.tick} `) ? "now" : ""}>{l}</div>)}{!log.length && <div>Fire an event to run the machine.</div>}</div>
        </section>
      </div>

      <div className="dz-col">
        <DraftLine d={d} />
        <div className="mo-bar cys-soft">
          <MI /><b>{m.id}</b>{preset && <span className="cys-tag">{preset}</span>}
          {machine?.vars?.map((v) => <span key={v.name} className="cys-tag dim">{v.name} {v.max}</span>)}
          <span style={{ flex: 1 }} />
          <span className="cys-tag dim" title="The server checks the lowering to Minecraft (display entities)">Minecraft {d.view!.mcVersion}</span>
          <span className="dz-mono">{d.changed.includes(m.id) ? "unsaved" : `saved${d.view!.designs.find((x) => x.id === m.id)?.seq ? ` · r${d.view!.designs.find((x) => x.id === m.id)!.seq}` : ""}`}</span>
        </div>
        <div className="mo-vp">
          <Frame spec={spec} frame={f} theme={theme} label={`${m.id} at tick ${f?.tick ?? 0}${f?.state ? `, state ${f.state}` : ""}`} />
          <span className="hud tl"><span className="cys-dot live" />{f?.state ? <>state <b>{f.state}</b> · </> : null}clip {f?.clip ?? "none"} tick {f?.clipTick ?? 0}</span>
          <span className="hud br"><DI n="info" />Cyrus preview renderer, approximate look</span>
        </div>
        <section className="cys-panel cys-glass mo-tl" aria-label="Timeline">
          <div className="mo-tlh">
            <button type="button" className="cys-ib sm" aria-label="Back one tick" onClick={() => setTick(Math.max(0, tick - 1))}><DI n="chevL" /></button>
            <button type="button" className="mo-play" aria-label={playing ? "Pause" : "Play"} onClick={() => { if (!playing && tick >= frames.length - 1) setTick(0); setPlaying(!playing); }}><SI n={playing ? "pause" : "play"} /></button>
            <button type="button" className="cys-ib sm" aria-label="Forward one tick" onClick={() => setTick(Math.min(frames.length - 1, tick + 1))}><DI n="chevR" /></button>
            <div className="cys-seg sm cys-soft">{[0.25, 0.5, 1].map((s) => <button key={s} type="button" className={speed === s ? "on" : ""} onClick={() => setSpeed(s)}>{s}x</button>)}</div>
            <div className="cys-seg sm cys-soft">{machine && <button type="button" className={mode === "sim" ? "on" : ""} onClick={() => { setMode("sim"); setTick(0); }}><SI n="play" />Simulation</button>}<button type="button" className={mode === "clip" ? "on" : ""} onClick={() => { setMode("clip"); setTick(0); }}><SI n="loop" />Clip</button></div>
            {mode === "clip" && <select className="cys-field" style={{ width: 150, height: 26 }} value={clip} onChange={(e) => { setClip(e.target.value); setTick(0); }} aria-label="Clip">{spec.clips.map((c) => <option key={c.name} value={c.name}>{c.name} · {c.length}t</option>)}</select>}
            <span className="mo-tcode">t <b>{f?.tick ?? 0}</b> · {((f?.tick ?? 0) / 20).toFixed(2)}s · 20 tps</span>
          </div>
          <Timeline spec={spec} frames={frames} tick={tick} setTick={(t) => { setPlaying(false); setTick(t); }} inputs={mode === "sim" ? inputs : []} />
        </section>
      </div>

      <div className="dz-col">
        <section className="cys-panel cys-glass dz-rtabs" style={{ flex: 1, minHeight: 0 }}>
          <div className="cys-tabs" role="tablist">
            <button type="button" role="tab" aria-selected={rtab === "knobs"} className={`cys-tab ${rtab === "knobs" ? "on" : ""}`} onClick={() => setRtab("knobs")}><DI n="sliders" />Knobs{pdef && <span className="n">{pdef.params.length}</span>}</button>
            <button type="button" role="tab" aria-selected={rtab === "export"} className={`cys-tab ${rtab === "export" ? "on" : ""}`} onClick={() => setRtab("export")}><DI n="external" />Export{!!rep?.dropped.length && <span className="n">{rep.dropped.length}</span>}</button>
            <button type="button" role="tab" aria-selected={rtab === "checks"} className={`cys-tab ${rtab === "checks" ? "on" : ""}`} onClick={() => setRtab("checks")}><DI n="check" />Checks</button>
          </div>
          <div className="dz-pane" style={{ padding: 0 }}>
            {rtab === "knobs" && (pdef ? (
              <>
                <p className="cys-hint" style={{ margin: "10px 14px 4px" }}>{pdef.title}: the keyframes come from these knobs, so change a knob rather than a key. Every change is a revision.</p>
                {pdef.params.map((p) => <Knob key={p.name} p={p} v={resolved[p.name]} was={savedResolved[p.name]} onSet={(v) => setKnob(p.name, v)} />)}
                <div style={{ padding: "4px 14px 12px" }}><button type="button" className="cys-btn xs ghost" onClick={() => { d.setFiles(d.files.map((x) => { if (x.id !== m.id) return x; const c = structuredClone(x) as unknown as MotionDesign; (c.motion as { params?: unknown }).params = {}; return c as unknown as DesignFile; })); toast("Knobs back to the preset defaults"); }}><DI n="rollback" />Defaults</button></div>
              </>
            ) : <p className="cys-hint" style={{ margin: "10px 14px" }}>A custom MotionSpec: its keys are edited in Model Studio&apos;s timeline (layer 2). Here you can preview, simulate and check it.</p>)}
            {rtab === "export" && <ExportPane rep={rep} />}
            {rtab === "checks" && (
              <div style={{ padding: "10px 12px" }}>
                <ul className="dz-issues">
                  {(fileRep?.errors ?? []).map((e, i) => <li key={`e${i}`} className="dz-issue err"><span className="ic"><DI n="close" /></span><code>{e.code}</code><span className="path">{e.path}</span><span className="m">{e.message}</span></li>)}
                  {(rep?.issues ?? []).map((e, i) => <li key={`i${i}`} className={`dz-issue ${e.severity === "error" ? "err" : "warn"}`}><span className="ic"><DI n={e.severity === "error" ? "close" : "warn"} /></span><code>{e.code}</code><span className="path">{e.path}</span><span className="m">{e.message}</span></li>)}
                  {rep?.ok && !rep.issues.length && <li className="dz-issue ok"><span className="ic"><DI n="check" /></span><code>minecraft caps</code><span className="path">pass</span></li>}
                  <li className="dz-issue info"><span className="ic"><DI n="minus" /></span><code>real client</code><span className="path">not run</span><span className="m">Interpolation smoothness, the vanilla particle stand-ins and sound timing have not been judged in a real client.</span></li>
                </ul>
              </div>
            )}
          </div>
          <PendingBar d={d} labels={(id) => id} />
        </section>
      </div>
    </main>
  );
}

function Knob({ p, v, was, onSet }: { p: ParamDef; v: number | string | undefined; was: number | string | undefined; onSet: (v: number | string) => void }) {
  const chg = was !== undefined && String(was) !== String(v);
  if (p.type === "number") return (
    <label className="mo-knob"><span>{p.label}{p.unit ? <span className="dz-sub"> {p.unit}</span> : null}</span><b className={chg ? "chg" : ""}>{String(v)}{chg ? <span className="dz-sub" style={{ textDecoration: "line-through", marginLeft: 6 }}>{String(was)}</span> : null}</b>
      <input type="range" min={p.min} max={p.max} step={p.step ?? (p.max - p.min <= 4 ? 0.05 : 1)} value={Number(v)} onChange={(e) => onSet(Number(e.target.value))} aria-label={p.label} /></label>
  );
  if (p.type === "enum") return <div className="mo-knob"><span>{p.label}</span><b className={chg ? "chg" : ""}>{String(v)}</b><div className="cys-seg sm cys-soft">{p.options.map((o) => <button key={o} type="button" className={o === v ? "on" : ""} onClick={() => onSet(o)}>{o}</button>)}</div></div>;
  return <div className="mo-knob"><span>{p.label}</span><b className="dz-mono" style={{ maxWidth: 160, overflow: "hidden", textOverflow: "ellipsis" }} title="Pick sounds in the Sound Studio">{String(v)}</b></div>;
}

function ExportPane({ rep }: { rep: NonNullable<import("./api").Analysis["motions"]>[number] | undefined }) {
  if (!rep) return <p className="cys-hint" style={{ margin: "10px 14px" }}>Checking the Minecraft lowering…</p>;
  const s = rep.stats, c = rep.caps;
  return (
    <>
      <div className="cys-eyebrow" style={{ margin: "12px 14px 8px" }}>Minecraft (display entities)</div>
      {s && <div className="dz-meters" style={{ gridTemplateColumns: "1fr 1fr", padding: "0 14px 12px" }}>
        <Meter label="Entities per prop" used={s.liveEntities} cap={c.liveEntities} /><Meter label="Particles per tick" used={s.particlesPerTick} cap={c.particlesPerTick} />
        <Meter label="Clips" used={s.clips} cap={c.clips} /><Meter label="Keys" used={s.keysTotal} cap={c.keysTotal} />
      </div>}
      {rep.program && <table className="mo-gtable"><tbody><tr><td>Parts</td><td>{rep.program.parts} display entities</td></tr><tr><td>Segments</td><td>{rep.program.segments} interpolation segments ({rep.program.snaps} snaps)</td></tr><tr><td>Cues</td><td>{rep.program.cues} sound / particle cues</td></tr></tbody></table>}
      <div className="cys-eyebrow" style={{ margin: "4px 14px 6px" }}>Left out on Minecraft</div>
      {rep.dropped.length ? <ul className="mo-drops">{rep.dropped.map((x, i) => <li key={i}><DI n="warn" /><span><code className="mono">{x.path}</code> {x.reason}</span></li>)}</ul> : <p className="cys-hint" style={{ margin: "0 14px 12px" }}>Nothing: every track lowers.</p>}
      <div className="dz-note" style={{ margin: "0 14px 14px" }}><DI n="info" /><span>Client smoothness is not verified: Minecraft interpolates linearly between segments, so eases are chained short segments.</span></div>
    </>
  );
}

function Timeline({ spec, frames, tick, setTick, inputs }: { spec: MotionSpec; frames: SimFrame[]; tick: number; setTick: (t: number) => void; inputs: Input[] }) {
  const ref = useRef<HTMLCanvasElement>(null);
  const rows = useMemo(() => {
    const tracks = new Map<string, { label: string; kind: string }>();
    for (const c of spec.clips) for (const t of c.tracks) { const k = t.kind === "transform" ? `${t.node}.${t.channel}` : t.kind === "material" ? `${t.node}.${t.channel}` : t.kind; if (!tracks.has(k)) tracks.set(k, { label: t.kind === "transform" || t.kind === "material" ? k : t.kind === "particle" ? "particles" : t.kind === "sound" ? "sound" : "events", kind: t.kind }); }
    return [...tracks.entries()].sort((a, b) => ["transform", "material", "particle", "sound", "event"].indexOf(a[1].kind) - ["transform", "material", "particle", "sound", "event"].indexOf(b[1].kind)).slice(0, 14);
  }, [spec]);
  useEffect(() => {
    const cv = ref.current; if (!cv) return;
    const draw = () => {
      const W = cv.parentElement!.clientWidth, H = 22 + 18 * (rows.length + 1) + 14, dpr = Math.min(2, window.devicePixelRatio || 1);
      cv.style.height = `${H}px`; cv.width = W * dpr; cv.height = H * dpr;
      const c = cv.getContext("2d")!; c.setTransform(dpr, 0, 0, dpr, 0, 0);
      const cs = getComputedStyle(cv); const v = (n: string) => cs.getPropertyValue(n).trim() || "#888";
      const L = 130, n = Math.max(1, frames.length - 1), x = (t: number) => L + ((W - L - 10) * t) / n;
      c.font = "500 10px ui-monospace, monospace"; c.textBaseline = "middle";
      for (let t = 0; t <= n; t += n > 200 ? 40 : 10) { c.fillStyle = v("--faint"); c.fillText(String(t), x(t) - 4, 10); }
      // state band
      const y0 = 30; c.fillStyle = v("--muted"); c.fillText("state machine", 8, y0);
      let s0 = 0;
      for (let i = 1; i <= frames.length; i++) if (i === frames.length || frames[i].state !== frames[s0].state) { const st = frames[s0].state; if (st) { c.fillStyle = v("--accent"); c.globalAlpha = 0.16 + (st === frames[Math.min(tick, n)]?.state ? 0.14 : 0); c.fillRect(x(s0), y0 - 7, Math.max(1, x(i - 1) - x(s0) + 1), 14); c.globalAlpha = 1; c.fillStyle = v("--ink-2"); if (x(i - 1) - x(s0) > 40) c.fillText(st, x(s0) + 4, y0); } s0 = i; }
      for (const inp of inputs) { c.fillStyle = v("--ink"); c.fillRect(x(inp.tick) - 1, y0 - 9, 2, 4); }
      rows.forEach(([key, r], i) => {
        const y = y0 + 18 * (i + 1);
        c.fillStyle = v("--muted"); c.fillText(r.label.slice(0, 18), 8, y);
        c.strokeStyle = v("--line"); c.beginPath(); c.moveTo(L, y); c.lineTo(W - 10, y); c.stroke();
        frames.forEach((f, ti) => {
          if (!f.clip) return;
          const clip = spec.clips.find((cl) => cl.name === f.clip);
          for (const t of clip?.tracks ?? []) {
            const k = t.kind === "transform" || t.kind === "material" ? `${t.node}.${t.channel}` : t.kind;
            if (k !== key) continue;
            const hitKey = (t.kind === "transform" ? (t.keys ?? []) : t.kind === "material" ? t.keys : []).some((kk) => Math.round(kk.t) === f.clipTick);
            const at = t.kind === "particle" || t.kind === "sound" || t.kind === "event" ? t.at === f.clipTick : false;
            if (hitKey) { c.fillStyle = v("--accent-ink"); c.beginPath(); c.moveTo(x(ti), y - 4); c.lineTo(x(ti) + 4, y); c.lineTo(x(ti), y + 4); c.lineTo(x(ti) - 4, y); c.closePath(); c.fill(); }
            if (at) { c.fillStyle = t.kind === "particle" ? v("--warn") : t.kind === "sound" ? v("--cyan") : v("--accent"); c.fillRect(x(ti) - 3, y - 4, 6, 8); }
            if (t.kind === "transform" && t.wave) { c.fillStyle = v("--accent"); c.globalAlpha = 0.25; c.fillRect(x(ti), y - 2, Math.max(1, x(1) - x(0)), 4); c.globalAlpha = 1; }
          }
        });
      });
      c.strokeStyle = v("--cyan"); c.lineWidth = 1.5; c.beginPath(); c.moveTo(x(tick), 16); c.lineTo(x(tick), H - 4); c.stroke(); c.lineWidth = 1;
    };
    draw(); const ro = new ResizeObserver(draw); ro.observe(cv.parentElement!); return () => ro.disconnect();
  }, [spec, frames, tick, rows, inputs]);
  const scrub = (e: React.PointerEvent<HTMLCanvasElement>) => { const b = e.currentTarget.getBoundingClientRect(); const L = 130; const t = Math.round(((e.clientX - b.left - L) / (b.width - L - 10)) * Math.max(1, frames.length - 1)); setTick(Math.max(0, Math.min(frames.length - 1, t))); };
  return (
    <div className="mo-tlb">
      <canvas ref={ref} role="slider" tabIndex={0} aria-label="Timeline" aria-valuemin={0} aria-valuemax={frames.length - 1} aria-valuenow={tick}
        onPointerDown={(e) => { e.currentTarget.setPointerCapture(e.pointerId); scrub(e); }} onPointerMove={(e) => { if (e.buttons) scrub(e); }}
        onKeyDown={(e) => { if (e.key === "ArrowLeft") setTick(Math.max(0, tick - 1)); if (e.key === "ArrowRight") setTick(Math.min(frames.length - 1, tick + 1)); }} />
    </div>
  );
}

// -------------------------------------------------------------------------------------------- preset browser
function Presets({ d, motion, onBack }: { d: Designer; motion: MotionDesign | null; onBack: (() => void) | null }) {
  const theme = useTheme();
  const toast = useToast();
  const [kind, setKind] = useState<"all" | "motion" | "effect" | "gen">("all");
  const [q, setQ] = useState("");
  const [sel, setSel] = useState<string>(MOTION_PRESETS[1]?.id ?? MOTION_PRESETS[0].id);
  const list = MOTION_PRESETS.filter((p) => (kind === "all" || (kind === "gen" ? p.generator : p.kind === kind && !p.generator)) && (!q.trim() || `${p.title} ${p.summary} ${p.tags.join(" ")}`.toLowerCase().includes(q.toLowerCase())));
  const p = presetById(sel) ?? MOTION_PRESETS[0];
  const fits = (id: string) => d.analysis?.motions.find((x) => (x.id && (d.files.find((f) => f.id === x.id) as unknown as MotionDesign | undefined)?.motion as { preset?: string } | undefined)?.preset === id);
  const use = () => {
    if (!motion) { toast("This mod has no motion design to change. Ask Cyrus for an animated prop first.", true); return; }
    d.setFiles(d.files.map((x) => (x.id !== motion.id ? x : ({ ...(x as unknown as MotionDesign), motion: { preset: p.id, params: {} } } as unknown as DesignFile))));
    toast(`${motion.id} now uses ${p.id} (a structure change; review, then save)`);
    onBack?.();
  };
  return (
    <main className="dz-ws" style={{ gridTemplateColumns: "220px minmax(0, 1fr) 340px" }} aria-label="Preset browser">
      <div className="dz-col">
        <section className="cys-panel cys-glass cys-hairline">
          <div className="cys-ph"><span className="cys-eyebrow">Kind</span></div>
          <div className="dz-body">{([["all", "All", MOTION_PRESETS.length], ["motion", "Motion", MOTION_PRESETS.filter((x) => x.kind === "motion" && !x.generator).length], ["effect", "Effects", MOTION_PRESETS.filter((x) => x.kind === "effect").length], ["gen", "Generators", MOTION_PRESETS.filter((x) => x.generator).length]] as const).map(([k, l, n]) => <button key={k} type="button" className={`dz-row ${kind === k ? "on" : ""}`} onClick={() => setKind(k)}><span className="tx"><b className="sans">{l}</b></span><span className="dz-mono">{n}</span></button>)}</div>
        </section>
        <section className="cys-panel cys-glass"><div className="cys-ph"><span className="cys-eyebrow">How Cyrus uses these</span></div><p className="cys-hint" style={{ margin: "0 14px 14px" }}>Cyrus picks a preset and sets its knobs first, then a generator, and writes a full motion spec only for simple mechanical motion. Plan gating for motion and effects is an open owner decision; keeping, installing and exporting are never gated.</p></section>
        {onBack && <button type="button" className="cys-btn sm" onClick={onBack}><DI n="chevL" />Back to {motion?.id}</button>}
      </div>
      <div className="dz-col">
        <div className="mo-search cys-soft"><SI n="search" /><input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search presets: reload, door, fire, walk…" aria-label="Search presets" /><span className="cys-tag dim">{list.length} presets</span></div>
        <div className="dz-scroll" style={{ flex: 1 }}>
          <div className="mo-grid">{list.map((x) => <PresetCard key={x.id} id={x.id} on={x.id === sel} theme={theme} onClick={() => setSel(x.id)} fit={fits(x.id)?.ok} />)}</div>
        </div>
      </div>
      <div className="dz-col">
        <section className="cys-panel cys-glass cys-hairline" style={{ flex: 1, minHeight: 0, overflow: "auto" }}>
          <div className="cys-ph"><span className="cys-eyebrow">{p.kind}</span><span className="cys-tag dim">{p.id}</span></div>
          <div className="mo-det-poster"><Poster id={p.id} theme={theme} /></div>
          <h2 style={{ margin: "0 14px 4px", font: "600 18px/1.2 var(--display)" }}>{p.title}</h2>
          <p style={{ margin: "0 14px 12px", fontSize: 12.5, lineHeight: 1.5, color: "var(--ink-2)" }}>{p.summary}</p>
          <div className="mo-kv"><span>tags</span><span className="dz-flow">{p.tags.map((t) => <span key={t} className="cys-tag dim">{t}</span>)}</span><span>source</span><span className="dz-flow"><span className="cys-tag acc">{p.provenance}</span><span className="cys-tag dim">licence {p.licence}</span></span></div>
          <div className="cys-eyebrow" style={{ margin: "4px 14px 4px" }}>Knobs <span className="cys-tag dim">{p.params.length}</span></div>
          {p.params.map((x) => <div key={x.name} className="mo-knob"><span>{x.label}</span><b>{String(x.default)}{x.type === "number" && x.unit ? ` ${x.unit}` : ""}</b></div>)}
          <div style={{ display: "flex", gap: 8, padding: "8px 14px 14px" }}><button type="button" className="cys-btn sm primary" style={{ flex: 1 }} disabled={!motion} onClick={use}><DI n="check" />{motion ? `Use for ${motion.id}` : "No motion design in this mod"}</button></div>
        </section>
      </div>
    </main>
  );
}
const POSTER: Record<string, { tick: number; inputs: Input[]; clip?: string }> = {
  "motion:gun_fire": { tick: 1, inputs: [], clip: "fire" }, "motion:gun_reload": { tick: 12, inputs: [{ tick: 1, event: "fire" }, { tick: 3, event: "reload" }] }, "motion:door_hinge": { tick: 9, inputs: [{ tick: 3, event: "toggle" }] },
  "gen:gait": { tick: 14, inputs: [{ tick: 1, event: "move" }] }, "effect:muzzle_flash": { tick: 1, inputs: [], clip: "play" }, "effect:explosion": { tick: 3, inputs: [], clip: "play" }, "effect:fire": { tick: 50, inputs: [], clip: "play" }, "effect:smoke": { tick: 70, inputs: [], clip: "play" }, "effect:water_splash": { tick: 5, inputs: [], clip: "play" },
};
function Poster({ id, theme }: { id: string; theme: ThemeName }) {
  const data = useMemo(() => { const p = presetById(id); if (!p) return null; const spec = p.build().spec; const pc = POSTER[id] ?? { tick: 10, inputs: [] }; try { const s = simulate(spec, { ...(pc.clip && spec.clips.some((c) => c.name === pc.clip) ? { clip: pc.clip } : {}), inputs: pc.inputs, ticks: pc.tick + 1, withPose: true, withParticles: true }); return { spec, frame: s.frames[Math.min(pc.tick, s.frames.length - 1)] }; } catch { return null; } }, [id]);
  if (!data) return null;
  return <Frame spec={data.spec} frame={data.frame} theme={theme} label={`${id} poster frame`} />;
}
function PresetCard({ id, on, theme, onClick, fit }: { id: string; on: boolean; theme: ThemeName; onClick: () => void; fit?: boolean }) {
  const p = presetById(id)!;
  const spec = useMemo(() => p.build().spec, [p]);
  return (
    <button type="button" className={`mo-card cys-glass ${on ? "on" : ""}`} onClick={onClick} aria-pressed={on}>
      <div className="poster"><Poster id={id} theme={theme} /><span className="cys-tag">{p.generator ? "generator" : p.kind}</span></div>
      <div className="body"><h3>{p.title}</h3><p>{p.summary}</p>
        <div className="dz-flow"><span className="cys-tag dim">{spec.clips.length} clip{spec.clips.length === 1 ? "" : "s"}</span>{spec.machines?.[0] && <span className="cys-tag dim">{spec.machines[0].states.length} states</span>}{fit !== undefined && <span className={`cys-tag ${fit ? "ok" : "warn"}`}>{fit ? "fits minecraft" : "check minecraft"}</span>}</div>
      </div>
    </button>
  );
}

// ------------------------------------------------------------------------------------------------ narrow (phone)
function Narrow({ d, m }: { d: Designer; m: MotionDesign }) {
  const theme = useTheme();
  const { spec, preset } = useMemo(() => specOf(m), [m]);
  const [tick, setTick] = useState(0);
  const [playing, setPlaying] = useState(false);
  const frames = useMemo(() => { if (!spec) return []; try { const evs = spec.machines?.[0] ? [...new Set(spec.machines[0].transitions.map((t) => t.on))] : []; return simulate(spec, { inputs: evs.slice(0, 2).map((e, i) => ({ tick: 2 + i * 20, event: e })), ticks: 60, withPose: true, withParticles: true }).frames; } catch { return []; } }, [spec]);
  useEffect(() => { if (!playing) return; const t = window.setInterval(() => setTick((x) => (x + 1) % Math.max(1, frames.length)), 50); return () => window.clearInterval(t); }, [playing, frames.length]);
  const rep = d.analysis?.motions.find((x) => x.id === m.id);
  const savedM = d.saved.find((x) => x.id === m.id) as unknown as MotionDesign | undefined;
  const pdef = preset ? presetById(preset) : null;
  const now = pdef ? resolveParams(pdef.params, (m.motion as { params?: Record<string, unknown> }).params ?? {}).values : {};
  const was = pdef ? resolveParams(pdef.params, ((savedM?.motion as { params?: Record<string, unknown> } | undefined)?.params) ?? {}).values : {};
  const changes = pdef ? pdef.params.filter((p) => String(now[p.name]) !== String(was[p.name])) : [];
  if (!spec) return null;
  return (
    <main className="dz-narrow mo-narrow" aria-label="Motion review">
      <section className="n-card cys-glass">
        <div className="n-h"><span className="dz-thumb plain" style={{ width: 44, height: 44 }}><MI /></span><div><h1>{m.id} motion</h1><p>{preset ?? "custom"}{spec.machines?.[0] ? `, ${spec.machines[0].states.length} states` : ""}{d.view!.designs.find((x) => x.id === m.id)?.seq ? `, revision r${d.view!.designs.find((x) => x.id === m.id)!.seq}` : ""}</p></div><span className="cys-tag dim" style={{ marginLeft: "auto" }}><SI n="eye" />read only</span></div>
        <div className="mo-vp"><Frame spec={spec} frame={frames[tick]} theme={theme} label={`${m.id} preview`} /></div>
        <div className="n-sec" style={{ display: "flex", alignItems: "center", gap: 10 }}><button type="button" className="mo-play" aria-label={playing ? "Pause" : "Play"} onClick={() => setPlaying(!playing)}><SI n={playing ? "pause" : "play"} /></button><span className="mo-tcode" style={{ marginLeft: 0 }}>t <b>{tick}</b> · {(tick / 20).toFixed(2)}s</span>{frames[tick]?.state && <span className="cys-tag acc" style={{ marginLeft: "auto" }}>{frames[tick].state}</span>}</div>
        <div className="n-sec"><span className="cys-eyebrow">What changed</span>{changes.length ? changes.map((p) => <div key={p.name} className="n-kv"><span>{p.label}</span><b>{String(was[p.name])} → {String(now[p.name])}</b></div>) : <p className="cys-hint" style={{ margin: 0 }}>Nothing waiting.</p>}</div>
        <div className="n-sec"><span className="cys-eyebrow">Checks</span>{rep?.stats && <p className="cys-hint" style={{ margin: "0 0 4px" }}>Fits Minecraft caps ({rep.stats.liveEntities}/{rep.caps.liveEntities} entities, {rep.stats.particlesPerTick}/{rep.caps.particlesPerTick} particles per tick).</p>}{(rep?.dropped ?? []).slice(0, 3).map((x, i) => <p key={i} className="cys-hint" style={{ margin: "0 0 4px" }}>{x.reason}</p>)}</div>
        <div className="n-note"><DI n="info" /><span>Approving keeps this motion in the mod as a revision; nothing is installed until you rebuild.</span></div>
        {STUDIO_DEFAULTS.mobile === "review_and_approve" && d.changed.length > 0 && <div className="n-act"><button type="button" className="cys-btn" onClick={() => void d.discard()}>Reject</button><button type="button" className="cys-btn primary" disabled={!d.analysis?.ok || d.saving} onClick={() => void d.save()}><DI n="check" />Approve revision</button></div>}
      </section>
    </main>
  );
}

