import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { modBuilderMetadata, requireModBuilderUser } from "@/lib/modbuilder/access";
import { designerStudioOn } from "@/lib/cyrus/designer/studio/deps";
import { modelStudioViewer } from "@/lib/cyrus/modelstudio/deps";
import { MotionStudio } from "@/components/cyrus/designers/MotionStudio";
import { studioContext } from "../../../studio-shared";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return modBuilderMetadata("Motion · Cyrus");
}

/**
 * The Motion panel (timeline + preview + preset browser) in the studio shell. Motion designs are a designer kind, so the
 * same gates apply: CYRUS_DESIGNER=1 (404 otherwise), then the studios gate. Not plan-gated (the motion gating options
 * A/B/C are an open owner decision); keeping, installing and exporting are never gated.
 */
export default async function MotionPage({ params, searchParams }: { params: Promise<{ id: string }>; searchParams: Promise<{ motion?: string | string[]; view?: string | string[] }> }) {
  await requireModBuilderUser();
  if (!designerStudioOn()) notFound();
  const { id } = await params;
  const { mod } = await studioContext(id);
  const q = await searchParams;
  const showModel = !!(await modelStudioViewer().catch(() => null));
  return <MotionStudio mod={mod} initialMotion={typeof q.motion === "string" && /^[a-z][a-z0-9_]{1,31}$/.test(q.motion) ? q.motion : null} initialView={q.view === "presets" ? "presets" : "motion"} showModel={showModel} />;
}
EOF
