// Cyrus designer studio UI (r27): seed the devhost THROWAWAY database with designer mods for the studio test accounts
// (run AFTER scripts/cyrus/studio-fixtures.ts, which creates the accounts): "Void Arsenal" (the item designer fixtures +
// the voidsteel sword texture from the texture library as void_reaper's item model), "Guild Craft" (the menu / quest
// fixtures), "Boss Trials" (the boss / encounter fixtures) and "Pistol Pack" (the motion fixtures). Designs are recorded
// exactly like a build's asset sync records them (kind design, origin generated, provenance.spec). Prints the build ids.
// Refuses to run against anything but devhost's wt_* database on 127.0.0.1:5433.
//   devhost run -- npx tsx scripts/cyrus/designer-fixtures.ts > .designer-mods.json
import { readFileSync } from "node:fs";
import path from "node:path";
import { db } from "../../lib/db";
import { canonicalJson, sha256Hex } from "../../lib/cyrus/assets/textures";
import { addRevision, createProject, recordAsset } from "../../lib/cyrus/engine-core/store";
import { DESIGN_KIND_MIME } from "../../lib/cyrus/designer/sync";
import { designKind, type DesignKind } from "../../lib/cyrus/designer/gameplay/spec";
import { saveTexture, type StudioServiceDeps } from "../../lib/cyrus/studios/service";
import { chainOf, prismaStudioStore } from "../../lib/cyrus/studios/store-prisma";
import { useTextureFromLibrary } from "../../lib/cyrus/library/use-in-project";
import { docFromSpec } from "../../lib/cyrus/studios/paint";
import { goldenDesigns, GOLDEN_NS } from "./designer-golden";
import { GP_NS, loadGameplayFixtures } from "./gameplay-golden";
import { BOSS_NS, loadBossFixtures } from "./boss-golden";

const url = process.env.DATABASE_URL ?? "";
if (!/@127\.0\.0\.1:5433\/wt_[a-z0-9_]+/.test(url)) { console.error("refusing: not the devhost throwaway database"); process.exit(2); }

const MOTION_FX = path.join(__dirname, "../../test/fixtures/cyrus-motion-mc");
const motions = () => ["lab_pistol", "lab_door"].map((n) => JSON.parse(readFileSync(path.join(MOTION_FX, `${n}.json`), "utf8")));
const MODS = [
  { title: "Void Arsenal", category: "weapons", plugin: "VoidArsenal", ns: GOLDEN_NS, designs: goldenDesigns, texture: { itemId: "sword_voidsteel", key: "void_reaper" } },
  { title: "Guild Craft", category: "quests", plugin: "GuildQuests", ns: GP_NS, designs: loadGameplayFixtures },
  { title: "Boss Trials", category: "creatures", plugin: "BossTrials", ns: BOSS_NS, designs: loadBossFixtures },
  { title: "Pistol Pack", category: "weapons", plugin: "PistolPack", ns: "nx_none", designs: motions },
] as const;
const ACCOUNTS = ["usr_studio_all", "usr_studio_saka", "usr_studio_free"];

async function seedMod(userId: string, m: (typeof MODS)[number]) {
  const meta = { title: m.title, category: m.category, categorySource: "owner", description: `${m.title}: designer fixtures for the studio screens.` };
  const b = await db.modBuild.create({ data: { userId, status: "succeeded", prompt: `${m.title} (designer fixtures)`, mcVersion: "1.21.11", pluginName: m.plugin, version: "1.0.0", cyrus: meta, result: { summary: m.title }, jarName: `${m.plugin}-1.0.0.jar`, jarSha256: "e".repeat(64), createdAt: new Date(Date.now() - 86400e3) } });
  const project = await createProject({ userId, game: "minecraft", rootBuildId: b.id });
  const ns = project.namespace;
  const designs = (m.designs() as unknown[]).map((d) => JSON.parse(JSON.stringify(d).split(`${m.ns}:`).join(`${ns}:`)) as { id: string });
  const rows = designs.map((d) => { const c = canonicalJson(d); return { d, c, sha: sha256Hex(c), kind: (designKind(d) ?? "item") as DesignKind }; });
  const rev = await addRevision(project.id, {
    kind: "generated", status: "passed", modBuildId: b.id, expectedHeadId: null, message: `${rows.length} designs`,
    manifest: [{ path: `plugin/${m.plugin}-1.0.0.jar`, sha256: "e".repeat(64), role: "artifact" }, ...rows.map((r) => ({ path: `assets/designs/${r.d.id}.json`, sha256: r.sha, role: "asset" as const }))],
  });
  for (const r of rows) await recordAsset(project.id, { revisionId: rev.id, assetKey: r.d.id, kind: "design", sha256: r.sha, size: r.c.length, origin: "generated", mime: DESIGN_KIND_MIME[r.kind], path: `assets/designs/${r.d.id}.json`, provenance: { generator: "cyrus-designer", ...(r.kind !== "item" ? { designKind: r.kind } : {}), spec: r.d, version: "1.21.11", modBuildId: b.id, kept: false, configVersion: 1 } });
  if ("texture" in m && m.texture) {
    const deps: StudioServiceDeps = { store: prismaStudioStore, planOf: async () => "all", chain: chainOf, deliveryOn: () => false };
    const used = await useTextureFromLibrary({ itemId: m.texture.itemId, key: m.texture.key, namespace: ns }, (k, p) => prismaStudioStore.reserve(project.id, k, p));
    if (!used.ok) throw new Error(used.error);
    const head = (await db.cyrusProject.findUnique({ where: { id: project.id } }))!.headRevisionId;
    await saveTexture(deps, { userId, projectId: project.id, key: m.texture.key, doc: docFromSpec(used.spec), baseAssetId: null, expectedHeadId: head, origin: "library", provenance: { library: used.provenance.library } });
  }
  return { buildId: b.id, projectId: project.id, namespace: ns };
}

(async () => {
  const out: Record<string, Record<string, unknown>> = {};
  for (const u of ACCOUNTS) {
    if (!(await db.user.findUnique({ where: { id: u } }))) { console.error(`no ${u}: run scripts/cyrus/studio-fixtures.ts first`); process.exit(1); }
    out[u.replace("usr_studio_", "")] = {};
    for (const m of MODS) out[u.replace("usr_studio_", "")][m.plugin] = await seedMod(u, m);
  }
  process.stdout.write(JSON.stringify(out, null, 1));
  await db.$disconnect();
})().catch(async (e) => { console.error(e); await db.$disconnect(); process.exit(1); });

