if (want("item-phone-light")) { const s = await open("all", "VoidArsenal", "items?item=void_reaper", { narrow: true, theme: "light" }); await done("item-phone-light", s); }
if (want("item-saka-dark")) { const s = await open("saka", "VoidArsenal", "items?item=void_reaper"); await done("item-saka-dark", s, "texture chip locked on Saka"); }
if (want("item-dark-saved")) {
  // a REAL save through the API (the draft from item-dark-edit is restored first)
  const s = await open("all", "VoidArsenal", "items?item=void_reaper");
  const b = s.page.getByRole("button", { name: /^Save as revision/ }).first();
  if (await b.count()) { await b.click(); await s.page.waitForTimeout(3000); }
  await done("item-dark-saved", s, "saved as a revision");
}

// --------------------------------------------------------------------------------------------- menus + quests
if (want("menu-dark")) { const s = await open("all", "GuildQuests", "menus?menu=shop"); await s.page.getByRole("gridcell", { name: /slot 47/ }).click(); await s.page.waitForTimeout(600); await done("menu-dark", s); }
if (want("menu-light")) { const s = await open("all", "GuildQuests", "menus?menu=shop", { theme: "light" }); await s.page.getByRole("gridcell", { name: /slot 47/ }).click(); await s.page.waitForTimeout(600); await done("menu-light", s); }
if (want("menu-dark-try")) {
  const s = await open("all", "GuildQuests", "menus?menu=shop");
  await s.page.getByRole("button", { name: "Try it", exact: true }).click(); await s.page.waitForTimeout(1200);
  for (const slot of [10, 46, 51, 14]) { await s.page.getByRole("gridcell", { name: new RegExp(`^slot ${slot}\\b`) }).click(); await s.page.waitForTimeout(900); }
  await done("menu-dark-try", s);
}
if (want("menu-dark-edit")) {
  const s = await open("all", "GuildQuests", "menus?menu=shop");
  await s.page.getByRole("gridcell", { name: /slot 47/ }).click(); await s.page.waitForTimeout(400);
  await stepper(s.page, "slot 47 price (emerald)", 7);
  await s.page.waitForTimeout(2500);
  await done("menu-dark-edit", s, "price 5 -> 7");
}
if (want("quests-dark")) {
  const s = await open("all", "GuildQuests", "menus?tab=quests&quest=trial_two");
  for (const b of [/^Start The First Trial/]) { const x = s.page.getByRole("button", { name: b }).first(); if (await x.count()) { await x.click(); await s.page.waitForTimeout(900); } }
  for (let i = 0; i < 5; i++) { const x = s.page.getByRole("button", { name: /^Kill zombie/ }).first(); if (await x.count()) { await x.click(); await s.page.waitForTimeout(500); } }
  await done("quests-dark", s);
}
if (want("quests-light")) { const s = await open("all", "GuildQuests", "menus?tab=quests&quest=trial_two", { theme: "light" }); await done("quests-light", s); }
if (want("menu-phone")) { const s = await open("all", "GuildQuests", "menus?menu=shop", { narrow: true }); await done("menu-phone", s); }

// -------------------------------------------------------------------------------------------------- bosses
if (want("boss-dark")) { const s = await open("all", "BossTrials", "bosses?boss=ember_warden"); await done("boss-dark", s); }
if (want("boss-light")) { const s = await open("all", "BossTrials", "bosses?boss=ember_warden", { theme: "light" }); await done("boss-light", s); }
if (want("boss-dark-fight")) {
  const s = await open("all", "BossTrials", "bosses?boss=ember_warden");
  await tab(s.page, "Fight"); await s.page.waitForTimeout(1000);
  for (const b of ["Hit 25%", "+5 s", "Hit 25%", "+5 s", "2nd player", "Hit 25%", "+5 s"]) { await s.page.getByRole("button", { name: b, exact: true }).click(); await s.page.waitForTimeout(500); }
  await s.page.waitForTimeout(1200);
  await done("boss-dark-fight", s);
}
if (want("boss-dark-encounter")) { const s = await open("all", "BossTrials", "bosses"); await s.page.getByRole("button", { name: /ash_trial/ }).first().click(); await s.page.waitForTimeout(1000); await done("boss-dark-encounter", s); }
if (want("boss-phone")) { const s = await open("all", "BossTrials", "bosses?boss=ember_warden", { narrow: true }); await done("boss-phone", s); }

// --------------------------------------------------------------------------------------------------- motion
if (want("motion-dark")) {
  const s = await open("all", "PistolPack", "motion?motion=lab_pistol", { wait: ".mo-ws, .mo-narrow" });
  for (const e of ["fire", "fire", "fire", "fire", "reload"]) { const b = s.page.getByRole("button", { name: e, exact: true }).first(); if (await b.count()) { await b.click(); await s.page.waitForTimeout(150); } }
  const tl = s.page.getByRole("slider", { name: "Timeline" }); const box = await tl.boundingBox(); if (box) await s.page.mouse.click(box.x + 130 + (box.width - 140) * 0.32, box.y + 20);
  await s.page.waitForTimeout(1200);
  await done("motion-dark", s);
}
if (want("motion-light")) { const s = await open("all", "PistolPack", "motion?motion=lab_pistol", { theme: "light", wait: ".mo-ws" }); await tab(s.page, "Export"); await s.page.waitForTimeout(800); await done("motion-light", s); }
if (want("motion-dark-knob")) {
  const s = await open("all", "PistolPack", "motion?motion=lab_door", { wait: ".mo-ws" });
  const r = s.page.locator(".mo-knob input[type=range]").first(); const box = await r.boundingBox(); if (box) await s.page.mouse.click(box.x + box.width * 0.8, box.y + box.height / 2);
  await s.page.waitForTimeout(2500);
  await done("motion-dark-knob", s, "door knob changed");
}
if (want("motion-presets")) { const s = await open("all", "PistolPack", "motion?view=presets", { wait: ".mo-grid" }); await s.page.waitForTimeout(1500); await done("motion-presets-dark", s); }
if (want("motion-presets-light")) { const s = await open("all", "PistolPack", "motion?view=presets", { theme: "light", wait: ".mo-grid" }); await s.page.waitForTimeout(1500); await done("motion-presets-light", s); }
if (want("motion-phone")) { const s = await open("all", "PistolPack", "motion?motion=lab_pistol", { narrow: true, wait: ".mo-narrow" }); await done("motion-phone", s); }

// ----------------------------------------------------------------------------------------------------- gates
if (want("gate-outsider")) {
  const c = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  await c.addCookies([{ name: T.cookie, value: T.outsider.token, url: BASE }]);
  const p = await c.newPage();
  const r = await p.goto(`${BASE}/dashboard/cyrus/${M.all.VoidArsenal.buildId}/studio/items`, { waitUntil: "networkidle", timeout: 120000 }).catch(() => null);
  const api = await p.request.get(`${BASE}/api/cyrus/designer/v1/projects?root=${M.all.VoidArsenal.buildId}`);
  await p.screenshot({ path: `${out}/designer-gate-outsider.png` });
  console.log("designer-gate-outsider.png", `page ${r?.status()} api ${api.status()}`);
  if (api.status() !== 404) failures++;
  await c.close();
}
await browser.close();
process.exit(failures ? 1 : 0);

