    case "potion_effect": return `${a.effect} for ${secs(a.durationTicks)}`;
    case "launch_projectile": return `launches a ${a.kind.replace("_", " ")}`;
    case "teleport_short": return `blinks up to ${a.range} blocks forward`;
    case "give_item": return `gives ${bare(a.item)}`;
